function act(obs, mem) {
  const D2R = Math.PI / 180, R2D = 180 / Math.PI, DT = 0.1;
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap180(a) { a = a % 360; if (a > 180) a -= 360; if (a < -180) a += 360; return a; }
  function ema(p, c, k) { return p + (c - p) * k; }
  function dist(ax, ay, bx, by) { const dx = bx - ax, dy = by - ay; return Math.sqrt(dx * dx + dy * dy); }
  function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }

  /* ============================ INIT ============================ */
  if (!mem.init) {
    const m = obs.mission || {};
    mem.init = 1;
    mem.size = num(m.size, 400);
    const bb = m.base || {};
    mem.base = { x: num(bb.x, num(obs.x, 200)), y: num(bb.y, num(obs.y, 200)) };
    mem.cap = num(m.capacity, 5);
    mem.hints = [];
    const hs = (m.hints && m.hints.length) ? m.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i];
      if (!h || !isFinite(h.x) || !isFinite(h.y)) continue;
      mem.hints.push({ x: h.x, y: h.y, est: num(h.estimate, 1), status: 0, kind: 0 });
    }
    mem.mode = 'goto'; mem.target = null; mem.modeT = 0;
    mem.px = num(obs.x, 200); mem.py = num(obs.y, 200);
    mem.lastGx = mem.px; mem.lastGy = mem.py;
    mem.posHist = [[num(obs.t, 0), mem.px, mem.py]];
    mem.hbias = 0;
    mem.kv = 3.0; mem.dead = 0.05;
    mem.ePerM = 0.00035; mem.eDrill = 0.0015;
    mem.vAvg = 1.7; mem.vGps = 0;
    mem.holdI = 0; mem.holdX = mem.px; mem.holdY = mem.py;
    mem.drillOn = 0; mem.drillT = 0;
    mem.searchTheta = 0; mem.searchStart = 0; mem.searchR = 12; mem.searchR0 = 12;
    mem.searchAdv = 0; mem.searchDone = 0;
    mem.bumpT = 0; mem.bumpSide = 1; mem.stuckT = 0;
    mem.zeroSciT = 0; mem.sciSeen = 0;
    mem.carriedPrev = num(obs.carried, 0);
    mem.batPrev = num(obs.battery, 1);
    mem.dockT = -1;
    mem.sitePos = null; mem.siteVal = 0; mem.siteSeenT = -1e9;
    mem.deliv = 0;
  }

  /* ============================ SENSE ============================ */
  const now = num(obs.t, 0);
  const battery = num(obs.battery, 1);
  const solar = num(obs.solar, 0);
  const carried = num(obs.carried, 0);
  const carriedPrev = mem.carriedPrev; mem.carriedPrev = carried;
  const pitch = num(obs.pitch, 0);
  const timeLeft = num(obs.timeLeft, 1200);
  const heading = num(obs.heading, 0);
  mem.modeT += DT;

  const consumed = -(battery - mem.batPrev - solar * DT);
  mem.batPrev = battery;

  const wl = num(obs.wheelLeft, 0), wr = num(obs.wheelRight, 0);
  const hRad = (heading + mem.hbias) * D2R;
  const vOdo = (wl + wr) / 2;
  let nx = mem.px + vOdo * Math.cos(hRad) * DT;
  let ny = mem.py + vOdo * Math.sin(hRad) * DT;
  const ox = num(obs.x, mem.px), oy = num(obs.y, mem.py);
  const gsame = (Math.abs(ox - mem.lastGx) < 1e-9 && Math.abs(oy - mem.lastGy) < 1e-9);
  if (!gsame) {
    const jx = ox - nx, jy = oy - ny;
    const jump = Math.sqrt(jx * jx + jy * jy);
    if (jump > 25) { nx = ox; ny = oy; }
    else if (jump > 3) { nx += jx * 0.6; ny += jy * 0.6; }
    else { nx += jx * 0.35; ny += jy * 0.35; }
  }
  mem.lastGx = ox; mem.lastGy = oy;
  const step = dist(mem.px, mem.py, nx, ny);
  mem.px = nx; mem.py = ny;
  mem.posHist.push([now, mem.px, mem.py]);
  if (mem.posHist.length > 30) mem.posHist.shift();

  let vGps = 0;
  {
    let i = mem.posHist.length - 1;
    while (i > 0 && now - mem.posHist[i - 1][0] > 0.5) i--;
    const p0 = mem.posHist[i];
    const tw = now - p0[0];
    if (tw > 0.15) vGps = ((mem.px - p0[1]) * Math.cos(hRad) + (mem.py - p0[2]) * Math.sin(hRad)) / tw;
  }
  mem.vGps = vGps;
  const speed = Math.abs(vGps);

  {
    const p0 = mem.posHist[0];
    const dx = mem.px - p0[1], dy = mem.py - p0[2];
    const dd = Math.sqrt(dx * dx + dy * dy);
    if (dd > 1.2) {
      const cand = wrap180(Math.atan2(dy, dx) * R2D - heading);
      const diff = wrap180(cand - mem.hbias);
      mem.hbias = wrap180(mem.hbias + diff * (Math.abs(diff) < 45 ? 0.05 : 0.008));
    }
  }

  if (step > 0.005 && consumed > 0) {
    const epm = consumed / step;
    if (epm > 1e-8 && epm < 0.02) mem.ePerM = ema(mem.ePerM, epm, epm < mem.ePerM * 0.5 ? 0.004 : 0.025);
  }
  if (mem.mode === 'sample' && mem.drillOn && consumed > 0) {
    mem.eDrill = ema(mem.eDrill, clamp(consumed / DT, 1e-7, 0.2), 0.05);
  }
  if (speed > 0.5) mem.vAvg = ema(mem.vAvg, speed, 0.012);

  const sci = num(obs.science, 0);
  if (sci > 1e-6) { mem.sciSeen = 1; mem.zeroSciT = 0; } else mem.zeroSciT += DT;

  if (obs.site && isFinite(obs.site.distance)) {
    const ang = (heading + num(obs.site.bearing, 0)) * D2R;
    mem.sitePos = { x: mem.px + obs.site.distance * Math.cos(ang), y: mem.py + obs.site.distance * Math.sin(ang) };
    mem.siteVal = num(obs.site.value, 1);
    mem.siteSeenT = now;
  }

  /* ============================ HELPERS ============================ */
  function holdCmd() {
    const v = mem.vGps;
    mem.holdI = clamp(mem.holdI - 0.45 * v * DT, -0.85, 0.85);
    let cmd = mem.holdI - 0.5 * v;
    const dx = mem.holdX - mem.px, dy = mem.holdY - mem.py;
    cmd += clamp(0.2 * (dx * Math.cos(hRad) + dy * Math.sin(hRad)), -0.35, 0.35);
    cmd = clamp(cmd, -0.9, 0.9);
    if (Math.abs(cmd) < mem.dead * 0.7) cmd = 0;
    return cmd;
  }

  function chooseNext() {
    let best = null, bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;
      const d1 = dist(mem.px, mem.py, h.x, h.y);
      const d2 = dist(h.x, h.y, mem.base.x, mem.base.y);
      const vEff = Math.max(0.6, mem.vAvg);
      const tNeed = (d1 + d2) / vEff * 1.4 + 18;
      if (tNeed > timeLeft * 0.95) continue;
      const eNeed = (d1 + d2) * mem.ePerM * 1.35 + 0.07;
      if (eNeed > battery * 0.95) continue;
      const score = h.est / (d1 + 0.45 * d2 + 30);
      if (score > bestScore) { bestScore = score; best = h; }
    }
    return best;
  }

  /* ============================ BUMP / RECOVERY ============================ */
  const rayA = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  let minFwd = 15, leftMin = 15, rightMin = 15, avoid = 0;
  const rays = obs.rays || [];
  for (let i = 0; i < 9; i++) {
    let r = num(rays[i], 15);
    if (r < 0) r = 15;
    if (r > 15) r = 15;
    const a = rayA[i];
    if (Math.abs(a) <= 20 && r < minFwd) minFwd = r;
    if (a < 0) { if (r < rightMin) rightMin = r; } else { if (r < leftMin) leftMin = r; }
    if (r < 10) {
      const w = (10 - r) / 10;
      avoid += w * Math.sin(a * D2R) * (1 + 1.2 * Math.cos(a * D2R));
    }
  }
  let turnBias = clamp(-0.5 * avoid, -1, 1);
  if (minFwd < 6) {
    const side = (leftMin >= rightMin) ? 1 : -1;
    turnBias = clamp(turnBias + side * ((6 - minFwd) / 6) * 0.85, -1, 1);
  }
  let vLim = 2.8;
  if (minFwd < 13) vLim = Math.min(vLim, 0.22 * (minFwd - 0.6));
  if (minFwd < 1.4) vLim = 0;
  vLim = Math.max(0, vLim);

  if (obs.bumped) {
    mem.bumpT = 0.8;
    mem.bumpSide = (leftMin <= rightMin) ? -1 : 1;
    mem.stuckT = 0;
  }
  if (mem.bumpT > 0 && mem.mode !== 'sample') {
    mem.bumpT -= DT;
    if (mem.bumpT > 0.45) return { left: -0.55, right: -0.55, drill: false };
    const t = 0.42 * mem.bumpSide;
    return { left: clamp(-t, -1, 1), right: clamp(t, -1, 1), drill: false };
  }

  /* ============================ SAMPLE ============================ */
  if (mem.mode === 'sample') {
