    const drilling = num(obs.drilling, 0);
    let done = false, sampled = false;
    if (drilling >= 5.85) { done = true; sampled = true; }
    if (carried > carriedPrev) { done = true; sampled = true; }
    if (mem.drillT > 9 && !obs.site && drilling < 0.4) { done = true; sampled = false; }
    if (battery < 0.03) { done = true; sampled = false; }
    if (done) {
      const sp = mem.sitePos || { x: mem.px, y: mem.py };
      for (let i = 0; i < mem.hints.length; i++) {
