        if (h.status === 0 && dist(h.x, h.y, sp.x, sp.y) < 25) h.status = sampled ? 1 : 3;
      }
      mem.mode = 'goto'; mem.target = null; mem.modeT = 0;
      mem.drillT = 0; mem.drillOn = 0;
      return { left: 0, right: 0, drill: false };
    }
    if (mem.drillT > 12 && drilling < 5.5) {
      mem.drillT = 0; mem.drillOn = 0; mem.modeT = 0;
      if (obs.site) {
        mem.mode = 'site';
      } else if (mem.sitePos) {
        mem.target = { x: mem.sitePos.x, y: mem.sitePos.y, est: Math.max(1, mem.siteVal), status: 0, kind: 1 };
        mem.searchR0 = 5; mem.searchR = 5; mem.searchAdv = 0; mem.searchDone = 0;
        mem.mode = 'goto';
      } else {
        mem.mode = 'goto'; mem.target = null;
      }
    }
    if (mem.mode === 'sample') {
      const c = holdCmd();
      return { left: c, right: c, drill: mem.drillOn ? true : false };
    }
  }

  /* ============================ DECIDE ============================ */
  const dBase = dist(mem.px, mem.py, mem.base.x, mem.base.y);
  const tBase = dBase / Math.max(0.5, mem.vAvg) * 1.5 + 6;
  const eBase = dBase * mem.ePerM * 1.5 + 0.045;
  const capLeft = mem.cap - carried;
  const critical = battery < eBase * 1.5;

  let mustReturn = false;
  if (capLeft <= 0) mustReturn = true;
  if (timeLeft < tBase + 12) mustReturn = true;
  if (battery < eBase * 1.3) mustReturn = true;
  if (carried > 0 && battery < 0.26 && timeLeft < 520) mustReturn = true;
  if (carried > 0 && timeLeft < 80) mustReturn = true;

  if (mem.mode === 'search' && mem.target && mem.target.status !== 0) {
    mem.mode = 'goto'; mem.modeT = 0;
  }

  const worth = (obs.site ? num(obs.site.value, 1) : 0) > 0.25 * (mem.target ? mem.target.est : 1);
  const wantSite = !!obs.site && capLeft > 0 && !critical &&
    (!mustReturn || mem.mode === 'site') && (worth || capLeft > 2 || mem.mode === 'site' || mem.mode === 'search');

  if (wantSite) {
    if (mem.mode !== 'site') { mem.mode = 'site'; mem.modeT = 0; }
  } else if (mem.mode === 'site' && !obs.site) {
    if (mem.sitePos && now - mem.siteSeenT < 6) {
      mem.target = { x: mem.sitePos.x, y: mem.sitePos.y, est: Math.max(1, mem.siteVal), status: 0, kind: 1 };
      mem.searchR0 = 5; mem.searchR = 5; mem.searchAdv = 0; mem.searchDone = 0;
    } else {
      mem.target = null;
    }
    mem.mode = 'goto'; mem.modeT = 0;
  } else if (mustReturn) {
    if (mem.mode !== 'return' && mem.mode !== 'dock') { mem.mode = 'return'; mem.target = null; mem.modeT = 0; }
  } else if (mem.mode === 'return' || mem.mode === 'dock') {
    /* stay on course home / at dock until recharge logic releases us */
  } else if (mem.mode === 'search') {
    /* keep searching */
  } else if (!mem.target || mem.target.status !== 0) {
    const t = chooseNext();
    mem.target = t;
    mem.mode = t ? 'goto' : 'return';
    mem.modeT = 0;
    if (t) {
      mem.searchR0 = (t.kind === 1) ? 5 : 12;
      mem.searchR = mem.searchR0;
      mem.searchAdv = 0; mem.searchDone = 0;
    }
  }

  /* ============================ DOCK ============================ */
  if (mem.mode === 'dock') {
    const waited = mem.dockT >= 0 ? now - mem.dockT : 99;
    if (timeLeft < 22) { const c = holdCmd(); return { left: c, right: c, drill: false }; }
    const charged = battery > 0.9;
    if ((charged && waited > 1.2) || waited > 25) {
      mem.mode = 'goto'; mem.target = null; mem.modeT = 0; mem.dockT = -1;
    } else {
      const c = holdCmd();
      return { left: c, right: c, drill: false };
    }
  }

  /* ============================ SITE APPROACH ============================ */
  if (mem.mode === 'site' && obs.site) {
    const s = obs.site;
    const sd = num(s.distance, 0);
    const err = wrap180(num(s.bearing, 0));
    const errA = Math.abs(err);
    if (sd < 1.35 && (speed < 0.22 || mem.modeT > 7)) {
      mem.mode = 'sample'; mem.modeT = 0;
      mem.holdX = mem.px; mem.holdY = mem.py;
      mem.holdI = clamp(0.012 * pitch, -0.35, 0.35);
      mem.drillT = 0; mem.drillOn = 0;
      return { left: 0, right: 0, drill: false };
    }
    if (sd < 1.8 && speed > 0.3) return { left: 0, right: 0, drill: false };
    let fwdCmd = 0, turnCmd = 0;
    if (errA > 45) {
      turnCmd = err > 0 ? 0.55 : -0.55;
    } else {
      turnCmd = clamp(err * 0.022, -0.55, 0.55);
      turnCmd = clamp(turnCmd + turnBias * (errA < 30 ? 0.9 : 0.4), -1, 1);
      let v = clamp(sd * 0.55, 0.22, 1.4);
      if (errA > 18) v *= 0.45;
      if (sd < 2.0) v = Math.min(v, 0.35);
      if (minFwd < 2.5) v = Math.min(v, 0.3);
      if (mem.modeT > 22) v = Math.min(v, 0.35);
      fwdCmd = v / Math.max(1, mem.kv);
      if (fwdCmd > 0 && fwdCmd < mem.dead + 0.05) fwdCmd = mem.dead + 0.05;
      fwdCmd = clamp(fwdCmd, 0, 1);
    }
    if (fwdCmd > 0.28 && speed < 0.12) mem.stuckT += DT; else mem.stuckT = Math.max(0, mem.stuckT - 0.15);
    if (mem.stuckT > 1.6) { mem.stuckT = 0; mem.bumpT = 0.7; }
    return { left: clamp(fwdCmd - turnCmd, -1, 1), right: clamp(fwdCmd + turnCmd, -1, 1), drill: false };
  }

  /* ============================ NAVIGATION ============================ */
  function goalOf() {
    let gx = mem.base.x, gy = mem.base.y, arriveR = 1.4;
    if (mem.mode === 'goto' && mem.target) { gx = mem.target.x; gy = mem.target.y; arriveR = 3.0; }
    else if (mem.mode === 'search' && mem.target) {
      gx = mem.target.x + mem.searchR * Math.cos(mem.searchTheta * D2R);
      gy = mem.target.y + mem.searchR * Math.sin(mem.searchTheta * D2R);
      arriveR = 3.4;
    }
    return { gx: gx, gy: gy, arriveR: arriveR, d: dist(mem.px, mem.py, gx, gy) };
  }

  let G = goalOf();

  if (mem.mode === 'goto' && mem.target && G.d < 3.2) {
    mem.mode = 'search'; mem.modeT = 0;
    mem.searchTheta = Math.atan2(mem.py - mem.target.y, mem.px - mem.target.x) * R2D;
    mem.searchStart = mem.searchTheta;
    mem.searchR = mem.searchR0; mem.searchAdv = 0; mem.searchDone = 0;
    G = goalOf();
  } else if (mem.mode === 'search' && mem.target) {
    if (G.d < 3.6) {
      mem.searchTheta += 24; mem.searchAdv += 24;
      if (mem.searchAdv >= 360) {
        if (mem.searchR < mem.searchR0 + 5) {
          mem.searchR = mem.searchR0 + 9; mem.searchAdv = 0; mem.searchTheta = mem.searchStart;
        } else mem.searchDone = 1;
      }
      G = goalOf();
    }
    if (mem.sciSeen && mem.zeroSciT > 25 && mem.searchAdv > 60) mem.searchDone = 1;
    if (mem.modeT > 95) mem.searchDone = 1;
    if (mem.searchDone) {
      mem.target.status = 3; mem.target = null; mem.mode = 'goto'; mem.modeT = 0;
      G = goalOf();
    }
  }

  if (mem.mode === 'return') {
    const d = dist(mem.px, mem.py, mem.base.x, mem.base.y);
    if ((d < 2.4 && speed < 0.7) || (obs.docked && d < 3.2)) {
      mem.mode = 'dock'; mem.modeT = 0; mem.dockT = now;
      mem.holdX = mem.px; mem.holdY = mem.py; mem.holdI = clamp(0.012 * pitch, -0.35, 0.35);
      return { left: 0, right: 0, drill: false };
    }
  }

  if (mem.mode === 'goto' && !mem.target) {
    return { left: 0, right: 0, drill: false };
  }

  let desired = Math.atan2(G.gy - mem.py, G.gx - mem.px) * R2D;
  const edge = Math.min(mem.px, mem.py, mem.size - mem.px, mem.size - mem.py);
  if (edge < 18 && G.d > 35) {
    const w = ((18 - edge) / 18) * 0.55;
    const inward = Math.atan2(mem.size / 2 - mem.py, mem.size / 2 - mem.px) * R2D;
    desired += wrap180(inward - desired) * w;
  }
  const err = wrap180(desired - (heading + mem.hbias));
  const errA = Math.abs(err);

  let turnCmd = clamp(err * 0.022, -0.55, 0.55);
  turnCmd = clamp(turnCmd + turnBias * (errA < 30 ? 1.0 : 0.5), -1, 1);

  let v = vLim;
  if (errA > 20) v = Math.min(v, 1.2);
  if (errA > 45) v = 0;
  if (G.d < G.arriveR + 8) v = Math.min(v, 0.3 + Math.max(0, G.d - G.arriveR) * 0.5);
  if (G.d <= G.arriveR) v = 0;

  let fwdCmd = v / Math.max(1, mem.kv);
  if (fwdCmd > 0 && fwdCmd < mem.dead + 0.05) fwdCmd = mem.dead + 0.05;
  fwdCmd = clamp(fwdCmd, 0, 1);

  if (fwdCmd > 0.28 && speed < 0.12) mem.stuckT += DT; else mem.stuckT = Math.max(0, mem.stuckT - 0.15);
  if (mem.stuckT > 1.6) { mem.stuckT = 0; mem.bumpT = 0.7; }

  return { left: clamp(fwdCmd - turnCmd, -1, 1), right: clamp(fwdCmd + turnCmd, -1, 1), drill: false };
}

function act(obs, mem) {
  var DT = 0.1, D2R = Math.PI / 180, R2D = 180 / Math.PI;
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap180(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
  function dist(ax, ay, bx, by) { var dx = bx - ax, dy = by - ay; return Math.sqrt(dx * dx + dy * dy); }
  function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }

