        db: dist(h.x, h.y, mem.bx, mem.by), s: 0 });
    }
    mem.hints.sort(function(a, b) { return (b.e / (b.db + 15)) - (a.e / (a.db + 15)); });
    mem.mode = 'plan'; mem.wpX = mem.bx; mem.wpY = mem.by;
    mem.arr = 5; mem.tgt = -1; mem.mT = 0;
    mem.x = num(obs.x, 200); mem.y = num(obs.y, 200);
    mem.lx = mem.x; mem.ly = mem.y;
    mem.spd = 0; mem.hdg = num(obs.heading, 0); mem.fSpd = 0;
    mem.bp = num(obs.battery, 1); mem.eM = 0.0004;
    mem.sTh = 0; mem.sR = 0; mem.sN = 0; mem.sCx = 0; mem.sCy = 0;
    mem.dT = 0; mem.hX = 0; mem.hY = 0; mem.hI = 0;
    mem.bT = 0; mem.bD = 1; mem.stT = 0;
    mem.siteP = null; mem.siteV = 0; mem.sTm = -999;
    mem.sciDec = 0; mem.dkT = -1;
    return { left: 0, right: 0, drill: false };
  }

  var t = num(obs.t, 0), tL = num(obs.timeLeft, 1200);
  var bat = num(obs.battery, 1), sol = num(obs.solar, 0);
  var car = num(obs.carried, 0), pit = num(obs.pitch, 0);
  var hdg = num(obs.heading, mem.hdg), sci = num(obs.science, 0);
  mem.x = num(obs.x, mem.x); mem.y = num(obs.y, mem.y);
  var dx = mem.x - mem.lx, dy = mem.y - mem.ly;
  var dStep = Math.sqrt(dx * dx + dy * dy);
  mem.spd = mem.spd * 0.8 + (dStep / DT) * 0.2;
  var hR = hdg * D2R;
  mem.fSpd = mem.fSpd * 0.7 + ((dx * Math.cos(hR) + dy * Math.sin(hR)) / DT) * 0.3;
  mem.lx = mem.x; mem.ly = mem.y; mem.hdg = hdg; mem.mT += DT;

  var cons = -(bat - mem.bp) + sol * DT; mem.bp = bat;
  if (dStep > 0.005 && cons > 0) {
