    var v = clamp(0.25 * along - 0.65 * vAvg, -0.18, 0.18);
    var omega = 0;
    if (Number.isFinite(anchorYaw)) {
      omega = clamp(wrap(anchorYaw - mem.yaw) * Math.PI / 180 * 0.35, -0.20, 0.20);
    }
    return drive(v, omega, drill, "hold");
  }

  function rayAt(deg) {
    deg = clamp(deg, -80, 80);
    var f = (deg + 80) / 20;
    var lo = Math.floor(f);
    var hi = Math.min(8, lo + 1);
    var frac = f - lo;
    return rays[lo] * (1 - frac) + rays[hi] * frac;
  }

  function chooseRecoverySign() {
    var leftSpace = 0.5 * (rayAt(40) + rayAt(60));
    var rightSpace = 0.5 * (rayAt(-40) + rayAt(-60));
    if (Math.abs(leftSpace - rightSpace) < 0.15) {
      return -num(mem.recoverSign, 1);
    }
    return leftSpace > rightSpace ? 1 : -1;
  }
  function escapeAction() {
    return drive(-0.34, num(mem.recoverSign, 1) * 0.78, false, "drive");
  }

  function watchProgress(key, d) {
    if (mem.progressKey !== key) {
      mem.progressKey = key;
      mem.progressBest = d;
      mem.progressAt = now;
      mem.progressStalls = 0;
      return;
    }
    if (now - num(mem.progressAt, now) < 10) return;
    if (d < num(mem.progressBest, d) - 0.75) {
      mem.progressBest = d;
      mem.progressStalls = 0;
    } else if (d > 4) {
      mem.progressStalls = num(mem.progressStalls, 0) + 1;
    }
    mem.progressBest = Math.min(num(mem.progressBest, d), d);
    mem.progressAt = now;
    if (mem.progressStalls >= 2) {
      mem.recoverSign = chooseRecoverySign();
      mem.recoverUntil = Math.max(num(mem.recoverUntil, -1), now + 0.9);
    }
    if (mem.progressStalls >= 4) {
      mem.failedNavKey = key;
      mem.progressStalls = 0;
      mem.recoverUntil = Math.max(num(mem.recoverUntil, -1), now + 0.8);
    }
  }

  function navigateRelative(rel, d, maxSpeed, stopD, key) {
    rel = wrap(num(rel, 0));
    d = Math.max(0, num(d, 999));
    if (d <= stopD) return holdAt(NaN, NaN, NaN, false);

    watchProgress(key, d);

    if (Math.abs(rel) > 100) {
      return drive(0, rel > 0 ? 0.82 : -0.82, false, "drive");
    }

    var preferred = clamp(rel, -70, 70);
    var chosen = preferred;
    var bestCost = Infinity;
    var look = 2.8 + 0.65 * maxSpeed;

    for (var a = -70; a <= 70; a += 10) {
      var clear = rayAt(a);
      var dev = Math.abs(wrap(rel - a));
      var blocked = Math.max(0, look - clear);
      var cost = 0.022 * dev + 0.62 * blocked * blocked;
      if (clear < 1.0) cost += 4;
      if (mem.steerKey === key && Number.isFinite(mem.steerAngle)) {
        cost += 0.003 * Math.abs(a - mem.steerAngle);
      }
      if (cost < bestCost) {
        bestCost = cost;
        chosen = a;
      }
    }
    mem.steerKey = key;
    mem.steerAngle = chosen;

    var selectedClear = rayAt(chosen);
    var speed = maxSpeed;
    if (now < num(mem.rayBlindUntil, -1)) speed = Math.min(speed, 0.72);

    var travel = d - stopD;
    if (travel <= 0) speed = 0;
    else speed = Math.min(speed, Math.sqrt(1.7 * travel));

    var safe = Math.sqrt(Math.max(0, 1.5 * (selectedClear - 1.2)));
    speed = Math.min(speed, safe);
    if (selectedClear < 4.0) {
      speed = Math.min(speed, Math.max(0.12, 0.30 + 0.26 * (selectedClear - 1.2)));
    }
    if (rayAt(0) < 1.05 && Math.abs(chosen) < 25) speed = 0;
    if (Math.abs(rel) > 80) speed = Math.min(speed, 0.18);
    else if (Math.abs(rel) > 58) speed = Math.min(speed, 0.48);
    if (Math.abs(chosen) > 58) speed = Math.min(speed, 0.42);

    var aRad = chosen * Math.PI / 180;
    var v = speed * Math.max(0, Math.cos(aRad));
    var omega = clamp(1.45 * aRad, -0.88, 0.88);
    if (Math.abs(chosen) < 3) omega = 0;
    return drive(v, omega, false, "drive");
  }

  function navigateToPoint(tx, ty, maxSpeed, stopD, key) {
    tx = mapX(tx);
    ty = mapY(ty);
    var dx = tx - mem.px;
    var dy = ty - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var world = Math.atan2(dy, dx) * 180 / Math.PI;
    return navigateRelative(wrap(world - mem.yaw), d, maxSpeed, stopD, key);
  }

  function getTarget(id) {
    if (!Number.isFinite(Number(id)) || id < 0 || id >= mem.targets.length) return null;
    return mem.targets[Math.floor(id)];
  }
  function addTarget(x, y, val, source) {
    var t = {
      id: mem.targets.length,
      source: source || "real",
      x: mapX(x), y: mapY(y),
      val: Math.max(1, num(val, 5)),
      done: false, bad: false, siteKnown: false,
      searchStarted: false, searchPass: 0, searchIndex: 0,
      points: [],
      startScience: 0, bestScience: 0,
      bestX: mapX(x), bestY: mapY(y)
    };
    mem.targets.push(t);
    return t;
  }
  function markDone(id) {
    var t = getTarget(id);
    if (t) {
      t.done = true;
      t.bad = false;
      t.doneTime = now;
    }
    if (mem.activeId === id) mem.activeId = -1;
    if (mem.pendingSample && mem.pendingSample.id === id) {
      mem.pendingSample = null;
    }
  }

  function beginSearch(t, cx, cy, pass) {
    var keepBest = Math.max(num(t.bestScience, 0), science);
    var keepX = num(t.bestX, cx);
    var keepY = num(t.bestY, cy);
    if (science > num(t.bestScience, 0)) {
      keepX = mem.px;
      keepY = mem.py;
    }

    t.searchStarted = true;
    t.searchPass = pass;
    t.searchIndex = 0;
    t.searchCenterX = mapX(cx);
    t.searchCenterY = mapY(cy);
    t.x = t.searchCenterX;
    t.y = t.searchCenterY;
    t.startScience = science;
    t.bestScience = keepBest;
    t.bestX = keepX;
    t.bestY = keepY;

    var radius;
    if (pass === 0) {
      radius = t.source === "signal" ? 22 :
        (t.source === "scout" ? 16 :
          (t.source === "site" ? 10 : 20));
    } else {
      radius = t.source === "signal" ? 12 : 10;
    }
    var lane = radius * 0.8;
    var rawPoints = [
      [-radius, -lane], [radius, -lane],
      [radius, 0], [-radius, 0],
      [-radius, lane], [radius, lane]
    ];
    t.points = [];
    for (var i = 0; i < rawPoints.length; i++) {
      t.points.push({
        x: mapX(t.searchCenterX + rawPoints[i][0]),
        y: mapY(t.searchCenterY + rawPoints[i][1])
      });
    }
  }

  function remainingSearch(t) {
    if (!t.searchStarted) {
      if (t.siteKnown || t.source === "site") return 35;
      if (t.source === "scout") return 125;
      return 165;
    }
    var pts = Array.isArray(t.points) ? t.points : [];
    var idx = Math.max(0, Math.floor(num(t.searchIndex, 0)));
    if (idx >= pts.length) return 0;
    var total = dist(mem.px, mem.py, pts[idx].x, pts[idx].y);
    for (var i = idx; i + 1 < pts.length; i++) {
      total += dist(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
    }
    return total;
  }

  function targetRoute(t) {
    var dHere = dist(mem.px, mem.py, t.x, t.y);
    var dBase = dist(t.x, t.y, mem.baseX, mem.baseY);
    return dHere + remainingSearch(t) + 1.35 * dBase + 18;
  }

  function targetFeasible(t, atDock) {
    if (!t || t.done || t.bad) return false;
    var route = targetRoute(t);
    var load = 1 + 0.15 * carried;
    var need = 0.09 + mem.energyPerM * route * load * 1.48 +
      0.025 * carried;
    if (atDock) {
      if (need > 1.13) return false;
    } else if (battery < need + 0.035) {
      return false;
    }
    var planSpeed = Math.max(0.45, num(mem.speedEst, 0.85) * 0.70);
    var eta = 28 + route / planSpeed * 1.02;
    if (timeLeft < eta + (carried > 0 ? 10 : 0)) return false;
    return true;
  }

  function targetScore(t) {
    var dHere = dist(mem.px, mem.py, t.x, t.y);
    var dBase = dist(t.x, t.y, mem.baseX, mem.baseY);
    var rem = remainingSearch(t);
    var val = Math.max(1, num(t.val, 5));
    if (t.siteKnown) val *= 1.12;
    if (t.source === "scout") val *= 0.72;
    return val / Math.max(18, 26 + dHere + 0.72 * dBase + 0.30 * rem);
  }

  function selectTarget(atDock) {
    var best = null, bestScore = -1;
    for (var i = 0; i < mem.targets.length; i++) {
      var t = mem.targets[i];
      if (!targetFeasible(t, atDock)) continue;
      var s = targetScore(t);
      if (s > bestScore) {
        bestScore = s;
        best = t;
      }
    }

    var active = getTarget(mem.activeId);
    if (active && targetFeasible(active, atDock)) {
      var activeScore = targetScore(active);
      if (!best || active.searchStarted ||
          activeScore >= bestScore * 0.78) {
        return active;
      }
    }

    mem.activeId = best ? best.id : -1;
    return best;
  }

  function createSignalTarget() {
    if (science < 0.035 || num(mem.signalCount, 0) >= 10) return null;
    for (var i = 0; i < mem.targets.length; i++) {
      var old = mem.targets[i];
      if (old.done || old.bad) continue;
      var d = dist(mem.px, mem.py, old.x, old.y);
      if (old.source === "signal" && d < 30) return null;
      if (old.source !== "signal" && d < 7) return null;
    }

    var value = clamp(8 + 35 * Math.sqrt(science), 8, 70);
    var t = addTarget(mem.px, mem.py, value, "signal");
    beginSearch(t, mem.px, mem.py, 0);
    mem.signalCount = num(mem.signalCount, 0) + 1;
    return t;
  }

  function createScout() {
    if (timeLeft < 90) return null;
    mem.scoutIndex = Math.max(0, num(mem.scoutIndex, 0));
    for (var tries = 0; tries < 24; tries++) {
      var idx = mem.scoutIndex++;
      var ring = Math.floor(idx / 8);
      var dir = idx % 8;
      var radius = 38 + ring * 44;
      var a = dir * Math.PI / 4 + ring * 0.17;
      var x = mapX(mem.baseX + radius * Math.cos(a));
      var y = mapY(mem.baseY + radius * Math.sin(a));
      var duplicate = false;
      for (var j = 0; j < mem.targets.length; j++) {
        if (mem.targets[j].source === "scout" &&
            dist(x, y, mem.targets[j].x, mem.targets[j].y) < 18) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) return addTarget(x, y, 5, "scout");
    }
    return null;
  }

  function registerSite(site) {
    var sd = Math.max(0, num(site.distance, 99));
    var sb = num(site.bearing, 0);
    var world = (mem.yaw + sb) * Math.PI / 180;
    var sx = mapX(mem.px + sd * Math.cos(world));
    var sy = mapY(mem.py + sd * Math.sin(world));

    var best = null, bestD = Infinity;
    for (var i = 0; i < mem.targets.length; i++) {
      var t = mem.targets[i];
      if (t.done) continue;
      var dd = dist(t.x, t.y, sx, sy);
      if (dd <= 27) {
        var adjusted = dd;
        if (t.id === mem.activeId) adjusted -= 5;
        if (t.siteKnown) adjusted -= 1;
        if (adjusted < bestD) {
          bestD = adjusted;
          best = t;
        }
      }
    }

    if (!best) {
      best = addTarget(sx, sy, num(site.value, 5), "site");
    } else {
      best.x = mapX(0.40 * best.x + 0.60 * sx);
      best.y = mapY(0.40 * best.y + 0.60 * sy);
      var sv = num(site.value, 0);
      if (sv > 0) best.val = sv;
    }
    best.siteKnown = true;
    best.bad = false;
    mem.activeId = best.id;
    return best.id;
  }

  function observeTargetScience(t) {
    if (science > num(t.bestScience, 0) +
        Math.max(0.006, num(t.bestScience, 0) * 0.06)) {
      t.bestScience = science;
      t.bestX = mem.px;
      t.bestY = mem.py;
    }
  }

  function finishSearch(t) {
    var moved = dist(
      num(t.bestX, t.searchCenterX),
      num(t.bestY, t.searchCenterY),
      t.searchCenterX, t.searchCenterY
    );
    var improved = num(t.bestScience, 0) >
      num(t.startScience, 0) +
        Math.max(0.015, num(t.startScience, 0) * 0.12);
    var signalStillStrong = t.source === "signal" &&
      num(t.bestScience, 0) > 0.045;

    if (t.searchPass === 0 &&
        ((improved && moved > 3.5) || signalStillStrong)) {
      var cx = num(t.bestX, t.searchCenterX);
      var cy = num(t.bestY, t.searchCenterY);
      beginSearch(t, cx, cy, 1);
      return;
    }

    t.bad = true;
    if (mem.activeId === t.id) mem.activeId = -1;
  }

  function targetAction(t) {
    observeTargetScience(t);

    if (!t.searchStarted) {
      var dCenter = dist(mem.px, mem.py, t.x, t.y);
      if (dCenter <= 5) {
        beginSearch(t, t.x, t.y, 0);
      } else {
        var approachKey = "target" + t.id + "_approach";
        var action = navigateToPoint(t.x, t.y, 1.25, 3.5, approachKey);
        if (mem.failedNavKey === approachKey) {
          mem.failedNavKey = null;
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        return action;
      }
    }

    for (var tries = 0; tries < 8; tries++) {
      if (t.searchIndex >= t.points.length) {
        finishSearch(t);
        return null;
      }
      var p = t.points[t.searchIndex];
      var d = dist(mem.px, mem.py, p.x, p.y);
      if (d <= 2.5) {
        t.searchIndex++;
        continue;
      }

      var key = "target" + t.id + "_search" + t.searchPass + "_" + t.searchIndex;
      var result = navigateToPoint(p.x, p.y, 1.05, 1.5, key);
      if (mem.failedNavKey === key) {
        mem.failedNavKey = null;
        t.searchIndex++;
        t.skippedPoints = num(t.skippedPoints, 0) + 1;
        if (t.skippedPoints >= 4) {
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        return null;
      }
      return result;
    }

    finishSearch(t);
    return null;
  }

  function processPendingSample() {
    var p = mem.pendingSample;
    if (!p) return null;

    if (carried > num(p.startCarried, carried) ||
        carriedValue > num(p.startValue, carriedValue) + 0.01 ||
        delivered > num(p.startDelivered, delivered) + 0.01) {
      markDone(p.id);
      return null;
    }

    var sd = obs.site ? num(obs.site.distance, 99) : null;
    if (!p.started) {
      if (sd !== null && sd > 1.55) {
        mem.pendingSample = null;
        return null;
      }
      if (sd === null && now - num(p.createdAt, now) > 2.5) {
        mem.pendingSample = null;
        return null;
      }

      var hold = holdAt(p.anchorX, p.anchorY, p.anchorYaw, false);
      var slow = Math.abs(vAvg) < 0.12 &&
        Math.abs(wl - wr) < 0.17 &&
        Math.abs(wl) < 0.18 && Math.abs(wr) < 0.18;
      p.stable = slow ? num(p.stable, 0) + 1 : 0;
      if (p.stable >= 2) {
        p.started = true;
        p.startedAt = now;
        p.startProgress = num(obs.drilling, 0);
        p.maxProgress = p.startProgress;
        p.lastProgressAt = now;
        var drillHold = holdAt(p.anchorX, p.anchorY, p.anchorYaw, true);
        return output(drillHold.left, drillHold.right, true, "hold");
      }
      return hold;
    }

    if (sd !== null && sd > 1.52) {
      p.started = false;
      p.stable = 0;
      p.createdAt = now;
      return holdAt(p.anchorX, p.anchorY, p.anchorYaw, false);
    }
    if (sd === null &&
        dist(mem.px, mem.py, p.anchorX, p.anchorY) > 1.4) {
      p.started = false;
      p.stable = 0;
      p.createdAt = now;
      return holdAt(p.anchorX, p.anchorY, p.anchorYaw, false);
    }

    var progress = num(obs.drilling, 0);
    if (progress > num(p.maxProgress, 0) + 0.025) {
      p.maxProgress = progress;
      p.lastProgressAt = now;
    }

    var still = Math.abs(vAvg) < 0.12 &&
      Math.abs(wl - wr) < 0.17 &&
      Math.abs(wl) < 0.18 && Math.abs(wr) < 0.18;
    var resultHold = holdAt(p.anchorX, p.anchorY, p.anchorYaw, still);

    if (num(p.maxProgress, 0) >= 6.0 &&
        now - num(p.startedAt, now) > 8.0) {
      markDone(p.id);
      return resultHold;
    }
    if (now - num(p.startedAt, now) > 30 &&
        now - num(p.lastProgressAt, p.startedAt) > 22 &&
        num(p.maxProgress, 0) < 5.8) {
      mem.pendingSample = null;
      var badTarget = getTarget(p.id);
      if (badTarget) badTarget.bad = true;
      return resultHold;
    }

    return output(resultHold.left, resultHold.right, still, "hold");
  }

  function handleSite() {
    if (!obs.site || carried >= mem.capacity) return null;
    var id = registerSite(obs.site);
    var d = Math.max(0, num(obs.site.distance, 99));

    if (d <= 1.30) {
      if (!mem.pendingSample || mem.pendingSample.id !== id) {
        mem.pendingSample = {
          id: id,
          createdAt: now,
          started: false,
          stable: 0,
          anchorX: mem.px,
          anchorY: mem.py,
          anchorYaw: mem.yaw,
          startCarried: carried,
          startValue: carriedValue,
          startDelivered: delivered,
          startProgress: num(obs.drilling, 0),
          maxProgress: num(obs.drilling, 0),
          lastProgressAt: now
        };
      }
      return processPendingSample();
    }

    return navigateRelative(
      num(obs.site.bearing, 0),
      d,
      0.70,
      0.72,
      "site" + id
    );
  }

  var beaconValid = validField(obs.beacon, "distance") &&
    validField(obs.beacon, "bearing");
  var beaconDistance = beaconValid ?
    Math.max(0, num(obs.beacon.distance, 99)) : 99;
  var geoHome = dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homeDistance = beaconValid && beaconDistance <= 20.5 ?
    beaconDistance : geoHome;

  function goHome() {
    if (isDocked) return output(0, 0, false, "idle");
    if (beaconValid && beaconDistance <= 20.5) {
      return navigateRelative(
        num(obs.beacon.bearing, 0),
        beaconDistance,
        1.10,
        0.90,
        "homeBeacon"
      );
    }
    return navigateToPoint(mem.baseX, mem.baseY, 1.10, 0.90, "homeGPS");
  }

  if (carried > num(mem.lastCarried, carried)) {
    if (mem.pendingSample) markDone(mem.pendingSample.id);
    else if (Number.isFinite(mem.lastSampleId)) markDone(mem.lastSampleId);
  }
  if (carriedValue > num(mem.lastCarriedValue, carriedValue) + 0.01 &&
      mem.pendingSample) {
    markDone(mem.pendingSample.id);
  }
  if (delivered > num(mem.lastDelivered, delivered) + 0.01) {
    mem.returning = false;
    mem.dockSince = null;
  }
  mem.lastCarried = carried;
  mem.lastCarriedValue = carriedValue;
  mem.lastDelivered = delivered;

  if (obs.bumped && !mem.bumpPrev) {
    mem.recoverSign = chooseRecoverySign();
    mem.recoverUntil = now + 1.0;
  }
  mem.bumpPrev = !!obs.bumped;

  if (isDocked && carried <= 0) {
    mem.returning = false;
    mem.dockSince = Number.isFinite(mem.dockSince) ? mem.dockSince : now;
  }

  var loadNow = 1 + 0.16 * carried;
  var returnNeed = 0.09 +
    mem.energyPerM * (1.52 * homeDistance + 12) * loadNow * 1.48 +
    (carried > 0 ? 0.045 : 0);
  var returnSpeed = Math.max(0.40, num(mem.speedEst, 0.85) * 0.68);
  var returnTime = 24 + homeDistance / returnSpeed * 1.32;
  var urgentReturn =
    carried >= mem.capacity ||
    battery < returnNeed + 0.04 ||
    battery < 0.085 ||
    (carried > 0 && timeLeft < returnTime + 12) ||
    (carried === 0 && timeLeft < returnTime + 5);

  if (urgentReturn) mem.returning = true;
  if (isDocked && carried <= 0) mem.returning = false;

  if (mem.pendingSample && mem.pendingSample.started && battery > 0.02) {
    var continuing = processPendingSample();
    if (continuing) return continuing;
  }

  if (mem.returning) {
    mem.pendingSample = null;
    return goHome();
  }

  if (mem.pendingSample) {
    var pendingAction = processPendingSample();
    if (pendingAction) return pendingAction;
  }

  if (now < num(mem.recoverUntil, -1) && !mem.pendingSample) {
    return escapeAction();
  }

  if (obs.site && carried < mem.capacity) {
    var siteAction = handleSite();
    if (siteAction) return siteAction;
  }

  if (isDocked && carried > 0) {
    return output(0, 0, false, "idle");
  }

  if (!mem.returning && carried < mem.capacity) createSignalTarget();

  var target = selectTarget(isDocked);
  if (!target) {
    createScout();
    target = selectTarget(isDocked);
  }

  if (isDocked && target) {
    if (!Number.isFinite(mem.dockSince)) mem.dockSince = now;
    var needAtDock = 0.09 +
      mem.energyPerM * targetRoute(target) *
        (1 + 0.15 * carried) * 1.48 +
      0.025 * carried;
    var dockWait = now - num(mem.dockSince, now);
    var plannedSpeed = Math.max(0.45, num(mem.speedEst, 0.85) * 0.70);
    var eta = 28 + targetRoute(target) / plannedSpeed;
    var maxWait = Math.min(100, Math.max(0, timeLeft - eta - 12));
    if (battery < Math.min(1.04, needAtDock + 0.05) &&
        dockWait < maxWait) {
      return output(0, 0, false, "idle");
    }
  } else if (!isDocked) {
    mem.dockSince = null;
  }

  for (var attempt = 0; attempt < 5; attempt++) {
    if (!target || !targetFeasible(target, isDocked)) {
      target = selectTarget(isDocked);
    }
    if (!target) break;

    var action = targetAction(target);
    if (action) return action;
    target = selectTarget(isDocked);
  }

  if (carried > 0 || !isDocked) {
    mem.returning = true;
    return goHome();
  }
