    mem.baseY = num(mission.base && mission.base.y, mem.sizeY * 0.5);
    mem.capacity = Math.max(1, num(mission.capacity, 5));
    mem.missionSeconds = num(mission.seconds, 1200);
    mem.targets = [];

    var hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (var hi = 0; hi < hints.length; hi++) {
      var h = hints[hi];
      var hx = num(h && h.x, NaN);
      var hy = num(h && h.y, NaN);
