        y: clamp(hy, 3, mem.sizeY - 3),
        val: Math.max(1, hv),
        radius: 21,
        done: false,
        bad: false,
        searchStarted: false,
        refined: false,
        theta: 0,
        step: 0,
        bestScience: 0,
        startScience: 0,
        bestX: hx,
