  }

  mem.baseX = num(mem.baseX, mem.sizeX * 0.5);
  mem.baseY = num(mem.baseY, mem.sizeY * 0.5);
  mem.capacity = Math.max(1, num(mem.capacity, 5));
  mem.missionSeconds = num(mem.missionSeconds, 1200);
  mem.energyPerM = clamp(num(mem.energyPerM, 0.0009), 0.00025, 0.02);

  function mapX(x) {
    return clamp(x, 3, mem.sizeX - 3);
  }
  function mapY(y) {
    return clamp(y, 3, mem.sizeY - 3);
  }

  var now = num(obs.t, Number.isFinite(mem.lastT) ? mem.lastT : 0);
  if (Number.isFinite(mem.lastT) && now < mem.lastT - 0.5) now = mem.lastT;
  var dt = 0.1;
  if (Number.isFinite(mem.lastT)) {
