  dt = clamp(dt, 0.05, 0.25);

  var timeLeft = num(obs.timeLeft, Math.max(0, mem.missionSeconds - now));
  var xObs = num(obs.x, Number.isFinite(mem.px) ? mem.px : mem.baseX);
  var yObs = num(obs.y, Number.isFinite(mem.py) ? mem.py : mem.baseY);
  var rawHeading = wrap(num(obs.heading, Number.isFinite(mem.yaw) ? mem.yaw : 0));
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  var vAvg = 0.5 * (wl + wr);
  var pitch = num(obs.pitch, 0);
  var battery = clamp(num(obs.battery, 1), 0, 1.2);
  var solar = Math.max(0, num(obs.solar, 0));
  var carried = Math.max(0, num(obs.carried, 0));
  var carriedValue = Math.max(0, num(obs.carriedValue, 0));
  var delivered = Math.max(0, num(obs.delivered, 0));
  var science = Math.max(0, num(obs.science, 0));
  var isDocked = !!obs.docked;

  if (!Number.isFinite(mem.px) || !Number.isFinite(mem.py) ||
      !Number.isFinite(mem.yaw)) {
    mem.px = xObs;
    mem.py = yObs;
    mem.yaw = rawHeading;
    mem.lastRawHeading = rawHeading;
    mem.lastGX = xObs;
    mem.lastGY = yObs;
    mem.gpsSame = 0;
    mem.gpsMoveSame = 0;
    mem.gpsFrozen = false;
    mem.calT = now;
    mem.calX = xObs;
    mem.calY = yObs;
    mem.calSigned = 0;
    mem.calTurn = 0;
  } else {
    var gpsDX = xObs - num(mem.lastGX, xObs);
    var gpsDY = yObs - num(mem.lastGY, yObs);
    var gpsStep = Math.sqrt(gpsDX * gpsDX + gpsDY * gpsDY);

    if (gpsStep < 0.025) {
      mem.gpsSame = num(mem.gpsSame, 0) + 1;
      mem.gpsMoveSame = num(mem.gpsMoveSame, 0) + Math.abs(vAvg) * dt;
    } else {
      mem.gpsSame = 0;
      mem.gpsMoveSame = 0;
    }

    if (!mem.gpsFrozen && mem.gpsSame > 28 && mem.gpsMoveSame > 1.8) {
      mem.gpsFrozen = true;
      mem.freezeGX = num(mem.lastGX, xObs);
      mem.freezeGY = num(mem.lastGY, yObs);
