    var odoDeg = clamp((wr - wl) / 0.6 * dt * 57.2957795, -35, 35);
    var predictedYaw = wrap(mem.yaw + odoDeg);
    var rawJump = Math.abs(wrap(rawHeading - num(mem.lastRawHeading, rawHeading)));
