    }

    var midYaw = wrap(mem.yaw - 0.5 * odoDeg) * Math.PI / 180;
    var useV = Math.abs(vAvg) < 0.035 ? 0 : vAvg;
    var predX = mem.px + useV * dt * Math.cos(midYaw);
    var predY = mem.py + useV * dt * Math.sin(midYaw);

