    mem.steerKey = key;
    mem.steerAngle = chosen;

    if (rayBlind) maxSpeed = Math.min(maxSpeed, 0.82);
    var selectedClear = rayAt(chosen);
    var travel = Math.max(0, d - stopD);
    var speed = Math.min(maxSpeed, Math.sqrt(1.45 * travel));
    var safeSpeed = Math.sqrt(1.25 * Math.max(0, selectedClear - 1.0));
    speed = Math.min(speed, safeSpeed);

