      id: mem.targets.length,
      source: source || "hint",
      x: mapX(x),
      y: mapY(y),
      val: Math.max(1, num(val, 5)),
      radius: Math.max(8, num(radius, 20)),
      done: false,
      bad: false,
      searchStarted: false,
      refined: false,
      theta: 0,
      step: 0,
      bestScience: 0,
      startScience: 0,
      bestX: mapX(x),
      bestY: mapY(y)
    };
    mem.targets.push(t);
    return t;
  }

  function markDone(id) {
    var t = getTarget(id);
    if (t) {
      t.done = true;
      t.bad = false;
      t.doneTime = now;
    }
    if (mem.activeId === id) mem.activeId = -1;
  }

  function startSearch(t) {
    t.searchStarted = true;
    t.refined = false;
    t.cx = mapX(mem.px);
    t.cy = mapY(mem.py);
    t.x = t.cx;
    t.y = t.cy;
    t.theta = 0.6;
    t.step = 0;
    t.startScience = science;
    t.bestScience = science;
    t.bestX = mem.px;
    t.bestY = mem.py;
  }

  function remainingSearch(t) {
    var radius = Math.max(8, num(t.radius, 20));
    var b = 1.7;
    if (!t.searchStarted) return radius * radius / (2 * b) + 5;
    var r = Math.min(radius, b * num(t.theta, 0.6));
    return Math.max(0, (radius * radius - r * r) / (2 * b)) + 5;
  }

  function targetRoute(t) {
    var dHere = dist(mem.px, mem.py, t.x, t.y);
    var dBase = dist(t.x, t.y, mem.baseX, mem.baseY);
    return dHere + remainingSearch(t) + 1.18 * dBase + 18;
  }

  function targetNeed(t) {
    var load = 1 + 0.17 * carried;
    return 0.08 + mem.energyPerM * targetRoute(t) * load * 1.50 +
      0.025 * carried;
  }

  function targetFeasible(t, atDock) {
    if (!t || t.done || t.bad) return false;
    var route = targetRoute(t);
    var need = 0.08 + mem.energyPerM * route *
      (1 + 0.17 * carried) * 1.50 + 0.025 * carried;
    if (atDock) {
      if (need > 1.13) return false;
    } else if (battery < need + 0.04) {
      return false;
    }
    var planSpeed = clamp(num(mem.speedEst, 1.0) * 0.74, 0.48, 1.5);
