    var improved = num(t.bestScience, 0) >
      num(t.startScience, 0) +
        Math.max(0.02, num(t.startScience, 0) * 0.22);

    if (!t.refined && improved && moved > 4.5) {
      t.refined = true;
      t.cx = mapX(t.bestX);
      t.cy = mapY(t.bestY);
      t.x = t.cx;
      t.y = t.cy;
      t.radius = Math.min(10, num(t.radius, 20));
