    mem.speedEst = clamp(
      0.98 * num(mem.speedEst, 0.55) + 0.02 * Math.abs(vAvg),
      0.30, 2.5
    );
  }

  function learnMotor(side, actual) {
    var gainKey = side === "L" ? "gainL" : "gainR";
    var gain = num(mem[gainKey], 2.8);
    var lastU = side === "L" ? num(mem.lastOutL, 0) : num(mem.lastOutR, 0);

    if (Math.abs(lastU) > 0.16 && actual * lastU > 0 &&
        Math.abs(actual) > 0.10) {
      var ratio = Math.abs(actual / lastU);
      if (ratio > 0.45 && ratio < 5.0) {
        gain = 0.99 * gain + 0.01 * ratio;
      }
    }
    mem[gainKey] = clamp(gain, 0.6, 5.0);
  }
  learnMotor("L", wl);
  learnMotor("R", wr);

  if (isDocked) {
    mem.energyAcc = 0;
    mem.distanceAcc = 0;
  } else if (Number.isFinite(mem.lastBattery)) {
    var grossUse = num(mem.lastBattery, battery) - battery +
      0.5 * (num(mem.lastSolar, solar) + solar) * dt;
    var wheelDistance = 0.5 * (Math.abs(wl) + Math.abs(wr)) * dt;
    if (wheelDistance > 0.01) {
      mem.energyAcc = num(mem.energyAcc, 0) + Math.max(0, grossUse);
      mem.distanceAcc = num(mem.distanceAcc, 0) + wheelDistance;
    }
    if (mem.distanceAcc >= 10) {
      var measured = mem.energyAcc /
        Math.max(1, mem.distanceAcc) / (1 + 0.14 * carried);
      if (measured > 0.00035 && Number.isFinite(measured)) {
        measured = clamp(measured, 0.00025, 0.02);
        if (measured > mem.energyPerM) {
          mem.energyPerM = 0.72 * mem.energyPerM + 0.28 * measured;
        } else {
          mem.energyPerM = 0.96 * mem.energyPerM + 0.04 * measured;
        }
      }
      mem.energyAcc = 0;
      mem.distanceAcc = 0;
    }
  }
  mem.lastBattery = battery;
  mem.lastSolar = solar;

  var rays = [];
  var rayMin = 15, rayMax = 0;
  var rayParts = [];
  for (var ri = 0; ri < 9; ri++) {
    var rv = obs.rays && obs.rays.length > ri ? num(obs.rays[ri], 15) : 15;
    rv = clamp(rv, 0, 15);
    rays.push(rv);
    rayMin = Math.min(rayMin, rv);
    rayMax = Math.max(rayMax, rv);
    rayParts.push(String(Math.round(rv * 4)));
  }

  var allClear = rayMin >= 14.7;
  var raySig = rayParts.join(",");
  if (raySig === mem.raySig) {
    mem.raySame = num(mem.raySame, 0) + 1;
    mem.rayMove = num(mem.rayMove, 0) +
      0.5 * (Math.abs(wl) + Math.abs(wr)) * dt;
  } else {
    mem.raySame = 0;
    mem.rayMove = 0;
  }
  if (!allClear && rayMax - rayMin < 0.07 &&
      mem.raySame > 50 && mem.rayMove > 4) {
    mem.rayBlindUntil = Math.max(num(mem.rayBlindUntil, -1), now + 20);
  }
  mem.raySig = raySig;
  var rayBlind = now < num(mem.rayBlindUntil, -1);

  function rayAt(deg) {
    if (rayBlind) return 15;
    deg = clamp(deg, -80, 80);
    var f = (deg + 80) / 20;
    var lo = Math.floor(f);
    var hi = Math.min(8, lo + 1);
    var frac = f - lo;
    return rays[lo] * (1 - frac) + rays[hi] * frac;
  }

  function output(left, right, drill, mode) {
    left = clamp(num(left, 0), -1, 1);
    right = clamp(num(right, 0), -1, 1);
    mem.lastOutL = left;
    mem.lastOutR = right;
    mem.lastMode = mode || "hold";
    return { left: left, right: right, drill: !!drill };
  }

  var pitchFF = clamp(pitch * 0.006, -0.10, 0.10);

  function wheelCommand(desired, actual, gain) {
    desired = clamp(desired, -1.2, 1.2);
    var u;
    if (Math.abs(desired) < 0.045) {
      u = -0.35 * actual + pitchFF;
    } else {
      u = desired / Math.max(0.6, gain) +
        0.12 * (desired - actual) + pitchFF;
      if (Math.abs(desired) > 0.15 && desired * u > 0 &&
          Math.abs(u) < 0.075) {
        u = desired < 0 ? -0.075 : 0.075;
      }
    }
    return clamp(u, -0.42, 0.42);
  }

  function drive(v, omega, drill, mode) {
    v = clamp(v, -0.80, 0.80);
    omega = clamp(omega, -1.35, 1.35);
    var leftSpeed = clamp(v - 0.3 * omega, -1.2, 1.2);
    var rightSpeed = clamp(v + 0.3 * omega, -1.2, 1.2);
    return output(
      wheelCommand(leftSpeed, wl, num(mem.gainL, 2.8)),
      wheelCommand(rightSpeed, wr, num(mem.gainR, 2.8)),
      drill,
      mode || "drive"
    );
  }

  function idle() {
    return output(0, 0, false, "idle");
  }

  function chooseRecoverySign() {
    var leftSpace = 0.5 * (rayAt(40) + rayAt(60));
    var rightSpace = 0.5 * (rayAt(-40) + rayAt(-60));
    if (Math.abs(leftSpace - rightSpace) < 0.15) {
      return -num(mem.recoverSign, 1);
    }
    return leftSpace > rightSpace ? 1 : -1;
  }

  function escapeAction() {
    return drive(-0.12, num(mem.recoverSign, 1) * 0.90, false, "recover");
  }

  function watchProgress(key, d, stopD) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navProgressAt = now;
      mem.navStalls = 0;
      return;
    }

    if (d < num(mem.navBest, d) - 0.75) {
      mem.navBest = d;
      mem.navProgressAt = now;
      mem.navStalls = 0;
      return;
    }
    mem.navBest = Math.min(num(mem.navBest, d), d);

    if (now - num(mem.navProgressAt, now) > 18 && d > stopD + 3) {
      mem.navProgressAt = now;
      mem.navStalls = num(mem.navStalls, 0) + 1;
      mem.recoverSign = chooseRecoverySign();
      mem.recoverUntil = Math.max(num(mem.recoverUntil, -1), now + 0.9);

      if (mem.navStalls >= 3 &&
          key.indexOf("home") !== 0 &&
          key.indexOf("site") !== 0) {
        mem.failedNavKey = key;
      }
    }
  }

  function navigateRelative(rel, d, maxSpeed, stopD, key) {
    rel = wrap(num(rel, 0));
    d = Math.max(0, num(d, 999));
    maxSpeed = clamp(maxSpeed, 0.10, 0.72);
    stopD = Math.max(0, stopD);

    if (d <= stopD) return drive(0, 0, false, "hold");

    watchProgress(key, d, stopD);

    if (now < num(mem.recoverUntil, -1)) return escapeAction();
    if (mem.failedNavKey === key) return drive(0, 0, false, "hold");

    var chosen = clamp(rel, -80, 80);
    if (Math.abs(rel) > 105) chosen = rel > 0 ? 80 : -80;

    var bestCost = Infinity;
    var look = 2.2 + 1.2 * maxSpeed;

    for (var a = -80; a <= 80; a += 10) {
      var clear = rayAt(a);
      var dev = Math.abs(wrap(rel - a));
      var blocked = Math.max(0, look - clear);
      var cost = 0.030 * dev + 0.72 * blocked * blocked;
      if (clear < 1.0) cost += 5;
      if (mem.steerKey === key && Number.isFinite(mem.steerAngle)) {
        cost += 0.002 * Math.abs(a - mem.steerAngle);
      }
      if (cost < bestCost) {
        bestCost = cost;
        chosen = a;
      }
    }
    mem.steerKey = key;
    mem.steerAngle = chosen;

    var selectedClear = rayAt(chosen);
    var travel = Math.max(0, d - stopD);
    var speed = Math.min(maxSpeed, Math.sqrt(1.10 * travel));
    var safeSpeed = Math.sqrt(1.15 * Math.max(0, selectedClear - 1.25));
    speed = Math.min(speed, safeSpeed);

    if (selectedClear < 3.5) {
      speed = Math.min(speed, Math.max(0, 0.18 + 0.20 * selectedClear));
    }
    if (selectedClear < 1.18) speed = 0;
    if (rayBlind) speed = Math.min(speed, 0.48);
    if (Math.abs(chosen) > 62) speed = Math.min(speed, 0.35);
    else if (Math.abs(chosen) > 45) speed = Math.min(speed, 0.52);

    var aRad = chosen * Math.PI / 180;
    var v = speed * Math.max(0, Math.cos(aRad));
    var omega = clamp(1.55 * aRad, -0.92, 0.92);
    if (Math.abs(chosen) < 3) omega = 0;

    return drive(v, omega, false, "nav");
  }

  function navigateToPoint(tx, ty, maxSpeed, stopD, key) {
    tx = mapX(tx);
    ty = mapY(ty);
    var dx = tx - mem.px;
    var dy = ty - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var world = Math.atan2(dy, dx) * 180 / Math.PI;
    return navigateRelative(wrap(world - mem.yaw), d, maxSpeed, stopD, key);
  }

  function getTarget(id) {
    if (!Number.isFinite(Number(id)) || id < 0 || id >= mem.targets.length) return null;
    return mem.targets[Math.floor(id)];
  }

  function addTarget(x, y, val, source, radius) {
    var t = {
      id: mem.targets.length,
      source: source || "hint",
      x: mapX(x),
      y: mapY(y),
      val: Math.max(1, num(val, 5)),
      radius: Math.max(8, num(radius, 18)),
      done: false,
      bad: false,
      searchStarted: false,
      searchPath: [],
      searchIndex: 0,
      refines: 0,
      bestScience: 0,
      startScience: 0,
      bestX: mapX(x),
      bestY: mapY(y)
    };
    mem.targets.push(t);
    return t;
  }

  function markDone(id) {
    var t = getTarget(id);
    if (t) {
      t.done = true;
      t.bad = false;
      t.doneTime = now;
    }
    if (mem.activeId === id) mem.activeId = -1;
  }

  function buildSearchPath(cx, cy, radius, id) {
    var points = [];
    var phase = (id * 2.399963229728653) % (2 * Math.PI);
    var crossR = Math.min(4.5, radius * 0.34);

    for (var k = 0; k < 4; k++) {
      var ca = phase + k * Math.PI * 0.5;
      points.push({
        x: mapX(cx + crossR * Math.cos(ca)),
        y: mapY(cy + crossR * Math.sin(ca))
      });
    }

    var b = 1.43;
    var theta = 0.55;
    var maxTheta = radius / b;
    var guard = 0;

    while (theta <= maxTheta && guard < 100) {
      var r = b * theta;
      if (r >= 5.5) {
        var angle = theta + phase;
        var px = mapX(cx + r * Math.cos(angle));
        var py = mapY(cy + r * Math.sin(angle));
        var last = points.length ? points[points.length - 1] : null;
        if (!last || dist(px, py, last.x, last.y) > 3.0) {
          points.push({ x: px, y: py });
        }
      }
      theta += 6.0 / Math.sqrt(r * r + b * b);
      guard++;
    }

    return points;
  }

  function beginSearch(t, cx, cy, radius) {
    t.searchStarted = true;
    t.x = mapX(cx);
    t.y = mapY(cy);
    t.centerX = t.x;
    t.centerY = t.y;
    t.radius = Math.max(8, num(radius, 18));
    t.searchPath = buildSearchPath(t.centerX, t.centerY, t.radius, t.id);
    t.searchIndex = 0;
    t.startScience = science;
    t.bestScience = science;
    t.bestX = mem.px;
    t.bestY = mem.py;
  }

  function remainingSearch(t) {
    if (!t.searchStarted) {
      var r = Math.max(8, num(t.radius, t.source === "hint" ? 20 : 16));
      return Math.PI * r * r / 9.0 + 18;
    }

    var pts = Array.isArray(t.searchPath) ? t.searchPath : [];
    var idx = Math.max(0, Math.floor(num(t.searchIndex, 0)));
    if (idx >= pts.length) return 0;

    var total = dist(mem.px, mem.py, pts[idx].x, pts[idx].y);
    for (var i = idx; i + 1 < pts.length; i++) {
      total += dist(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
    }
    return total;
  }

  function targetRoute(t) {
    var dHere = dist(mem.px, mem.py, t.x, t.y);
    var dBase = dist(t.x, t.y, mem.baseX, mem.baseY);
    return dHere + remainingSearch(t) + 1.22 * dBase + 18;
  }

  function targetNeed(t) {
    var load = 1 + 0.16 * carried;
    return 0.14 + mem.energyPerM * targetRoute(t) * load * 1.35 +
      0.035 * (carried + 1);
  }

  function targetFeasible(t, atDock) {
    if (!t || t.done || t.bad) return false;

    var route = targetRoute(t);
    var need = 0.14 + mem.energyPerM * route *
      (1 + 0.16 * carried) * 1.35 + 0.035 * (carried + 1);

    if (atDock) {
      if (need > 1.12) return false;
    } else if (battery < need + 0.045) {
      return false;
    }

    var planSpeed = clamp(num(mem.speedEst, 0.55) * 0.78, 0.40, 0.90);
    var eta = route / planSpeed + 28 + 8 * (carried + 1);
    return timeLeft > eta;
  }

  function targetScore(t) {
    var dHere = dist(mem.px, mem.py, t.x, t.y);
    var dBase = dist(t.x, t.y, mem.baseX, mem.baseY);
    var rem = remainingSearch(t);
    var val = Math.max(1, num(t.val, 5));
    if (t.source === "scout") val *= 0.78;
    if (t.bestScience > 0) {
      val *= 1 + Math.min(0.40, t.bestScience * 0.12);
    }
    return val / Math.max(25, 30 + dHere + 0.75 * rem + 0.90 * dBase);
  }

  function selectTarget(atDock) {
    var best = null;
    var bestScore = -1;

    for (var i = 0; i < mem.targets.length; i++) {
      var t = mem.targets[i];
      if (!targetFeasible(t, atDock)) continue;
      var s = targetScore(t);
      if (s > bestScore) {
        bestScore = s;
        best = t;
      }
    }

    var active = getTarget(mem.activeId);
    if (active && targetFeasible(active, atDock)) {
      if (active.searchStarted) return active;
      var activeScore = targetScore(active);
      if (!best || activeScore >= bestScore * 0.78) return active;
    }

    mem.activeId = best ? best.id : -1;
    return best;
  }

  function createSignalTarget() {
    if (science < 0.035 || num(mem.signalCount, 0) >= 12) return null;

    for (var i = 0; i < mem.targets.length; i++) {
      var old = mem.targets[i];
      if (old.source === "signal" &&
          dist(mem.px, mem.py, old.x, old.y) < 27) return null;
      if (!old.done && old.searchStarted &&
          dist(mem.px, mem.py, num(old.centerX, old.x), num(old.centerY, old.y)) < 16) {
        return null;
      }
    }

    var value = clamp(8 + 28 * Math.sqrt(science), 8, 65);
    var radius = science > 0.25 ? 13 : (science > 0.10 ? 16 : 18);
    var t = addTarget(mem.px, mem.py, value, "signal", radius);
    beginSearch(t, mem.px, mem.py, radius);
    mem.signalCount = num(mem.signalCount, 0) + 1;
    return t;
  }

  function createScout() {
    if (timeLeft < 65 || num(mem.scoutIndex, 0) >= 120) return null;

    for (var tries = 0; tries < 32; tries++) {
      var idx = mem.scoutIndex++;
      var ring = Math.floor(idx / 8);
      var dir = idx % 8;
      var radius = 42 + ring * 44;
      var angle = dir * Math.PI / 4 + ring * 0.17;
      var sx = mapX(mem.baseX + radius * Math.cos(angle));
      var sy = mapY(mem.baseY + radius * Math.sin(angle));
      var duplicate = false;

      for (var j = 0; j < mem.targets.length; j++) {
        var old = mem.targets[j];
        if (old.source === "scout" && dist(sx, sy, old.x, old.y) < 22) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) return addTarget(sx, sy, 9, "scout", 17);
    }
    return null;
  }

  function observeTargetScience(t) {
    if (science > num(t.bestScience, 0) +
        Math.max(0.006, num(t.bestScience, 0) * 0.05)) {
      t.bestScience = science;
      t.bestX = mem.px;
      t.bestY = mem.py;
    }
  }

  function finishSearch(t) {
    var moved = dist(num(t.bestX, t.centerX), num(t.bestY, t.centerY),
      t.centerX, t.centerY);
    var improved = num(t.bestScience, 0) >
      num(t.startScience, 0) + Math.max(0.009, num(t.startScience, 0) * 0.08);

    if (num(t.refines, 0) < 1 && improved && moved > 3.5 &&
        num(t.bestScience, 0) > 0.025) {
      t.refines = num(t.refines, 0) + 1;
      var newRadius = Math.max(8, Math.min(11, num(t.radius, 18) * 0.55));
      beginSearch(t, t.bestX, t.bestY, newRadius);
      return false;
    }

    markDone(t.id);
    return true;
  }

  function targetAction(t) {
    observeTargetScience(t);

    if (!t.searchStarted) {
      var dCenter = dist(mem.px, mem.py, t.x, t.y);
      if (dCenter > 4.0) {
        var approachKey = "approach_" + t.id;
        if (mem.failedNavKey === approachKey) {
          mem.failedNavKey = null;
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        var approach = navigateToPoint(t.x, t.y, 0.66, 3.6, approachKey);
        if (mem.failedNavKey === approachKey) {
          mem.failedNavKey = null;
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        return approach;
      }

      if (t.source === "scout" && science < 0.018) {
        markDone(t.id);
        return null;
      }

      var radius = t.source === "hint" ? 20 :
        (t.source === "signal" ? Math.max(10, num(t.radius, 16)) : 17);
      if (t.source === "hint" && science < 0.012) radius = 13;
      beginSearch(t, mem.px, mem.py, radius);
    }

    for (var tries = 0; tries < 8; tries++) {
      var pts = Array.isArray(t.searchPath) ? t.searchPath : [];
      if (t.searchIndex >= pts.length) {
        finishSearch(t);
        return null;
      }

      var p = pts[t.searchIndex];
      var pd = dist(mem.px, mem.py, p.x, p.y);
      if (pd <= 1.9) {
        t.searchIndex++;
        continue;
      }

      var key = "search_" + t.id + "_" + t.searchIndex;
      if (mem.failedNavKey === key) {
        mem.failedNavKey = null;
        t.searchIndex++;
        t.skipped = num(t.skipped, 0) + 1;
        if (t.skipped >= 6) {
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        continue;
      }

      var action = navigateToPoint(p.x, p.y, 0.60, 1.55, key);
      if (mem.failedNavKey === key) {
        mem.failedNavKey = null;
        t.searchIndex++;
        t.skipped = num(t.skipped, 0) + 1;
        if (t.skipped >= 6) {
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        return null;
      }
      return action;
    }

    finishSearch(t);
    return null;
  }

  function holdSample(p, drill) {
    var dx = p.anchorX - mem.px;
    var dy = p.anchorY - mem.py;
    var yr = mem.yaw * Math.PI / 180;
    var along = dx * Math.cos(yr) + dy * Math.sin(yr);
    var v = clamp(0.55 * along - 0.65 * vAvg, -0.16, 0.16);

    var yawErr = wrap(num(p.anchorYaw, mem.yaw) - mem.yaw) * Math.PI / 180;
    var measuredOmega = (wr - wl) / 0.6;
    var omega = clamp(1.15 * yawErr - 0.38 * measuredOmega, -0.25, 0.25);

    return drive(v, omega, drill, "hold");
  }

  function processSample() {
    var p = mem.sample;
    if (!p) return null;

    var sd = obs.site && validField(obs.site, "distance")
      ? Math.max(0, num(obs.site.distance, 99))
      : null;

    if (sd !== null) p.lastSeen = now;

    if (sd !== null && sd > 1.55) {
      p.stable = 0;
      if (obs.site) {
        return navigateRelative(
          num(obs.site.bearing, 0),
          sd,
          0.38,
          1.10,
          "site"
        );
      }
      return holdSample(p, false);
    }

    if (sd === null && now - num(p.lastSeen, now) > 6 &&
        num(obs.drilling, 0) < 0.1) {
      mem.sample = null;
      return null;
    }

    var inRange = sd !== null ? sd <= 1.50 :
      (now - num(p.lastSeen, now) <= 6 &&
       dist(mem.px, mem.py, p.anchorX, p.anchorY) <= 1.55);

    var progress = Math.max(0, num(obs.drilling, 0));
    p.maxProgress = Math.max(num(p.maxProgress, 0), progress);

    var still = Math.abs(vAvg) < 0.12 &&
      Math.abs(wl) < 0.18 &&
      Math.abs(wr) < 0.18 &&
      Math.abs(wr - wl) < 0.17;

    if (inRange && still) p.stable = num(p.stable, 0) + 1;
    else p.stable = 0;

    var drill = inRange && still && p.stable >= 3;
    if (drill) p.started = true;

    return holdSample(p, drill);
  }

  function handleSite() {
    if (!obs.site || carried >= mem.capacity) return null;

    var sd = Math.max(0, num(obs.site.distance, 99));
    var siteValue = num(obs.site.value, 0);
    var active = getTarget(mem.activeId);
    if (active && siteValue > 0) active.val = Math.max(active.val, siteValue);

    if (sd <= 1.42) {
      if (!mem.sample) {
        mem.sample = {
          anchorX: mem.px,
          anchorY: mem.py,
          anchorYaw: mem.yaw,
          targetId: mem.activeId,
          stable: 0,
          started: false,
          maxProgress: num(obs.drilling, 0),
          lastSeen: now
        };
      }
      return processSample();
    }

    return navigateRelative(
      num(obs.site.bearing, 0),
      sd,
      0.48,
      1.10,
      "site"
    );
  }

  var beaconValid = validField(obs.beacon, "distance") &&
    validField(obs.beacon, "bearing");
  var beaconDistance = beaconValid ?
    Math.max(0, num(obs.beacon.distance, 99)) : 99;
  var geoHome = dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homeDistance = beaconValid && beaconDistance <= 22.5
    ? beaconDistance
    : geoHome;

  function goHome() {
    if (isDocked) return idle();

    if (beaconValid && beaconDistance <= 22.5) {
      if (beaconDistance <= 2.2) return drive(0, 0, false, "hold");
      return navigateRelative(
        num(obs.beacon.bearing, 0),
        beaconDistance,
        0.68,
        2.0,
        "homeBeacon"
      );
    }

    if (geoHome <= 2.2) return drive(0, 0, false, "hold");
    return navigateToPoint(mem.baseX, mem.baseY, 0.68, 2.0, "homeGPS");
  }

