      if (clear < 1.25) cost += 60;
      var edge = edgeDistance(a);
      if (edge < 3.5) cost += 1.4 * (3.5 - edge) * (3.5 - edge);
      if (mem.steerKey === key && Number.isFinite(mem.steerAngle)) {
        cost += 0.008 * Math.abs(a - mem.steerAngle);
      }
      return cost;
    }

    bestCost = costAt(rel);
    for (var a = -80; a <= 80; a += 10) {
      var c = costAt(a);
      if (c < bestCost) {
        bestCost = c;
        bestAngle = a;
      }
    }

    mem.steerKey = key;
    mem.steerAngle = bestAngle;
    return bestAngle;
  }

  function navigateRelative(rel, d, maxSpeed, stopD, key) {
    rel = wrap(num(rel, 0));
    d = Math.max(0, num(d, 999));
    maxSpeed = clamp(maxSpeed, 0.10, 0.90);
    stopD = Math.max(0, stopD);

    if (d <= stopD) return drive(0, 0, false, "hold");

    watchProgress(key, d, stopD);
    if (now < num(mem.recoverUntil, -1)) return escapeAction();

    if (mem.failedKey === key &&
        key.indexOf("site") !== 0 &&
        key.indexOf("home") !== 0) {
      return drive(0, 0, false, "hold");
    }

    var chosen = chooseSteer(rel, maxSpeed, key);
    var errDeg = wrap(chosen);
    var errRad = errDeg * Math.PI / 180;

    if (Math.abs(errDeg) > 28) {
      var turnRate = clamp(1.75 * Math.abs(errRad), 0.42, 0.78);
      return drive(0, (errDeg > 0 ? 1 : -1) * turnRate, false, "turn");
    }

    var travel = Math.max(0, d - stopD);
    var speed = Math.min(maxSpeed, Math.sqrt(0.62 * travel));
    if (Math.abs(errDeg) > 15) speed *= 0.55;
    else if (Math.abs(errDeg) > 8) speed *= 0.78;

    var clear = Math.abs(chosen) <= 80 ? rayAt(chosen) : rayAt(0);
    if (clear < 1.35) {
      speed = 0;
    } else if (clear < 4.2) {
      speed = Math.min(speed, Math.max(0.10, 0.28 * (clear - 1.15)));
    }
    if (rayBlind) speed = Math.min(speed, 0.58);

    var omega = clamp(1.55 * errRad, -0.48, 0.48);
    if (Math.abs(errDeg) < 2.5) omega = 0;
    return drive(speed, omega, false, "nav");
  }

  function navigateToPoint(tx, ty, maxSpeed, stopD, key) {
    tx = mapX(tx);
    ty = mapY(ty);
    var dx = tx - mem.px;
    var dy = ty - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var world = Math.atan2(dy, dx) * 180 / Math.PI;
    return navigateRelative(wrap(world - mem.yaw), d, maxSpeed, stopD, key);
  }

  var bumpNow = !!obs.bumped;
  if (bumpNow && !mem.bumpPrev) {
    mem.recoverSign = chooseRecoverySign();
    mem.recoverUntil = now + 1.1;
  }
  mem.bumpPrev = bumpNow;

  function getTarget(id) {
    if (!Number.isFinite(Number(id)) || id < 0 || id >= mem.targets.length) return null;
    return mem.targets[Math.floor(id)];
  }

  function addTarget(x, y, val, source, radius) {
    var t = {
      id: mem.targets.length,
      source: source || "hint",
      x: mapX(x),
      y: mapY(y),
      val: Math.max(1, num(val, 5)),
      radius: Math.max(8, num(radius, 18)),
      done: false,
      bad: false,
      searchStarted: false,
      points: [],
      searchIndex: 0,
      refines: 0,
      bestScience: 0,
      startScience: 0,
      bestX: mapX(x),
      bestY: mapY(y)
    };
    mem.targets.push(t);
    return t;
  }

  function markDone(id) {
    var t = getTarget(id);
    if (t) {
      t.done = true;
      t.bad = false;
      t.doneTime = now;
    }
    if (mem.activeId === id) mem.activeId = -1;
  }

  function buildSearchPath(cx, cy, radius, id) {
    var pts = [];
    var b = 1.4;
    var theta = 0.65;
    var maxTheta = radius / b;
    var phase = (id * 2.399963229728653) % (2 * Math.PI);
    var guard = 0;

    while (theta <= maxTheta && guard < 150) {
      var r = b * theta;
      var a = theta + phase;
      var px = mapX(cx + r * Math.cos(a));
      var py = mapY(cy + r * Math.sin(a));
      var last = pts.length ? pts[pts.length - 1] : null;

      if (!last || dist(px, py, last.x, last.y) > 1.8) {
        pts.push({ x: px, y: py });
      }

      var step = 5.7 / Math.sqrt(r * r + b * b);
      theta += clamp(step, 0.20, 3.2);
      guard++;
