    t.x = mapX(cx);
    t.y = mapY(cy);
    t.cx = t.x;
    t.cy = t.y;
    t.radius = Math.max(8, num(radius, 18));
    t.points = buildSearchPath(t.cx, t.cy, t.radius, t.id);
    t.searchIndex = 0;
    t.startScience = science;
    t.bestScience = science;
    t.bestX = mem.px;
    t.bestY = mem.py;
  }

  function observeScience(t) {
    var old = num(t.bestScience, 0);
    if (science > old + Math.max(0.005, old * 0.06)) {
      t.bestScience = science;
      t.bestX = mem.px;
      t.bestY = mem.py;
    }
  }

  function remainingSearch(t) {
    if (!t.searchStarted) {
      var r = Math.max(8, num(t.radius, t.source === "scout" ? 12 : 19));
      return r * r / (2 * 1.4) + 10;
    }

    var pts = Array.isArray(t.points) ? t.points : [];
    var idx = Math.max(0, Math.floor(num(t.searchIndex, 0)));
    if (idx >= pts.length) return 0;

    var total = dist(mem.px, mem.py, pts[idx].x, pts[idx].y);
    for (var i = idx; i + 1 < pts.length; i++) {
