    var homeFromCenter = dist(t.x, t.y, mem.baseX, mem.baseY);
    var searchRoute;

    if (t.searchStarted) {
      searchRoute = rem;
    } else {
      searchRoute = dist(mem.px, mem.py, t.x, t.y) + rem;
    }

    var homeRoute = homeFromCenter + 0.40 * radius;
    return searchRoute + 1.12 * homeRoute + 16;
  }

  function targetNeed(t) {
    return 0.095 +
      mem.energyPerM * targetRoute(t) * (1 + 0.16 * carried) * 1.32 +
      0.025 * (carried + 1);
  }

  function targetFeasible(t, atDock) {
    if (!t || t.done || t.bad) return false;

    var route = targetRoute(t);
    var need = 0.095 +
      mem.energyPerM * route * (1 + 0.16 * carried) * 1.32 +
      0.025 * (carried + 1);

    if (atDock) {
      if (need > 1.16) return false;
    } else if (battery < need + 0.055) {
      return false;
    }

    var planSpeed = clamp(num(mem.speedEst, 0.65) * 0.88, 0.50, 1.1);
    var eta = route / planSpeed + 18 + 7 * (carried + 1);
    if (timeLeft < eta + 8) return false;
    return true;
  }

  function targetScore(t) {
