    for (var i = 0; i < mem.targets.length; i++) {
      var old = mem.targets[i];
      if (old.source === "signal" &&
          dist(mem.px, mem.py, old.x, old.y) < 20) return null;
      if (!old.done && !old.bad &&
          dist(mem.px, mem.py, old.x, old.y) < 11) return null;
