    }

    markDone(t.id);
    return true;
  }

  function targetAction(t) {
    observeScience(t);

    if (!t.searchStarted) {
      var dCenter = dist(mem.px, mem.py, t.x, t.y);
      if (dCenter > 3.6) {
        var approachKey = "approach_" + t.id;
        if (mem.failedKey === approachKey) {
          mem.failedKey = null;
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }

        var approach = navigateToPoint(t.x, t.y, 0.82, 2.2, approachKey);
        if (mem.failedKey === approachKey) {
          mem.failedKey = null;
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        return approach;
      }

      if (t.source === "scout" && science < 0.018) {
        markDone(t.id);
        return null;
      }

      beginSearch(t, t.x, t.y,
        t.source === "hint" ? 19 : Math.max(8, num(t.radius, 14)));
    }

    for (var tries = 0; tries < 8; tries++) {
      var pts = Array.isArray(t.points) ? t.points : [];
      if (t.searchIndex >= pts.length) {
        finishSearch(t);
        return null;
      }

      var p = pts[t.searchIndex];
      var pd = dist(mem.px, mem.py, p.x, p.y);
      if (pd <= 1.75) {
        t.searchIndex++;
        continue;
      }

      var key = "search_" + t.id + "_" + t.searchIndex;
      if (mem.failedKey === key) {
        mem.failedKey = null;
        t.searchIndex++;
        t.skipped = num(t.skipped, 0) + 1;
        if (t.skipped >= 7) {
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        continue;
      }

      var action = navigateToPoint(p.x, p.y, 0.78, 1.55, key);
      if (mem.failedKey === key) {
        mem.failedKey = null;
        t.searchIndex++;
        t.skipped = num(t.skipped, 0) + 1;
        if (t.skipped >= 7) {
          t.bad = true;
          if (mem.activeId === t.id) mem.activeId = -1;
          return null;
        }
        return null;
      }
      return action;
    }

    finishSearch(t);
    return null;
  }

  var siteObj = obs.site || null;

  function holdSample(p, drill) {
    return drive(0, 0, drill, "sample");
  }

  function processSample() {
    var p = mem.sample;
    if (!p) return null;

    var sd = siteObj && validField(siteObj, "distance")
      ? Math.max(0, num(siteObj.distance, 99))
      : null;

    if (sd !== null) {
      p.lastSeen = now;
      p.lastDist = sd;
      var bearing = num(siteObj.bearing, 0);
      var worldBearing = (mem.yaw + bearing) * Math.PI / 180;
      p.siteX = mem.px + sd * Math.cos(worldBearing);
      p.siteY = mem.py + sd * Math.sin(worldBearing);

      if (sd > 1.42) {
        p.stable = 0;
        return navigateRelative(bearing, sd, 0.32, 0.88, "site");
      }
    } else if (now - num(p.lastSeen, now) > 2.0 &&
               num(obs.drilling, 0) < 0.1) {
      mem.sample = null;
      return null;
    }

    var progress = Math.max(0, num(obs.drilling, 0));
    p.maxProgress = Math.max(num(p.maxProgress, 0), progress);

    var inRange;
    if (sd !== null) {
      inRange = sd <= 1.42;
    } else {
      var age = now - num(p.lastSeen, now);
      var estimatedDistance = dist(mem.px, mem.py,
        num(p.siteX, p.anchorX), num(p.siteY, p.anchorY));
      inRange = age <= 1.5 &&
        (num(p.lastDist, 99) <= 1.42 || estimatedDistance <= 1.40 || progress > 0.05);
    }

    var still = Math.abs(wl) < 0.13 &&
      Math.abs(wr) < 0.13 &&
      Math.abs(vAvg) < 0.12;

    if (inRange && still) p.stable = num(p.stable, 0) + 1;
    else p.stable = 0;

    var drill = inRange && still && p.stable >= 2;
    if (drill) p.started = true;
    return holdSample(p, drill);
  }

  function handleSite() {
    if (!siteObj || carried >= mem.capacity) return null;

    var sd = Math.max(0, num(siteObj.distance, 99));
    var siteValue = num(siteObj.value, 0);
    var active = getTarget(mem.activeId);
    if (active && siteValue > 0) active.val = Math.max(active.val, siteValue);

    if (sd <= 1.55) {
      if (!mem.sample) {
        var bearing = num(siteObj.bearing, 0);
        var worldBearing = (mem.yaw + bearing) * Math.PI / 180;
        mem.sample = {
          anchorX: mem.px,
          anchorY: mem.py,
          siteX: mem.px + sd * Math.cos(worldBearing),
          siteY: mem.py + sd * Math.sin(worldBearing),
          targetId: mem.activeId,
          stable: 0,
          started: false,
          maxProgress: num(obs.drilling, 0),
          lastSeen: now,
          lastDist: sd
        };
