    }

    return navigateRelative(
      num(siteObj.bearing, 0),
      sd,
      0.42,
      1.00,
      "site"
    );
  }

  var beaconValid = validField(obs.beacon, "distance") &&
    validField(obs.beacon, "bearing");
  var beaconDistance = beaconValid ?
    Math.max(0, num(obs.beacon.distance, 99)) : 99;
  var geoHome = dist(mem.px, mem.py, mem.baseX, mem.baseY);
  var homeDistance = beaconValid && beaconDistance <= 22
    ? beaconDistance
    : geoHome;

  function goHome() {
    if (isDocked) return idle();

    if (beaconValid && beaconDistance <= 22) {
      if (beaconDistance <= 2.15) return drive(0, 0, false, "home");
      return navigateRelative(
        num(obs.beacon.bearing, 0),
        beaconDistance,
        0.84,
        1.85,
        "homeBeacon"
      );
    }

    if (geoHome <= 2.15) return drive(0, 0, false, "home");
    return navigateToPoint(mem.baseX, mem.baseY, 0.84, 1.85, "homeGPS");
  }

  var carriedUp = carried > num(mem.lastCarried, carried);
  var valueUp = carriedValue > num(mem.lastCarriedValue, carriedValue) + 0.01;
  var deliveredUp = delivered > num(mem.lastDelivered, delivered) + 0.01;

  if (carriedUp || valueUp) {
    var completedId = mem.sample ? mem.sample.targetId : mem.activeId;
    if (Number.isFinite(Number(completedId)) && completedId >= 0) {
      markDone(Number(completedId));
    }
    mem.sample = null;
  }

  if (deliveredUp) {
    mem.returning = false;
    mem.dockSince = null;
  }

  mem.lastCarried = carried;
  mem.lastCarriedValue = carriedValue;
  mem.lastDelivered = delivered;

  if (isDocked && carried <= 0) {
    mem.returning = false;
    if (!Number.isFinite(mem.dockSince)) mem.dockSince = now;
  }

  var loadNow = 1 + 0.16 * carried;
  var homeNeed = 0.09 +
    mem.energyPerM * (homeDistance + 12) * loadNow * 1.55 +
    0.025 * carried;
  var homeSpeed = clamp(num(mem.speedEst, 0.65) * 0.72, 0.42, 1.05);
  var homeEta = 24 + homeDistance / homeSpeed * 1.25 + 7 * carried;

  var urgentReturn = !isDocked && (
    carried >= mem.capacity ||
    battery < homeNeed + (carried > 0 ? 0.075 : 0.14) ||
    battery < 0.07 ||
    timeLeft < homeEta + (carried > 0 ? 14 : 5)
  );

  if (urgentReturn && mem.sample && carried === 0 &&
      num(obs.drilling, 0) >= 4.7 &&
      battery > homeNeed + 0.025 &&
      timeLeft > homeEta + 7) {
    var nearlyDone = processSample();
    if (nearlyDone) return nearlyDone;
  }

  if (urgentReturn) {
    mem.returning = true;
    mem.sample = null;
  }

  if (mem.returning && !isDocked) return goHome();
  if (isDocked && carried > 0) return idle();

  if (mem.sample && !isDocked) {
    var pendingSample = processSample();
    if (pendingSample) return pendingSample;
  }

  if (!mem.returning && siteObj && carried < mem.capacity && !isDocked) {
    var siteAction = handleSite();
    if (siteAction) return siteAction;
  }

  if (!mem.returning && carried < mem.capacity) createSignalTarget();

  var target = selectTarget(isDocked);
  if (!target) {
    createScout();
    target = selectTarget(isDocked);
  }

  if (isDocked && target) {
    if (!Number.isFinite(mem.dockSince)) mem.dockSince = now;
    var needed = targetNeed(target);
    var dockWait = now - num(mem.dockSince, now);
    var launchAt = Math.min(1.0, needed + 0.035);
    var planSpeed = clamp(num(mem.speedEst, 0.65) * 0.88, 0.50, 1.1);
    var eta = targetRoute(target) / planSpeed + 25;

    if (battery + 0.005 < launchAt &&
        dockWait < 120 &&
        timeLeft > eta + 15) {
      return idle();
    }
  } else if (!isDocked) {
    mem.dockSince = null;
  }

  for (var attempt = 0; attempt < 6; attempt++) {
    if (!target || !targetFeasible(target, isDocked)) {
      target = selectTarget(isDocked);
    }
    if (!target) break;

    var action = targetAction(target);
    if (action) return action;
    target = selectTarget(isDocked);
  }

  if (!isDocked) {
    mem.returning = true;
    return goHome();
  }

  return idle();
}

