    mem.lastCarried = 0;
    mem.lastCarriedValue = 0;
    mem.lastDelivered = 0;

    mem.raySig = "";
    mem.raySame = 0;
    mem.rayMove = 0;
    mem.rayBlindUntil = -1;
  }

  if (!Array.isArray(mem.targets)) mem.targets = [];

  if (!mem.missionLoaded && obs.mission) {
    var mission = obs.mission;
    var sz = mission.size;

    if (Array.isArray(sz)) {
      mem.sizeX = Math.max(20, num(sz[0], 400));
      mem.sizeY = Math.max(20, num(sz[1], mem.sizeX));
    } else if (sz && typeof sz === "object") {
      mem.sizeX = Math.max(20, num(sz.width, num(sz.x, num(mission.width, 400))));
      mem.sizeY = Math.max(20, num(sz.height, num(sz.y, num(mission.height, mem.sizeX))));
    } else {
      mem.sizeX = Math.max(20, num(sz, num(mission.width, 400)));
      mem.sizeY = Math.max(20, num(mission.height, mem.sizeX));
    }

    mem.baseX = num(mission.base && mission.base.x, mem.sizeX * 0.5);
    mem.baseY = num(mission.base && mission.base.y, mem.sizeY * 0.5);
    mem.capacity = Math.max(1, num(mission.capacity, 5));
    mem.missionSeconds = num(mission.seconds, 1200);
    mem.targets = [];

    var hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (var hi = 0; hi < hints.length; hi++) {
      var h = hints[hi];
      var hx = num(h && h.x, NaN);
      var hy = num(h && h.y, NaN);
      if (!Number.isFinite(hx) || !Number.isFinite(hy)) continue;

      var tx = clamp(hx, 5, mem.sizeX - 5);
      var ty = clamp(hy, 5, mem.sizeY - 5);
      var duplicate = false;
      for (var hj = 0; hj < mem.targets.length; hj++) {
        if (dist(tx, ty, mem.targets[hj].x, mem.targets[hj].y) < 7) {
          mem.targets[hj].val = Math.max(
            mem.targets[hj].val,
            Math.max(1, num(h && h.estimate, num(h && h.value, 5)))
          );
          duplicate = true;
          break;
        }
      }
      if (duplicate) continue;

      mem.targets.push({
        id: mem.targets.length,
        source: "hint",
        x: tx,
        y: ty,
        originX: tx,
        originY: ty,
        val: Math.max(1, num(h && h.estimate, num(h && h.value, 5))),
        radius: 22,
        done: false,
        bad: false,
        searchStarted: false,
        points: [],
        searchIndex: 0,
        refines: 0,
        bestScience: 0,
        startScience: 0,
        bestX: tx,
        bestY: ty,
        skipped: 0
      });
    }
    mem.missionLoaded = true;
  }

  mem.sizeX = Math.max(20, num(mem.sizeX, 400));
  mem.sizeY = Math.max(20, num(mem.sizeY, 400));
  mem.baseX = num(mem.baseX, mem.sizeX * 0.5);
  mem.baseY = num(mem.baseY, mem.sizeY * 0.5);
  mem.capacity = Math.max(1, num(mem.capacity, 5));
  mem.missionSeconds = num(mem.missionSeconds, 1200);
  mem.energyPerM = clamp(num(mem.energyPerM, 0.0015), 0.00025, 0.03);

  function mapX(x) {
    return clamp(x, 5, mem.sizeX - 5);
  }
  function mapY(y) {
    return clamp(y, 5, mem.sizeY - 5);
  }

  var now = num(obs.t, Number.isFinite(mem.lastT) ? mem.lastT : 0);
  if (Number.isFinite(mem.lastT) && now < mem.lastT - 0.5) now = mem.lastT;

  var dt = 0.1;
  if (Number.isFinite(mem.lastT)) {
    var dtRaw = now - mem.lastT;
    if (dtRaw > 0.01 && dtRaw < 0.7) dt = dtRaw;
  }
  dt = clamp(dt, 0.05, 0.25);

  var timeLeft = num(obs.timeLeft, Math.max(0, mem.missionSeconds - now));
  var xObs = num(obs.x, Number.isFinite(mem.px) ? mem.px : mem.baseX);
  var yObs = num(obs.y, Number.isFinite(mem.py) ? mem.py : mem.baseY);
  var rawHeading = wrap(num(obs.heading, Number.isFinite(mem.yaw) ? mem.yaw : 0));
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  var vAvg = 0.5 * (wl + wr);
  var pitch = num(obs.pitch, 0);
  var battery = clamp(num(obs.battery, 1), 0, 1.6);
  var solar = Math.max(0, num(obs.solar, 0));
  var carried = Math.max(0, num(obs.carried, 0));
  var carriedValue = Math.max(0, num(obs.carriedValue, 0));
  var delivered = Math.max(0, num(obs.delivered, 0));
  var science = Math.max(0, num(obs.science, 0));
  var isDocked = !!obs.docked;
  var wheelPath = 0.5 * (Math.abs(wl) + Math.abs(wr)) * dt;

  if (!mem.poseInit || !Number.isFinite(mem.px) ||
      !Number.isFinite(mem.py) || !Number.isFinite(mem.yaw)) {
    mem.poseInit = true;
    mem.px = xObs;
    mem.py = yObs;
    mem.yaw = rawHeading;
    mem.lastRawHeading = rawHeading;
    mem.lastGX = xObs;
    mem.lastGY = yObs;
    mem.gpsSame = 0;
    mem.gpsDrive = 0;
    mem.gpsFrozen = false;
    mem.calT = now;
    mem.calX = xObs;
    mem.calY = yObs;
    mem.calSigned = 0;
    mem.calTurn = 0;
  } else {
    var oldPX = mem.px;
    var oldPY = mem.py;
    var oldYaw = mem.yaw;
    var gpsDX = xObs - num(mem.lastGX, xObs);
    var gpsDY = yObs - num(mem.lastGY, yObs);
    var gpsStep = Math.sqrt(gpsDX * gpsDX + gpsDY * gpsDY);

    if (gpsStep < 0.025) {
      mem.gpsSame = num(mem.gpsSame, 0) + 1;
      mem.gpsDrive = num(mem.gpsDrive, 0) + Math.abs(vAvg) * dt;
    } else {
      mem.gpsSame = 0;
      mem.gpsDrive = 0;
    }

    if (!mem.gpsFrozen && mem.gpsSame > 30 && mem.gpsDrive > 1.8) {
      mem.gpsFrozen = true;
      mem.freezeGX = num(mem.lastGX, xObs);
      mem.freezeGY = num(mem.lastGY, yObs);
    }
    if (mem.gpsFrozen &&
        dist(xObs, yObs, num(mem.freezeGX, xObs), num(mem.freezeGY, yObs)) > 0.9) {
      mem.gpsFrozen = false;
      mem.gpsSame = 0;
      mem.gpsDrive = 0;
    }

    var odoDeg = clamp((wr - wl) / 0.6 * dt * 57.2957795, -50, 50);
    var predictedYaw = wrap(oldYaw + odoDeg);
    var rawJump = Math.abs(wrap(rawHeading - num(mem.lastRawHeading, rawHeading)));

    if (rawJump > 70 && Math.abs(odoDeg) < 28) {
      mem.headingRejectUntil = Math.max(
        num(mem.headingRejectUntil, -1),
        now + 1.8
      );
    }

    var compassTarget = wrap(rawHeading + num(mem.headingBias, 0));
    if (now < num(mem.headingRejectUntil, -1)) {
      mem.yaw = predictedYaw;
    } else {
      var compassError = wrap(compassTarget - predictedYaw);
      mem.yaw = wrap(
        predictedYaw + clamp(0.58 * compassError, -24, 24)
      );
    }

    var midYaw = wrap(oldYaw + 0.5 * wrap(mem.yaw - oldYaw)) * Math.PI / 180;
    var useV = Math.abs(vAvg) < 0.025 ? 0 : vAvg;
    var predX = oldPX + useV * dt * Math.cos(midYaw);
    var predY = oldPY + useV * dt * Math.sin(midYaw);
    var mismatch = dist(predX, predY, xObs, yObs);

    if (gpsStep > 10) {
      mem.gpsRejectUntil = Math.max(num(mem.gpsRejectUntil, -1), now + 1.2);
    }

    if (mem.gpsFrozen || now < num(mem.gpsRejectUntil, -1)) {
      mem.px = predX;
      mem.py = predY;
    } else {
      var alpha = Math.abs(vAvg) < 0.08 ? 0.12 : 0.36;
      if (Math.abs(vAvg) >= 0.08 && Math.abs(vAvg) < 0.24) alpha = 0.25;
      if (mismatch > 5) alpha = 0.14;
      if (mismatch > 11) alpha = 0;
      mem.px = predX + alpha * (xObs - predX);
      mem.py = predY + alpha * (yObs - predY);
    }

    var straight = !mem.gpsFrozen &&
      now >= num(mem.headingRejectUntil, -1) &&
      Math.abs(vAvg) > 0.25 &&
      Math.abs(wr - wl) < 0.28;

    if (straight) {
      if (!Number.isFinite(mem.calT)) {
        mem.calT = now;
        mem.calX = mem.px;
        mem.calY = mem.py;
        mem.calSigned = 0;
        mem.calTurn = 0;
      }
      mem.calSigned = num(mem.calSigned, 0) + vAvg * dt;
      mem.calTurn = num(mem.calTurn, 0) + Math.abs(wr - wl) * dt / 0.6;

      if (now - num(mem.calT, now) >= 4) {
        var cdx = mem.px - num(mem.calX, mem.px);
        var cdy = mem.py - num(mem.calY, mem.py);
        var cd = Math.sqrt(cdx * cdx + cdy * cdy);

        if (cd > 1.5 && Math.abs(num(mem.calSigned, 0)) > 1.0 &&
            num(mem.calTurn, 0) < 0.55) {
          var course = Math.atan2(cdy, cdx) * 180 / Math.PI;
          if (mem.calSigned < 0) course = wrap(course + 180);
          var biasObs = wrap(course - rawHeading);
          if (Math.abs(biasObs) < 105) {
            mem.headingBias = clamp(
              num(mem.headingBias, 0) +
                0.06 * wrap(biasObs - num(mem.headingBias, 0)),
              -100, 100
            );
          }
        }

        mem.calT = now;
        mem.calX = mem.px;
        mem.calY = mem.py;
        mem.calSigned = 0;
        mem.calTurn = 0;
      }
    } else {
      mem.calT = now;
      mem.calX = mem.px;
      mem.calY = mem.py;
      mem.calSigned = 0;
      mem.calTurn = 0;
    }

    mem.lastRawHeading = rawHeading;
    mem.lastGX = xObs;
    mem.lastGY = yObs;
  }

  if (Math.abs(vAvg) > 0.25 && Math.abs(wr - wl) < 0.55) {
    mem.speedEst = clamp(
      0.97 * num(mem.speedEst, 0.65) + 0.03 * Math.abs(vAvg),
      0.25, 2.6
    );
  }

  function learnMotor(side, actual) {
    var gainKey = side === "L" ? "gainL" : "gainR";
    var stallKey = side === "L" ? "stallL" : "stallR";
    var out = side === "L" ? num(mem.lastOutL, 0) : num(mem.lastOutR, 0);
    var gain = num(mem[gainKey], 2.5);

    if (Math.abs(out) > 0.18) {
      if (Math.abs(actual) < 0.055) {
        mem[stallKey] = num(mem[stallKey], 0) + 1;
      } else {
        mem[stallKey] = 0;
      }

      if (actual * out > 0 && Math.abs(actual) > 0.08) {
        var ratio = Math.abs(actual / out);
        if (ratio > 0.15 && ratio < 5.5) {
          gain = 0.99 * gain + 0.01 * ratio;
        }
      }

      if (num(mem[stallKey], 0) > 18) {
        gain = Math.max(0.5, gain * 0.90);
        mem[stallKey] = 0;
      }
    } else {
      mem[stallKey] = 0;
    }
    mem[gainKey] = clamp(gain, 0.5, 5.5);
  }

  learnMotor("L", wl);
  learnMotor("R", wr);

  if (isDocked) {
    mem.energyAcc = 0;
    mem.distanceAcc = 0;
  } else if (Number.isFinite(mem.lastBattery)) {
    var grossUse = num(mem.lastBattery, battery) - battery +
      0.5 * (num(mem.lastSolar, solar) + solar) * dt;

    if (wheelPath > 0.006) {
      mem.energyAcc = num(mem.energyAcc, 0) + Math.max(0, grossUse);
      mem.distanceAcc = num(mem.distanceAcc, 0) + wheelPath;
    }

    if (mem.distanceAcc >= 8) {
      var measured = mem.energyAcc /
        Math.max(1, mem.distanceAcc) /
        (1 + 0.12 * carried);
      if (measured > 0.0003 && Number.isFinite(measured)) {
        measured = clamp(measured, 0.00025, 0.03);
        if (measured > mem.energyPerM) {
          mem.energyPerM = 0.80 * mem.energyPerM + 0.20 * measured;
        } else {
          mem.energyPerM = 0.96 * mem.energyPerM + 0.04 * measured;
        }
      }
      mem.energyAcc = 0;
      mem.distanceAcc = 0;
    }
  }
  mem.lastBattery = battery;
  mem.lastSolar = solar;

  var rays = [];
  var rayMin = 15, rayMax = 0;
  var rayParts = [];
  for (var ri = 0; ri < 9; ri++) {
    var rv = obs.rays && obs.rays.length > ri ? num(obs.rays[ri], 15) : 15;
    rv = clamp(rv, 0, 15);
    rays.push(rv);
    rayMin = Math.min(rayMin, rv);
    rayMax = Math.max(rayMax, rv);
    rayParts.push(String(Math.round(rv * 4)));
  }

  var allClear = rayMin >= 14.7;
  var raySig = rayParts.join(",");
  if (raySig === mem.raySig) {
    mem.raySame = num(mem.raySame, 0) + 1;
    mem.rayMove = num(mem.rayMove, 0) + wheelPath;
  } else {
    mem.raySame = 0;
    mem.rayMove = 0;
  }
  if (!allClear && rayMax - rayMin < 0.07 &&
      mem.raySame > 55 && mem.rayMove > 4) {
    mem.rayBlindUntil = Math.max(num(mem.rayBlindUntil, -1), now + 20);
  }
  mem.raySig = raySig;
  var rayBlind = now < num(mem.rayBlindUntil, -1);

  function rayAt(deg) {
    if (rayBlind) return 15;
    deg = clamp(deg, -80, 80);
    var f = (deg + 80) / 20;
    var lo = Math.floor(f);
    var hi = Math.min(8, lo + 1);
    var frac = f - lo;
    return rays[lo] * (1 - frac) + rays[hi] * frac;
  }

  function output(left, right, drill, mode) {
    left = clamp(num(left, 0), -1, 1);
    right = clamp(num(right, 0), -1, 1);
    mem.lastOutL = left;
    mem.lastOutR = right;
    mem.lastMode = mode || "drive";
    mem.lastT = now;
    return { left: left, right: right, drill: !!drill };
  }

  var pitchFF = clamp(pitch * 0.006, -0.13, 0.13);

  function wheelCommand(desired, actual, gain) {
    desired = clamp(desired, -1.4, 1.4);
    gain = Math.max(0.5, gain);

    var u;
    if (Math.abs(desired) < 0.035) {
      u = -0.85 * actual / gain + pitchFF;
    } else {
      var base = desired / gain + 0.20 * (desired - actual);
      if (Math.abs(desired) > 0.14 && desired * base > 0 &&
          Math.abs(base) < 0.075) {
        base = desired < 0 ? -0.075 : 0.075;
      }
      u = base + pitchFF;
    }
    return clamp(u, -0.82, 0.82);
  }

  function drive(v, omega, drill, mode) {
    v = clamp(v, -1.05, 1.05);
    omega = clamp(omega, -1.25, 1.25);
    var leftSpeed = clamp(v - 0.3 * omega, -1.35, 1.35);
    var rightSpeed = clamp(v + 0.3 * omega, -1.35, 1.35);
    return output(
      wheelCommand(leftSpeed, wl, num(mem.gainL, 2.5)),
      wheelCommand(rightSpeed, wr, num(mem.gainR, 2.5)),
      drill,
      mode || "drive"
    );
  }

  function idle() {
    return drive(0, 0, false, "idle");
  }

  function chooseRecoverySign() {
    var leftSpace = 0.5 * (rayAt(40) + rayAt(60));
    var rightSpace = 0.5 * (rayAt(-40) + rayAt(-60));
    if (Math.abs(leftSpace - rightSpace) < 0.15) {
      return -num(mem.recoverSign, 1);
    }
    return leftSpace > rightSpace ? 1 : -1;
  }

  function escapeAction() {
    return drive(-0.18, num(mem.recoverSign, 1) * 0.68, false, "recover");
  }

  function edgeDistance(angle) {
    var a = (mem.yaw + angle) * Math.PI / 180;
    var ux = Math.cos(a), uy = Math.sin(a);
    var best = 1e6;

    if (ux > 0.001) best = Math.min(best, (mem.sizeX - 5 - mem.px) / ux);
    if (ux < -0.001) best = Math.min(best, (5 - mem.px) / ux);
    if (uy > 0.001) best = Math.min(best, (mem.sizeY - 5 - mem.py) / uy);
    if (uy < -0.001) best = Math.min(best, (5 - mem.py) / uy);

    return Math.max(0, best);
  }

  function watchNavigation(key, d, stopD) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navProgressAt = now;
      mem.navStalls = 0;
      return;
    }

    if (d < num(mem.navBest, d) - 0.8) {
      mem.navBest = d;
      mem.navProgressAt = now;
      mem.navStalls = 0;
      return;
    }

    mem.navBest = Math.min(num(mem.navBest, d), d);
    if (now - num(mem.navProgressAt, now) > 24 && d > stopD + 3) {
      mem.navProgressAt = now;
      mem.navBest = d;
      mem.navStalls = num(mem.navStalls, 0) + 1;
      mem.recoverSign = chooseRecoverySign();
      mem.recoverUntil = Math.max(num(mem.recoverUntil, -1), now + 1.0);

      if (mem.navStalls >= 4 &&
          (key.indexOf("scan_") === 0 || key.indexOf("approach_") === 0)) {
        mem.failedNavKey = key;
        mem.navStalls = 0;
      }
    }
  }

  function chooseSteer(rel, maxSpeed, key) {
    rel = wrap(rel);
    if (Math.abs(rel) > 78) return rel;

    var look = 2.8 + 1.5 * maxSpeed;
    var bestAngle = rel;
    var bestCost = Infinity;

    for (var a = -80; a <= 80; a += 10) {
      var clear = rayAt(a);
      var deviation = Math.abs(wrap(rel - a));
      var blocked = Math.max(0, look - clear);
      var cost = 0.045 * deviation + 0.95 * blocked * blocked;

      if (clear < 1.15) cost += 80;
      if (deviation > 55) cost += 0.12 * (deviation - 55) * (deviation - 55);

      var edge = edgeDistance(a);
      if (edge < 4.2) cost += 1.5 * (4.2 - edge) * (4.2 - edge);

      if (mem.steerKey === key && Number.isFinite(mem.steerAngle)) {
        cost += 0.004 * Math.abs(a - mem.steerAngle);
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
      }
    }

    mem.steerKey = key;
    mem.steerAngle = bestAngle;
    return bestAngle;
  }

  function navigateRelative(rel, d, maxSpeed, stopD, key) {
    rel = wrap(num(rel, 0));
    d = Math.max(0, num(d, 999));
    maxSpeed = clamp(maxSpeed, 0.10, 0.95);
    stopD = Math.max(0, stopD);

    if (d <= stopD) return drive(0, 0, false, "hold");

    watchNavigation(key, d, stopD);
    if (now < num(mem.recoverUntil, -1)) return escapeAction();

    var chosen = chooseSteer(rel, maxSpeed, key);
    var errDeg = wrap(chosen);
    var errRad = errDeg * Math.PI / 180;

    if (Math.abs(errDeg) > 74) {
      var sign;
      if (Math.abs(errDeg) > 150 &&
          now < num(mem.turnSignUntil, -1) &&
          num(mem.turnSign, 0) !== 0) {
        sign = num(mem.turnSign, errDeg > 0 ? 1 : -1);
      } else {
        sign = errDeg > 0 ? 1 : -1;
        mem.turnSign = sign;
        mem.turnSignUntil = now + 4;
      }
      return drive(0, sign * 0.72, false, "turn");
    }

    var travel = Math.max(0, d - stopD);
    var speed = Math.min(maxSpeed, Math.sqrt(0.65 * travel));
    speed *= clamp(Math.cos(errRad), 0.22, 1);

    if (Math.abs(errDeg) > 52) speed = Math.min(speed, 0.22);

    var clearPath = rayAt(chosen);
    if (clearPath < 3.6) {
      speed = Math.min(speed, Math.max(0, 0.22 * (clearPath - 1.05)));
    }
    if (clearPath < 1.2) speed = 0;
    if (rayBlind) speed = Math.min(speed, 0.65);

    var omega = clamp(1.45 * errRad, -0.88, 0.88);
    if (Math.abs(errDeg) < 2.5) omega = 0;
    return drive(speed, omega, false, "nav");
  }

  function navigateToPoint(tx, ty, maxSpeed, stopD, key) {
    tx = mapX(tx);
    ty = mapY(ty);
    var dx = tx - mem.px;
    var dy = ty - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var world = Math.atan2(dy, dx) * 180 / Math.PI;
    return navigateRelative(wrap(world - mem.yaw), d, maxSpeed, stopD, key);
  }

  function getTarget(id) {
    if (!Number.isFinite(Number(id)) || Number(id) < 0 ||
        Number(id) >= mem.targets.length) return null;
    return mem.targets[Math.floor(Number(id))];
  }

  function addTarget(x, y, val, source, radius) {
    x = mapX(x);
    y = mapY(y);
    var t = {
      id: mem.targets.length,
      source: source || "hint",
      x: x,
      y: y,
      originX: x,
      originY: y,
      val: Math.max(1, num(val, 5)),
      radius: Math.max(8, num(radius, 18)),
      done: false,
      bad: false,
      searchStarted: false,
      points: [],
      searchIndex: 0,
      refines: 0,
      bestScience: 0,
      startScience: 0,
      bestX: x,
      bestY: y,
      skipped: 0
    };
    mem.targets.push(t);
    return t;
  }

  function markDone(id) {
    var t = getTarget(id);
    if (t) {
      t.done = true;
      t.bad = false;
      t.doneTime = now;
    }
    if (Number(mem.activeId) === Number(id)) mem.activeId = -1;
  }

  function buildSearchPath(cx, cy, radius, id) {
    var pts = [];
    function addPoint(px, py) {
      px = mapX(px);
      py = mapY(py);
      var last = pts.length ? pts[pts.length - 1] : null;
      if (!last || dist(px, py, last.x, last.y) > 3.2) {
        pts.push({ x: px, y: py });
      }
    }

    addPoint(cx, cy);
    var pitchSpacing = 13;
    var b = pitchSpacing / (2 * Math.PI);
    var theta = 0.48;
    var phase = (id * 2.399963229728653) % (2 * Math.PI);
    var guard = 0;

    while (b * theta <= radius && guard < 180) {
      var r = b * theta;
      var a = theta + phase;
      addPoint(cx + r * Math.cos(a), cy + r * Math.sin(a));

      var step = 6.5 / Math.sqrt(r * r + b * b);
      theta += clamp(step, 0.22, 1.8);
      guard++;
    }
    return pts;
  }

  function beginSearch(t, cx, cy, radius) {
    t.searchStarted = true;
    t.centerX = mapX(cx);
    t.centerY = mapY(cy);
    t.radius = Math.max(8, num(radius, 18));
    t.points = buildSearchPath(t.centerX, t.centerY, t.radius, t.id);
    t.searchIndex = 0;
    t.startScience = science;
    t.bestScience = science;
    t.bestX = mem.px;
    t.bestY = mem.py;
