    mem.gpsWheelPath = 0;
    mem.gpsFrozen = false;
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calHX = 0;
    mem.calHY = 0;
    mem.calSign = 0;
  } else {
    var oldPX = mem.px;
    var oldPY = mem.py;
    var oldYaw = mem.yaw;
    var gpsDX = xObs - num(mem.lastGX, xObs);
    var gpsDY = yObs - num(mem.lastGY, yObs);
    var gpsStep = Math.sqrt(gpsDX * gpsDX + gpsDY * gpsDY);

    if (gpsStep < 0.025) {
      mem.gpsSame = num(mem.gpsSame, 0) + 1;
      mem.gpsWheelPath = num(mem.gpsWheelPath, 0) + wheelPath;
    } else {
      mem.gpsSame = 0;
      mem.gpsWheelPath = 0;
    }

    if (!mem.gpsFrozen && mem.gpsSame > 28 &&
        mem.gpsWheelPath > 1.8) {
      mem.gpsFrozen = true;
      mem.freezeGX = xObs;
      mem.freezeGY = yObs;
    }
    if (mem.gpsFrozen &&
        dist(xObs, yObs, num(mem.freezeGX, xObs), num(mem.freezeGY, yObs)) > 0.8) {
      mem.gpsFrozen = false;
      mem.gpsSame = 0;
      mem.gpsWheelPath = 0;
    }

    var odoDeg = clamp((wr - wl) / 0.6 * dt * 57.2957795, -40, 40);
    var predictedYaw = wrap(oldYaw + odoDeg);
    var rawJump = Math.abs(wrap(rawHeading - num(mem.lastRawHeading, rawHeading)));

    if (rawJump > 65 && Math.abs(odoDeg) < 22) {
      mem.headingRejectUntil = Math.max(
        num(mem.headingRejectUntil, -1),
        now + 1.8
      );
    }

    if (now < num(mem.headingRejectUntil, -1)) {
      mem.yaw = predictedYaw;
    } else {
      var compassTarget = wrap(rawHeading + num(mem.headingBias, 0));
      var compassError = wrap(compassTarget - predictedYaw);
      mem.yaw = wrap(
        predictedYaw + clamp(0.36 * compassError, -11, 11)
      );
    }

    var midYaw = wrap(oldYaw + 0.5 * wrap(mem.yaw - oldYaw)) *
      Math.PI / 180;
    var useV = Math.abs(vAvg) < 0.025 ? 0 : vAvg;
    var predX = oldPX + useV * dt * Math.cos(midYaw);
    var predY = oldPY + useV * dt * Math.sin(midYaw);
    var mismatch = dist(predX, predY, xObs, yObs);

    if (gpsStep > 10) {
      mem.gpsRejectUntil = Math.max(
        num(mem.gpsRejectUntil, -1),
        now + 1.0
      );
    }

    if (mem.gpsFrozen || now < num(mem.gpsRejectUntil, -1)) {
      mem.px = predX;
      mem.py = predY;
    } else {
      var gpsAlpha = Math.abs(vAvg) < 0.08 ? 0.62 : 0.48;
      if (mismatch > 5) gpsAlpha = 0.20;
      if (mismatch > 12) gpsAlpha = 0.05;
      if (gpsStep > 10) gpsAlpha = 0;
      mem.px = predX + gpsAlpha * (xObs - predX);
      mem.py = predY + gpsAlpha * (yObs - predY);
    }

    var straight = !mem.gpsFrozen &&
      now >= num(mem.headingRejectUntil, -1) &&
      gpsStep < 8 &&
      Math.abs(vAvg) > 0.28 &&
      Math.abs(wr - wl) < 0.34;

    if (straight) {
      var sign = vAvg < 0 ? -1 : 1;
      if (mem.calSign !== 0 && sign !== mem.calSign) {
        mem.calDX = 0;
        mem.calDY = 0;
        mem.calHX = 0;
        mem.calHY = 0;
      }
      mem.calSign = sign;
      mem.calDX = num(mem.calDX, 0) + gpsDX;
      mem.calDY = num(mem.calDY, 0) + gpsDY;
      var hr = rawHeading * Math.PI / 180;
      mem.calHX = num(mem.calHX, 0) + Math.cos(hr) * dt;
      mem.calHY = num(mem.calHY, 0) + Math.sin(hr) * dt;

      var calDist = Math.sqrt(
        mem.calDX * mem.calDX + mem.calDY * mem.calDY
      );
      if (calDist > 4.5 &&
          Math.sqrt(mem.calHX * mem.calHX + mem.calHY * mem.calHY) > 0.5) {
        var course = Math.atan2(mem.calDY, mem.calDX) * 180 / Math.PI;
        if (mem.calSign < 0) course = wrap(course + 180);
        var rawMean = Math.atan2(mem.calHY, mem.calHX) * 180 / Math.PI;
        var biasObs = wrap(course - rawMean);
        if (Math.abs(biasObs) < 70) {
          mem.headingBias = clamp(
            num(mem.headingBias, 0) +
              0.10 * wrap(biasObs - num(mem.headingBias, 0)),
            -70, 70
          );
        }
        mem.calDX = 0;
        mem.calDY = 0;
        mem.calHX = 0;
        mem.calHY = 0;
        mem.calSign = 0;
      }
    } else {
      mem.calDX = 0;
      mem.calDY = 0;
      mem.calHX = 0;
      mem.calHY = 0;
      mem.calSign = 0;
    }

    mem.lastRawHeading = rawHeading;
    mem.lastGX = xObs;
    mem.lastGY = yObs;
  }

  if (Math.abs(vAvg) > 0.22 && Math.abs(wr - wl) < 0.48) {
    mem.speedEst = clamp(
      0.97 * num(mem.speedEst, 0.65) + 0.03 * Math.abs(vAvg),
      0.35, 1.35
    );
  }

  function learnMotor(side, actual) {
    var gainKey = side === "L" ? "gainL" : "gainR";
    var out = side === "L" ? num(mem.lastOutL, 0) : num(mem.lastOutR, 0);
    var gain = num(mem[gainKey], 3.0);

    if ((mem.lastMode === "nav" || mem.lastMode === "turn" ||
         mem.lastMode === "recover") &&
        Math.abs(out) > 0.20 &&
        actual * out > 0 &&
        Math.abs(actual) > 0.10) {
      var ratio = Math.abs(actual / out);
      if (ratio > 0.65 && ratio < 5.5) {
        gain = 0.996 * gain + 0.004 * ratio;
      }
    }
    mem[gainKey] = clamp(gain, 1.1, 5.5);
  }

  learnMotor("L", wl);
  learnMotor("R", wr);

  if (isDocked) {
    mem.energyAcc = 0;
    mem.distanceAcc = 0;
  } else if (Number.isFinite(mem.lastBattery) && wheelPath > 0.004) {
    mem.distanceAcc = num(mem.distanceAcc, 0) + wheelPath;

    if (battery < 0.985 || solar < 0.003 ||
        num(mem.lastBattery, battery) < 0.985) {
      var grossUse = num(mem.lastBattery, battery) - battery +
        0.5 * (num(mem.lastSolar, solar) + solar) * dt;
      mem.energyAcc = num(mem.energyAcc, 0) + Math.max(0, grossUse);
    }

    if (mem.distanceAcc >= 8) {
      var measuredEnergy = mem.energyAcc /
        Math.max(1, mem.distanceAcc) /
        (1 + 0.12 * carried);
      if (measuredEnergy > 0.0003 && Number.isFinite(measuredEnergy)) {
        measuredEnergy = clamp(measuredEnergy, 0.0004, 0.025);
        if (measuredEnergy > mem.energyPerM) {
          mem.energyPerM = 0.78 * mem.energyPerM +
            0.22 * measuredEnergy;
        } else {
          mem.energyPerM = 0.96 * mem.energyPerM +
            0.04 * measuredEnergy;
        }
      }
      mem.energyAcc = 0;
      mem.distanceAcc = 0;
    }
  }
  mem.lastBattery = battery;
  mem.lastSolar = solar;

  var rays = [];
  var rayMin = 15;
  var rayMax = 0;
  var rayParts = [];
  for (var ri = 0; ri < 9; ri++) {
    var rv = obs.rays && obs.rays.length > ri
      ? num(obs.rays[ri], 15)
      : 15;
    rv = clamp(rv, 0, 15);
    rays.push(rv);
    rayMin = Math.min(rayMin, rv);
    rayMax = Math.max(rayMax, rv);
    rayParts.push(String(Math.round(rv * 3)));
  }

  var allClear = rayMin >= 14.7;
  var raySig = rayParts.join(",");
  if (raySig === mem.raySig) {
    mem.raySame = num(mem.raySame, 0) + 1;
    mem.rayMove = num(mem.rayMove, 0) + wheelPath;
  } else {
    mem.raySame = 0;
    mem.rayMove = 0;
  }
  if (!allClear && rayMax - rayMin < 0.06 &&
      mem.raySame > 45 && mem.rayMove > 3.5) {
    mem.rayBlindUntil = Math.max(
      num(mem.rayBlindUntil, -1),
      now + 20
    );
  }
  mem.raySig = raySig;
  var rayBlind = now < num(mem.rayBlindUntil, -1);

  function rayAt(deg) {
    if (rayBlind) return 15;
    deg = clamp(deg, -80, 80);
    var f = (deg + 80) / 20;
    var lo = Math.floor(f);
    var hi = Math.min(8, lo + 1);
    var frac = f - lo;
    return rays[lo] * (1 - frac) + rays[hi] * frac;
  }

  function output(left, right, drill, mode) {
    left = clamp(num(left, 0), -1, 1);
    right = clamp(num(right, 0), -1, 1);
    mem.lastOutL = left;
    mem.lastOutR = right;
    mem.lastMode = mode || "drive";
    mem.lastT = now;
    return { left: left, right: right, drill: !!drill };
  }

  var pitchFF = clamp(pitch * 0.0055, -0.09, 0.09);

  function wheelCommand(desired, actual, gain) {
    desired = clamp(desired, -1.1, 1.1);
    gain = Math.max(1.1, gain);

    var base;
    if (Math.abs(desired) < 0.035) {
      return clamp(pitchFF - 0.22 * actual, -0.70, 0.70);
    }

    base = desired / gain + 0.07 * (desired - actual);
    if (Math.abs(desired) > 0.11 && desired * base > 0 &&
        Math.abs(base) < 0.09) {
      base = desired < 0 ? -0.09 : 0.09;
    }
    return clamp(base + pitchFF, -0.70, 0.70);
  }

  function drive(v, omega, drill, mode) {
    v = clamp(v, -0.85, 0.85);
    omega = clamp(omega, -1.10, 1.10);
    var leftSpeed = clamp(v - 0.3 * omega, -1.1, 1.1);
    var rightSpeed = clamp(v + 0.3 * omega, -1.1, 1.1);
    return output(
      wheelCommand(leftSpeed, wl, num(mem.gainL, 3.0)),
      wheelCommand(rightSpeed, wr, num(mem.gainR, 3.0)),
      drill,
      mode || "drive"
    );
  }

  function edgeDistance(relativeAngle) {
    var a = (mem.yaw + relativeAngle) * Math.PI / 180;
    var ux = Math.cos(a);
    var uy = Math.sin(a);
    var best = 1e6;

    if (ux > 0.001) {
      best = Math.min(best, (mem.sizeX - 5 - mem.px) / ux);
    }
    if (ux < -0.001) {
      best = Math.min(best, (5 - mem.px) / ux);
    }
    if (uy > 0.001) {
      best = Math.min(best, (mem.sizeY - 5 - mem.py) / uy);
    }
    if (uy < -0.001) {
      best = Math.min(best, (5 - mem.py) / uy);
    }
    return Math.max(0, best);
  }

  function chooseRecoverySign() {
    var leftSpace = 0.5 * (rayAt(40) + rayAt(60));
    var rightSpace = 0.5 * (rayAt(-40) + rayAt(-60));
    if (Math.abs(leftSpace - rightSpace) < 0.15) {
      return -num(mem.recoverSign, 1);
    }
    return leftSpace > rightSpace ? 1 : -1;
  }

  function escapeAction() {
    return drive(-0.18, num(mem.recoverSign, 1) * 0.72, false, "recover");
  }

  function watchNavigation(key, d, stopD) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navProgressAt = now;
      mem.navStalls = 0;
      return;
    }

    if (d < num(mem.navBest, d) - 0.75) {
      mem.navBest = d;
      mem.navProgressAt = now;
      mem.navStalls = 0;
      return;
    }

    if (d < num(mem.navBest, d)) mem.navBest = d;
    if (now - num(mem.navProgressAt, now) > 14 &&
        d > stopD + 2.0) {
      mem.navProgressAt = now;
      mem.navBest = d;
      mem.navStalls = num(mem.navStalls, 0) + 1;
      mem.recoverSign = chooseRecoverySign();
      mem.recoverUntil = Math.max(
        num(mem.recoverUntil, -1),
        now + 0.9
      );

      if (mem.navStalls >= 3 &&
          key.indexOf("home") !== 0 &&
          key !== "site") {
        mem.failedKey = key;
        mem.navStalls = 0;
      }
    }
  }

  function chooseSteer(rel, maxSpeed, key) {
    rel = wrap(rel);
    if (Math.abs(rel) > 82) return rel;

    var look = 3.0 + 2.0 * maxSpeed;
    var candidates = [clamp(rel, -80, 80)];
    for (var a = -80; a <= 80; a += 10) candidates.push(a);

    var bestAngle = candidates[0];
    var bestCost = Infinity;

    for (var ci = 0; ci < candidates.length; ci++) {
      var angle = candidates[ci];
      var clear = rayAt(angle);
      var deviation = Math.abs(wrap(rel - angle));
      var blocked = Math.max(0, look - clear);
      var cost = 0.045 * deviation + 1.25 * blocked * blocked;

      if (clear < 1.15) cost += 70;
      var edge = edgeDistance(angle);
      if (edge < 4.5) {
        cost += 1.1 * (4.5 - edge) * (4.5 - edge);
      }
      if (mem.steerKey === key && Number.isFinite(mem.steerAngle)) {
        cost += 0.003 * Math.abs(angle - mem.steerAngle);
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = angle;
      }
    }

    mem.steerKey = key;
    mem.steerAngle = bestAngle;
    return bestAngle;
  }

  function navigateRelative(rel, d, maxSpeed, stopD, key) {
    rel = wrap(num(rel, 0));
    d = Math.max(0, num(d, 999));
    maxSpeed = clamp(maxSpeed, 0.10, 0.90);
    stopD = Math.max(0, stopD);

    if (d <= stopD) return drive(0, 0, false, "hold");

    watchNavigation(key, d, stopD);
    if (now < num(mem.recoverUntil, -1)) return escapeAction();

    var chosen = chooseSteer(rel, maxSpeed, key);
    var errDeg = wrap(chosen);
    var errRad = errDeg * Math.PI / 180;

    if (Math.abs(errDeg) > 42) {
      var sign;
      if (Math.abs(errDeg) > 155 &&
          mem.turnSignKey === key &&
          now < num(mem.turnSignUntil, -1) &&
          num(mem.turnSign, 0) !== 0) {
        sign = num(mem.turnSign, errDeg > 0 ? 1 : -1);
      } else {
        sign = errDeg > 0 ? 1 : -1;
        mem.turnSign = sign;
        mem.turnSignKey = key;
        mem.turnSignUntil = now + 3.0;
      }
      return drive(0, sign * 0.82, false, "turn");
    }

    var travel = Math.max(0, d - stopD);
    var speed = Math.min(maxSpeed, Math.sqrt(0.30 * travel));
    speed *= clamp(Math.cos(errRad), 0.35, 1);

    if (Math.abs(errDeg) > 25) speed *= 0.70;
    else if (Math.abs(errDeg) > 12) speed *= 0.86;

    var clearPath = rayAt(chosen);
    if (clearPath < 5.0) {
      speed *= clamp((clearPath - 1.15) / 3.85, 0.12, 1);
    }
    if (clearPath < 1.25) speed = 0;
    if (rayBlind) speed = Math.min(speed, 0.48);

    var edge = edgeDistance(chosen);
    if (edge < 3.0) speed = Math.min(speed, 0.22);
    else if (edge < 6.0) speed = Math.min(speed, 0.42);

    var omega = clamp(1.25 * errRad, -0.75, 0.75);
    if (Math.abs(errDeg) < 2.0) omega = 0;
    return drive(speed, omega, false, "nav");
  }

  function navigateToPoint(tx, ty, maxSpeed, stopD, key) {
    tx = mapX(tx);
    ty = mapY(ty);
    var dx = tx - mem.px;
    var dy = ty - mem.py;
    var d = Math.sqrt(dx * dx + dy * dy);
    var worldBearing = Math.atan2(dy, dx) * 180 / Math.PI;
    return navigateRelative(
      wrap(worldBearing - mem.yaw),
      d,
      maxSpeed,
      stopD,
      key
    );
  }

  function getTarget(id) {
    var n = Number(id);
    if (!Number.isFinite(n) || n < 0 || n >= mem.targets.length) return null;
    return mem.targets[Math.floor(n)];
  }

  function addTarget(x, y, val, source, radius) {
    x = mapX(x);
    y = mapY(y);
    var t = {
      id: mem.targets.length,
      source: source || "hint",
      x: x,
      y: y,
      originX: x,
      originY: y,
      val: Math.max(1, num(val, 5)),
      radius: Math.max(8, num(radius, 18)),
      done: false,
      bad: false,
      searchStarted: false,
      points: [],
      searchIndex: 0,
      refines: 0,
      bestScience: 0,
      startScience: 0,
      bestX: x,
      bestY: y,
      skipped: 0
    };
    mem.targets.push(t);
    return t;
  }

  function markDone(id) {
    var t = getTarget(id);
    if (t) {
      t.done = true;
      t.bad = false;
      t.doneTime = now;
    }
    if (Number(mem.activeId) === Number(id)) mem.activeId = -1;
  }

  function buildSearchPath(cx, cy, radius, id) {
    var pts = [];

    function addPoint(px, py) {
      px = mapX(px);
      py = mapY(py);
      var last = pts.length ? pts[pts.length - 1] : null;
      if (!last || dist(px, py, last.x, last.y) > 4.5) {
        pts.push({ x: px, y: py });
      }
    }

    addPoint(cx, cy);
    var pitchSpacing = 12;
    var b = pitchSpacing / (2 * Math.PI);
    var theta = 0.55;
    var phase = (id * 2.399963229728653) % (2 * Math.PI);
    var guard = 0;

    while (b * theta <= radius && guard < 180) {
      var r = b * theta;
      var a = theta + phase;
      addPoint(cx + r * Math.cos(a), cy + r * Math.sin(a));

      var step = 5.5 / Math.sqrt(r * r + b * b);
      theta += clamp(step, 0.18, 1.45);
      guard++;
    }
    return pts;
  }

  function beginSearch(t, cx, cy, radius) {
    t.searchStarted = true;
    t.centerX = mapX(cx);
    t.centerY = mapY(cy);
    t.radius = Math.max(8, num(radius, 18));
    t.points = buildSearchPath(t.centerX, t.centerY, t.radius, t.id);
    t.searchIndex = 0;
    t.startScience = science;
    t.bestScience = science;
    t.bestX = mem.px;
    t.bestY = mem.py;
  }

  function observeScience(t) {
    var best = num(t.bestScience, 0);
    if (science > best + Math.max(0.003, best * 0.05)) {
      t.bestScience = science;
      t.bestX = mem.px;
      t.bestY = mem.py;
    }
  }

  function expectedScanLength(t) {
    var r = Math.max(8, num(t.radius, 18));
    return Math.min(180, Math.PI * r * r / 12 + 6);
  }

  function remainingSearch(t) {
    if (!t.searchStarted) return expectedScanLength(t);

    var pts = Array.isArray(t.points) ? t.points : [];
    var idx = Math.max(0, Math.floor(num(t.searchIndex, 0)));
    if (idx >= pts.length) return 0;

    var total = dist(mem.px, mem.py, pts[idx].x, pts[idx].y);
    for (var i = idx; i + 1 < pts.length; i++) {
      total += dist(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
    }
    return total;
  }

  function targetRoute(t) {
    var scan = remainingSearch(t);
    if (t.searchStarted) {
      var pts = Array.isArray(t.points) ? t.points : [];
      var end = pts.length ? pts[pts.length - 1] : {
        x: num(t.centerX, t.x),
        y: num(t.centerY, t.y)
      };
      return scan + dist(end.x, end.y, mem.baseX, mem.baseY) + 12;
    }

    return dist(mem.px, mem.py, t.x, t.y) +
      scan +
      dist(t.x, t.y, mem.baseX, mem.baseY) +
      0.55 * Math.max(8, num(t.radius, 18)) +
      12;
  }

  function targetNeed(t) {
    var route = targetRoute(t);
    return 0.09 +
      mem.energyPerM * route * (1 + 0.16 * carried) * 1.42 +
      0.025 * (carried + 1);
  }

  function targetFeasible(t, atDock) {
    if (!t || t.done || t.bad) return false;

    var route = targetRoute(t);
    var need = 0.09 +
      mem.energyPerM * route * (1 + 0.16 * carried) * 1.42 +
      0.025 * (carried + 1);
    var planSpeed = clamp(num(mem.speedEst, 0.65) * 0.78, 0.42, 1.10);
    var eta = route / planSpeed * 1.18 + 22 + 7 * (carried + 1);

    if (timeLeft < eta + 8) return false;
    if (atDock) return need <= 1.20;
    return battery > need + 0.055;
  }

  function targetScore(t) {
    var dHere = dist(mem.px, mem.py, t.x, t.y);
    var dBase = dist(t.x, t.y, mem.baseX, mem.baseY);
    var scan = t.searchStarted ? remainingSearch(t) : expectedScanLength(t);
    var value = Math.max(1, num(t.val, 5));

    if (t.source === "scout") value *= 0.72;
    if (t.source === "signal") value *= 0.90;
    if (t.bestScience > 0) {
      value *= 1 + Math.min(0.35, t.bestScience * 0.20);
    }

    return value /
      Math.max(25, 34 + dHere + 0.52 * scan + 0.70 * dBase);
  }

  function selectTarget(atDock) {
    var active = getTarget(mem.activeId);
    if (active && targetFeasible(active, atDock)) return active;

    var best = null;
    var bestScore = -1;
    for (var i = 0; i < mem.targets.length; i++) {
      var t = mem.targets[i];
      if (!targetFeasible(t, atDock)) continue;
      var score = targetScore(t);
      if (score > bestScore) {
        bestScore = score;
        best = t;
      }
    }

    mem.activeId = best ? best.id : -1;
    return best;
  }

  function anyPendingTarget() {
    for (var i = 0; i < mem.targets.length; i++) {
      if (!mem.targets[i].done && !mem.targets[i].bad) return true;
    }
    return false;
  }

  function createSignalTarget() {
    if (science < 0.055 || num(mem.signalCount, 0) >= 6) return null;

    for (var i = 0; i < mem.targets.length; i++) {
      var old = mem.targets[i];
      if (dist(mem.px, mem.py, old.x, old.y) < 23 &&
          !old.done && !old.bad) return null;
      if (old.source === "signal" &&
          dist(mem.px, mem.py, old.x, old.y) < 28) return null;
    }

    var value = clamp(10 + 40 * Math.sqrt(science), 10, 58);
    var radius = science > 0.32 ? 14 : 16;
    var t = addTarget(mem.px, mem.py, value, "signal", radius);
    beginSearch(t, mem.px, mem.py, radius);
    mem.signalCount = num(mem.signalCount, 0) + 1;
    return t;
  }

  function createScout() {
    if (timeLeft < 65 || num(mem.scoutIndex, 0) >= 96 ||
        anyPendingTarget()) return null;

    for (var tries = 0; tries < 24; tries++) {
      var idx = mem.scoutIndex++;
      var ring = Math.floor(idx / 8);
