        continue;
      }

      var key = "s_" + t.id + "_" + t.searchIndex;
      if (mem.failedKey === key) {
        mem.failedKey = null;
        t.searchIndex++;
        t.skipped = num(t.skipped, 0) + 1;
        if (t.skipped >= 8) {
          t.bad = true;
          if (Number(mem.activeId) === Number(t.id)) mem.activeId = -1;
