      var worldBearing = (mem.yaw + bearing) * Math.PI / 180;
      p.siteX = mem.px + sd * Math.cos(worldBearing);
      p.siteY = mem.py + sd * Math.sin(worldBearing);

      if (sd > 1.40) {
