      if (wallD > 10) offset = side * 25;

      const tb = Math.atan2(dy, dx) * DEG;
      const erel = wrapDeg(tb - navHdg);
      const clearT = rayAtDeg(clamp(erel, -80, 80), R);

      if (Math.abs(erel) < 85 && clearT > 4.8 && R[4] > 3.0 && d > 5) {
        if (!mem2.wall.clearSince) mem2.wall.clearSince = obs2.t;
        else if (obs2.t - mem2.wall.clearSince > 0.8) {
          mem2.wall = null;
        }
      } else {
        mem2.wall.clearSince = 0;
      }

      if (mem2.wall) {
        return steerRel(offset, Math.min(speed, 1.25), obs2, mem2, R, navHdg);
      }
    }

    if (mem2.wall && obs2.t >= mem2.wall.until) {
      mem2.wall = null;
    }

    let sp = speed;
    if (d < 8) sp = Math.min(sp, 0.60 + d * 0.14);
    if (d < 3) sp = Math.min(sp, 0.45);
    if (d < 0.8) sp = 0;

    const tb = Math.atan2(dy, dx) * DEG;
    const er = wrapDeg(tb - navHdg);
    return steerRel(er, sp, obs2, mem2, R, navHdg);
  }

  function driveBase(obs2, mem2, R, navHdg, urgent) {
    const db = distXY(mem2.pos.x, mem2.pos.y, mem2.base.x, mem2.base.y);
    const wheelMax = Math.max(
      Math.abs(isFinite(+obs2.wheelLeft) ? +obs2.wheelLeft : 0),
      Math.abs(isFinite(+obs2.wheelRight) ? +obs2.wheelRight : 0)
    );
    if (obs2.docked) return setMotors(0, 0, obs2, mem2);
    if (db < 0.85) return setMotors(0, 0, obs2, mem2);

    if (db < 3.0) {
      if (wheelMax > 0.12) return setMotors(0, 0, obs2, mem2);
      let br;
      if (obs2.beacon && isFinite(obs2.beacon.bearing)) {
        br = obs2.beacon.bearing;
      } else {
        const tb = Math.atan2(mem2.base.y - mem2.pos.y, mem2.base.x - mem2.pos.x) * DEG;
        br = wrapDeg(tb - navHdg);
      }
      return steerRel(br, 0.11, obs2, mem2, R, navHdg);
    }

    if (obs2.beacon && isFinite(obs2.beacon.bearing) &&
        obs2.beacon.distance < 20) {
      let sp = db > 15 ? 2.1 : (db > 6 ? 1.15 : 0.60);
      if (urgent && db > 30) sp = Math.min(2.35, sp + 0.15);
      return steerRel(obs2.beacon.bearing, sp, obs2, mem2, R, navHdg);
    }

    let sp = db > 15 ? 2.1 : (db > 6 ? 1.2 : 0.62);
    if (urgent && db > 30) sp = Math.min(2.35, sp + 0.15);
    return navTo(mem2.base.x, mem2.base.y, sp, obs2, mem2, R, navHdg, "base", true);
  }

  function holdStation(obs2, mem2, drillOn) {
    let tl = 0, tr = 0;
    const dr = mem2.drill;
    if (dr && dr.pos) {
      const dx = dr.pos.x - mem2.pos.x;
      const dy = dr.pos.y - mem2.pos.y;
      const dp = hypot2(dx, dy);
      if (dp > 0.28) {
        const bh = Math.atan2(dy, dx) * DEG;
        const er = wrapDeg(bh - (mem2.hdg - (mem2.bias || 0)));
        if (Math.abs(er) < 60) {
          const v = Math.min(0.10, (dp - 0.18) * 0.5);
          const rate = clamp(er * RAD * 1.2, -0.6, 0.6);
          tl = v - rate * 0.06;
          tr = v + rate * 0.06;
        } else {
          const rr = (er >= 0 ? 1 : -1) * 0.06;
          tl = -rr;
          tr = rr;
        }
      }
    }
    const c = setMotors(tl, tr, obs2, mem2);
    c.drill = !!drillOn;
    return c;
  }

  function updateScience(obs2, mem2) {
    if (!mem2.sciHist) mem2.sciHist = [];
    let s = isFinite(obs2.science) ? obs2.science : 0;
    if (s < 0) s = 0;
    const last = mem2.sciHist.length ? mem2.sciHist[mem2.sciHist.length - 1] : null;
    if (!last || obs2.t - last.t > 0.75 ||
        distXY(last.x, last.y, mem2.pos.x, mem2.pos.y) > 0.55) {
      mem2.sciHist.push({ x: mem2.pos.x, y: mem2.pos.y, s: s, t: obs2.t });
      while (mem2.sciHist.length > 32) mem2.sciHist.shift();
    }

    let A = 0, B = 0, C = 0, D = 0, E = 0, n = 0;
    for (let i = 1; i < mem2.sciHist.length; i++) {
      const a = mem2.sciHist[i - 1];
      const b = mem2.sciHist[i];
      const dx = b.x - a.x, dy = b.y - a.y;
      const d2 = dx * dx + dy * dy;
      if (d2 > 0.12) {
        const d = Math.sqrt(d2);
        const ux = dx / d, uy = dy / d;
        const r = (b.s - a.s) / d;
        A += ux * ux; B += ux * uy; C += uy * uy;
        D += ux * r; E += uy * r;
        n++;
      }
    }
    const det = A * C - B * B;
    if (n >= 3 && det > 0.06) {
      const gx = (D * C - E * B) / det;
      const gy = (E * A - D * B) / det;
      if (isFinite(gx) && isFinite(gy) &&
          (gx * gx + gy * gy) < 1e6) {
        mem2.grad = { x: gx, y: gy, t: obs2.t };
      } else {
        mem2.grad = null;
      }
    } else {
      mem2.grad = null;
    }
  }

  function matchVisibleSite(obs2, mem2, navHdg) {
    if (!obs2.site || !isFinite(obs2.site.distance) || !isFinite(obs2.site.bearing)) {
      mem2.visibleCand = null;
      mem2.visibleSite = null;
      return;
    }
    const d = Math.max(0, obs2.site.distance);
    const br = obs2.site.bearing;
    const ang = (navHdg + br) * RAD;
    const sx = mem2.pos.x + d * Math.cos(ang);
    const sy = mem2.pos.y + d * Math.sin(ang);
    const val = isFinite(obs2.site.value) ? obs2.site.value : 1;

    let best = null, bestD = 1e9;
    for (let i = 0; i < mem2.candidates.length; i++) {
      const c = mem2.candidates[i];
      if (c.state === 2) continue;
      const dd = distXY(c.x, c.y, sx, sy);
      if (dd < bestD) {
        bestD = dd;
        best = c;
      }
    }

    if (best && bestD < 35) {
      best.x = best.x * 0.25 + sx * 0.75;
      best.y = best.y * 0.25 + sy * 0.75;
      best.val = val;
      best.discovered = true;
      best.seen = obs2.t;
      if (best.state === 3) best.state = 0;
    } else {
      best = {
        id: mem2.nextId++,
        x: sx, y: sy, val: val,
        state: 0, discovered: true, tries: 0,
        cooldown: 0, seen: obs2.t
      };
      mem2.candidates.push(best);
    }
    mem2.visibleCand = best;
    mem2.visibleSite = {
      cand: best, x: sx, y: sy, d: d,
      bearing: br, value: val
    };
  }

  function needReturn(obs2, mem2, carrying) {
    const db = distXY(mem2.pos.x, mem2.pos.y, mem2.base.x, mem2.base.y);
    const cap = mem2.capacity || 5;
    if (carrying >= cap) return true;
    const bat = isFinite(obs2.battery) ? obs2.battery : 1;
    const baseDrain = mem2.energy && mem2.energy.base ? mem2.energy.base : 0.0016;
    const mult = 1 + 0.12 * carrying;
    const needE = db * baseDrain * mult * 1.55 + 0.045;
    if (bat < needE + 0.025) {
      if (carrying > 0 || db > 8) return true;
    }
    if (bat < 0.075) return true;
    if (carrying > 0) {
      const rt = db / 1.0 + 12;
      if ((obs2.timeLeft || 0) < rt + 8) return true;
      if ((obs2.timeLeft || 0) < 30) return true;
    } else {
      if (bat < 0.15 && db > 20 && (obs2.timeLeft || 0) > 60) return true;
    }
    return false;
  }

  function chargeNeeded(obs2, mem2) {
    if (!obs2.docked) return false;
    const b = isFinite(obs2.battery) ? obs2.battery : 1;
    if (obs2.timeLeft < 70) return false;
    if (b < 0.52) return true;
    if (b < 0.72 && obs2.timeLeft > 180) return true;
    if (b < 0.86 && obs2.timeLeft > 600) return true;
    return false;
  }

  function chooseCandidate(obs2, mem2, carrying) {
    let best = null, bestScore = -1e18;
    const cap = mem2.capacity || 5;
    for (let i = 0; i < mem2.candidates.length; i++) {
      const c = mem2.candidates[i];
      if (c.state >= 2) continue;
      if (c.cooldown && c.cooldown > obs2.t) continue;

      const d = distXY(mem2.pos.x, mem2.pos.y, c.x, c.y);
      const db = distXY(mem2.base.x, mem2.base.y, c.x, c.y);
      let val = isFinite(c.val) && c.val > 0 ? c.val : 0.1;

      let score = Math.pow(val, 0.92) / (d + 25);
      if (c.discovered) score *= 1.22;
      if (c.tries > 0) score *= 0.82;

      const tLeft = obs2.timeLeft || 0;
      const timeTo = d / 0.82 + 8;
      const timeBack = db / 0.82 + 12;
      if (carrying + 1 >= cap) {
        if (tLeft < timeTo + timeBack + 8) score *= 0.015;
      } else {
        if (tLeft < timeTo + 20) score *= 0.05;
      }

      if (carrying > 0) {
        const curDb = distXY(mem2.pos.x, mem2.pos.y, mem2.base.x, mem2.base.y);
        if (db > curDb + 30) score *= 0.88;
      }

      if (score > bestScore) {
        bestScore = score;
        best = c;
      }
    }
    return best;
  }

  function chooseExplore(obs2, mem2) {
    let best = null, bestD = 1e9;
    for (let i = 0; i < mem2.explorePts.length; i++) {
      const p = mem2.explorePts[i];
      if (p.used) continue;
      const d = distXY(mem2.pos.x, mem2.pos.y, p.x, p.y);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }
    return best;
  }

  let wl = isFinite(+obs.wheelLeft) ? +obs.wheelLeft : 0;
  let wr = isFinite(+obs.wheelRight) ? +obs.wheelRight : 0;
  let speedAvg = (wl + wr) * 0.5;
  let wheelMax = Math.max(Math.abs(wl), Math.abs(wr));

  let headingMeas = isFinite(obs.heading) ? wrapDeg(obs.heading) : mem.hdg;
  let yawWheel = (wr - wl) / 0.6;
  let diffH = wrapDeg(headingMeas - mem.hdg);
  let allowH = Math.max(35, Math.abs(yawWheel * dt * DEG) * 2 + 15);
  if (Math.abs(diffH) <= allowH) {
    mem.hdg = wrapDeg(mem.hdg + 0.65 * diffH);
    mem.headJump = 0;
  } else {
    mem.headJump = (mem.headJump || 0) + 1;
    if (mem.headJump > 15) mem.hdg = wrapDeg(mem.hdg + 0.12 * diffH);
  }

  const midRad = (mem.hdg - yawWheel * dt * DEG * 0.5) * RAD;
  const deadX = mem.pos.x + speedAvg * Math.cos(midRad) * dt;
  const deadY = mem.pos.y + speedAvg * Math.sin(midRad) * dt;

  let gpsChanged = false;
  if (isFinite(+obs.x) && isFinite(+obs.y)) {
    const gx = +obs.x, gy = +obs.y;
    const moved = distXY(mem.gpsPrev.x, mem.gpsPrev.y, gx, gy);
    if (moved > 0.03) {
      const interval = obs.t - mem.lastGpsChangeT;
      if (interval > 0.1 && interval < 12) {
        mem.gpsInterval = mem.gpsInterval * 0.85 + interval * 0.15;
      }
      mem.lastGpsChangeT = obs.t;
      mem.gpsPrev.x = gx;
      mem.gpsPrev.y = gy;
      gpsChanged = true;
    }
    const stale = obs.t - mem.lastGpsChangeT;
    const frozenThresh = Math.max(2.5, (mem.gpsInterval || 1) * 3 + 0.8);
    if (stale > frozenThresh && Math.abs(speedAvg) > 0.2) {
      mem.gpsFrozen = true;
    }

    if (gpsChanged) {
      const innov = distXY(deadX, deadY, gx, gy);
      const maxInnov = Math.max(6, Math.abs(speedAvg) * (stale + 0.5) * 1.8 + 5);
      if (!mem.gpsFrozen || innov < maxInnov) {
        mem.pos.x = deadX + (gx - deadX) * 0.68;
        mem.pos.y = deadY + (gy - deadY) * 0.68;
        if (mem.gpsFrozen && innov < maxInnov) mem.gpsFrozen = false;
      } else {
        mem.pos.x = deadX;
        mem.pos.y = deadY;
      }
    } else {
      mem.pos.x = deadX;
      mem.pos.y = deadY;
      if (stale < 0.7) mem.gpsFrozen = false;
    }
  } else {
    mem.pos.x = deadX;
    mem.pos.y = deadY;
  }

  if (!mem.gpsFrozen && gpsChanged && Math.abs(speedAvg) > 0.5) {
    if (!mem.coursePrev) {
      mem.coursePrev = { x: obs.x, y: obs.y, t: obs.t, h: mem.hdg };
    } else if (obs.t - mem.coursePrev.t > 1.2) {
      const dx = obs.x - mem.coursePrev.x;
      const dy = obs.y - mem.coursePrev.y;
      const dd = hypot2(dx, dy);
      if (dd > 1.2 && Math.abs(wrapDeg(mem.hdg - mem.coursePrev.h)) < 8) {
        const course = Math.atan2(dy, dx) * DEG;
        const bInst = wrapDeg((mem.coursePrev.h + mem.hdg) * 0.5 - course);
        if (Math.abs(bInst) < 60) {
          mem.bias = wrapDeg((mem.bias || 0) * 0.96 + bInst * 0.04);
        }
      }
      mem.coursePrev = { x: obs.x, y: obs.y, t: obs.t, h: mem.hdg };
    }
  } else if (!mem.coursePrev || obs.t - mem.coursePrev.t > 4) {
    mem.coursePrev = null;
  }

  const navHdg = wrapDeg(mem.hdg - (mem.bias || 0));

  const R = new Array(9);
  const rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    let val = +rawRays[i];
    if (!isFinite(val) || val < 0) val = 15;
    if (val > 15) val = 15;
    const prevVal = isFinite(mem.rayPrev[i]) ? mem.rayPrev[i] : val;
    if (Math.abs(val - prevVal) < 0.005 && val < 14.9) {
      mem.raySame[i]++;
    } else {
      mem.raySame[i] = 0;
    }
    mem.rayPrev[i] = val;
    if (mem.raySame[i] > 35) mem.rayBad[i] = obs.t + 5;
    R[i] = val;
  }
  mem.nearBlock = (R[4] < 1.0 || !!mem.wall);

  updateScience(obs, mem);

  if (mem.energy) {
    const pB = mem.energy.prevB;
    const bat = isFinite(obs.battery) ? obs.battery : pB;
    const solar = isFinite(obs.solar) ? obs.solar : 0;
    const dB = pB + solar * dt - bat;
    const moved = distXY(mem.energy.prevX, mem.energy.prevY, mem.pos.x, mem.pos.y);
    if (!obs.docked && !mem.drill && moved > 0.04 && dB > 0 && dB < 0.08) {
      const ratio = dB / moved;
      if (ratio > 0.00001 && ratio < 0.02) {
        const carriedNow = obs.carried || 0;
        const baseRatio = ratio / (1 + 0.12 * carriedNow);
        const n = mem.energy.n || 0;
        if (n === 0) mem.energy.base = baseRatio;
        else mem.energy.base = mem.energy.base * 0.98 + baseRatio * 0.02;
        mem.energy.n = Math.min(60, n + 1);
      }
    }
    if (isFinite(obs.battery)) mem.energy.prevB = obs.battery;
    mem.energy.prevX = mem.pos.x;
    mem.energy.prevY = mem.pos.y;
    mem.drainPerM = mem.energy.base || 0.0016;
  }

  matchVisibleSite(obs, mem, navHdg);

  const bumpNow = !!obs.bumped;
  const bumpVal = (typeof obs.bumped === "number") ? obs.bumped : (bumpNow ? 1 : 0);
  const newBump = bumpNow && (!mem.bumpPrev || bumpVal > (mem.bumpPrevVal || 0));
  if (newBump) {
    const leftOpen = (R[6] || 0) + (R[7] || 0) + (R[8] || 0);
    const rightOpen = (R[0] || 0) + (R[1] || 0) + (R[2] || 0);
    mem.avoidDir = leftOpen > rightOpen ? 45 : -45;
    mem.bumpT = obs.t;
    mem.drive.iL = 0;
    mem.drive.iR = 0;
    if (mem.target) mem.target.bumps = (mem.target.bumps || 0) + 1;
  }
  mem.bumpPrev = bumpNow;
  mem.bumpPrevVal = bumpVal;

  mem.lastT = obs.t;

  if (mem.drill) {
    const dr = mem.drill;
    const carriedNow = obs.carried || 0;
    if (carriedNow > dr.startCarried) {
      if (dr.cand && dr.cand.state !== 2) dr.cand.state = 2;
      mem.samples.push({
        t: obs.t, x: dr.pos ? dr.pos.x : mem.pos.x,
        y: dr.pos ? dr.pos.y : mem.pos.y, value: dr.value || 0
      });
      mem.drill = null;
      mem.search = null;
      mem.target = null;
      mem.travel = null;
      mem.wall = null;
      mem.sciHist = [];
      mem.grad = null;
      mem.returning = false;
    } else {
      const resetDrill = (dr.lastDrill || 0) > 0.2 &&
        ((isFinite(obs.drilling) ? obs.drilling : 0) < dr.lastDrill - 0.35);
      if (!obs.site || obs.site.distance > 1.70 || resetDrill || obs.bumped) {
        mem.drill = null;
        return setMotors(0, 0, obs, mem);
      } else {
        dr.lastDrill = isFinite(obs.drilling) ? obs.drilling : 0;
        return holdStation(obs, mem, true);
      }
    }
  }

  if (mem.bumpT !== undefined && obs.t - mem.bumpT < 1.05) {
    mem.drive.iL = 0;
    mem.drive.iR = 0;
    return setMotors(-0.55, -0.55, obs, mem);
  }
  if (mem.bumpT !== undefined && obs.t - mem.bumpT < 2.0) {
    const dir = (mem.avoidDir || 45) >= 0 ? 1 : -1;
    return setMotors(-0.43 * dir, 0.43 * dir, obs, mem);
  }

  const carrying = obs.carried || 0;
  const cap = mem.capacity || 5;
  const dbNow = distXY(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);

  if (carrying > 0 && (obs.docked || dbNow < 3.4)) {
    if (obs.docked) {
      return setMotors(0, 0, obs, mem);
    }
    return driveBase(obs, mem, R, navHdg, true);
  }

  let urgent = needReturn(obs, mem, carrying);
  if (urgent) mem.returning = true;

  if (mem.returning) {
    if (obs.docked) {
      if (carrying === 0) {
        if (chargeNeeded(obs, mem)) return setMotors(0, 0, obs, mem);
        if ((isFinite(obs.battery) ? obs.battery : 1) > 0.45) mem.returning = false;
      } else {
        return setMotors(0, 0, obs, mem);
      }
    } else if (dbNow < 1.8 && carrying === 0) {
      if (chargeNeeded(obs, mem)) return driveBase(obs, mem, R, navHdg, true);
      mem.returning = false;
    } else {
      return driveBase(obs, mem, R, navHdg, urgent);
    }
  }

  if (carrying === 0 && obs.docked && chargeNeeded(obs, mem)) {
    return setMotors(0, 0, obs, mem);
  }
  if (carrying === 0 && !obs.docked && dbNow < 4.0 && chargeNeeded(obs, mem)) {
    return driveBase(obs, mem, R, navHdg, false);
  }

  if (obs.site && carrying < cap && !mem.returning) {
    const dSite = obs.site.distance;
    const brSite = obs.site.bearing;
    const stillEnough = Math.max(Math.abs(wl), Math.abs(wr)) < 0.18;

    if (dSite < 1.48 && stillEnough) {
      mem.drill = {
        startCarried: carrying,
        cand: mem.visibleCand,
        pos: { x: mem.pos.x, y: mem.pos.y },
        t0: obs.t,
        lastDrill: isFinite(obs.drilling) ? obs.drilling : 0,
        value: obs.site.value
      };
      return holdStation(obs, mem, true);
    }

    if (dSite < 1.55 && wheelMax > 0.10) {
      return setMotors(0, 0, obs, mem);
    }

    let sp = 1.8;
    if (dSite > 6) sp = 1.9;
    else if (dSite > 3) sp = 1.1;
    else if (dSite > 1.8) sp = 0.58;
    else if (dSite > 1.42) sp = 0.20;
    else sp = 0;
    if (dSite < 2.4) sp = Math.min(sp, Math.max(0, (dSite - 1.25) * 0.65));
    if (sp < 0.05) return setMotors(0, 0, obs, mem);
    return steerRel(brSite, sp, obs, mem, R, navHdg);
  }

  if (mem.search) {
    const s = mem.search;
    if (obs.t - s.startT > 95) {
      if (s.c && s.c.state < 2) s.c.state = 3;
      mem.search = null;
      mem.target = null;
      mem.travel = null;
      mem.wall = null;
      return setMotors(0, 0, obs, mem);
    }

    let rad = 14.0;
    let wx = s.cx + rad * Math.cos(s.ang);
    let wy = s.cy + rad * Math.sin(s.ang);
    let dW = distXY(mem.pos.x, mem.pos.y, wx, wy);

    if (dW < 2.6 || obs.t - s.lastAdv > 12) {
      s.ang += 0.34906585;
      s.steps++;
      s.lastAdv = obs.t;
      if (s.steps >= 18) {
        if (s.c && s.c.state < 2) {
          s.c.state = 3;
          s.c.tries = (s.c.tries || 0) + 1;
        }
        mem.search = null;
        mem.target = null;
        mem.travel = null;
        mem.wall = null;
        return setMotors(0, 0, obs, mem);
      }
      wx = s.cx + rad * Math.cos(s.ang);
      wy = s.cy + rad * Math.sin(s.ang);
      dW = distXY(mem.pos.x, mem.pos.y, wx, wy);
    }

    const sci = isFinite(obs.science) ? obs.science : 0;
    if (!s.maxS || sci > s.maxS) s.maxS = sci;
    if (obs.t - s.startT > 14 && s.maxS < 1e-9) {
      if (s.c && s.c.state < 2) s.c.state = 3;
      mem.search = null;
      mem.target = null;
      mem.travel = null;
      mem.wall = null;
      return setMotors(0, 0, obs, mem);
    }

    const tb = Math.atan2(wy - mem.pos.y, wx - mem.pos.x) * DEG;
    const er = wrapDeg(tb - navHdg);
    let sp = dW < 3 ? 0.75 : 1.55;
    return steerRel(er, sp, obs, mem, R, navHdg);
  }

  if (mem.target) {
    const tg = mem.target;
    if (tg.c && tg.c.state >= 2) {
      mem.target = null;
      mem.travel = null;
      mem.wall = null;
    } else {
      const dT = distXY(mem.pos.x, mem.pos.y, tg.x, tg.y);

      if (tg.type === "hint" && dT < 4.5) {
        const sci = isFinite(obs.science) ? obs.science : 0;
        if (sci < 1e-9) {
          if (tg.c) tg.c.state = 3;
          mem.target = null;
          mem.travel = null;
          mem.wall = null;
          return setMotors(0, 0, obs, mem);
        }
        let ang = Math.atan2(mem.pos.y - tg.y, mem.pos.x - tg.x);
        if (!isFinite(ang) || dT < 2.0) ang = 0;
        mem.search = {
          c: tg.c,
          cx: tg.c ? tg.c.x : tg.x,
          cy: tg.c ? tg.c.y : tg.y,
          ang: ang,
          steps: 0,
          lastAdv: obs.t,
          startT: obs.t,
          maxS: sci
        };
        mem.target = null;
        mem.travel = null;
        mem.wall = null;
        return setMotors(0, 0, obs, mem);
      }

      if (tg.type === "site" && dT < 1.8 && !obs.site) {
        if (tg.c) tg.c.state = 3;
        mem.target = null;
        mem.travel = null;
        mem.wall = null;
        return setMotors(0, 0, obs, mem);
      }

      const key = "t" + (tg.c ? tg.c.id : (tg.x + "," + tg.y));
      const cmd = navTo(tg.x, tg.y, 2.12, obs, mem, R, navHdg, key, false);
      if (mem.abandonTarget) {
        mem.abandonTarget = false;
        if (tg.c) tg.c.state = 3;
        mem.target = null;
        mem.travel = null;
        mem.wall = null;
        return setMotors(0, 0, obs, mem);
      }
      return cmd;
    }
  }

  const c = chooseCandidate(obs, mem, carrying);
  if (c) {
    const typ = c.discovered ? "site" : "hint";
    mem.target = {
      c: c, x: c.x, y: c.y, type: typ, bumps: 0
    };
    mem.travel = null;
    mem.wall = null;
    const key = "t" + c.id;
    return navTo(c.x, c.y, 2.12, obs, mem, R, navHdg, key, false);
  }

  if (carrying > 0) {
    mem.returning = true;
    return driveBase(obs, mem, R, navHdg, true);
  }

  const sciNow = isFinite(obs.science) ? obs.science : 0;
  if (sciNow > 1e-7 && mem.grad && isFinite(mem.grad.x) && isFinite(mem.grad.y) &&
      obs.t - mem.grad.t < 6) {
    const gl = hypot2(mem.grad.x, mem.grad.y);
    if (gl > 1e-9) {
      let gx = mem.pos.x + (mem.grad.x / gl) * 26;
      let gy = mem.pos.y + (mem.grad.y / gl) * 26;
      gx = clamp(gx, 4, mem.size - 4);
      gy = clamp(gy, 4, mem.size - 4);
      const key = "g" + Math.floor(obs.t / 5);
      return navTo(gx, gy, 1.75, obs, mem, R, navHdg, key, false);
    }
  }

  let ep = chooseExplore(obs, mem);
  if (!ep) {
    const ang = (obs.t * 0.037) % (2 * PI);
    const rad = 70 + 50 * Math.sin(obs.t * 0.011);
    let wx = clamp(mem.pos.x + Math.cos(ang) * rad, 8, mem.size - 8);
    let wy = clamp(mem.pos.y + Math.sin(ang) * rad, 8, mem.size - 8);
    return navTo(wx, wy, 1.55, obs, mem, R, navHdg, "wx" + Math.floor(obs.t / 8), false);
  }

  const dEp = distXY(mem.pos.x, mem.pos.y, ep.x, ep.y);
  if (dEp < 6.0) {
    ep.used = true;
    if (sciNow > 1e-8) {
      mem.search = {
        c: null, cx: ep.x, cy: ep.y,
        ang: 0, steps: 0,
        lastAdv: obs.t, startT: obs.t,
        maxS: sciNow
      };
      mem.target = null;
      mem.travel = null;
      mem.wall = null;
      return setMotors(0, 0, obs, mem);
    }
    return setMotors(0, 0, obs, mem);
  }

  const keyE = "e" + ep.x + "," + ep.y;
  const cmdE = navTo(ep.x, ep.y, 1.75, obs, mem, R, navHdg, keyE, false);
  if (mem.abandonTarget) {
    mem.abandonTarget = false;
    ep.used = true;
    mem.travel = null;
    mem.wall = null;
    return setMotors(0, 0, obs, mem);
  }
  return cmdE;
}

function act(obs, mem) {
  "use strict";
  const PI = Math.PI;
  const RAD = PI / 180;
  const DEG = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrapDeg(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }
  function hypot2(x, y) { return Math.sqrt(x * x + y * y); }
  function dist(x1, y1, x2, y2) { return hypot2(x2 - x1, y2 - y1); }

  if (!mem || typeof mem !== "object") mem = {};

  if (!mem.init) {
    mem.init = 1;
    const mis = obs.mission || {};
    mem.size = isFinite(+mis.size) ? +mis.size : 400;
    mem.missionSeconds = isFinite(+mis.seconds) ? +mis.seconds : 1200;
    mem.capacity = isFinite(+mis.capacity) ? +mis.capacity : 5;
    mem.base = {
      x: (mis.base && isFinite(+mis.base.x)) ? +mis.base.x : +obs.x,
      y: (mis.base && isFinite(+mis.base.y)) ? +mis.base.y : +obs.y
    };

    mem.cands = [];
    const hs = Array.isArray(mis.hints) ? mis.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = +h.x, hy = +h.y;
      if (!isFinite(hx) || !isFinite(hy)) continue;
      let hv = +h.estimate;
      if (!isFinite(hv) || hv <= 0) hv = 1;
      mem.cands.push({
        id: i,
        x: hx, y: hy, val: hv,
        state: 0,
        discovered: false
      });
    }
    mem.nextId = mem.cands.length;

    mem.explore = [];
    for (let gx = 30; gx <= mem.size - 25; gx += 55) {
      for (let gy = 30; gy <= mem.size - 25; gy += 55) {
        if (dist(gx, gy, mem.base.x, mem.base.y) > 18) {
          mem.explore.push({ x: gx, y: gy, used: false });
        }
      }
    }

    mem.pos = { x: +obs.x, y: +obs.y };
    mem.lastRaw = { x: +obs.x, y: +obs.y };
    mem.gpsLast = +obs.t;
    mem.gpsInterval = 1;
    mem.gpsFrozen = false;
    mem.calib = null;

    mem.heading = isFinite(+obs.heading) ? wrapDeg(+obs.heading) : 0;
    mem.headJump = 0;
    mem.bias = 0;
    mem.biasN = 0;

    mem.mc = {
      L: { i: 0, g: 2.5, dz: 0.04, c: 0 },
      R: { i: 0, g: 2.5, dz: 0.04, c: 0 }
    };
    mem.lastCmdF = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;

    mem.energy = {
      prevB: isFinite(+obs.battery) ? +obs.battery : 1,
      prevX: +obs.x,
      prevY: +obs.y,
      drain: 0.0018
    };

    mem.prevBumpVal = 0;
    mem.recoverUntil = -1e9;
    mem.recoverTurn = 1;
    mem.stuck = { t: +obs.t, x: +obs.x, y: +obs.y, c: 0 };

    mem.target = null;
    mem.search = null;
    mem.nav = null;
    mem.visibleCand = null;
    mem.drill = null;
    mem.returning = false;
    mem.samples = 0;
    mem.lastSampleT = -1e9;
    mem.lastT = +obs.t;
  }

  let t = isFinite(+obs.t) ? +obs.t : 0;
  let dt = 0.1;
  if (isFinite(mem.lastT)) {
    let ddt = t - mem.lastT;
    if (ddt > 0.001 && ddt < 2.0) dt = ddt;
  }
  mem.lastT = t;

  let wl = isFinite(+obs.wheelLeft) ? +obs.wheelLeft : 0;
  let wr = isFinite(+obs.wheelRight) ? +obs.wheelRight : 0;
  let speedAvg = (wl + wr) * 0.5;
  let maxWheel = Math.max(Math.abs(wl), Math.abs(wr));

  // Compass filtering and jump rejection.
  let rawH = isFinite(+obs.heading) ? wrapDeg(+obs.heading) : mem.heading;
  let dh = wrapDeg(rawH - mem.heading);
  let predYaw = (wr - wl) / 0.6 * dt * DEG;
  let allowH = Math.max(28, Math.abs(predYaw) * 3 + 10);
  if (Math.abs(dh) < allowH || Math.abs(wrapDeg(dh - predYaw)) < 22) {
    mem.heading = wrapDeg(mem.heading + 0.58 * dh);
    mem.headJump = 0;
  } else {
    mem.headJump = (mem.headJump || 0) + 1;
    if (mem.headJump > 12) {
      mem.heading = wrapDeg(mem.heading + clamp(dh, -6, 6));
    } else {
      mem.heading = wrapDeg(mem.heading + clamp(predYaw, -12, 12));
    }
  }

  let trueHeading = wrapDeg(mem.heading - (mem.bias || 0));

  // Odometry and GPS fusion.
  let hRad = trueHeading * RAD;
  let odx = mem.pos.x + speedAvg * Math.cos(hRad) * dt;
  let ody = mem.pos.y + speedAvg * Math.sin(hRad) * dt;

  let rawX = +obs.x;
  let rawY = +obs.y;
  let rawGood = isFinite(rawX) && isFinite(rawY);

  if (rawGood) {
    let movedRaw = dist(mem.lastRaw.x, mem.lastRaw.y, rawX, rawY);
    if (movedRaw > 0.012) {
      let iv = t - mem.gpsLast;
      if (iv > 0.08 && iv < 12) {
        mem.gpsInterval = mem.gpsInterval * 0.85 + iv * 0.15;
      }
      mem.gpsLast = t;
      mem.lastRaw.x = rawX;
      mem.lastRaw.y = rawY;
      mem.gpsFrozen = false;
    }

    let stale = t - mem.gpsLast;
    if (stale > Math.max(2.2, (mem.gpsInterval || 1) * 3 + 1) && Math.abs(speedAvg) > 0.16) {
      mem.gpsFrozen = true;
    }

    if (!mem.gpsFrozen) {
      let innov = dist(odx, ody, rawX, rawY);
      if (innov < 12 + Math.abs(speedAvg) * stale * 2 + 6) {
        mem.pos.x = odx * 0.25 + rawX * 0.75;
        mem.pos.y = ody * 0.25 + rawY * 0.75;
      } else {
        mem.pos.x = odx;
        mem.pos.y = ody;
      }
    } else {
      mem.pos.x = odx;
      mem.pos.y = ody;
    }
  } else {
    mem.pos.x = odx;
    mem.pos.y = ody;
  }

  // Learn compass bias from straight GPS motion.
  if (!mem.gpsFrozen && rawGood && speedAvg > 0.5 && Math.abs(wl - wr) < 0.8) {
    if (!mem.calib) {
      mem.calib = { x: rawX, y: rawY, t: t, h: mem.heading };
    } else if (t - mem.calib.t > 1.0) {
      let dd = dist(mem.calib.x, mem.calib.y, rawX, rawY);
      if (dd > 1.0 && Math.abs(wrapDeg(mem.heading - mem.calib.h)) < 15) {
        let course = Math.atan2(rawY - mem.calib.y, rawX - mem.calib.x) * DEG;
        let avgH = wrapDeg(mem.calib.h + wrapDeg(mem.heading - mem.calib.h) * 0.5);
        let bInst = wrapDeg(avgH - course);
        if (Math.abs(wrapDeg(bInst - (mem.bias || 0))) < 50) {
          mem.bias = wrapDeg((mem.bias || 0) + wrapDeg(bInst - (mem.bias || 0)) * 0.12);
          mem.biasN = (mem.biasN || 0) + 1;
        }
      }
      mem.calib = { x: rawX, y: rawY, t: t, h: mem.heading };
    }
  } else {
    if (!mem.calib || t - mem.calib.t > 0.8) mem.calib = null;
  }

  // Beacon gives an absolute bearing when near base; use it to calibrate heading bias.
  let dbForBeacon = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  if (obs.beacon && isFinite(+obs.beacon.bearing) &&
      dbForBeacon > 2.0 && dbForBeacon < 20) {
    let expectedAbs = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
    let trueObs = wrapDeg(expectedAbs - (+obs.beacon.bearing));
    let bInst = wrapDeg(mem.heading - trueObs);
    if (Math.abs(wrapDeg(bInst - (mem.bias || 0))) < 60) {
      mem.bias = wrapDeg((mem.bias || 0) + wrapDeg(bInst - (mem.bias || 0)) * 0.25);
      mem.biasN = (mem.biasN || 0) + 1;
    }
  }

  trueHeading = wrapDeg(mem.heading - (mem.bias || 0));

  // Range readings.
  const R = new Array(9);
  const rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    let v = +rawRays[i];
    if (!isFinite(v) || v < 0) v = 15;
    if (v > 15) v = 15;
    R[i] = v;
  }

  // Energy-use estimate.
  let batNow = isFinite(+obs.battery) ? +obs.battery : 1;
  let solar = isFinite(+obs.solar) ? +obs.solar : 0;
  let moved = dist(mem.energy.prevX, mem.energy.prevY, mem.pos.x, mem.pos.y);
  if (!obs.docked && !(mem.drill && mem.drill.lastDrill > 0.1)) {
    let used = mem.energy.prevB + solar * dt - batNow;
    if (moved > 0.025 && used > 0 && used < 0.10) {
      let ratio = used / moved / (1 + 0.12 * (isFinite(+obs.carried) ? +obs.carried : 0));
      if (ratio > 0.00015 && ratio < 0.012) {
        mem.energy.drain = mem.energy.drain * 0.98 + ratio * 0.02;
      }
    }
  }
  mem.energy.prevB = batNow;
  mem.energy.prevX = mem.pos.x;
  mem.energy.prevY = mem.pos.y;

  // Detect new bump.
  let bumpVal = (typeof obs.bumped === "number") ? (+obs.bumped) : (obs.bumped ? 1 : 0);
  let newBump = bumpVal > 0 && (!mem.prevBumpVal || bumpVal > mem.prevBumpVal);
  if (newBump) {
    let leftOpen = R[6] + R[7] + R[8];
    let rightOpen = R[0] + R[1] + R[2];
    mem.recoverTurn = leftOpen >= rightOpen ? 1 : -1;
    mem.recoverUntil = Math.max(mem.recoverUntil || -1e9, t + 1.05);
    mem.mc.L.i = 0;
    mem.mc.R.i = 0;
  }
  mem.prevBumpVal = bumpVal;

  // Basic stuck detection for commanded forward motion.
  if (!mem.stuck) mem.stuck = { t: t, x: mem.pos.x, y: mem.pos.y, c: 0 };
  if (t - mem.stuck.t > 2.5) {
    let dd = dist(mem.pos.x, mem.pos.y, mem.stuck.x, mem.stuck.y);
    let cmdF = mem.lastCmdF || 0;
    if (cmdF > 0.35 && dd < 0.38 && t > (mem.recoverUntil || -1e9)) {
      mem.stuck.c = (mem.stuck.c || 0) + 1;
    } else {
      mem.stuck.c = Math.max(0, (mem.stuck.c || 0) - 1);
    }
    if (mem.stuck.c >= 3) {
      let leftOpen = R[6] + R[7] + R[8];
      let rightOpen = R[0] + R[1] + R[2];
      mem.recoverTurn = leftOpen >= rightOpen ? 1 : -1;
      mem.recoverUntil = t + 1.2;
      mem.stuck.c = 0;
      mem.mc.L.i = 0;
      mem.mc.R.i = 0;
    }
    mem.stuck.t = t;
    mem.stuck.x = mem.pos.x;
    mem.stuck.y = mem.pos.y;
  }

  function driveWheels(vL, vR) {
    vL = clamp(vL, -3, 3);
    vR = clamp(vR, -3, 3);

    let aL = isFinite(+obs.wheelLeft) ? +obs.wheelLeft : 0;
    let aR = isFinite(+obs.wheelRight) ? +obs.wheelRight : 0;

    if (!mem.mc) mem.mc = {
      L: { i: 0, g: 2.5, dz: 0.04, c: 0 },
      R: { i: 0, g: 2.5, dz: 0.04, c: 0 }
    };
    if (!mem.mc.L) mem.mc.L = { i: 0, g: 2.5, dz: 0.04, c: 0 };
    if (!mem.mc.R) mem.mc.R = { i: 0, g: 2.5, dz: 0.04, c: 0 };

    function ctrl(target, actual, s) {
      let err = target - actual;
      let oldI = s.i;
      s.i += err * dt * 0.8;
      s.i = clamp(s.i, -4, 4);

      let kp = 0.9;
      let ki = 0.45;
      let ff = target / Math.max(0.7, s.g);
      let c = ff + kp * err + ki * s.i;

      if (Math.abs(target) > 0.03 && Math.abs(actual) < 0.08 && Math.abs(c) < s.dz) {
