        c = -1;
      }

      if (Math.abs(c) > 0.25 && Math.abs(actual) > 0.10 && c * actual > 0) {
        let r = Math.abs(actual / c);
        if (r > 0.25 && r < 8) {
          s.g = clamp(s.g * 0.995 + r * 0.005, 0.7, 7);
        }
      }

      if (Math.abs(target) > 0.15 && Math.abs(actual) < 0.04 && Math.abs(c) > s.dz + 0.02) {
