      return c;
    }

    let cL = ctrl(vL, aL, mem.mc.L);
    let cR = ctrl(vR, aR, mem.mc.R);

    mem.lastCmdL = vL;
    mem.lastCmdR = vR;
    mem.lastCmdF = (vL + vR) * 0.5;

    return { left: cL, right: cR, drill: false };
  }

  function driveToBearing(relBearingDeg, speed, allowReverse) {
    let err = wrapDeg(relBearingDeg);
    let v = clamp(speed, 0, 2.5);
    let maxOm = 1.6;
    let absE = Math.abs(err);
    let om = 0;

    if (absE > 120) {
      v = 0;
      om = (err > 0 ? 1 : -1) * maxOm * 0.90;
    } else if (absE > 62) {
      v = Math.min(v, 0.18);
      om = (err > 0 ? 1 : -1) * maxOm * 0.92;
    } else {
      let red = clamp(1 - absE / 135, 0.24, 1);
      v *= red;
      om = clamp(err * RAD * 2.15, -maxOm, maxOm);
    }

    // Frontal obstacle handling.
    let central = Math.min(R[3], R[4], R[5]);
    if (central < 4.5) {
      let leftOpen = R[6] + R[7] + R[8];
      let rightOpen = R[0] + R[1] + R[2];
      let turn = leftOpen >= rightOpen ? 1 : -1;
      if (central < 1.25) {
        v = 0;
        om = turn * maxOm;
      } else {
        let f = clamp((central - 1.2) / 3.3, 0, 1);
        v *= f;
        if (central < 3.2) {
          om += turn * maxOm * 0.65 * clamp((3.2 - central) / 2.0, 0, 1);
        }
      }
    }

    // Hard map-edge avoidance.
    let margin = 6.5;
    if (mem.pos.x < margin || mem.pos.x > mem.size - margin ||
        mem.pos.y < margin || mem.pos.y > mem.size - margin) {
      let toCenter = Math.atan2(mem.size * 0.5 - mem.pos.y, mem.size * 0.5 - mem.pos.x) * DEG;
      let relC = wrapDeg(toCenter - trueHeading);
      err = wrapDeg(err * 0.25 + relC * 0.75);
      if (Math.abs(err) > 25) v = Math.min(v, 0.45);
      om = clamp(err * RAD * 2.0, -maxOm, maxOm);
    }

    if (Math.abs(+obs.pitch || 0) > 18) v = Math.min(v, 1.15);

    let vL = v - om * 0.3;
    let vR = v + om * 0.3;
    return driveWheels(vL, vR);
  }

  function goToPoint(tx, ty, speed, key) {
    let d = dist(mem.pos.x, mem.pos.y, tx, ty);
    if (!mem.nav || mem.nav.key !== key) {
      mem.nav = { key: key, startT: t, lastProgT: t, bestD: d, stuck: 0 };
    }
    let n = mem.nav;
    if (d < n.bestD - 0.6) {
      n.bestD = d;
      n.lastProgT = t;
    }

    if (t - n.lastProgT > 22 && d > 6) {
      n.lastProgT = t;
      n.stuck = (n.stuck || 0) + 1;
      let leftOpen = R[6] + R[7] + R[8];
      let rightOpen = R[0] + R[1] + R[2];
      mem.recoverTurn = leftOpen >= rightOpen ? 1 : -1;
      mem.recoverUntil = Math.max(mem.recoverUntil || -1e9, t + 0.9);
      mem.mc.L.i = 0;
      mem.mc.R.i = 0;
      if (n.stuck >= 4) {
        mem.nav = null;
        return null;
      }
    }

    let abs = Math.atan2(ty - mem.pos.y, tx - mem.pos.x) * DEG;
    let rel = wrapDeg(abs - trueHeading);
    let sp = clamp(speed, 0, 2.4);
    if (d < 6) sp = Math.min(sp, 0.45 + d * 0.10);
    if (d < 2) sp = Math.min(sp, 0.28);
    if (Math.abs(+obs.pitch || 0) > 20) sp = Math.min(sp, 1.15);
    return driveToBearing(rel, sp, false);
  }

  function findCandNear(x, y, rad) {
    let best = null;
    let bd = rad;
    for (let i = 0; i < mem.cands.length; i++) {
      const c = mem.cands[i];
      if (c.state === 1) continue;
      let d = dist(c.x, c.y, x, y);
      if (d < bd) {
        bd = d;
        best = c;
      }
    }
    return best;
  }

  function updateVisibleSite() {
    mem.visibleCand = null;
    if (!obs.site || !isFinite(+obs.site.distance) || !isFinite(+obs.site.bearing)) return;
    let d = +obs.site.distance;
    if (d > 8.5) return;
    let abs = (trueHeading + (+obs.site.bearing)) * RAD;
    let sx = mem.pos.x + d * Math.cos(abs);
    let sy = mem.pos.y + d * Math.sin(abs);
    let val = isFinite(+obs.site.value) ? +obs.site.value : 1;

    let best = null;
    let bd = 12;
    for (let i = 0; i < mem.cands.length; i++) {
