    mem.R[i] = r;
  }

  let carriedNow = Math.max(0, Math.floor(finite(obs.carried, 0)));
  let deliveredNow = finite(obs.delivered, 0);
  let bat = finite(obs.battery, 1);
  let solar = finite(obs.solar, 0);
  let timeLeft = finite(obs.timeLeft, Math.max(0, mem.missionSeconds - t));
  if (timeLeft < 0) timeLeft = 0;
  let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);

  // Detect new samples and unloads.
  let prevCarried = Math.floor(finite(mem.lastCarried, 0));
  if (carriedNow > prevCarried) {
    let gained = carriedNow - prevCarried;
    mem.samplesCollected += gained;

    let sx = mem.pos.x, sy = mem.pos.y;
    if (mem.lastSeenSite) {
      sx = mem.lastSeenSite.x;
      sy = mem.lastSeenSite.y;
    }
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h.done && dist(h.x, h.y, sx, sy) < 31) h.done = true;
    }
    if (mem.drill && mem.drill.hint) mem.drill.hint.done = true;
    mem.drill = null;
    mem.search = null;
    mem.target = null;
    mem.nav = null;
    mem.lastSeenSite = null;
  }

  if (carriedNow < prevCarried && obs.docked) {
    mem.deliveryCount += prevCarried - carriedNow;
    mem.hasDelivered = true;
  }
  if (deliveredNow > (mem.lastDelivered || 0) + 1e-9) mem.hasDelivered = true;
  mem.lastCarried = carriedNow;
  mem.lastDelivered = deliveredNow;
  mem.lastCarriedValue = finite(obs.carriedValue, 0);

  // Bump recovery.
  let bumpVal = (typeof obs.bumped === "number") ? +obs.bumped : (obs.bumped ? 1 : 0);
  let newBump = bumpVal > 0 && (mem.bumpPrev || 0) <= 0;
  if (newBump) {
    let leftOpen = (mem.R[5] || 15) + (mem.R[6] || 15) + (mem.R[7] || 15) + (mem.R[8] || 15);
    let rightOpen = (mem.R[0] || 15) + (mem.R[1] || 15) + (mem.R[2] || 15) + (mem.R[3] || 15);
    let dir = leftOpen >= rightOpen ? 1 : -1;
    mem.recover = {
      reverseUntil: t + 0.85,
      turnUntil: t + 1.75,
      dir: dir
    };
    mem.drill = null;
    mem.nav = null;
    mem.lastBumpT = t;
  }
  mem.bumpPrev = bumpVal;

  // Energy-use estimate per metre, excluding drilling and docking.
  let movedStep = dist(mem.pos.x, mem.pos.y, mem.prevPos.x, mem.prevPos.y);
  if (!obs.docked && !mem.drill && movedStep > 0.025) {
    let used = (mem.prevBat || bat) + solar * dt - bat;
    if (used > 0.00001 && used < 0.10) {
      let ratio = used / movedStep / (1 + 0.12 * carriedNow);
      if (ratio > 0.00008 && ratio < 0.025) {
        mem.drain = mem.drain * 0.974 + ratio * 0.026;
        mem.energyN = (mem.energyN || 0) + 1;
      }
    }
  }
  mem.prevBat = bat;
  mem.prevPos.x = mem.pos.x;
  mem.prevPos.y = mem.pos.y;

  // Science history and local linear gradient.
  let sci = finite(obs.science, 0);
  if (sci < 0) sci = 0;
  if (!mem.sciHist) mem.sciHist = [];
  let lastSci = mem.sciHist.length ? mem.sciHist[mem.sciHist.length - 1] : null;
  if (!lastSci || t - lastSci.t > 0.9 || dist(mem.pos.x, mem.pos.y, lastSci.x, lastSci.y) > 0.55) {
    mem.sciHist.push({ x: mem.pos.x, y: mem.pos.y, s: sci, t: t });
    while (mem.sciHist.length > 34) mem.sciHist.shift();
  }

  let validSci = [];
  for (let i = 0; i < mem.sciHist.length; i++) {
    if (t - mem.sciHist[i].t < 45) validSci.push(mem.sciHist[i]);
  }
  if (validSci.length >= 6) {
    let n = validSci.length;
    let sxm = 0, sym = 0, ssm = 0;
    for (let i = 0; i < n; i++) {
      sxm += validSci[i].x;
      sym += validSci[i].y;
      ssm += validSci[i].s;
    }
    sxm /= n; sym /= n; ssm /= n;
    let A = 0, B = 0, C = 0, D = 0, E = 0;
    for (let i = 0; i < n; i++) {
      let u = validSci[i].x - sxm;
      let v = validSci[i].y - sym;
      let w = validSci[i].s - ssm;
      A += u * u;
      B += u * v;
      C += v * v;
      D += u * w;
      E += v * w;
    }
    let det = A * C - B * B;
    if (det > 1e-5) {
      let gx = (D * C - E * B) / det;
      let gy = (E * A - D * B) / det;
      if (isFinite(gx) && isFinite(gy) && hyp(gx, gy) < 100) {
        mem.sciGrad = { x: gx, y: gy, t: t };
      } else {
        mem.sciGrad = null;
      }
    } else {
      mem.sciGrad = null;
    }
  } else {
    mem.sciGrad = null;
  }

  function setWheels(tL, tR, drillOn) {
    tL = finite(tL, 0);
    tR = finite(tR, 0);
    tL = clamp(tL, -2.8, 2.8);
    tR = clamp(tR, -2.8, 2.8);

    let maxDelta = 3.6 * dt;
    if (maxDelta < 0.025) maxDelta = 0.025;

    if (mem.rtL === undefined) mem.rtL = tL;
    else mem.rtL += clamp(tL - mem.rtL, -maxDelta, maxDelta);

    if (mem.rtR === undefined) mem.rtR = tR;
    else mem.rtR += clamp(tR - mem.rtR, -maxDelta, maxDelta);

    if (!mem.mc) {
      mem.mc = {
        L: { i: 0, g: 2.5, dz: 0.07, prevCmd: 0, cmd: 0 },
        R: { i: 0, g: 2.5, dz: 0.07, prevCmd: 0, cmd: 0 }
      };
    }
    if (!mem.mc.L) mem.mc.L = { i: 0, g: 2.5, dz: 0.07, prevCmd: 0, cmd: 0 };
    if (!mem.mc.R) mem.mc.R = { i: 0, g: 2.5, dz: 0.07, prevCmd: 0, cmd: 0 };

    function wheelCtrl(target, actual, s) {
      if (!isFinite(actual)) actual = 0;
      let err = target - actual;
      let oldI = s.i || 0;

      s.i = clamp(oldI + err * dt * 0.70, -6, 6);

      let g = s.g || 2.5;
      if (g < 0.45) g = 0.45;
      let ff = target / g;
      let c = ff + 0.58 * err + 0.18 * s.i;

      if (Math.abs(target) > 0.045 && Math.abs(actual) < 0.055 && Math.abs(c) < (s.dz || 0.07)) {
        c = (target > 0 ? 1 : -1) * Math.max(0.07, s.dz || 0.07);
      }

      if (Math.abs(target) < 0.025 && Math.abs(actual) > 0.025) {
        c += -actual * 0.72;
      }

      let saturated = (c > 1 || c < -1);
      c = clamp(c, -1, 1);

      if (saturated && ((c > 0.99 && err > 0) || (c < -0.99 && err < 0))) {
        s.i = oldI;
      }
      s.i = clamp(s.i, -6, 6);

      let prevCmd = s.prevCmd || 0;
      if (Math.abs(prevCmd) > 0.15 && Math.abs(actual) > 0.12 && prevCmd * actual > 0) {
        let ratio = actual / prevCmd;
        if (ratio > 0.25 && ratio < 8) {
          s.g = clamp((s.g || 2.5) * 0.997 + ratio * 0.003, 0.35, 6.5);
        }
      }

      if (Math.abs(target) > 0.12 && Math.abs(actual) < 0.045) {
        s.dz = Math.min(0.38, (s.dz || 0.07) + 0.0009);
      } else if (Math.abs(actual) > 0.12) {
        s.dz = Math.max(0.028, (s.dz || 0.07) * 0.9995);
      }

      s.prevCmd = c;
      s.cmd = c;
      return c;
    }

    let cL = wheelCtrl(mem.rtL, wl, mem.mc.L);
    let cR = wheelCtrl(mem.rtR, wr, mem.mc.R);

    return {
      left: clamp(cL, -1, 1),
      right: clamp(cR, -1, 1),
      drill: !!drillOn
    };
  }

  function steerRel(rel, speed) {
    let e = wrapDeg(rel);
    let sp = clamp(speed, 0, 0.92);

    let rays = mem.R;
    let central = Math.min(rays[3] || 15, rays[4] || 15, rays[5] || 15);

    if (central < 2.8) {
      let leftOpen = (rays[5] || 15) + (rays[6] || 15) + (rays[7] || 15) + (rays[8] || 15);
      let rightOpen = (rays[0] || 15) + (rays[1] || 15) + (rays[2] || 15) + (rays[3] || 15);
      let turn = leftOpen >= rightOpen ? 1 : -1;

      if (central < 0.85) {
        sp = Math.min(sp, 0.08);
        e = turn * 75;
      } else {
        sp *= clamp((central - 0.65) / 2.0, 0.15, 1.0);
        if (Math.abs(e) < 55) e += turn * 22;
      }
    }

    if (e > 12) {
      let dL = Math.min(rays[6] || 15, rays[7] || 15, rays[8] || 15);
      if (dL < 0.9) e = Math.min(e, 5);
    }
    if (e < -12) {
      let dR = Math.min(rays[0] || 15, rays[1] || 15, rays[2] || 15);
      if (dR < 0.9) e = Math.max(e, -5);
    }

    let margin = 6.0;
    let edge = Math.min(mem.pos.x, mem.pos.y, mem.size - mem.pos.x, mem.size - mem.pos.y);
    if (edge < margin) {
      let toC = Math.atan2(mem.size * 0.5 - mem.pos.y, mem.size * 0.5 - mem.pos.x) * DEG;
      let relC = wrapDeg(toC - trueHeading);
      let w = clamp((margin - edge) / margin, 0, 1) * 0.85;
      e = wrapDeg(e * (1 - w) + relC * w);
      if (Math.abs(relC) > 20) sp = Math.min(sp, 0.45);
    }

    let pitch = finite(obs.pitch, 0);
    if (pitch > 14) sp = Math.min(sp, 0.95 - pitch * 0.012);
    if (pitch > 26) sp = Math.min(sp, 0.34);

    let ae = Math.abs(e);
    if (ae > 105) sp = Math.min(sp, 0.08);
    else if (ae > 65) sp = Math.min(sp, 0.18);
    else if (ae > 30) sp = Math.min(sp, 0.55);

    let er = e * RAD;
    let yawMeas = (wr - wl) / 0.6;
    if (!isFinite(yawMeas)) yawMeas = 0;

    let yawDes = clamp(1.15 * er - 0.35 * yawMeas, -0.90, 0.90);
    if (sp < 0.055 && ae > 4) {
      yawDes = clamp(0.55 * er - 0.20 * yawMeas, -0.72, 0.72);
    }

    const halfBase = 0.3;
    let vL = sp - yawDes * halfBase;
    let vR = sp + yawDes * halfBase;

    let maxAbs = Math.max(Math.abs(vL), Math.abs(vR), 1e-9);
    if (maxAbs > 2.65) {
      let k = 2.65 / maxAbs;
      vL *= k;
      vR *= k;
    }

    return setWheels(vL, vR, false);
  }

  function goPoint(tx, ty, speed, key) {
    let d = dist(mem.pos.x, mem.pos.y, tx, ty);
    if (!mem.nav || mem.nav.key !== key) {
      mem.nav = {
        key: key,
        startT: t,
        best: d,
        lastProgress: t,
        stuck: 0
      };
    }
    let nav = mem.nav;

    if (d < nav.best - 0.45) {
      nav.best = d;
      nav.lastProgress = t;
      nav.stuck = 0;
    }

    if (t - nav.lastProgress > 14 && d > 4.0) {
      nav.lastProgress = t;
      nav.stuck = (nav.stuck || 0) + 1;
      if (nav.stuck >= 3) return null;

      let leftOpen = (mem.R[5] || 15) + (mem.R[6] || 15) + (mem.R[7] || 15) + (mem.R[8] || 15);
      let rightOpen = (mem.R[0] || 15) + (mem.R[1] || 15) + (mem.R[2] || 15) + (mem.R[3] || 15);
      let dir = leftOpen >= rightOpen ? 1 : -1;
      mem.recover = {
        reverseUntil: t + 0.65,
        turnUntil: t + 1.35,
        dir: dir
      };
      return setWheels(-0.32, -0.32, false);
    }

    if (d < 0.65) return setWheels(0, 0, false);

    let absB = Math.atan2(ty - mem.pos.y, tx - mem.pos.x) * DEG;
    let rel = wrapDeg(absB - trueHeading);

    let sp = clamp(speed, 0, 0.92);
    if (d < 5.0) sp = Math.min(sp, 0.25 + d * 0.09);
    if (d < 1.6) sp = Math.min(sp, 0.22);
    if (d < 0.55) sp = 0;

    return steerRel(rel, sp);
  }

  function goBase() {
    if (obs.docked) return setWheels(0, 0, false);

    if (obs.beacon && isFinite(+obs.beacon.distance) && isFinite(+obs.beacon.bearing)) {
      let bd = +obs.beacon.distance;
      let br = +obs.beacon.bearing;
      if (bd < 1.65) return setWheels(0, 0, false);
      let sp = clamp((bd - 1.15) * 0.78, 0.14, 0.90);
      if (bd < 4.0) sp = Math.min(sp, 0.30);
      if (bd > 16.0) sp = 0.90;
      return steerRel(br, sp);
    }

    let dBase = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (dBase < 1.65) return setWheels(0, 0, false);

    let absB = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
    let rel = wrapDeg(absB - trueHeading);
    let sp = dBase > 20 ? 0.90 : (dBase > 6 ? 0.62 : 0.34);
    if (dBase < 3.0) sp = Math.min(sp, 0.18);
    return steerRel(rel, sp);
  }

  function beginDrill(val, hint) {
    mem.drill = {
      startCarried: carriedNow,
      lastDrill: isFinite(+obs.drilling) ? +obs.drilling : 0,
      t0: t,
      value: val || 0,
      hint: hint || null
    };
    return setWheels(0, 0, true);
  }

  function handleSite() {
    if (!obs.site || !isFinite(+obs.site.distance) || !isFinite(+obs.site.bearing)) return null;
    let d = Math.max(0, +obs.site.distance);
    let br = +obs.site.bearing;
    let val = finite(obs.site.value, 0);

    if (d <= 8.05) {
      let absSite = (trueHeading + br) * RAD;
      let sx = mem.pos.x + d * Math.cos(absSite);
      let sy = mem.pos.y + d * Math.sin(absSite);
      mem.lastSeenSite = { x: sx, y: sy, value: val, t: t };
    }

    if (d <= 1.38) {
      if (wheelMax < 0.14) {
        let hint = null;
        if (mem.search && mem.search.hint) hint = mem.search.hint;
        else if (mem.target && mem.target.hint) hint = mem.target.hint;
        return beginDrill(val, hint);
      }
      return setWheels(0, 0, false);
    }

    if (d < 1.70 && wheelMax > 0.24) return setWheels(0, 0, false);

    let sp = clamp((d - 1.05) * 0.80, 0.12, 0.90);
    if (d < 2.5) sp = Math.min(sp, 0.45);
    return steerRel(br, sp);
  }

  function startSearch(hx, hy, hint) {
    let cx = clamp(hx, 7, mem.size - 7);
    let cy = clamp(hy, 7, mem.size - 7);
    let a0 = Math.atan2(mem.pos.y - cy, mem.pos.x - cx);
    if (!isFinite(a0)) a0 = 0;

    let pts = [];
    pts.push({ x: cx, y: cy });
    let n = 10;
    let radius = 14.0;
    for (let i = 0; i < n; i++) {
      let a = a0 + (i + 0.5) * (2 * PI / n);
      pts.push({
        x: clamp(cx + radius * Math.cos(a), 7, mem.size - 7),
        y: clamp(cy + radius * Math.sin(a), 7, mem.size - 7)
      });
    }

    mem.searchId = (mem.searchId || 0) + 1;
    mem.search = {
      id: mem.searchId,
      hint: hint || null,
      cx: cx,
      cy: cy,
      pts: pts,
      idx: 0,
      startT: t,
      lastAdv: t,
      maxSci: sci,
      limit: 92
    };
    mem.target = null;
    mem.nav = null;
  }

  function runSearch() {
    let s = mem.search;
    if (!s) return null;
    if (s.hint && s.hint.done) {
      mem.search = null;
      mem.nav = null;
      return null;
    }

    if (sci > s.maxSci) s.maxSci = sci;

    if (t - s.startT > (s.limit || 92)) {
      if (s.hint) s.hint.done = true;
      mem.search = null;
      mem.nav = null;
      return null;
    }

    if (t - s.startT > 8 && s.maxSci < 1e-8) {
      if (s.hint) s.hint.done = true;
      mem.search = null;
      mem.nav = null;
      return null;
    }

    if (s.idx >= s.pts.length) {
      if (s.hint) s.hint.done = true;
      mem.search = null;
      mem.nav = null;
      return null;
    }

    let p = s.pts[s.idx];
    let d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
    if (d < 2.2 || t - s.lastAdv > 14) {
      s.idx++;
      s.lastAdv = t;
      if (s.idx >= s.pts.length) {
        if (s.hint) s.hint.done = true;
        mem.search = null;
        mem.nav = null;
        return null;
      }
      p = s.pts[s.idx];
      d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
    }

    let sp = d < 4.0 ? 0.55 : 0.90;
    let key = "s" + s.id + "_" + s.idx;
    let cmd = goPoint(p.x, p.y, sp, key);
    if (!cmd) {
      if (s.hint) s.hint.done = true;
      mem.search = null;
      mem.nav = null;
      return null;
    }
    return cmd;
  }

  function chooseHint(carrying) {
    let best = null;
    let bestScore = -1e99;
    let tleft = timeLeft;
    let bpos = mem.pos;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.done) continue;

      let d = dist(bpos.x, bpos.y, h.x, h.y);
      let dBase = dist(mem.base.x, mem.base.y, h.x, h.y);
      let val = Math.max(0.1, h.val || 1);

      let score = Math.pow(val, 0.72) / (24 + d + 0.42 * dBase);
      if (h.attempts > 0) score *= 0.55;
      if (carrying > 0) score /= (1 + 0.0022 * dBase);

      let tNeed = (d + dBase) / 0.62 + 28 + 5 * carrying;
      if (tleft < tNeed + 18) score *= 0.03;

      let eNeed = (d + dBase) * (mem.drain || 0.0018) * (1 + 0.12 * carrying) * 1.75 + 0.05;
      if (bat < eNeed) score *= 0.03;

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best;
  }

  function navigateTarget() {
    let tg = mem.target;
    if (!tg) return null;

    if (tg.type === "hint") {
      let h = tg.hint;
      if (!h || h.done) {
        mem.target = null;
        return null;
      }

      let d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      if (d < 5.5) {
        startSearch(h.x, h.y, h);
        let cmd = runSearch();
        return cmd || null;
      }

      let sp = d > 30 ? 0.90 : (d > 10 ? 0.78 : 0.52);
      let cmd = goPoint(h.x, h.y, sp, "h" + h.id);
      if (!cmd) {
        h.attempts = (h.attempts || 0) + 1;
        if (h.attempts >= 3) h.done = true;
        mem.target = null;
        mem.nav = null;
        return null;
      }
      return cmd;
    }
    return null;
  }

  function chooseExplorePoint() {
    let best = null;
    let bd = 1e99;
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (p.used) continue;
      let d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < bd) {
        bd = d;
        best = p;
      }
    }
    return best;
  }

  function doExplore() {
    if (sci > 1e-7 && mem.sciGrad && t - mem.sciGrad.t < 5.0) {
      let gx = mem.sciGrad.x, gy = mem.sciGrad.y;
      let mag = hyp(gx, gy);
      if (mag > 1e-7 && mag < 100) {
        let step = 11.0;
        let tx = clamp(mem.pos.x + gx / mag * step, 8, mem.size - 8);
        let ty = clamp(mem.pos.y + gy / mag * step, 8, mem.size - 8);
        let key = "grad" + Math.floor(t / 4);
        let cmd = goPoint(tx, ty, 0.82, key);
        if (cmd) return cmd;
      }
    }

    let p = chooseExplorePoint();
    if (p) {
      let d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < 5.5) {
        p.used = true;
        if (sci > 1e-7 && !mem.search) {
          startSearch(p.x, p.y, null);
          let cmd = runSearch();
          if (cmd) return cmd;
        }
        return setWheels(0, 0, false);
      }
      let sp = d > 30 ? 0.82 : 0.65;
      let cmd = goPoint(p.x, p.y, sp, "e" + p.id);
      if (!cmd) {
        p.used = true;
        return setWheels(0, 0, false);
      }
      return cmd;
    }

    let ang = (t * 0.031) % (2 * PI);
    let rad = 34 + 18 * Math.sin(t * 0.013);
    let tx = clamp(mem.pos.x + Math.cos(ang) * rad, 8, mem.size - 8);
    let ty = clamp(mem.pos.y + Math.sin(ang) * rad, 8, mem.size - 8);
    let key = "wander" + Math.floor(t / 6);
    let cmd = goPoint(tx, ty, 0.76, key);
    return cmd || setWheels(0, 0, false);
  }

  // Recovery first.
  if (mem.recover) {
    let rec = mem.recover;
    if (t < rec.reverseUntil) {
      let dir = rec.dir || 1;
      let yaw = 0.55 * dir;
      let v = -0.45;
      return setWheels(v - yaw * 0.3, v + yaw * 0.3, false);
    }
    if (t < rec.turnUntil) {
      let dir = rec.dir || 1;
      let yaw = 0.80 * dir;
      return setWheels(-yaw * 0.3, yaw * 0.3, false);
    }
    mem.recover = null;
  }

  // Active drilling.
  if (mem.drill) {
    let dr = mem.drill;
    let valid = !!obs.site && isFinite(+obs.site.distance) && (+obs.site.distance) < 1.78;
    let drillSec = isFinite(+obs.drilling) ? +obs.drilling : 0;

    if (!valid) {
      mem.drill = null;
    } else if (dr.lastDrill > 0.45 && drillSec < dr.lastDrill - 0.25) {
      mem.drill = null;
    } else {
      dr.lastDrill = drillSec;
      if (t - dr.t0 > 12.0 && carriedNow <= dr.startCarried) {
        mem.drill = null;
      } else {
        return setWheels(0, 0, true);
      }
    }
  }

  // Return decision.
  if (!mem.returning) {
    let need = false;
    let cap = mem.capacity || 5;

    if (carriedNow > 0) {
      let reserve = db * (mem.drain || 0.0018) * (1 + 0.15 * carriedNow) * 1.85 +
                    0.060 + 0.020 * carriedNow;
      let timeNeed = db / 0.62 + 18 + 8 * carriedNow;
      let hasBank = mem.hasDelivered || deliveredNow > 0;
      let targetBatch = hasBank ? (timeLeft > 550 ? 3 : 2) : 1;

      if (carriedNow >= cap) need = true;
      if (carriedNow >= targetBatch) need = true;
      if (bat < reserve) need = true;
      if (timeLeft < timeNeed + 16) need = true;
    } else {
      if (bat < 0.11 && timeLeft > 70 && db > 15) need = true;
      if (timeLeft < 55 && db > 8) need = true;
    }

    if (need) mem.returning = true;
  }

  if (mem.returning) {
    if (obs.docked && carriedNow === 0) {
      let goal = timeLeft > 600 ? 0.75 : (timeLeft > 250 ? 0.58 : 0.34);
      if (bat < goal && timeLeft > 70) {
        return setWheels(0, 0, false);
      }
      mem.returning = false;
      mem.target = null;
      mem.search = null;
      mem.nav = null;
    } else {
      if (obs.docked && carriedNow > 0) return setWheels(0, 0, false);
      return goBase();
    }
