  }

  // Empty rover near base and low battery: dock and charge.
  if (carriedNow === 0 && timeLeft > 80 && db < 8.0 && bat < 0.50) {
    if (obs.docked) {
      let goal = timeLeft > 600 ? 0.72 : (timeLeft > 250 ? 0.56 : 0.34);
      if (bat < goal) return setWheels(0, 0, false);
    } else {
      return goBase();
    }
  }

  // Opportunistic real site, which is much more precise than hints.
  if (obs.site && carriedNow < (mem.capacity || 5)) {
    let siteCmd = handleSite();
    if (siteCmd) return siteCmd;
  }

  // If the precise site just left the 8 m window, briefly pursue its last fix.
  if (!obs.site && mem.lastSeenSite && carriedNow < (mem.capacity || 5) &&
      t - mem.lastSeenSite.t < 12) {
    let dls = dist(mem.pos.x, mem.pos.y, mem.lastSeenSite.x, mem.lastSeenSite.y);
    if (dls < 10.0 && dls > 0.75) {
      let cmd = goPoint(mem.lastSeenSite.x, mem.lastSeenSite.y, 0.55, "lastsite");
      if (cmd) return cmd;
    } else if (dls <= 0.85 && wheelMax < 0.12) {
      return beginDrill(mem.lastSeenSite.value || 0, null);
    }
  }

  // Short initial straight calibration.
  if (mem.samplesCollected === 0 && t < 1.8 && (mem.biasN || 0) < 2) {
    return steerRel(0, 0.36);
  }

  // Local search around a hint.
  if (mem.search) {
    let cmd = runSearch();
    if (cmd) return cmd;
  }

  // Current hint target.
  if (mem.target) {
    let cmd = navigateTarget();
    if (cmd) return cmd;
  }

  // Choose next hint.
  let h = chooseHint(carriedNow);
  if (h) {
    mem.target = { type: "hint", hint: h };
    let cmd = navigateTarget();
    if (cmd) return cmd;
  }

  if (carriedNow > 0) {
    mem.returning = true;
    return goBase();
  }

  if (timeLeft < 8) return setWheels(0, 0, false);

  return doExplore();
}

function act(obs, mem) {
  "use strict";

  const PI = Math.PI;
  const RAD = PI / 180;
  const DEG = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrapDeg(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }
  function hyp(a, b) { return Math.sqrt(a * a + b * b); }
  function dist(x1, y1, x2, y2) { return hyp(x2 - x1, y2 - y1); }
  function finite(v, d) { v = +v; return isFinite(v) ? v : d; }

  if (!mem || typeof mem !== "object") mem = {};

  if (!mem.init) {
    mem.init = true;
    const mis = obs.mission || {};
    mem.size = finite(mis.size, 400);
    mem.missionSeconds = finite(mis.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(finite(mis.capacity, 5)));
    mem.base = {
      x: mis.base && isFinite(+mis.base.x) ? +mis.base.x : finite(obs.x, mem.size / 2),
      y: mis.base && isFinite(+mis.base.y) ? +mis.base.y : finite(obs.y, mem.size / 2)
    };

    mem.hints = [];
    const hs = Array.isArray(mis.hints) ? mis.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = +h.x;
      const hy = +h.y;
      if (!isFinite(hx) || !isFinite(hy)) continue;
      let hv = +h.estimate;
      if (!isFinite(hv) || hv <= 0) hv = 1;
      mem.hints.push({
        id: i,
        x: hx,
        y: hy,
        val: hv,
        done: false,
        attempts: 0
      });
    }

    mem.pos = {
      x: finite(obs.x, mem.base.x),
      y: finite(obs.y, mem.base.y)
    };
    mem.head = wrapDeg(finite(obs.heading, 0));
    mem.bias = 0;
    mem.trueHeading = mem.head;

    mem.gL = 2.5;
    mem.gR = 2.5;
    mem.dz = 0.065;
    mem.cmdL = 0;
    mem.cmdR = 0;
    mem.movingIntent = false;

    mem.prevBat = finite(obs.battery, 1);
    mem.prevX = mem.pos.x;
    mem.prevY = mem.pos.y;
    mem.drain = 0.0015;

    mem.prevCarried = Math.max(0, Math.floor(finite(obs.carried, 0)));
    mem.prevDelivered = finite(obs.delivered, 0);
    mem.samplesCollected = 0;
    mem.hasDelivered = false;
    mem.lastDeliverT = -1e9;

    mem.search = null;
    mem.target = null;
    mem.targetStartT = -1e9;
    mem.drill = null;
    mem.returning = false;
    mem.lastSite = null;

    mem.recoverUntil = -1e9;
    mem.recoverDir = 1;
    mem.prevBump = 0;

    mem.lastRawX = mem.pos.x;
    mem.lastRawY = mem.pos.y;
    mem.lastRawT = finite(obs.t, 0);
    mem.gpsFrozen = false;
    mem.lastAcceptT = finite(obs.t, 0);

    mem.checkT = finite(obs.t, 0);
    mem.checkPos = { x: mem.pos.x, y: mem.pos.y };
    mem.stuckCount = 0;

    mem.cal = null;
    mem.jumpCount = 0;
    mem.lastFallback = -1e9;

    mem.explore = [];
    for (let gx = 30; gx <= mem.size - 20; gx += 42) {
      for (let gy = 30; gy <= mem.size - 20; gy += 42) {
        if (dist(gx, gy, mem.base.x, mem.base.y) > 18) {
          mem.explore.push({ x: gx, y: gy, used: false });
        }
      }
    }

    mem.lastT = finite(obs.t, 0);
  }

  let t = finite(obs.t, mem.lastT + 0.1);
  let dt = 0.1;
  if (isFinite(mem.lastT)) {
    const dd = t - mem.lastT;
    if (dd > 0.001 && dd < 1.0) dt = dd;
    else if (dd >= 1.0 && dd < 5.0) dt = 0.5;
  }
  mem.lastT = t;

  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const wheelMax = Math.max(Math.abs(wl), Math.abs(wr));
  const battery = finite(obs.battery, mem.prevBat || 1);
  const solar = finite(obs.solar, 0);
  const carried = Math.max(0, Math.floor(finite(obs.carried, 0)));
  const carriedValue = finite(obs.carriedValue, 0);
  const delivered = finite(obs.delivered, 0);
  const capacity = mem.capacity || 5;
  const timeLeft = Math.max(0, finite(obs.timeLeft, mem.missionSeconds - t));
  const pitch = finite(obs.pitch, 0);
  let science = finite(obs.science, 0);
  if (science < 0) science = 0;
  const drilling = finite(obs.drilling, 0);

  const rays = new Array(9);
  const rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    let r = +rawRays[i];
    if (!isFinite(r) || r < 0) r = 15;
    if (r > 15) r = 15;
    rays[i] = r;
  }
  mem.R = rays;

  // Heading filtering with simple jump rejection.
  const rawH = wrapDeg(finite(obs.heading, mem.head));
  const dh = wrapDeg(rawH - mem.head);
  const predYawDeg = ((wr - wl) / 0.6) * dt * DEG;
  if (Math.abs(dh) < 40 || Math.abs(wrapDeg(dh - predYawDeg)) < 25) {
    mem.head = wrapDeg(mem.head + dh * 0.62);
    mem.jumpCount = 0;
  } else {
    mem.jumpCount = (mem.jumpCount || 0) + 1;
    if (mem.jumpCount > 10) {
      mem.head = rawH;
      mem.jumpCount = 0;
    } else {
      mem.head = wrapDeg(mem.head + clamp(predYawDeg, -8, 8));
    }
  }

  let trueHeading = wrapDeg(mem.head - (mem.bias || 0));

  // Predict position with odometry, then fuse GPS when plausible.
  const oldX = mem.pos.x;
  const oldY = mem.pos.y;
  const speedAvg = (wl + wr) * 0.5;

  let predX = mem.pos.x + speedAvg * Math.cos(trueHeading * RAD) * dt;
  let predY = mem.pos.y + speedAvg * Math.sin(trueHeading * RAD) * dt;

  const rawX = +obs.x;
  const rawY = +obs.y;
  const rawGood = isFinite(rawX) && isFinite(rawY);

  if (rawGood) {
    const rawMoved = dist(rawX, rawY, mem.lastRawX, mem.lastRawY);
    if (rawMoved > 0.012) {
      mem.lastRawX = rawX;
      mem.lastRawY = rawY;
      mem.lastRawT = t;
      mem.gpsFrozen = false;
    } else if (t - mem.lastRawT > 2.8 && Math.abs(speedAvg) > 0.10) {
      mem.gpsFrozen = true;
    }

    if (!mem.gpsFrozen) {
      const innov = dist(predX, predY, rawX, rawY);
      if (innov < 12 || t - mem.lastAcceptT > 3.0) {
        mem.pos.x = predX * 0.30 + rawX * 0.70;
        mem.pos.y = predY * 0.30 + rawY * 0.70;
        mem.lastAcceptT = t;
      } else {
        mem.pos.x = predX;
        mem.pos.y = predY;
      }
    } else {
      mem.pos.x = predX;
      mem.pos.y = predY;
    }
  } else {
    mem.pos.x = predX;
    mem.pos.y = predY;
  }

  mem.pos.x = clamp(mem.pos.x, -8, mem.size + 8);
  mem.pos.y = clamp(mem.pos.y, -8, mem.size + 8);

  // Beacon bias calibration.
  let dbNow = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  if (obs.beacon && isFinite(+obs.beacon.bearing) && isFinite(+obs.beacon.distance)) {
    const bd = +obs.beacon.distance;
    const br = +obs.beacon.bearing;
    if (bd > 1.2 && bd < 22 && Math.abs(bd - dbNow) < 10) {
      const expected = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
      const hTrueObs = wrapDeg(expected - br);
      const biasInst = wrapDeg(mem.head - hTrueObs);
      const delta = wrapDeg(biasInst - (mem.bias || 0));
      if (Math.abs(delta) < 65) {
