      }
    }
  }

  // Straight-line GPS course bias calibration.
  trueHeading = wrapDeg(mem.head - (mem.bias || 0));
  const movingStraight = speedAvg > 0.32 && Math.abs(wl - wr) < 0.45;
  if (movingStraight && !mem.gpsFrozen) {
    if (!mem.cal) {
      mem.cal = { x: mem.pos.x, y: mem.pos.y, t: t, h: mem.head };
    } else if (t - mem.cal.t > 1.2) {
      const moved = dist(mem.pos.x, mem.pos.y, mem.cal.x, mem.cal.y);
      if (moved > 0.65) {
        const course = Math.atan2(mem.pos.y - mem.cal.y, mem.pos.x - mem.cal.x) * DEG;
        const avgH = wrapDeg(mem.cal.h + wrapDeg(mem.head - mem.cal.h) * 0.5);
        const biasInst = wrapDeg(avgH - course);
        const delta = wrapDeg(biasInst - (mem.bias || 0));
        if (Math.abs(delta) < 45) {
