  if (carried > prevCarried) {
    const gained = carried - prevCarried;
    mem.samplesCollected = (mem.samplesCollected || 0) + gained;

    let activeHint = null;
    if (mem.drill && mem.drill.hint) activeHint = mem.drill.hint;
    else if (mem.search && mem.search.hint) activeHint = mem.search.hint;
    else if (mem.target) activeHint = mem.target;

    if (activeHint) activeHint.done = true;

    let nearest = null;
    let nearestD = 36;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.done) continue;
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      if (d < nearestD) {
        nearestD = d;
        nearest = h;
      }
    }
    if (nearest) nearest.done = true;

    mem.drill = null;
    mem.search = null;
    mem.target = null;
    mem.lastSite = null;
  }

