    mem.hasDelivered = true;
    mem.lastDeliverT = t;
    mem.returning = false;
    mem.search = null;
    mem.target = null;
    mem.drill = null;
  }

  mem.prevCarried = carried;
  mem.prevDelivered = delivered;

  // Bump handling.
  const bumpVal = (typeof obs.bumped === "number") ? +obs.bumped : (obs.bumped ? 1 : 0);
  const newBump = bumpVal > 0 && !((mem.prevBump || 0) > 0);
  mem.prevBump = bumpVal;
  if (newBump) {
    const leftOpen = (rays[5] || 15) + (rays[6] || 15) + (rays[7] || 15) + (rays[8] || 15);
    const rightOpen = (rays[0] || 15) + (rays[1] || 15) + (rays[2] || 15) + (rays[3] || 15);
    mem.recoverDir = leftOpen >= rightOpen ? 1 : -1;
    mem.recoverUntil = t + 1.55;
    mem.movingIntent = false;
    mem.drill = null;
