      const rightOpen = (rays[0] || 15) + (rays[1] || 15) + (rays[2] || 15) + (rays[3] || 15);
      mem.recoverDir = leftOpen >= rightOpen ? 1 : -1;
      mem.recoverUntil = t + 1.45;
      mem.stuckCount = 0;
      mem.movingIntent = false;
      mem.drill = null;
      if (mem.search && mem.search.idx < mem.search.pts.length) mem.search.idx++;
