    if (maxD > 0.50) maxD = 0.50;
    if (maxD < 0.035) maxD = 0.035;
    let c = prev + clamp(desired - prev, -maxD, maxD);
    c = clamp(c, -1, 1);
    if (side === "L") mem.cmdL = c;
    else mem.cmdR = c;
    return c;
  }

  function targetToCmd(target, side, actual) {
    if (Math.abs(target) < 0.018) return 0;
    const g = side === "L" ? (mem.gL || 2.5) : (mem.gR || 2.5);
    let raw = target / clamp(g, 0.35, 6.5);
    const dz = mem.dz || 0.06;
    if (raw > 0) raw += dz;
    else if (raw < 0) raw -= dz;
    raw += clamp(pitch * 0.0038, -0.14, 0.14);
    return clamp(raw, -1, 1);
  }

