    vR = clamp(finite(vR, 0), -2.3, 2.3);

    const cL = targetToCmd(vL, "L", wl);
    const cR = targetToCmd(vR, "R", wr);

    const outL = slewCmd("L", cL);
    const outR = slewCmd("R", cR);

    mem.movingIntent = Math.abs((vL + vR) * 0.5) > 0.08;
    return { left: outL, right: outR, drill: !!drillOn };
  }

  function holdStill(drillOn) {
    mem.movingIntent = false;

    const baseComp = clamp(pitch * 0.009, -0.28, 0.28);
    let cL = baseComp + clamp(-wl * 0.85, -0.50, 0.50);
    let cR = baseComp + clamp(-wr * 0.85, -0.50, 0.50);
    cL = clamp(cL, -0.82, 0.82);
    cR = clamp(cR, -0.82, 0.82);

    const outL = slewCmd("L", cL);
    const outR = slewCmd("R", cR);
    return { left: outL, right: outR, drill: !!drillOn };
  }

  function driveRel(relBearingDeg, speed) {
    let e = wrapDeg(relBearingDeg);
    let sp = clamp(finite(speed, 0.8), 0, 1.45);

    const front = Math.min(rays[3] || 15, rays[4] || 15, rays[5] || 15);
    const leftOpen = (rays[5] || 15) + (rays[6] || 15) + (rays[7] || 15) + (rays[8] || 15);
    const rightOpen = (rays[0] || 15) + (rays[1] || 15) + (rays[2] || 15) + (rays[3] || 15);

    if (front < 3.0) {
      const turnDir = leftOpen >= rightOpen ? 1 : -1;
      if (front < 1.0) {
        e = turnDir * 95;
        sp = 0;
      } else {
        sp *= clamp((front - 0.65) / 2.35, 0.12, 1);
        const w = clamp((3.0 - front) / 2.5, 0, 1);
        e = wrapDeg(e * (1 - 0.62 * w) + turnDir * 72 * w);
      }
    }

    const sideL = Math.min(rays[6] || 15, rays[7] || 15, rays[8] || 15);
    const sideR = Math.min(rays[0] || 15, rays[1] || 15, rays[2] || 15);
    if (sideL < 0.85 && e < 35) e = wrapDeg(e - 16 * (1 - sideL / 0.85));
    if (sideR < 0.85 && e > -35) e = wrapDeg(e + 16 * (1 - sideR / 0.85));

    const edge = Math.min(mem.pos.x, mem.pos.y, mem.size - mem.pos.x, mem.size - mem.pos.y);
    if (edge < 9.0) {
      const toC = Math.atan2(mem.size * 0.5 - mem.pos.y, mem.size * 0.5 - mem.pos.x) * DEG;
      const relC = wrapDeg(toC - trueHeading);
      const w = clamp((9.0 - edge) / 9.0, 0, 1) * 0.85;
      e = wrapDeg(e * (1 - w) + relC * w);
      if (sp > 0.70) sp = 0.70;
    }

    const absE = Math.abs(e);
    let v = sp;
    if (absE > 120) v = 0;
    else if (absE > 65) v *= 0.15;
    else if (absE > 30) v *= 0.45 + 0.55 * (65 - absE) / 35;

    const er = e * RAD;
    let omega = clamp(er * 1.35, -1.00, 1.00);
    const yawMeas = (wr - wl) / 0.6;
    if (isFinite(yawMeas)) omega -= clamp(yawMeas * 0.075, -0.14, 0.14);

    let vL = v - omega * 0.30;
    let vR = v + omega * 0.30;

    return setWheelTargets(vL, vR, false);
  }

  function doRecovery() {
    const rem = mem.recoverUntil - t;
    const dir = mem.recoverDir || 1;
    let res;
    if (rem > 0.72) {
      res = setWheelTargets(-0.46, -0.46, false);
    } else {
      res = setWheelTargets(-dir * 0.42, dir * 0.42, false);
    }
    mem.movingIntent = false;
    return res;
  }

  function goBase() {
    if (obs.beacon && isFinite(+obs.beacon.distance) && isFinite(+obs.beacon.bearing)) {
      const bd = +obs.beacon.distance;
      const br = +obs.beacon.bearing;
      if (bd < 1.15) return holdStill(false);
      let sp;
      if (bd > 14) sp = 1.20;
      else if (bd > 5) sp = 0.80;
      else if (bd > 2.5) sp = 0.48;
      else sp = 0.25;
      return driveRel(br, sp);
    }

    const d = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (d < 1.0) return holdStill(false);

    const absB = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
    const rel = wrapDeg(absB - trueHeading);
    let sp;
    if (d > 30) sp = 1.20;
    else if (d > 8) sp = 0.80;
    else if (d > 3) sp = 0.45;
    else sp = 0.24;
    return driveRel(rel, sp);
  }

  function makeSearchPoints(cx, cy, maxR) {
    cx = clamp(cx, 5, mem.size - 5);
    cy = clamp(cy, 5, mem.size - 5);

    const pts = [{ x: cx, y: cy }];
    const b = 11.0 / (2 * PI);
    let a0 = Math.atan2(mem.pos.y - cy, mem.pos.x - cx);
    if (!isFinite(a0)) a0 = 0;

    let theta = 0.20;
    let r = b * theta;
    let guard = 0;
    while (r <= maxR && guard++ < 220) {
      const a = a0 + theta;
      pts.push({
        x: clamp(cx + r * Math.cos(a), 5, mem.size - 5),
        y: clamp(cy + r * Math.sin(a), 5, mem.size - 5)
      });
      let step = 3.5 / Math.max(1.4, r);
      if (step > 0.58) step = 0.58;
      if (step < 0.12) step = 0.12;
      theta += step;
      r = b * theta;
    }
    return pts;
  }

  function startSearch(cx, cy, hint) {
    const val = hint ? Math.max(0.5, hint.val || 1) : 1;
    const maxR = hint ? clamp(18.0 + Math.min(11.0, val * 1.8), 20.0, 30.0) : 23.0;
    const maxTime = hint ? clamp(78.0 + Math.min(70.0, val * 10.0), 88.0, 155.0) : 72.0;

    mem.search = {
      cx: cx,
      cy: cy,
      hint: hint || null,
      pts: makeSearchPoints(cx, cy, maxR),
      idx: 0,
      startT: t,
      lastWayT: t,
      maxTime: maxTime,
      maxR: maxR,
      maxSci: science,
      sciSeen: science > 1e-7
    };
    mem.target = null;
  }

  function finishSearch() {
    const s = mem.search;
    if (s && s.hint) {
      s.hint.attempts = (s.hint.attempts || 0) + 1;
      s.hint.done = true;
    }
    mem.search = null;
    mem.target = null;
  }

  function runSearch() {
    const s = mem.search;
    if (!s) return null;

    if (s.hint && s.hint.done) {
      mem.search = null;
      return null;
    }

    if (science > s.maxSci) s.maxSci = science;
    if (science > 1e-7) s.sciSeen = true;

    const dCenter = dist(mem.pos.x, mem.pos.y, s.cx, s.cy);

    if (!s.sciSeen && t - s.startT > 14.0 && dCenter < 12.0) {
      finishSearch();
      return null;
    }

    if (t - s.startT > s.maxTime) {
      finishSearch();
      return null;
    }

    while (s.idx < s.pts.length) {
      const p = s.pts[s.idx];
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < 1.70 || t - s.lastWayT > 15.0) {
        s.idx++;
        s.lastWayT = t;
      } else {
        break;
      }
    }

    if (s.idx >= s.pts.length) {
      finishSearch();
      return null;
    }

    const p = s.pts[s.idx];
    const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
    const abs = Math.atan2(p.y - mem.pos.y, p.x - mem.pos.x) * DEG;
    const rel = wrapDeg(abs - trueHeading);

    let sp;
    if (d > 8) sp = 1.02;
    else if (d > 3) sp = 0.74;
    else sp = 0.44;

    return driveRel(rel, sp);
  }

  function chooseHint(carrying) {
    let best = null;
    let bestScore = -1e99;
    const curBase = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    const firstLeg = !mem.hasDelivered && (delivered <= 0) && (mem.samplesCollected || 0) === 0;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.done) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dbh = dist(mem.base.x, mem.base.y, h.x, h.y);
      const val = Math.max(0.1, h.val || 1);

      let score;
      if (firstLeg && carrying === 0) {
        score = (0.3 + Math.min(6.0, val) * 0.10) / (14.0 + d);
      } else if (carrying > 0) {
        const detour = Math.max(0, d + dbh - curBase);
        score = Math.pow(val, 0.72) / (18.0 + d + 0.75 * detour);
      } else {
        score = Math.pow(val, 0.72) / (18.0 + d + 0.58 * dbh);
      }

      const needTime = (d + (carrying > 0 ? dbh : 0)) / 0.55 + 28;
      if (timeLeft < needTime) score *= 0.025;

      const eNeed = (d + (carrying > 0 ? dbh : 0)) *
                    (mem.drain || 0.0015) *
                    (1 + 0.15 * carrying) * 2.0 + 0.055;
      if (battery < eNeed + 0.025) score *= 0.08;

      if (h.attempts > 0) score *= 0.52;
      if (h.x < 4 || h.x > mem.size - 4 || h.y < 4 || h.y > mem.size - 4) score *= 0.75;

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best;
  }

  function handleVisibleSite() {
    if (!obs.site) return null;
    if (!isFinite(+obs.site.distance) || !isFinite(+obs.site.bearing)) return null;
    if (carried >= capacity) return null;

    const d = Math.max(0, +obs.site.distance);
    const br = +obs.site.bearing;
    const val = finite(obs.site.value, 0);

    // Remember last seen approximate position.
    const absSite = (trueHeading + br) * RAD;
    mem.lastSite = {
      x: mem.pos.x + d * Math.cos(absSite),
      y: mem.pos.y + d * Math.sin(absSite),
      t: t,
      value: val
    };

    if (d > 1.35) {
      let sp;
      if (d > 5.5) sp = 1.05;
      else if (d > 3.0) sp = 0.78;
      else if (d > 1.8) sp = 0.43;
      else sp = 0.22;

      sp = Math.min(sp, Math.max(0.10, (d - 1.02) * 0.72));

      if (d < 1.65 && wheelMax > 0.22) return holdStill(false);
      return driveRel(br, sp);
    }

    if (wheelMax < 0.13) {
      let hint = null;
      if (mem.search && mem.search.hint) hint = mem.search.hint;
      else if (mem.target) hint = mem.target;

      mem.drill = {
        startCarried: carried,
        hint: hint,
        t0: t,
        lastDrill: drilling,
        value: val
      };
      return holdStill(true);
    }

    return holdStill(false);
  }

  // Recovery overrides normal driving.
  if (t < mem.recoverUntil) {
    return doRecovery();
  }

  // Compute base distance and urgent return metrics.
  let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  let bd = db;
  if (obs.beacon && isFinite(+obs.beacon.distance)) {
    bd = +obs.beacon.distance;
  }

  // Active drilling.
  if (mem.drill) {
    const dSite = obs.site && isFinite(+obs.site.distance) ? +obs.site.distance : Infinity;
    const canDrill = obs.site && dSite < 1.56;
    const tooLate = timeLeft < db / 0.62 + 18;
    const lowBat = battery < 0.035;

    if (!canDrill || tooLate || lowBat) {
      mem.drill = null;
    } else {
      if (carried > mem.drill.startCarried) {
        mem.drill = null;
      } else {
        let badProgress = false;
        if (t - mem.drill.t0 > 13.0 && carried <= mem.drill.startCarried) {
          badProgress = true;
        }
        if (badProgress) {
          mem.drill = null;
        } else {
          mem.drill.lastDrill = drilling;
          return holdStill(true);
        }
      }
    }
  }

  const carryFactor = 1 + 0.15 * carried;
  const eReserve = db * (mem.drain || 0.0015) * carryFactor * 1.9 + 0.060;
  const tReserve = db / 0.55 + 22;

  if (carried >= capacity) mem.returning = true;

  if (!mem.returning && carried > 0) {
    if (db < 4.2) mem.returning = true;
    if (battery < eReserve + 0.025) mem.returning = true;
    if (timeLeft < tReserve + 12) mem.returning = true;
  }

  if (!mem.returning && carried === 0) {
    if (battery < 0.10 && db < 150 && timeLeft > 120) mem.returning = true;
    if (battery < 0.040) mem.returning = true;
  }

  // Returning / delivery.
  if (mem.returning) {
    if (carried > 0) {
      if (obs.docked || bd < 2.85 || db < 2.85) {
        return holdStill(false);
      }
      return goBase();
    } else {
      if (obs.docked || bd < 3.0 || db < 3.0) {
        const chTarget = timeLeft > 700 ? 0.98 :
                         timeLeft > 420 ? 0.82 :
                         timeLeft > 220 ? 0.64 : 0.46;
        if (battery < chTarget && timeLeft > 55) {
          return holdStill(false);
        }
        mem.returning = false;
      } else {
        return goBase();
      }
    }
  }

  // Optional charging while at base with no cargo.
  const atBaseZone = !!obs.docked || bd < 3.1 || db < 3.1;
  if (carried === 0 && atBaseZone) {
    const chTarget = timeLeft > 750 ? 0.98 :
                     timeLeft > 450 ? 0.84 :
                     timeLeft > 240 ? 0.66 : 0.48;
    if (battery < chTarget && timeLeft > 75) {
      return holdStill(false);
    }
  }

  // Opportunistic visible site.
  if (!mem.returning && obs.site && carried < capacity) {
    const dSite = +obs.site.distance;
    if (isFinite(dSite) && dSite < 8.2) {
      const cmd = handleVisibleSite();
      if (cmd) return cmd;
    }
  }

  // Briefly pursue a just-lost site fix.
  if (!mem.returning && !obs.site && mem.lastSite && carried < capacity &&
      t - mem.lastSite.t < 9.0) {
    const dls = dist(mem.pos.x, mem.pos.y, mem.lastSite.x, mem.lastSite.y);
    if (dls > 0.75 && dls < 9.5) {
      const abs = Math.atan2(mem.lastSite.y - mem.pos.y, mem.lastSite.x - mem.pos.x) * DEG;
      const rel = wrapDeg(abs - trueHeading);
      const sp = dls > 3 ? 0.68 : 0.34;
      return driveRel(rel, sp);
    }
    if (dls <= 0.85) mem.lastSite = null;
  }

  // Current search.
  if (mem.search) {
    const cmd = runSearch();
    if (cmd) return cmd;
  }

  // Choose or navigate to a hint.
  if (mem.target && mem.target.done) mem.target = null;

  if (!mem.target) {
    const h = chooseHint(carried);
    if (h) {
      mem.target = h;
      mem.targetStartT = t;
    }
  }

  if (mem.target) {
    const h = mem.target;
    if (h.done) {
      mem.target = null;
    } else {
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);

      if (d < 10.5) {
        startSearch(h.x, h.y, h);
        const cmd = runSearch();
        if (cmd) return cmd;
      } else if (t - (mem.targetStartT || t) > 185.0) {
        h.attempts = (h.attempts || 0) + 1;
        h.done = true;
        mem.target = null;
      } else {
        const abs = Math.atan2(h.y - mem.pos.y, h.x - mem.pos.x) * DEG;
        const rel = wrapDeg(abs - trueHeading);
        let sp;
        if (d > 35) sp = 1.24;
        else if (d > 12) sp = 1.00;
        else sp = 0.60;
        return driveRel(rel, sp);
      }
    }
  }

  // No hints left: use a science-triggered local search or explore map.
  if (science > 0.04 && t - (mem.lastFallback || -1e9) > 24.0) {
    mem.lastFallback = t;
    startSearch(mem.pos.x, mem.pos.y, null);
    const cmd = runSearch();
    if (cmd) return cmd;
  }

  let bestP = null;
  let bestD = 1e99;
  if (!mem.explore) mem.explore = [];
  for (let i = 0; i < mem.explore.length; i++) {
    const p = mem.explore[i];
    if (p.used) continue;
    const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
    if (d < bestD) {
      bestD = d;
      bestP = p;
    }
  }

  if (bestP) {
    if (bestD < 5.0) {
      bestP.used = true;
      if (science > 0.005) {
        startSearch(bestP.x, bestP.y, null);
        const cmd = runSearch();
        if (cmd) return cmd;
      }
      return holdStill(false);
    }

    const abs = Math.atan2(bestP.y - mem.pos.y, bestP.x - mem.pos.x) * DEG;
    const rel = wrapDeg(abs - trueHeading);
    const sp = bestD > 30 ? 1.12 : 0.78;
    return driveRel(rel, sp);
  }

  // Last-resort wandering.
  const ang = (t * 0.027) % (2 * PI);
  const rad = 30.0 + 12.0 * Math.sin(t * 0.011);
  const tx = clamp(mem.pos.x + Math.cos(ang) * rad, 8, mem.size - 8);
  const ty = clamp(mem.pos.y + Math.sin(ang) * rad, 8, mem.size - 8);
  const absW = Math.atan2(ty - mem.pos.y, tx - mem.pos.x) * DEG;
  const relW = wrapDeg(absW - trueHeading);
  return driveRel(relW, 0.72);
}

function act(obs, mem) {
  "use strict";

  const PI = Math.PI;
  const RAD = PI / 180;
  const DEG = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrapDeg(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }
  function hyp(a, b) { return Math.sqrt(a * a + b * b); }
  function dist(x1, y1, x2, y2) { return hyp(x2 - x1, y2 - y1); }
  function finite(v, d) { v = +v; return isFinite(v) ? v : d; }

  if (!mem || typeof mem !== "object") mem = {};

  if (!mem.init) {
    mem.init = true;
    const mis = obs.mission || {};
    mem.size = finite(mis.size, 400);
    mem.missionSeconds = finite(mis.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(finite(mis.capacity, 5)));
    mem.base = {
      x: mis.base && isFinite(+mis.base.x) ? +mis.base.x : finite(obs.x, 0),
      y: mis.base && isFinite(+mis.base.y) ? +mis.base.y : finite(obs.y, 0)
    };

    mem.hints = [];
    const hs = Array.isArray(mis.hints) ? mis.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = +h.x, hy = +h.y;
      if (!isFinite(hx) || !isFinite(hy)) continue;
      let hv = +h.estimate;
      if (!isFinite(hv) || hv <= 0) hv = 1;
      mem.hints.push({
        id: mem.hints.length,
        x: hx, y: hy,
        val: hv,
        done: false,
        attempts: 0
      });
    }

    mem.pos = {
      x: finite(obs.x, mem.base.x),
      y: finite(obs.y, mem.base.y)
    };
    mem.head = wrapDeg(finite(obs.heading, 0));
    mem.bias = 0;
    mem.headJump = 0;
    mem.cal = null;

    mem.lastRawX = mem.pos.x;
    mem.lastRawY = mem.pos.y;
    mem.lastRawT = finite(obs.t, 0);
    mem.lastGpsAccept = finite(obs.t, 0);
    mem.gpsFrozen = false;

    mem.wheels = {
      L: { cmd: 0, I: 0, hI: 0, g: 1.5, dz: 0.06, stall: 0, filt: 0, wasHold: false },
      R: { cmd: 0, I: 0, hI: 0, g: 1.5, dz: 0.06, stall: 0, filt: 0, wasHold: false }
    };

    mem.prevBat = finite(obs.battery, 1);
    mem.drain = 0.0018;
    mem.drainN = 0;

    mem.lastCarried = Math.max(0, Math.floor(finite(obs.carried, 0)));
    mem.lastDelivered = finite(obs.delivered, 0);
    mem.samplesCollected = 0;
    mem.hasDelivered = mem.lastDelivered > 0;
    mem.lastSampleT = -1e9;
    mem.deliverT = -1e9;

    mem.sample = null;
    mem.targetHint = null;
    mem.search = null;
    mem.returning = false;
    mem.ignoreSiteUntil = -1e9;
    mem.ignoreSitePos = null;

    mem.recoverUntil = -1e9;
    mem.recoverReverseUntil = -1e9;
    mem.recoverDir = 1;
    mem.prevBump = 0;

    mem.stuckCheckT = finite(obs.t, 0);
    mem.stuckPos = { x: mem.pos.x, y: mem.pos.y };
    mem.stuckHead = mem.head;
    mem.stuckCount = 0;

    mem.prevMoving = false;
    mem.prevHold = false;
    mem.prevDrill = false;
    mem.movingIntent = false;
    mem.holding = false;

    mem.sciHist = [];
    mem.sciGrad = null;
    mem.lastSite = null;

    mem.explore = [];
    const spacing = 58;
    for (let gx = 32; gx <= mem.size - 32; gx += spacing) {
      for (let gy = 32; gy <= mem.size - 32; gy += spacing) {
