  const wr = finite(obs.wheelRight, 0);
  const wheelMax = Math.max(Math.abs(wl), Math.abs(wr));
  const speedAvg = (wl + wr) * 0.5;

  const battery = finite(obs.battery, mem.prevBat || 1);
  const solar = finite(obs.solar, 0);
  const carried = Math.max(0, Math.floor(finite(obs.carried, 0)));
  const carriedValue = finite(obs.carriedValue, 0);
  const delivered = finite(obs.delivered, 0);
  const capacity = mem.capacity || 5;
  const timeLeft = Math.max(0, finite(obs.timeLeft, mem.missionSeconds - t));
  const pitch = finite(obs.pitch, 0);
  const drilling = finite(obs.drilling, 0);

  let science = finite(obs.science, 0);
  if (science < 0) science = 0;

  const rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  const R = new Array(9);
  for (let i = 0; i < 9; i++) {
    let r = +rawRays[i];
    if (!isFinite(r) || r < 0) r = 15;
    if (r > 15) r = 15;
    R[i] = r;
  }
  mem.R = R;

  // Heading filter with jump rejection.
  const rawH = wrapDeg(finite(obs.heading, mem.head));
  const predYawDeg = ((wr - wl) / 0.6) * dt * DEG;
  const dh = wrapDeg(rawH - mem.head);
  if (Math.abs(dh - predYawDeg) < 35 || Math.abs(dh) < 25) {
    mem.head = wrapDeg(mem.head + dh * 0.55);
    mem.headJump = 0;
  } else {
    mem.headJump = (mem.headJump || 0) + 1;
    if (mem.headJump > 8) {
      mem.head = rawH;
      mem.headJump = 0;
    } else {
      mem.head = wrapDeg(mem.head + clamp(predYawDeg, -15, 15));
    }
  }

  let trueHeading = wrapDeg(mem.head - (mem.bias || 0));

  // Position propagation and GPS fusion.
  const oldX = mem.pos.x;
  const oldY = mem.pos.y;
  const predX = mem.pos.x + speedAvg * Math.cos(trueHeading * RAD) * dt;
  const predY = mem.pos.y + speedAvg * Math.sin(trueHeading * RAD) * dt;

  const rawX = +obs.x;
  const rawY = +obs.y;
  if (isFinite(rawX) && isFinite(rawY)) {
    const rawMoved = dist(rawX, rawY, mem.lastRawX, mem.lastRawY);
    if (rawMoved > 0.015) {
      mem.lastRawX = rawX;
      mem.lastRawY = rawY;
      mem.lastRawT = t;
      mem.gpsFrozen = false;
    } else if (t - mem.lastRawT > 2.5 && Math.abs(speedAvg) > 0.12) {
      mem.gpsFrozen = true;
    }

    if (!mem.gpsFrozen) {
      const innov = dist(predX, predY, rawX, rawY);
      if (innov < 10 || t - mem.lastGpsAccept > 2.5) {
        mem.pos.x = predX * 0.30 + rawX * 0.70;
        mem.pos.y = predY * 0.30 + rawY * 0.70;
        mem.lastGpsAccept = t;
      } else {
        mem.pos.x = predX;
        mem.pos.y = predY;
      }
    } else {
      mem.pos.x = predX;
      mem.pos.y = predY;
    }
  } else {
    mem.pos.x = predX;
    mem.pos.y = predY;
  }
  mem.pos.x = clamp(mem.pos.x, -10, mem.size + 10);
  mem.pos.y = clamp(mem.pos.y, -10, mem.size + 10);

  // Beacon compass bias.
  const dbRawNow = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  if (obs.beacon && isFinite(+obs.beacon.distance) && isFinite(+obs.beacon.bearing)) {
    const bd = +obs.beacon.distance;
    const br = +obs.beacon.bearing;
    if (bd > 1.0 && bd < 24 && Math.abs(bd - dbRawNow) < 12) {
      const absB = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
      const trueObs = wrapDeg(absB - br);
      const biasInst = wrapDeg(mem.head - trueObs);
      const delta = wrapDeg(biasInst - (mem.bias || 0));
      if (Math.abs(delta) < 70) {
        mem.bias = wrapDeg((mem.bias || 0) + delta * 0.08);
      }
    }
  }

  trueHeading = wrapDeg(mem.head - (mem.bias || 0));

  // GPS course correction while moving straight.
  const movingStraight = speedAvg > 0.30 && Math.abs(wl - wr) < 0.35 && !mem.gpsFrozen;
  if (movingStraight) {
    if (!mem.cal) {
      mem.cal = { x: mem.pos.x, y: mem.pos.y, t: t, h: mem.head };
    } else if (t - mem.cal.t > 1.2) {
      const movedCal = dist(mem.pos.x, mem.pos.y, mem.cal.x, mem.cal.y);
      if (movedCal > 0.6) {
        const course = Math.atan2(mem.pos.y - mem.cal.y, mem.pos.x - mem.cal.x) * DEG;
        const avgH = wrapDeg(mem.cal.h + wrapDeg(mem.head - mem.cal.h) * 0.5);
        const biasInst = wrapDeg(avgH - course);
        const delta = wrapDeg(biasInst - (mem.bias || 0));
        if (Math.abs(delta) < 50) {
          mem.bias = wrapDeg((mem.bias || 0) + delta * 0.03);
        }
        mem.cal = { x: mem.pos.x, y: mem.pos.y, t: t, h: mem.head };
      } else {
        mem.cal.t = t;
      }
    }
  } else {
    if (!mem.cal || t - mem.cal.t > 2.0) mem.cal = null;
  }

  trueHeading = wrapDeg(mem.head - (mem.bias || 0));

  // Base distance, preferring beacon when plausible.
  let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  if (obs.beacon && isFinite(+obs.beacon.distance)) {
    const bd = +obs.beacon.distance;
    if (bd >= 0 && bd < 25 && Math.abs(bd - db) < 12) db = bd;
  }

  // Science history and local gradient.
  const lastH = mem.sciHist.length ? mem.sciHist[mem.sciHist.length - 1] : null;
  if (!lastH || t - lastH.t > 0.5 || dist(mem.pos.x, mem.pos.y, lastH.x, lastH.y) > 0.5) {
    mem.sciHist.push({ x: mem.pos.x, y: mem.pos.y, s: science, t: t });
    while (mem.sciHist.length > 60) mem.sciHist.shift();
  }

  mem.sciGrad = null;
  {
    const pts = [];
    for (let i = mem.sciHist.length - 1; i >= 0 && pts.length < 45; i--) {
      const p = mem.sciHist[i];
      if (t - p.t > 30) break;
      pts.push(p);
    }
    if (pts.length >= 8) {
      let n = pts.length, sx = 0, sy = 0, ss = 0;
      for (let i = 0; i < n; i++) {
        sx += pts[i].x;
        sy += pts[i].y;
        ss += pts[i].s;
      }
      sx /= n; sy /= n; ss /= n;
      let A = 0, B = 0, C = 0, D = 0, E = 0;
      for (let i = 0; i < n; i++) {
        const u = pts[i].x - sx;
        const v = pts[i].y - sy;
        const w = pts[i].s - ss;
        A += u * u;
        B += u * v;
        C += v * v;
        D += u * w;
        E += v * w;
      }
      const det = A * C - B * B;
      if (det > 0.08) {
        const gx = (D * C - E * B) / det;
        const gy = (E * A - D * B) / det;
        const gm = hyp(gx, gy);
        if (isFinite(gx) && isFinite(gy) && gm > 1e-7 && gm < 1e6) {
          mem.sciGrad = { x: gx, y: gy, t: t };
        }
      } else if (pts.length >= 4) {
        const p0 = pts[pts.length - 1];
        const p1 = pts[0];
        const dx = p1.x - p0.x;
        const dy = p1.y - p0.y;
        const md = hyp(dx, dy);
        const ds = p1.s - p0.s;
        if (md > 1.0 && Math.abs(ds) > 0.02) {
          const dir = ds >= 0 ? 1 : -1;
          mem.sciGrad = { x: dir * dx / md, y: dir * dy / md, t: t };
        }
      }
    }
  }

  // Event bookkeeping.
  const prevCarried = mem.lastCarried || 0;
  if (carried > prevCarried) {
    mem.samplesCollected += carried - prevCarried;
    mem.lastSampleT = t;

    let nearest = null;
    let nearestD = 1e99;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.done) continue;
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      if (d < nearestD && d < 35) {
        nearestD = d;
        nearest = h;
      }
    }
    if (nearest) nearest.done = true;
    if (mem.targetHint) mem.targetHint.done = true;
    if (mem.search && mem.search.hint) mem.search.hint.done = true;

    mem.sample = null;
    mem.search = null;
    mem.targetHint = null;
  }

  if (carried < prevCarried) {
    if (obs.docked || dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) < 3.2) {
      mem.hasDelivered = true;
      mem.deliverT = t;
    }
  }

  if (delivered > (mem.lastDelivered || 0) + 1e-9) {
    mem.hasDelivered = true;
    mem.deliverT = t;
  }

  mem.lastCarried = carried;
  mem.lastDelivered = Math.max(mem.lastDelivered || 0, delivered);

  // Bump detection.
  const bumpVal = (typeof obs.bumped === "number") ? +obs.bumped : (obs.bumped ? 1 : 0);
  if (bumpVal > 0 && !((mem.prevBump || 0) > 0)) {
    const leftOpen = R[5] + R[6] + R[7] + R[8];
    const rightOpen = R[0] + R[1] + R[2] + R[3];
    mem.recoverDir = leftOpen >= rightOpen ? 1 : -1;
    mem.recoverUntil = t + 1.45;
    mem.recoverReverseUntil = t + 0.60;
    mem.sample = null;
    mem.movingIntent = false;
  }
  mem.prevBump = bumpVal;

  // Stuck detection.
  if (t - mem.stuckCheckT > 4.0) {
    const moved = dist(mem.pos.x, mem.pos.y, mem.stuckPos.x, mem.stuckPos.y);
    const turned = Math.abs(wrapDeg(mem.head - mem.stuckHead));
    if (mem.prevMoving && !mem.prevHold && moved < 0.25 && turned < 25) {
      mem.stuckCount = (mem.stuckCount || 0) + 1;
    } else {
      mem.stuckCount = 0;
    }

    if (mem.stuckCount >= 2 && t > mem.recoverUntil) {
      const leftOpen = R[5] + R[6] + R[7] + R[8];
      const rightOpen = R[0] + R[1] + R[2] + R[3];
      mem.recoverDir = leftOpen >= rightOpen ? 1 : -1;
      mem.recoverUntil = t + 1.55;
      mem.recoverReverseUntil = t + 0.65;
      mem.stuckCount = 0;
      mem.sample = null;
    }

    mem.stuckCheckT = t;
    mem.stuckPos.x = mem.pos.x;
    mem.stuckPos.y = mem.pos.y;
    mem.stuckHead = mem.head;
  }

  // Energy per metre estimate, excluding holds/drilling.
  const usedEnergy = (mem.prevBat + solar * dt) - battery;
  const movedStep = dist(mem.pos.x, mem.pos.y, oldX, oldY);
  if (usedEnergy > 0.000001 && usedEnergy < 0.08 &&
      movedStep > 0.04 && speedAvg > 0.25 &&
      mem.prevMoving && !mem.prevDrill && !obs.docked) {
    const ratio = usedEnergy / movedStep / (1 + 0.12 * carried);
    if (ratio > 0.00015 && ratio < 0.008) {
      mem.drain = clamp(mem.drain * 0.995 + ratio * 0.005, 0.0004, 0.006);
      mem.drainN = (mem.drainN || 0) + 1;
    }
  }
  mem.prevBat = battery;

  // ---------------------------------------------------------------------------
  // Low-level control helpers.
  // ---------------------------------------------------------------------------

  function slew(prev, desired, maxRate) {
    let md = maxRate * dt;
    if (md > 0.5) md = 0.5;
    if (md < 0.02) md = 0.02;
    return prev + clamp(desired - prev, -md, md);
  }

  function wheelControl(side, target, actual, hold) {
    const s = mem.wheels[side];
    actual = finite(actual, 0);
    s.filt = (s.filt || 0) * 0.55 + actual * 0.45;

    if (hold) {
      if (!s.wasHold) {
        s.hI = 0;
        s.I = 0;
      }
      s.wasHold = true;

      if (Math.abs(s.filt) > 0.03) {
        s.hI = clamp((s.hI || 0) + (-s.filt) * dt * 0.12, -0.50, 0.50);
      } else {
        s.hI = (s.hI || 0) * 0.9995;
      }

      const slopeComp = clamp(pitch * 0.0045, -0.16, 0.16);
      let cmd = slopeComp + s.hI - s.filt * 0.30;
      if (Math.abs(cmd) < 0.015 && Math.abs(s.filt) < 0.03) cmd = 0;

      s.cmd = slew(s.cmd || 0, clamp(cmd, -0.90, 0.90), 4.0);
    } else {
      if (s.wasHold) {
        s.I = 0;
        s.hI = 0;
      }
      s.wasHold = false;

      const tc = clamp(finite(target, 0), -2.7, 2.7);
      const err = tc - s.filt;
      s.I = clamp((s.I || 0) + err * dt * 0.12, -0.8, 0.8);

      const g = clamp(s.g || 1.5, 0.2, 6.0);
      let ff = tc / g;
      const dz = s.dz || 0.06;
      if (Math.abs(tc) > 0.04) {
        if (ff >= 0) ff = Math.max(ff, dz);
        else ff = Math.min(ff, -dz);
      }

      let cmd = ff + err * 0.30 + s.I;
      if (cmd > 1.0 && err > 0) s.I = Math.min(s.I, 0.8);
      if (cmd < -1.0 && err < 0) s.I = Math.max(s.I, -0.8);

      s.cmd = slew(s.cmd || 0, clamp(cmd, -1.0, 1.0), 5.0);

      if (Math.abs(s.cmd) > 0.25 && Math.abs(s.filt) > 0.12 && s.cmd * s.filt > 0) {
        const obsGain = s.filt / s.cmd;
        if (obsGain > 0.15 && obsGain < 8.0) {
          s.g = clamp((s.g || 1.5) * 0.995 + obsGain * 0.005, 0.2, 6.0);
        }
      }

      if (Math.abs(tc) > 0.12 && Math.abs(s.filt) < 0.02) {
        s.stall = (s.stall || 0) + dt;
        if (s.stall > 0.8) {
          s.dz = Math.min(0.25, (s.dz || 0.06) + 0.010);
          s.stall = 0;
        }
      } else {
        s.stall = 0;
        if (Math.abs(s.filt) > 0.08) {
          s.dz = Math.max(0.030, (s.dz || 0.06) * 0.9995);
        }
      }
    }

    s.cmd = clamp(s.cmd || 0, -1.0, 1.0);
    return s.cmd;
  }

  function setDrive(vL, vR, drillOn) {
    mem.movingIntent = Math.abs((vL + vR) * 0.5) > 0.06 || Math.abs(vR - vL) > 0.10;
    mem.holding = false;
    vL = clamp(finite(vL, 0), -2.7, 2.7);
    vR = clamp(finite(vR, 0), -2.7, 2.7);
    const cL = wheelControl("L", vL, wl, false);
    const cR = wheelControl("R", vR, wr, false);
    return { left: clamp(cL, -1, 1), right: clamp(cR, -1, 1), drill: !!drillOn };
  }

  function holdStill(drillOn) {
    mem.movingIntent = false;
    mem.holding = true;
    const cL = wheelControl("L", 0, wl, true);
    const cR = wheelControl("R", 0, wr, true);
    return { left: clamp(cL, -1, 1), right: clamp(cR, -1, 1), drill: !!drillOn };
  }

  function driveRel(rel, speed) {
    let e = wrapDeg(rel);
    let sp = clamp(finite(speed, 0.8), 0, 1.35);

    const front = Math.min(R[3], R[4], R[5]);
    const leftOpen = R[5] + R[6] + R[7] + R[8];
    const rightOpen = R[0] + R[1] + R[2] + R[3];

    if (front < 3.0) {
      const turn = leftOpen >= rightOpen ? 1 : -1;
      const u = clamp((3.0 - front) / 2.2, 0, 1);
      if (front < 0.90) {
        sp = 0;
        e = turn * 85;
      } else {
        sp = Math.min(sp, Math.max(0.05, (front - 0.50) * 0.50));
        e = wrapDeg(e * (1 - 0.65 * u) + turn * 60 * u);
      }
    }

    if (R[8] < 0.8 && e > 0) e = wrapDeg(e - 12 * (1 - R[8] / 0.8));
    if (R[0] < 0.8 && e < 0) e = wrapDeg(e + 12 * (1 - R[0] / 0.8));

    const edge = Math.min(mem.pos.x, mem.pos.y, mem.size - mem.pos.x, mem.size - mem.pos.y);
    if (edge < 10) {
      const toC = Math.atan2(mem.size * 0.5 - mem.pos.y, mem.size * 0.5 - mem.pos.x) * DEG;
      const relC = wrapDeg(toC - trueHeading);
      const w = clamp((10 - edge) / 10, 0, 1) * 0.90;
      e = wrapDeg(e * (1 - w) + relC * w);
      if (edge < 5) sp = Math.min(sp, 0.35);
      else sp = Math.min(sp, 0.80);
    }

    const ae = Math.abs(e);
    if (ae > 120) sp = Math.min(sp, 0.06);
    else if (ae > 70) sp = Math.min(sp, 0.25);
    else if (ae > 35) sp = Math.min(sp, 0.60);

    if (pitch > 18) sp = Math.min(sp, 0.80 - pitch * 0.010);
    if (pitch > 30) sp = Math.min(sp, 0.25);

    const er = e * RAD;
    let omega = clamp(er * 1.5, -1.0, 1.0);
    const yawMeas = (wr - wl) / 0.6;
    if (isFinite(yawMeas)) omega -= clamp(yawMeas * 0.08, -0.15, 0.15);

    let vL = sp - omega * 0.30;
    let vR = sp + omega * 0.30;

    const maxAbs = Math.max(Math.abs(vL), Math.abs(vR), 1e-9);
    if (maxAbs > 2.5) {
      vL *= 2.5 / maxAbs;
      vR *= 2.5 / maxAbs;
    }

    return setDrive(vL, vR, false);
  }

  function driveToPoint(tx, ty, speed) {
    const d = dist(mem.pos.x, mem.pos.y, tx, ty);
    if (d < 0.55) return holdStill(false);

    const absB = Math.atan2(ty - mem.pos.y, tx - mem.pos.x) * DEG;
    const rel = wrapDeg(absB - trueHeading);

    let sp = clamp(finite(speed, 0.8), 0, 1.35);
    if (d < 2.2) sp = Math.min(sp, Math.max(0.12, (d - 0.4) * 0.5));
    if (d < 0.9) sp = Math.min(sp, 0.16);

    return driveRel(rel, sp);
  }

  function goBase() {
    if (obs.beacon && isFinite(+obs.beacon.distance) && isFinite(+obs.beacon.bearing)) {
      const bd = +obs.beacon.distance;
      const br = +obs.beacon.bearing;
      if (bd < 0.9) return holdStill(false);
      let sp;
      if (bd > 12) sp = 1.10;
      else if (bd > 4) sp = 0.75;
      else if (bd > 2) sp = 0.45;
      else sp = 0.25;
      return driveRel(br, sp);
    }

    const d = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (d < 0.9) return holdStill(false);

    const absB = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
    const rel = wrapDeg(absB - trueHeading);

    let sp;
    if (d > 25) sp = 1.10;
    else if (d > 6) sp = 0.80;
    else if (d > 3) sp = 0.45;
    else sp = 0.25;

    return driveRel(rel, sp);
  }

  function chooseHint(carrying) {
    let best = null;
    let bestScore = -1e99;
    const curDb = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    const drainUse = clamp(mem.drain || 0.0018, 0.0006, 0.005);

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.done) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dbh = dist(mem.base.x, mem.base.y, h.x, h.y);
      const val = Math.max(0.1, h.val || 1);

      let score;
      if (carrying === 0) {
        score = Math.pow(val, 0.80) / (18 + d + 0.25 * dbh);
      } else {
        const detour = Math.max(0, d + dbh - curDb);
        score = Math.pow(val, 0.80) / (22 + d + 0.70 * detour);
      }

      if (h.attempts > 0) score *= 0.50;

      const legs = d + dbh + 30;
      const needT = legs / 0.55 + 25 + 8 * carrying;
      const needE = legs * drainUse * (1 + 0.15 * carrying) * 1.35 + 0.06 + 0.01 * carrying;

      if (timeLeft < needT * 0.95) continue;
      if (battery < needE * 0.90) continue;

      if (h.x < 5 || h.x > mem.size - 5 || h.y < 5 || h.y > mem.size - 5) score *= 0.75;

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }

    return best;
  }

  function makeSpiral(cx, cy, maxR, spacing) {
    cx = clamp(cx, 6, mem.size - 6);
    cy = clamp(cy, 6, mem.size - 6);

    const pts = [{ x: cx, y: cy }];
    const b = spacing / (2 * PI);
    let theta = 0.8;
    let steps = 0;
    const stepDist = 4.0;

    while (steps++ < 300) {
      const r = b * theta;
      if (r > maxR) break;
      pts.push({
        x: clamp(cx + r * Math.cos(theta), 5, mem.size - 5),
        y: clamp(cy + r * Math.sin(theta), 5, mem.size - 5)
      });
      const dtheta = stepDist / Math.max(r, 1.5);
      theta += clamp(dtheta, 0.12, 0.8);
    }
    return pts;
  }

  function finishSearch() {
    if (mem.search && mem.search.hint) {
      mem.search.hint.done = true;
      mem.search.hint.attempts = (mem.search.hint.attempts || 0) + 1;
    }
    mem.search = null;
  }

  function startSearch(cx, cy, hint) {
    const val = hint ? Math.max(0.5, hint.val || 1) : 1;
    const maxR = hint ? clamp(18 + Math.min(10, val * 2), 20, 28) : 22;
    mem.search = {
      cx: clamp(cx, 6, mem.size - 6),
      cy: clamp(cy, 6, mem.size - 6),
      hint: hint || null,
      pts: makeSpiral(cx, cy, maxR, 7.0),
      idx: 0,
      startT: t,
      lastWayT: t,
      maxTime: hint ? 95 : 70,
      maxR: maxR,
      maxSci: science,
      sciSeen: science > 0.03
    };
    mem.targetHint = null;
  }

  function runSearch() {
    const s = mem.search;
    if (!s) return null;

    if (s.hint && s.hint.done) {
      mem.search = null;
      return null;
    }

    if (science > s.maxSci) s.maxSci = science;
    if (science > 1e-7) s.sciSeen = true;

    if (t - s.startT > s.maxTime) {
      finishSearch();
      return null;
    }

    if (!s.sciSeen && t - s.startT > 15) {
      finishSearch();
      return null;
    }

    while (s.idx < s.pts.length) {
      const p = s.pts[s.idx];
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < 1.6 || t - s.lastWayT > 12) {
        s.idx++;
        s.lastWayT = t;
      } else {
        break;
      }
    }

    if (s.idx >= s.pts.length) {
      finishSearch();
      return null;
    }

    if (t - s.startT < 30 && mem.sciGrad && t - mem.sciGrad.t < 2.0 && science > 0.03) {
      const gx = mem.sciGrad.x;
      const gy = mem.sciGrad.y;
      const gm = hyp(gx, gy);
      if (gm > 1e-7) {
        const step = 7.0;
        const tx = clamp(mem.pos.x + gx / gm * step, 5, mem.size - 5);
        const ty = clamp(mem.pos.y + gy / gm * step, 5, mem.size - 5);
        const dg = dist(mem.pos.x, mem.pos.y, tx, ty);
        const dc = dist(tx, ty, s.cx, s.cy);
        if (dg > 1.0 && dg < 15 && dc < s.maxR + 10) {
          return driveToPoint(tx, ty, 0.82);
        }
      }
    }

    const p = s.pts[s.idx];
    const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
    let sp;
    if (d > 6) sp = 0.90;
    else if (d > 2) sp = 0.60;
    else sp = 0.40;

    return driveToPoint(p.x, p.y, sp);
  }

  function doExplore() {
    if (mem.sciGrad && t - mem.sciGrad.t < 2.0 && science > 0.03 && timeLeft > 25) {
      const gx = mem.sciGrad.x;
      const gy = mem.sciGrad.y;
      const gm = hyp(gx, gy);
      if (gm > 1e-7) {
        const step = 8.0;
        const tx = clamp(mem.pos.x + gx / gm * step, 5, mem.size - 5);
        const ty = clamp(mem.pos.y + gy / gm * step, 5, mem.size - 5);
        return driveToPoint(tx, ty, 0.82);
      }
    }

    let best = null;
    let bestD = 1e99;
    for (let i = 0; i < mem.explore.length; i++) {
      const p = mem.explore[i];
      if (p.used) continue;
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }

    if (best) {
      if (bestD < 4.5) {
        best.used = true;
        if (science > 0.02) {
          startSearch(best.x, best.y, null);
          const cmd = runSearch();
          if (cmd) return cmd;
        }
        return holdStill(false);
      }
      const sp = bestD > 40 ? 1.00 : 0.75;
      return driveToPoint(best.x, best.y, sp);
    }

    const ang = (t * 0.05) % (2 * PI);
    const tx = clamp(mem.pos.x + 30 * Math.cos(ang), 8, mem.size - 8);
    const ty = clamp(mem.pos.y + 30 * Math.sin(ang), 8, mem.size - 8);
    return driveToPoint(tx, ty, 0.70);
  }

  function sampleOrApproach() {
    if (!obs.site) return null;
    if (!isFinite(+obs.site.distance) || !isFinite(+obs.site.bearing)) return null;

    const d = Math.max(0, +obs.site.distance);
    const br = +obs.site.bearing;
    const val = finite(obs.site.value, 0);

    const absSite = (trueHeading + br) * RAD;
    mem.lastSite = {
      x: mem.pos.x + d * Math.cos(absSite),
      y: mem.pos.y + d * Math.sin(absSite),
      t: t,
      value: val
    };

    if (d > 1.25) {
      if (mem.sample && d > 1.55) mem.sample = null;
      let sp;
      if (d > 5) sp = 0.90;
      else if (d > 2) sp = 0.55;
      else sp = Math.max(0.12, (d - 0.60) * 0.50);
      return driveRel(br, sp);
    }

    if (!mem.sample) {
      mem.sample = {
        startT: t,
        startCarried: carried,
        stable: 0,
        drill: false,
        value: val,
        hint: mem.search && mem.search.hint ? mem.search.hint : mem.targetHint
      };
    }

    const s = mem.sample;

    if (wheelMax < 0.13) s.stable += dt;
    else s.stable = 0;

    if (!s.drill && s.stable >= 0.20) s.drill = true;

    if (carried <= s.startCarried && t - s.startT > 24) {
      mem.sample = null;
      mem.ignoreSiteUntil = t + 6.0;
      mem.ignoreSitePos = { x: mem.lastSite.x, y: mem.lastSite.y };
      if (mem.search && mem.search.hint) mem.search.hint.done = true;
      if (mem.targetHint) mem.targetHint.done = true;
