      const eff = Math.max(0.04, Math.abs(s.cmd) - 0.035);
      const gg = Math.abs(a) / eff;
      if (gg > 0.25 && gg < 6.0 && Math.abs(err) < Math.max(0.30, 0.60 * mag)) {
        s.g = clamp((s.g || 1.8) * 0.998 + gg * 0.002, 0.40, 6.0);
      }
    }

    if (Math.abs(target) > 0.20 && Math.abs(a) < 0.03) {
      s.stall = (s.stall || 0) + dt;
      if (s.stall > 0.9) {
        s.dz = Math.min(0.20, (s.dz || 0.06) + 0.008);
        s.stall = 0;
      }
    } else {
      s.stall = 0;
      if (Math.abs(a) > 0.10) s.dz = Math.max(0.035, (s.dz || 0.06) * 0.9995);
    }

    return s.cmd;
  }

  function setDrive(vL, vR, drillOn) {
    vL = clamp(finite(vL, 0), -2.6, 2.6);
    vR = clamp(finite(vR, 0), -2.6, 2.6);
    const movingTarget = Math.abs(vL) + Math.abs(vR) > 0.060;
    mem.movingIntent = movingTarget;
    const holding = !movingTarget;
    const cL = wheelControl("L", vL, wl, holding);
    const cR = wheelControl("R", vR, wr, holding);
    return { left: clamp(cL, -1, 1), right: clamp(cR, -1, 1), drill: !!drillOn };
  }

  function holdStill(drillOn) {
    return setDrive(0, 0, drillOn);
  }

  function triggerAvoid(dir, duration, reverseTime) {
    if (!mem.avoid || t >= mem.avoid.until) {
      mem.avoid = {
        until: t + (duration || 1.25),
        reverseUntil: t + (reverseTime || 0.55),
        dir: dir || 1
      };
    }
  }

  function driveRel(rel, speed) {
    let e = wrapDeg(rel);
    let sp = clamp(finite(speed, 0.8), 0, 1.38);
    const actualMax = Math.max(Math.abs(wl), Math.abs(wr));

    // Very close front obstacle: reverse now and recover next ticks.
    if (front < 0.82 || (front < 1.10 && actualMax > 0.66) || R[4] < 0.55) {
      const dir = leftClear >= rightClear ? 1 : -1;
      triggerAvoid(dir, 1.35, 0.58);
      return setDrive(-0.36, -0.36, false);
    }

    const edge = Math.min(mem.pos.x, mem.pos.y, mem.size - mem.pos.x, mem.size - mem.pos.y);
    if (edge < 12) {
      const toC = Math.atan2(mem.size * 0.5 - mem.pos.y, mem.size * 0.5 - mem.pos.x) * DEG;
      const relC = wrapDeg(toC - trueHeading);
      const w = clamp((12 - edge) / 12, 0, 1) * 0.82;
      e = wrapDeg(e * (1 - w) + relC * w);
      if (edge < 5) sp = Math.min(sp, 0.28);
      else sp = Math.min(sp, 0.85);
    }

    if (sideL < 0.95 && e > -25) e = wrapDeg(e - 16 * (1 - sideL / 0.95));
    if (sideR < 0.95 && e < 25) e = wrapDeg(e + 16 * (1 - sideR / 0.95));

    if (front < 3.2) {
      const u = clamp((3.2 - front) / 3.2, 0, 1);
      const dir = leftClear >= rightClear ? 1 : -1;
      e = wrapDeg(e * (1 - 0.58 * u) + dir * 68 * 0.58 * u);
      sp = Math.min(sp, Math.max(0.03, (front - 0.65) * 0.52));
    }
    if (front < 1.55) sp = Math.min(sp, 0.13);
    else if (front < 2.35) sp = Math.min(sp, 0.42);

    if (front < 2.7 && actualMax > Math.max(0.34, (front - 0.45) * 0.62)) {
      sp = Math.min(sp, 0.06);
    }

    if (pitch > 24) sp = Math.min(sp, 0.68);
    if (pitch > 34) sp = Math.min(sp, 0.34);
    if (pitch < -24) sp = Math.min(sp, 0.78);

    const absE = Math.abs(e);
    if (absE > 110) sp = 0;
    else if (absE > 72) sp *= 0.25;
    else if (absE > 42) sp *= 0.58;

    let omega = clamp(e * RAD * 1.25, -0.92, 0.92);
    const yawMeas = (wr - wl) / 0.6;
    if (isFinite(yawMeas)) omega -= clamp(yawMeas * 0.10, -0.15, 0.15);

    let vL = sp - omega * 0.30;
    let vR = sp + omega * 0.30;

    let maxWheel = 1.65;
    if (front < 1.25) maxWheel = 0.30;
    else if (front < 2.05) maxWheel = 0.58;
    else if (front < 3.6) maxWheel = 0.92;

    vL = clamp(vL, -maxWheel, maxWheel);
    vR = clamp(vR, -maxWheel, maxWheel);

    return setDrive(vL, vR, false);
  }

  function driveToPoint(tx, ty, speed) {
    const d = dist(mem.pos.x, mem.pos.y, tx, ty);
    if (d < 0.55) return holdStill(false);
    const absB = Math.atan2(ty - mem.pos.y, tx - mem.pos.x) * DEG;
    const rel = wrapDeg(absB - trueHeading);
    let sp = clamp(finite(speed, 0.8), 0, 1.30);
    if (d < 2.6) sp = Math.min(sp, Math.max(0.10, (d - 0.35) * 0.42));
    return driveRel(rel, sp);
  }

  function goBase() {
    if (beaconValid) {
      if (beaconDist < 2.05 && carried > 0) return holdStill(false);
      let sp;
      if (beaconDist > 18) sp = 1.16;
      else if (beaconDist > 8) sp = 0.92;
      else if (beaconDist > 4) sp = 0.62;
      else sp = 0.30;
      if (carried > 0) sp *= 0.92;
      return driveRel(beaconBearing, sp);
    }

    const d = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (d < 2.0 && carried > 0) return holdStill(false);
    const absB = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
    const rel = wrapDeg(absB - trueHeading);
    let sp;
    if (d > 18) sp = 1.14;
    else if (d > 8) sp = 0.90;
    else if (d > 4) sp = 0.60;
    else sp = 0.30;
    if (carried > 0) sp *= 0.92;
    return driveRel(rel, sp);
  }

  function makeSpiral(cx, cy, maxR, spacing) {
    cx = clamp(cx, 5, mem.size - 5);
    cy = clamp(cy, 5, mem.size - 5);
    const pts = [{ x: cx, y: cy }];
    const b = spacing / (2 * PI);
    let theta = 0.85;
    let guard = 0;
    while (guard++ < 280) {
      const r = b * theta;
      if (r > maxR) break;
      const x = cx + r * Math.cos(theta);
      const y = cy + r * Math.sin(theta);
      pts.push({ x: clamp(x, 5, mem.size - 5), y: clamp(y, 5, mem.size - 5) });
      const dtheta = 3.6 / Math.max(r, 1.5);
      theta += clamp(dtheta, 0.12, 0.78);
    }
    return pts;
  }

  function startSearch(cx, cy, hint) {
    cx = clamp(cx, 5, mem.size - 5);
    cy = clamp(cy, 5, mem.size - 5);

    if (mem.search && mem.search.hint === hint &&
        Math.abs(mem.search.cx - cx) < 2.0 && Math.abs(mem.search.cy - cy) < 2.0) {
      return;
    }

    const val = hint ? Math.max(0.5, hint.val || 1) : 1;
    const maxR = hint ? clamp(18 + Math.min(10, val * 2.0), 20, 28) : 20;
    const maxTime = hint ? (val > 3.0 ? 115 : 92) : 65;

    mem.search = {
      cx: cx,
      cy: cy,
      hint: hint || null,
      pts: makeSpiral(cx, cy, maxR, 7.0),
      idx: 0,
      startT: t,
      lastWayT: t,
      maxTime: maxTime,
      maxR: maxR,
      maxSci: science,
      sciSeen: science > 0.008,
      drill: false
    };
    mem.targetHint = null;
  }

  function finishSearch(markDone) {
    const s = mem.search;
    if (s && s.hint && markDone) {
      s.hint.attempts = (s.hint.attempts || 0) + 1;
      s.hint.done = true;
    }
    mem.search = null;
  }

  function runSearch() {
    const s = mem.search;
    if (!s) return null;

    if (s.hint && s.hint.done) {
      mem.search = null;
      return null;
    }

    if (science > s.maxSci) s.maxSci = science;
    if (science > 0.006) s.sciSeen = true;

    if (!s.sciSeen && t - s.startT > 10.5) {
      finishSearch(true);
      return null;
    }
    if (t - s.startT > s.maxTime) {
      finishSearch(true);
      return null;
    }

    // Strong local gradient chase first.
    if (science > 0.004 && mem.sciGrad && t - mem.sciGrad.t < 2.3 && mem.sciGrad.mag > 1e-7) {
      const gm = mem.sciGrad.mag;
      const step = 5.8;
      const tx = clamp(mem.pos.x + mem.sciGrad.x / gm * step, 5, mem.size - 5);
      const ty = clamp(mem.pos.y + mem.sciGrad.y / gm * step, 5, mem.size - 5);
      const dc = dist(tx, ty, s.cx, s.cy);
      if (dist(mem.pos.x, mem.pos.y, tx, ty) > 1.1 && dc < s.maxR + 10) {
        return driveToPoint(tx, ty, 0.80);
      }
    }

    while (s.idx < s.pts.length) {
      const p = s.pts[s.idx];
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < 1.65 || t - s.lastWayT > 12.0) {
        s.idx++;
        s.lastWayT = t;
      } else {
        break;
      }
    }

    if (s.idx >= s.pts.length) {
      finishSearch(true);
      return null;
    }

    const p = s.pts[s.idx];
    const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
    let sp;
    if (d > 6) sp = 0.88;
    else if (d > 2) sp = 0.62;
    else sp = 0.40;
    return driveToPoint(p.x, p.y, sp);
  }

  function chooseHint(carrying) {
    let best = null;
    let bestScore = -1e99;
    const curBase = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    const drainUse = clamp(mem.drain || 0.0022, 0.0005, 0.0055);

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.done) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dbh = dist(mem.base.x, mem.base.y, h.x, h.y);
      const val = Math.max(0.2, h.val || 1);

      let cost;
      if (carrying > 0) {
        const extra = Math.max(0, d + dbh - curBase);
        cost = d + 0.70 * extra + 15;
      } else {
        cost = d + 0.55 * dbh + 20;
      }

      const needT = (d + dbh) / 0.52 + 32 + 8 * carrying;
      if (timeLeft < needT && carrying > 0) continue;

      const needE = (d + dbh) * drainUse * (1 + 0.15 * carrying) * 1.9 + 0.065;
      if (battery < needE && carrying > 0) continue;

      let score = Math.pow(val, 1.25) / (cost + 25);
      if (h.attempts > 0) score *= 0.38;
      if (h.x < 7 || h.x > mem.size - 7 || h.y < 7 || h.y > mem.size - 7) score *= 0.82;

      if (carrying === 0 && t < 260) score *= 1 + 16 / (d + 22);

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best;
  }

  function estimateSitePos(d, br) {
    const abs = (trueHeading + br) * RAD;
    return {
      x: mem.pos.x + d * Math.cos(abs),
      y: mem.pos.y + d * Math.sin(abs)
    };
  }

  function failedSample() {
    if (mem.sample && mem.sample.hint) {
      mem.sample.hint.attempts = (mem.sample.hint.attempts || 0) + 1;
      mem.sample.hint.done = true;
    }
    if (mem.lastSite) {
      mem.ignore = { until: t + 10, x: mem.lastSite.x, y: mem.lastSite.y };
    }
    mem.sample = null;
    mem.search = null;
    mem.targetHint = null;
  }

  function handleSite() {
    if (!obs.site) return null;
    const d = Math.max(0, +obs.site.distance);
    const br = +obs.site.bearing;
    const val = finite(obs.site.value, 0);
    if (!isFinite(d) || !isFinite(br)) return null;
    if (d > 8.05) return null;

    const sp = estimateSitePos(d, br);
    mem.lastSite = { x: sp.x, y: sp.y, t: t, value: val };

    let s = mem.sample;
    if (s) {
      if (!s.site || dist(s.site.x, s.site.y, sp.x, sp.y) > 3.0) {
        s = null;
        mem.sample = null;
      }
    }

    const keepDist = s ? 1.47 : 1.32;
    if (d > keepDist) {
      mem.sample = null;
      s = null;
      let driveSpeed;
      if (d > 6) driveSpeed = 0.90;
      else if (d > 3) driveSpeed = 0.58;
      else if (d > 1.8) driveSpeed = 0.32;
      else driveSpeed = Math.max(0.10, (d - 0.35) * 0.45);
      if (Math.max(Math.abs(wl), Math.abs(wr)) > 0.72 && d < 2.5) driveSpeed = 0.07;
      return driveRel(br, driveSpeed);
    }

    if (!mem.sample) {
      mem.sample = {
        startT: t,
        startCarried: carried,
        stable: 0,
        drill: false,
        value: val,
        hint: mem.search ? mem.search.hint : mem.targetHint,
        site: { x: sp.x, y: sp.y }
      };
    }

    s = mem.sample;
    if (!s.hint) s.hint = mem.search ? mem.search.hint : mem.targetHint;

    const vmax = Math.max(Math.abs(wl), Math.abs(wr));
    if (vmax < 0.135) s.stable += dt;
    else s.stable = Math.max(0, s.stable - dt * 0.7);

    if (s.stable > 0.20 || drilling > 0.01) s.drill = true;

    if (t - s.startT > 24.0 && carried <= s.startCarried) {
      failedSample();
      return holdStill(false);
    }

    if (s.drill && d < 1.48) {
      return holdStill(true);
    }

    return holdStill(false);
  }

  function doExplore() {
    if (science > 0.10 && mem.sciGrad && t - mem.sciGrad.t < 2.3 && mem.sciGrad.mag > 1e-7) {
      const gm = mem.sciGrad.mag;
      const step = 8.0;
      const tx = clamp(mem.pos.x + mem.sciGrad.x / gm * step, 5, mem.size - 5);
      const ty = clamp(mem.pos.y + mem.sciGrad.y / gm * step, 5, mem.size - 5);
      if (dist(mem.pos.x, mem.pos.y, tx, ty) > 1.2) {
        return driveToPoint(tx, ty, 0.84);
      }
    }

    let best = null;
    let bestD = 1e99;
    for (let i = 0; i < mem.explore.length; i++) {
      const p = mem.explore[i];
      if (p.used) continue;
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }

    if (best) {
      if (bestD < 5.0) {
        best.used = true;
        if (science > 0.015) {
          startSearch(mem.pos.x, mem.pos.y, null);
          const cmd = runSearch();
          if (cmd) return cmd;
        }
        return holdStill(false);
      }
      const sp = bestD > 42 ? 1.02 : 0.80;
      return driveToPoint(best.x, best.y, sp);
    }

    const ang = (t * 0.037) % (2 * PI);
    const tx = clamp(mem.pos.x + 30 * Math.cos(ang), 9, mem.size - 9);
    const ty = clamp(mem.pos.y + 30 * Math.sin(ang), 9, mem.size - 9);
    return driveToPoint(tx, ty, 0.72);
  }

  // Recovery has priority.
  if (mem.avoid && t < mem.avoid.until) {
    if (t < mem.avoid.reverseUntil) {
      return setDrive(-0.36, -0.36, false);
    }
    const dir = mem.avoid.dir || 1;
    return setDrive(-dir * 0.48, dir * 0.48, false);
  }

  const atBase = !!obs.docked || db < 2.85;
  const full = carried >= capacity;
  const carryFactor = 1 + 0.15 * carried;
  const drainUse = clamp(mem.drain || 0.0022, 0.0005, 0.0055);
  const eBack = db * drainUse * carryFactor * 2.15 + 0.065 + 0.012 * carried;
  const tBack = db / 0.48 + 25 + 9 * carried;

  if (full) mem.returning = true;
  if (carried > 0 && (battery < eBack + 0.025 || timeLeft < tBack + 16)) mem.returning = true;
  if (carried === 0 && battery < 0.10 && db > 8 && timeLeft > 120) mem.returning = true;
  if (timeLeft < 42) mem.returning = true;

  if (mem.returning) {
    mem.sample = null;
    mem.search = null;
    mem.targetHint = null;
  }

  // Deliver if carrying and at base.
  if (carried > 0 && atBase) {
    mem.returning = false;
    mem.chargeStartT = null;
    return holdStill(false);
  }

  // Return if requested and not at base, or with cargo.
  if (mem.returning) {
    if (carried > 0 || !atBase) {
      return goBase();
    }

    // Empty and at base: charge, then resume.
    const goal = timeLeft > 800 ? 0.96 :
                 timeLeft > 500 ? 0.88 :
                 timeLeft > 260 ? 0.76 : 0.56;
    if (battery < goal - 0.005 && timeLeft > 70) {
      if (!mem.chargeStartT) {
        mem.chargeStartT = t;
        mem.chargeStartBat = battery;
      }
      const waited = t - mem.chargeStartT;
      const gained = battery - mem.chargeStartBat;
      const critical = battery < 0.20;
      const maxWait = critical ? 90 : 40;
      if (waited < maxWait && (gained > 0.008 || waited < 6 || critical)) {
        return holdStill(false);
      }
    }

    mem.returning = false;
    mem.chargeStartT = null;
  }

  // At base empty: charge briefly if useful.
  if (carried === 0 && atBase) {
    const goal = timeLeft > 800 ? 0.96 :
                 timeLeft > 500 ? 0.88 :
                 timeLeft > 260 ? 0.76 : 0.56;
    if (battery < goal - 0.005 && timeLeft > 70) {
      if (!mem.chargeStartT) {
        mem.chargeStartT = t;
        mem.chargeStartBat = battery;
      }
      const waited = t - mem.chargeStartT;
      const gained = battery - mem.chargeStartBat;
      const critical = battery < 0.20;
      const maxWait = critical ? 90 : 40;
      if (waited < maxWait && (gained > 0.008 || waited < 6 || critical)) {
        return holdStill(false);
      }
    }
    mem.chargeStartT = null;
    if (timeLeft < 35) return holdStill(false);
  } else {
    mem.chargeStartT = null;
  }

  // Opportunistic site sampling unless returning/urgent.
  if (!mem.returning && carried < capacity && obs.site) {
    const dSite = +obs.site.distance;
    if (isFinite(dSite) && dSite < 8.05) {
      let skip = false;
      if (mem.ignore && t < mem.ignore.until) {
        const sp = estimateSitePos(dSite, +obs.site.bearing);
        if (dist(sp.x, sp.y, mem.ignore.x, mem.ignore.y) < 3.8) skip = true;
      }
      if (!skip) {
        const cmd = handleSite();
        if (cmd) return cmd;
      }
    }
  }

  // If carrying and idle, decide whether another sample is worth the detour.
  if (carried > 0 && !mem.returning && !mem.search && !mem.targetHint) {
    if (db < 35) {
      mem.returning = true;
      return goBase();
    }

    const h = chooseHint(carried);
    if (!h) {
      mem.returning = true;
      return goBase();
    }

    const dH = dist(mem.pos.x, mem.pos.y, h.x, h.y);
    const dbh = dist(mem.base.x, mem.base.y, h.x, h.y);
    const extra = Math.max(0, dH + dbh - db);
    const avgVal = carriedValue / Math.max(1, carried);

    let worth = false;
    if (extra < 48 && dH < 72) worth = true;
    if (h.val > Math.max(3.0, avgVal * 1.45) && extra < 125 && dH < 150) worth = true;
    if (carried < 2 && extra < 85 && dH < 105) worth = true;

    const needT2 = (dH + dbh) / 0.52 + 45;
    const needE2 = (dH + dbh) * drainUse * carryFactor * 1.75 + 0.085;
    if (timeLeft < needT2 || battery < needE2) worth = false;

    if (!worth) {
      mem.returning = true;
      return goBase();
    }

    mem.targetHint = h;
    mem.targetStartT = t;
  }

  // Continue active search.
  if (mem.search) {
    const cmd = runSearch();
    if (cmd) return cmd;
  }

  // Navigate to selected hint.
  if (mem.targetHint && mem.targetHint.done) mem.targetHint = null;

  if (mem.targetHint) {
    const h = mem.targetHint;
    const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);

    if (d < 11.0 || (science > 0.45 && d < 20.0)) {
      startSearch(h.x, h.y, h);
      const cmd = runSearch();
      if (cmd) return cmd;
    } else {
      if (t - (mem.targetStartT || t) > 255.0) {
        h.attempts = (h.attempts || 0) + 1;
        if (h.attempts >= 2) h.done = true;
        mem.targetHint = null;
      } else {
        const abs = Math.atan2(h.y - mem.pos.y, h.x - mem.pos.x) * DEG;
        const rel = wrapDeg(abs - trueHeading);
        let sp;
        if (d > 45) sp = 1.18;
        else if (d > 15) sp = 0.96;
        else sp = 0.66;
        return driveRel(rel, sp);
      }
    }
  }

  // Choose a new hint if none.
  if (!mem.returning && carried < capacity) {
    const h = chooseHint(carried);
    if (h) {
      mem.targetHint = h;
      mem.targetStartT = t;
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      if (d < 11.0) {
        startSearch(h.x, h.y, h);
        const cmd = runSearch();
        if (cmd) return cmd;
      } else {
        const abs = Math.atan2(h.y - mem.pos.y, h.x - mem.pos.x) * DEG;
        const rel = wrapDeg(abs - trueHeading);
        let sp;
        if (d > 45) sp = 1.18;
        else if (d > 15) sp = 0.96;
        else sp = 0.66;
        return driveRel(rel, sp);
      }
    }
  }

  // Opportunistic science-driven local search if nothing else is active.
  if (!mem.returning && carried < capacity && !mem.search && !mem.targetHint && !obs.site) {
    if (science > 1.15 && t - (mem.lastOpp || -1e9) > 42.0) {
      mem.lastOpp = t;
      startSearch(mem.pos.x, mem.pos.y, null);
      const cmd = runSearch();
      if (cmd) return cmd;
    }
  }

  if (carried > 0) {
    mem.returning = true;
    return goBase();
  }

  const ex = doExplore();
  if (ex) return ex;

  return holdStill(false);
}

function act(obs, mem) {
  "use strict";

  const PI = Math.PI;
  const RAD = PI / 180;
  const DEG = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrapDeg(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }
  function hyp(a, b) { return Math.sqrt(a * a + b * b); }
  function dist(x1, y1, x2, y2) { return hyp(x2 - x1, y2 - y1); }
  function finite(v, d) { v = +v; return isFinite(v) ? v : d; }

  if (!mem || typeof mem !== "object") mem = {};

  if (!mem.init) {
    mem.init = true;
    const mis = obs.mission || {};
    mem.size = finite(mis.size, 400);
    mem.missionSeconds = finite(mis.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(finite(mis.capacity, 5)));
    mem.base = {
      x: mis.base && isFinite(+mis.base.x) ? +mis.base.x : finite(obs.x, mem.size / 2),
      y: mis.base && isFinite(+mis.base.y) ? +mis.base.y : finite(obs.y, mem.size / 2)
    };

    mem.hints = [];
    const hs = Array.isArray(mis.hints) ? mis.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = +h.x;
      const hy = +h.y;
      let hv = +h.estimate;
      if (!isFinite(hx) || !isFinite(hy)) continue;
      if (!isFinite(hv) || hv <= 0) hv = 1;
      mem.hints.push({
        x: hx,
        y: hy,
        val: hv,
        done: false,
        attempts: 0
      });
    }

    mem.pos = { x: finite(obs.x, mem.base.x), y: finite(obs.y, mem.base.y) };
    mem.head = wrapDeg(finite(obs.heading, 0));
    mem.bias = 0;
    mem.headJump = 0;
    mem.cal = null;

    mem.lastRawX = mem.pos.x;
    mem.lastRawY = mem.pos.y;
    mem.lastRawT = finite(obs.t, 0);
    mem.lastGpsAccept = finite(obs.t, 0);
    mem.gpsFrozen = false;

    mem.prevBat = finite(obs.battery, 1);
    mem.drain = 0.0030;
    mem.drainN = 0;

    mem.lastCarried = Math.max(0, Math.floor(finite(obs.carried, 0)));
    mem.lastDelivered = finite(obs.delivered, 0);
    mem.lastDeliverT = -1e9;
    mem.lastSampleT = -1e9;

    mem.targetHint = null;
    mem.search = null;
    mem.sample = null;
    mem.returning = false;
    mem.ignore = null;

    mem.avoid = null;
    mem.prevBump = 0;
    mem.stuckT = finite(obs.t, 0);
    mem.stuckPos = { x: mem.pos.x, y: mem.pos.y };
    mem.stuckCount = 0;
    mem.movingIntent = false;

    mem.chargeStart = null;
    mem.chargeStartBat = 0;

    mem.lastSite = null;

    mem.v = 0;
    mem.omega = 0;

    mem.wheels = {
      L: { cmd: 0, g: 1.45, dz: 0.075, I: 0, f: 0, stall: 0, holding: false },
      R: { cmd: 0, g: 1.45, dz: 0.075, I: 0, f: 0, stall: 0, holding: false }
    };

    mem.explore = [];
    const esp = 55;
    for (let gx = 24; gx <= mem.size - 24; gx += esp) {
      for (let gy = 24; gy <= mem.size - 24; gy += esp) {
        if (dist(gx, gy, mem.base.x, mem.base.y) > 28) {
          mem.explore.push({ x: gx, y: gy, used: false });
        }
      }
    }

    mem.lastT = finite(obs.t, 0);
  }

  let t = finite(obs.t, mem.lastT + 0.1);
  let dt = 0.1;
  if (isFinite(mem.lastT)) {
    const dd = t - mem.lastT;
    if (dd > 0.001 && dd < 1.0) dt = dd;
    else if (dd >= 1.0 && dd < 5.0) dt = 0.5;
  }
  dt = clamp(dt, 0.02, 0.5);
  mem.lastT = t;

  const wl = finite(obs.wheelLeft, 0);
  const wr = finite(obs.wheelRight, 0);
  const wheelMax = Math.max(Math.abs(wl), Math.abs(wr));
  const speedAvg = (wl + wr) * 0.5;

  const battery = finite(obs.battery, mem.prevBat || 1);
  const solar = finite(obs.solar, 0);
  const carried = Math.max(0, Math.floor(finite(obs.carried, 0)));
  const capacity = mem.capacity || 5;
  const timeLeft = Math.max(0, finite(obs.timeLeft, mem.missionSeconds - t));
  const pitch = finite(obs.pitch, 0);
  const drilling = finite(obs.drilling, 0);
  const delivered = finite(obs.delivered, 0);
  let science = finite(obs.science, 0);
  if (science < 0) science = 0;

  const rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  const R = new Array(9);
  for (let i = 0; i < 9; i++) {
    let r = +rawRays[i];
    if (!isFinite(r) || r < 0) r = 15;
    if (r > 15) r = 15;
    R[i] = r;
  }
  mem.R = R;

  const prevCarried = mem.lastCarried || 0;
  const oldX = mem.pos.x;
  const oldY = mem.pos.y;

  const rawH = wrapDeg(finite(obs.heading, mem.head));
  const predYawDeg = ((wr - wl) / 0.6) * dt * DEG;
  const dh = wrapDeg(rawH - mem.head);
  if (Math.abs(dh) < 24 || Math.abs(dh - predYawDeg) < 38) {
    mem.head = wrapDeg(mem.head + dh * 0.55);
    mem.headJump = 0;
  } else {
    mem.headJump = (mem.headJump || 0) + 1;
    if (mem.headJump > 7) {
      mem.head = rawH;
      mem.headJump = 0;
    } else {
      mem.head = wrapDeg(mem.head + clamp(predYawDeg, -14, 14));
    }
  }

  let trueHeading = wrapDeg(mem.head - (mem.bias || 0));

  const predX = mem.pos.x + speedAvg * Math.cos(trueHeading * RAD) * dt;
  const predY = mem.pos.y + speedAvg * Math.sin(trueHeading * RAD) * dt;

  const rawX = +obs.x;
  const rawY = +obs.y;
  if (isFinite(rawX) && isFinite(rawY)) {
    const rawMoved = dist(rawX, rawY, mem.lastRawX, mem.lastRawY);
    if (rawMoved > 0.012) {
      mem.lastRawX = rawX;
      mem.lastRawY = rawY;
      mem.lastRawT = t;
      mem.gpsFrozen = false;
    } else if (t - mem.lastRawT > 2.8 && Math.abs(speedAvg) > 0.10) {
      mem.gpsFrozen = true;
    }

    if (!mem.gpsFrozen) {
      const innov = dist(predX, predY, rawX, rawY);
      if (innov < 9 || t - mem.lastGpsAccept > 2.8) {
        const w = innov < 2.5 ? 0.65 : 0.35;
        mem.pos.x = predX * (1 - w) + rawX * w;
        mem.pos.y = predY * (1 - w) + rawY * w;
        mem.lastGpsAccept = t;
      } else {
        mem.pos.x = predX;
        mem.pos.y = predY;
      }
    } else {
      mem.pos.x = predX;
      mem.pos.y = predY;
    }
  } else {
    mem.pos.x = predX;
    mem.pos.y = predY;
  }
  mem.pos.x = clamp(mem.pos.x, -12, mem.size + 12);
  mem.pos.y = clamp(mem.pos.y, -12, mem.size + 12);

  let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  let beaconValid = false;
  let beaconBearing = 0;
  let beaconDist = db;
  if (obs.beacon && isFinite(+obs.beacon.distance) && isFinite(+obs.beacon.bearing)) {
    const bd = +obs.beacon.distance;
    const br = +obs.beacon.bearing;
    if (bd >= 0 && bd < 25) {
      beaconValid = true;
      beaconDist = bd;
      beaconBearing = br;
      if (Math.abs(bd - db) < 15 || bd < 12) db = bd;

      if (bd > 1.0 && bd < 23 && Math.abs(bd - db) < 15) {
        const absB = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
        const trueObs = wrapDeg(absB - br);
        const biasInst = wrapDeg(mem.head - trueObs);
        const delta = wrapDeg(biasInst - (mem.bias || 0));
        if (Math.abs(delta) < 60) {
          mem.bias = wrapDeg((mem.bias || 0) + delta * 0.055);
        }
      }
    }
  }

  trueHeading = wrapDeg(mem.head - (mem.bias || 0));

  if (Math.abs(wl - wr) < 0.26 && speedAvg > 0.18 && !mem.gpsFrozen) {
    if (!mem.cal) {
      mem.cal = { x: mem.pos.x, y: mem.pos.y, t: t, h: mem.head };
    } else if (t - mem.cal.t > 1.5) {
      const movedCal = dist(mem.pos.x, mem.pos.y, mem.cal.x, mem.cal.y);
      if (movedCal > 0.8) {
        const course = Math.atan2(mem.pos.y - mem.cal.y, mem.pos.x - mem.cal.x) * DEG;
        const avgH = wrapDeg(mem.cal.h + wrapDeg(mem.head - mem.cal.h) * 0.5);
        const biasInst = wrapDeg(avgH - course);
        const delta = wrapDeg(biasInst - (mem.bias || 0));
        if (Math.abs(delta) < 45) {
          mem.bias = wrapDeg((mem.bias || 0) + delta * 0.020);
        }
        mem.cal = { x: mem.pos.x, y: mem.pos.y, t: t, h: mem.head };
      } else if (t - mem.cal.t > 3.0) {
        mem.cal = { x: mem.pos.x, y: mem.pos.y, t: t, h: mem.head };
      }
    }
  } else {
    if (!mem.cal || t - mem.cal.t > 3.0) mem.cal = null;
  }

  trueHeading = wrapDeg(mem.head - (mem.bias || 0));

  if (obs.site && isFinite(+obs.site.distance) && isFinite(+obs.site.bearing)) {
    const sd = +obs.site.distance;
    const sb = +obs.site.bearing;
    const absS = (trueHeading + sb) * RAD;
    mem.lastSite = {
      x: mem.pos.x + sd * Math.cos(absS),
      y: mem.pos.y + sd * Math.sin(absS),
      t: t,
      value: finite(obs.site.value, 0)
    };
  }

  const usedEnergy = (mem.prevBat + solar * dt) - battery;
  const pathStep = Math.max(Math.abs(wl), Math.abs(wr)) * dt;
  if (usedEnergy > 0.000001 && usedEnergy < 0.12 && pathStep > 0.015 && !obs.docked) {
    const ratio = usedEnergy / pathStep / (1 + 0.15 * carried);
    if (ratio > 0.00010 && ratio < 0.012) {
      mem.drain = clamp(mem.drain * 0.997 + ratio * 0.003, 0.0008, 0.0080);
      mem.drainN = (mem.drainN || 0) + 1;
    }
  }
  mem.prevBat = battery;

  const prevDelivered = mem.lastDelivered || 0;
  if (carried > prevCarried) {
    let sx = mem.pos.x;
    let sy = mem.pos.y;
    if (mem.sample && mem.sample.site) {
      sx = mem.sample.site.x;
      sy = mem.sample.site.y;
    } else if (mem.lastSite && t - mem.lastSite.t < 4) {
      sx = mem.lastSite.x;
      sy = mem.lastSite.y;
    }

    let bestH = null;
    let bestD = 1e9;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.done) continue;
      const hd = dist(h.x, h.y, sx, sy);
      if (hd < 40 && hd < bestD) {
        bestD = hd;
        bestH = h;
      }
    }
    if (bestH) {
      bestH.done = true;
      bestH.attempts = (bestH.attempts || 0) + 1;
    }
    if (mem.targetHint) mem.targetHint.done = true;
    if (mem.search && mem.search.hint) {
      mem.search.hint.done = true;
      mem.search.hint.attempts = (mem.search.hint.attempts || 0) + 1;
    }

    mem.sample = null;
    mem.search = null;
    mem.targetHint = null;
    mem.ignore = null;
    mem.lastSampleT = t;
  }

  if (delivered > prevDelivered + 1e-9) {
    mem.lastDeliverT = t;
    mem.returning = false;
    mem.sample = null;
    mem.search = null;
    mem.targetHint = null;
    mem.ignore = null;
    mem.chargeStart = null;
  } else if (carried < prevCarried) {
    if ((obs.docked || db < 3.2) && delivered >= prevDelivered - 1e-9) {
      mem.returning = false;
      mem.sample = null;
      mem.search = null;
      mem.targetHint = null;
      mem.chargeStart = null;
    }
  }

  mem.lastCarried = carried;
  mem.lastDelivered = Math.max(prevDelivered, delivered);

  const bumpVal = (typeof obs.bumped === "number") ? +obs.bumped : (obs.bumped ? 1 : 0);

  function rateCmd(prev, desired, maxRate) {
    let m = maxRate * dt;
    if (m < 0.01) m = 0.01;
    if (m > 0.7) m = 0.7;
    return clamp(prev + clamp(desired - prev, -m, m), -1, 1);
  }

  function wheelCtrl(side, target, actual, holding) {
    const s = mem.wheels[side];
    const a = finite(actual, 0);
    s.f = s.f * 0.65 + a * 0.35;
    const af = s.f;
    let tgt = clamp(finite(target, 0), -0.95, 0.95);

    if (holding || Math.abs(tgt) < 0.022) {
      if (!s.holding) {
        s.I = 0;
        s.holding = true;
      }
      const err = -af;
      s.I = clamp((s.I || 0) + err * dt * 0.95, -0.68, 0.68);
      let c = s.I - af * 1.35;
      if (Math.abs(af) < 0.022 && Math.abs(s.I) < 0.035) c = 0;
      s.cmd = rateCmd(s.cmd || 0, clamp(c, -1, 1), 8.0);
      return clamp(s.cmd, -1, 1);
    }

    if (s.holding) {
      s.I = 0;
      s.holding = false;
    }

    const sign = tgt >= 0 ? 1 : -1;
    const mag = Math.abs(tgt);
    const g = clamp(s.g || 1.45, 0.35, 6.0);
    const dz = s.dz || 0.075;
    let ff = sign * (mag / g + dz);

    const err = tgt - af;
    s.I = clamp((s.I || 0) + err * dt * 0.20, -0.26, 0.26);
    let c = ff + err * 0.55 + s.I;

    if (c > 1 && err > 0) s.I = Math.min(s.I, 0.20);
    if (c < -1 && err < 0) s.I = Math.max(s.I, -0.20);

    c = clamp(c, -1, 1);
    s.cmd = rateCmd(s.cmd || 0, c, 5.0);

    if (Math.abs(s.cmd) > 0.15 && Math.abs(af) > 0.045 && s.cmd * af > 0) {
      let eff = Math.abs(s.cmd) - dz;
      if (eff < 0.05) eff = 0.05;
      const gg = Math.abs(af) / eff;
      if (gg > 0.20 && gg < 6.0) {
        s.g = clamp((s.g || 1.45) * 0.995 + gg * 0.005, 0.35, 6.0);
      }
    }

    if (mag > 0.15 && Math.abs(af) < 0.024) {
      s.stall = (s.stall || 0) + dt;
      if (s.stall > 0.8) {
        s.dz = Math.min(0.25, (s.dz || 0.075) + 0.006);
        s.stall = 0;
      }
    } else {
      s.stall = 0;
      if (Math.abs(af) > 0.08) {
        s.dz = Math.max(0.020, (s.dz || 0.075) * 0.9995);
      }
    }

    return clamp(s.cmd, -1, 1);
  }

  function setWheels(vL, vR, drillOn) {
    vL = clamp(finite(vL, 0), -0.95, 0.95);
    vR = clamp(finite(vR, 0), -0.95, 0.95);
    const holdL = Math.abs(vL) < 0.022;
    const holdR = Math.abs(vR) < 0.022;
    mem.movingIntent = Math.max(Math.abs(vL), Math.abs(vR)) > 0.08;
    const cL = wheelCtrl("L", vL, wl, holdL);
    const cR = wheelCtrl("R", vR, wr, holdR);
    return { left: cL, right: cR, drill: !!drillOn };
  }

  function holdStill(drillOn) {
    mem.v = 0;
    mem.omega = 0;
    return setWheels(0, 0, !!drillOn);
  }

  function triggerAvoid(dir, duration, reverseTime) {
    if (!mem.avoid || t >= mem.avoid.until) {
      mem.avoid = {
        until: t + (duration || 1.25),
        reverseUntil: t + (reverseTime || 0.55),
        dir: dir || 1
      };
      mem.v = 0;
      mem.omega = 0;
      mem.sample = null;
    }
  }

  function executeAvoid() {
    if (!mem.avoid) return holdStill(false);
    if (t < mem.avoid.reverseUntil) {
      return setWheels(-0.30, -0.30, false);
    }
    if (t < mem.avoid.until) {
      const d = mem.avoid.dir || 1;
      return setWheels(-0.32 * d, 0.32 * d, false);
    }
    mem.avoid = null;
    return holdStill(false);
  }

  function commandRel(rel, speed) {
    let e = wrapDeg(finite(rel, 0));
    let sp = clamp(finite(speed, 0), 0, 0.80);

    const front = Math.min(R[3], R[4], R[5]);
    const sideL = R[5] + R[6] + R[7] + R[8];
    const sideR = R[0] + R[1] + R[2] + R[3];
    const dir = sideL >= sideR ? 1 : -1;

    if (front < 0.62 && wheelMax > 0.15) {
      triggerAvoid(dir, 1.25, 0.55);
      return executeAvoid();
    }

    if (front < 3.0) {
      const cap = Math.max(0, (front - 0.55) * 0.55);
      sp = Math.min(sp, cap);
      if (front < 2.0) {
        const w = clamp((2.0 - front) / 2.0, 0, 1) * 0.75;
        e = wrapDeg(e * (1 - w) + dir * 70 * w);
      }
    }
    if (front < 1.0) sp = Math.min(sp, 0.08);

    const minL = Math.min(R[6], R[7], R[8]);
    const minR = Math.min(R[0], R[1], R[2]);
    if (minL < 0.8 && e > -12) e = wrapDeg(e - 20 * (1 - minL / 0.8));
    if (minR < 0.8 && e < 12) e = wrapDeg(e + 20 * (1 - minR / 0.8));

    const edge = Math.min(mem.pos.x, mem.pos.y, mem.size - mem.pos.x, mem.size - mem.pos.y);
    if (edge < 12) {
      const toC = Math.atan2(mem.size * 0.5 - mem.pos.y, mem.size * 0.5 - mem.pos.x) * DEG;
      const relC = wrapDeg(toC - trueHeading);
      const w = clamp((12 - edge) / 12, 0, 1) * 0.88;
      e = wrapDeg(e * (1 - w) + relC * w);
      sp = Math.min(sp, edge < 4 ? 0.15 : 0.55);
    }

    if (pitch > 26) sp = Math.min(sp, 0.55);
    if (pitch > 36) sp = Math.min(sp, 0.30);

    const ae = Math.abs(e);
    let vDes;
    let omDes;

    if (ae > 105) {
      vDes = 0;
      omDes = e > 0 ? 0.68 : -0.68;
    } else if (ae > 55) {
      vDes = sp * 0.12;
      omDes = e > 0 ? 0.66 : -0.66;
    } else if (ae > 25) {
      vDes = sp * 0.45;
      omDes = clamp(e * RAD * 1.60, -0.76, 0.76);
    } else {
      vDes = sp * Math.max(0.35, Math.cos(e * RAD));
      omDes = clamp(e * RAD * 1.90, -0.76, 0.76);
    }

    const actMax = Math.max(Math.abs(wl), Math.abs(wr));
    if (actMax > 0.95 && vDes > 0) {
      vDes = Math.min(vDes, 0.15);
      if (actMax > 1.15) omDes *= 0.5;
    }

    const maxAcc = 1.45;
    const maxAng = 2.4;
    mem.v = (mem.v || 0) + clamp(vDes - (mem.v || 0), -maxAcc * dt, maxAcc * dt);
    mem.omega = (mem.omega || 0) + clamp(omDes - (mem.omega || 0), -maxAng * dt, maxAng * dt);

    let vL = mem.v - mem.omega * 0.30;
    let vR = mem.v + mem.omega * 0.30;

    const mm = Math.max(Math.abs(vL), Math.abs(vR));
    if (mm > 0.84) {
      vL *= 0.84 / mm;
      vR *= 0.84 / mm;
    }

    return setWheels(vL, vR, false);
  }

  function driveToPoint(tx, ty, speed) {
    const dx = tx - mem.pos.x;
    const dy = ty - mem.pos.y;
    const d = hyp(dx, dy);
    if (d < 0.38) return holdStill(false);
    const absB = Math.atan2(dy, dx) * DEG;
    const rel = wrapDeg(absB - trueHeading);
    let sp = clamp(finite(speed, 0.5), 0, 0.80);
    if (d < 2.5) sp = Math.min(sp, Math.max(0.08, (d - 0.32) * 0.46));
    return commandRel(rel, sp);
  }

  function goBase() {
    if (beaconValid && beaconDist < 24) {
      if (beaconDist < 2.55) return holdStill(false);
      let sp;
      if (beaconDist > 14) sp = 0.70;
      else if (beaconDist > 6) sp = 0.46;
      else sp = 0.24;
      return commandRel(beaconBearing, sp);
    }

    if (db < 2.55) return holdStill(false);
    const absB = Math.atan2(mem.base.y - mem.pos.y, mem.base.x - mem.pos.x) * DEG;
    const rel = wrapDeg(absB - trueHeading);
    let sp;
    if (db > 14) sp = 0.70;
    else if (db > 6) sp = 0.46;
    else sp = 0.24;
    return commandRel(rel, sp);
  }

  function makeSpiral(cx, cy, maxR, spacing) {
    const pts = [];
    const b = spacing / (2 * PI);
    let theta = 0.40;
    for (let i = 0; i < 520; i++) {
      const r = b * theta;
      if (r > maxR) break;
      pts.push({
        x: clamp(cx + r * Math.cos(theta), 4, mem.size - 4),
        y: clamp(cy + r * Math.sin(theta), 4, mem.size - 4)
      });
      const dTheta = 3.0 / Math.max(r, 2.0);
      theta += clamp(dTheta, 0.12, 0.90);
    }
    return pts;
  }

  function startSearch(cx, cy, hint) {
    cx = clamp(finite(cx, mem.pos.x), 4, mem.size - 4);
    cy = clamp(finite(cy, mem.pos.y), 4, mem.size - 4);

    let val = hint ? Math.max(0.5, +hint.val || 1) : 1;
    let maxR = hint ? clamp(20 + Math.min(4, val * 0.8), 20, 24) : 18;
    const spacing = 13.0;
    const pts = makeSpiral(cx, cy, maxR, spacing);

    mem.search = {
      cx: cx,
      cy: cy,
      hint: hint || null,
      pts: pts,
      idx: 0,
      startT: t,
      lastWayT: t,
      maxTime: hint ? (val > 3 ? 150 : 120) : 80,
      maxR: maxR,
      maxSci: science
    };
  }

  function finishSearch(markDone) {
    if (mem.search && mem.search.hint) {
      const h = mem.search.hint;
      h.attempts = (h.attempts || 0) + 1;
      if (markDone) h.done = true;
    }
    mem.search = null;
  }

  function runSearch() {
    const s = mem.search;
    if (!s) return null;

    if (science > s.maxSci) s.maxSci = science;

    if (s.hint && s.hint.done) {
      mem.search = null;
      return null;
    }

    if (t - s.startT > s.maxTime) {
      finishSearch(true);
      return null;
    }

