      for (let i = 0; i < n; i++) {
        const u = pts[i].x - sx;
        const v = pts[i].y - sy;
        const w = pts[i].s - ss;
        A += u * u;
        B += u * v;
        C += v * v;
        Dv += u * w;
        E += v * w;
      }
      const det = A * C - B * B;
      if (det > 0.05) {
        const gx = (Dv * C - E * B) / det;
        const gy = (E * A - Dv * B) / det;
        const gm = hyp(gx, gy);
        if (isFinite(gx) && isFinite(gy) && gm > 1e-8 && gm < 1e5) {
          mem.sciGrad = { x: gx, y: gy, mag: gm, t: t };
        }
      } else if (pts.length >= 4) {
        const p0 = pts[pts.length - 1];
        const p1 = pts[0];
        const dx = p1.x - p0.x;
        const dy = p1.y - p0.y;
        const md = hyp(dx, dy);
        const ds = p1.s - p0.s;
        if (md > 1.0 && Math.abs(ds) > 0.02) {
          const dir = ds >= 0 ? 1 : -1;
          mem.sciGrad = { x: dir * dx / md, y: dir * dy / md, mag: Math.abs(ds) / md, t: t };
        }
      }
    }
  }

  const usedEnergy = (mem.prevBat + solar * dt) - battery;
  const stepW = Math.abs(speedAvg) * dt;
  if (usedEnergy > 0.000001 && usedEnergy < 0.12 && stepW > 0.008 && !obs.docked) {
    const ratio = usedEnergy / stepW / (1 + 0.15 * carried);
    if (ratio > 0.00015 && ratio < 0.02) {
      mem.drain = clamp(mem.drain * 0.996 + ratio * 0.004, 0.00035, 0.010);
      mem.drainN = (mem.drainN || 0) + 1;
    }
  }
  mem.prevBat = battery;

  const prevCarried = mem.lastCarried || 0;

  if (carried > prevCarried) {
    let sx = mem.pos.x;
    let sy = mem.pos.y;
    if (mem.sample && mem.sample.site) {
      sx = mem.sample.site.x;
      sy = mem.sample.site.y;
    } else if (mem.lastSite) {
      sx = mem.lastSite.x;
      sy = mem.lastSite.y;
    }

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h.done && dist(h.x, h.y, sx, sy) < 24) {
        h.done = true;
        h.attempts = (h.attempts || 0) + 1;
      }
    }
    if (mem.targetHint && dist(mem.targetHint.x, mem.targetHint.y, sx, sy) < 26) {
      mem.targetHint.done = true;
    }
    if (mem.search && mem.search.hint) {
      mem.search.hint.done = true;
      mem.search.hint.attempts = (mem.search.hint.attempts || 0) + 1;
    }

    mem.sample = null;
    mem.search = null;
    mem.targetHint = null;
    mem.ignore = null;
    mem.mustReturn = true;
    mem.lastSampleT = t;
    mem.chargeStart = null;
  }

  if (delivered > mem.lastDelivered + 1e-9) {
    mem.lastDeliverT = t;
    mem.mustReturn = false;
    mem.sample = null;
    mem.search = null;
    mem.targetHint = null;
    mem.ignore = null;
    mem.chargeStart = null;
  } else if (carried < prevCarried && db < 3.5) {
    mem.mustReturn = false;
    mem.sample = null;
    mem.search = null;
    mem.targetHint = null;
    mem.chargeStart = null;
  }

  mem.lastCarried = carried;
  mem.lastDelivered = Math.max(mem.lastDelivered || 0, delivered);

  const bumpVal = (typeof obs.bumped === "number") ? +obs.bumped : (obs.bumped ? 1 : 0);
  if (bumpVal > 0 && !((mem.prevBump || 0) > 0)) {
    const dir = leftClear >= rightClear ? 1 : -1;
    if (!mem.avoid || t >= mem.avoid.until) {
      mem.avoid = { until: t + 1.25, revUntil: t + 0.55, dir: dir };
    }
    if (mem.sample) {
      mem.sample.stable = 0;
    }
  }
  mem.prevBump = bumpVal;

  if (t - mem.stuckT > 3.0) {
    const moved = dist(mem.pos.x, mem.pos.y, mem.stuckPos.x, mem.stuckPos.y);
    if (mem.movingIntent && !mem.sample && moved < 0.16) {
      mem.stuckCount = (mem.stuckCount || 0) + 1;
    } else {
      mem.stuckCount = 0;
    }

    if (mem.stuckCount >= 2) {
      const dir = leftClear >= rightClear ? 1 : -1;
      if (!mem.avoid || t >= mem.avoid.until) {
        mem.avoid = { until: t + 1.5, revUntil: t + 0.6, dir: dir };
      }
      if (mem.search) {
        if (mem.search.hint) {
          mem.search.hint.attempts = (mem.search.hint.attempts || 0) + 1;
          mem.search.hint.done = true;
        }
        mem.search = null;
      }
      if (mem.targetHint) {
        mem.targetHint.done = true;
        mem.targetHint = null;
      }
      mem.stuckCount = 0;
    }

    mem.stuckT = t;
    mem.stuckPos = { x: mem.pos.x, y: mem.pos.y };
  }

  function rateCmd(prev, desired, rate) {
    let maxStep = rate * dt;
    if (maxStep < 0.02) maxStep = 0.02;
    if (maxStep > 0.8) maxStep = 0.8;
    return clamp(prev + clamp(desired - prev, -maxStep, maxStep), -1, 1);
  }

  function wheelControl(side, target, actual, hold) {
    const s = mem.wheels[side];
    actual = fin(actual, 0);
    s.f = (s.f || 0) * 0.66 + actual * 0.34;
    const a = s.f;
    target = clamp(fin(target, 0), -2.6, 2.6);

    if (hold || Math.abs(target) < 0.026) {
      if (!s.lastHold) {
        s.I = 0;
        s.lastHold = true;
      }
      const err = -a;
      s.I = clamp((s.I || 0) + err * dt * 0.90, -0.70, 0.70);
      const slope = clamp(pitch * 0.006, -0.35, 0.35);
      let c = -a * 1.10 + s.I + slope;
      if (Math.abs(a) < 0.016 && Math.abs(s.I) < 0.025 && Math.abs(slope) < 0.04) c = 0;
      c = clamp(c, -1, 1);
      s.cmd = rateCmd(s.cmd || 0, c, 9.0);
      return clamp(s.cmd, -1, 1);
    }

    if (s.lastHold) {
      s.I = 0;
      s.lastHold = false;
    }

    const sg = target >= 0 ? 1 : -1;
    const mag = Math.abs(target);
    const g = clamp(s.g || 2.5, 0.45, 8.0);
    const dz = clamp(s.dz || 0.065, 0.02, 0.25);

    let ff = sg * (mag / g + dz);
    const err = target - a;
    s.I = clamp((s.I || 0) + err * dt * 0.075, -0.25, 0.25);

    let c = ff + err * 0.32 + s.I;
    c += clamp(pitch * 0.0025, -0.12, 0.12);

    if (c > 1 && err > 0) s.I = Math.min(s.I, 0.16);
    if (c < -1 && err < 0) s.I = Math.max(s.I, -0.16);

    c = clamp(c, -1, 1);
    s.cmd = rateCmd(s.cmd || 0, c, 6.0);

    if (Math.abs(s.cmd) > 0.12 && Math.abs(a) > 0.045 && s.cmd * a > 0) {
      let eff = Math.abs(s.cmd) - dz;
      if (eff > 0.04) {
        const ge = Math.abs(a) / eff;
        if (ge > 0.25 && ge < 8.0) {
          s.g = clamp((s.g || 2.5) * 0.995 + ge * 0.005, 0.45, 8.0);
        }
      }
    }

    if (mag > 0.15 && Math.abs(a) < 0.025) {
      s.stall = (s.stall || 0) + dt;
      if (s.stall > 0.8) {
        s.dz = clamp((s.dz || 0.065) + 0.0045, 0.02, 0.25);
        s.stall = 0;
      }
    } else {
      s.stall = 0;
      if (Math.abs(a) > 0.08) {
        s.dz = clamp((s.dz || 0.065) * 0.9996, 0.02, 0.25);
      }
    }

    return clamp(s.cmd, -1, 1);
  }

  function setWheels(vL, vR, drillOn) {
    vL = clamp(fin(vL, 0), -2.6, 2.6);
    vR = clamp(fin(vR, 0), -2.6, 2.6);
    const holdL = Math.abs(vL) < 0.026;
    const holdR = Math.abs(vR) < 0.026;
    mem.movingIntent = Math.max(Math.abs(vL), Math.abs(vR)) > 0.08;
    const cL = wheelControl("L", vL, wl, holdL);
    const cR = wheelControl("R", vR, wr, holdR);
    return { left: clamp(cL, -1, 1), right: clamp(cR, -1, 1), drill: !!drillOn };
  }

  function holdStill(drillOn) {
    return setWheels(0, 0, !!drillOn);
  }

  function triggerAvoid(dir, duration, reverseTime) {
    if (!mem.avoid || t >= mem.avoid.until) {
      mem.avoid = {
        until: t + (duration || 1.25),
        revUntil: t + (reverseTime || 0.55),
        dir: dir || 1
      };
    }
  }

  function doAvoid() {
    if (!mem.avoid) return null;
    if (t < mem.avoid.revUntil) {
      return setWheels(-0.30, -0.30, false);
    }
    if (t < mem.avoid.until) {
      const d = mem.avoid.dir || 1;
      return setWheels(-0.30 * d, 0.30 * d, false);
    }
    mem.avoid = null;
    return null;
  }

  function driveRel(rel, speed) {
    let e = wrapDeg(fin(rel, 0));
    let sp = clamp(fin(speed, 0.45), 0, 0.82);

    const frontMin = Math.min(R[3], R[4], R[5]);

    if (frontMin < 0.72 && wheelMax > 0.10) {
      const dir = leftClear >= rightClear ? 1 : -1;
      triggerAvoid(dir, 1.25, 0.55);
      return doAvoid();
    }

    if (frontMin < 2.1) {
      const cap = Math.max(0, (frontMin - 0.45) * 0.50);
      sp = Math.min(sp, cap);

      if (frontMin < 1.25) {
        const dir = leftClear >= rightClear ? 1 : -1;
        e = wrapDeg(e * 0.42 + dir * 62 * 0.58);
        sp = Math.min(sp, 0.10);
      }
    }

    let sideMinL = Math.min(R[5], R[6], R[7], R[8]);
    let sideMinR = Math.min(R[0], R[1], R[2], R[3]);
    if (sideMinL < 0.58 && e > -8) {
      e = wrapDeg(e - 12 * (1 - sideMinL / 0.58));
    }
    if (sideMinR < 0.58 && e < 8) {
      e = wrapDeg(e + 12 * (1 - sideMinR / 0.58));
    }

    const edge = Math.min(mem.pos.x, mem.pos.y, size - mem.pos.x, size - mem.pos.y);
    if (edge < 15) {
      const toC = Math.atan2(size * 0.5 - mem.pos.y, size * 0.5 - mem.pos.x) * DEG;
      const relC = wrapDeg(toC - trueHeading);
      const w = clamp((15 - edge) / 15, 0, 1);
      e = wrapDeg(e * (1 - w) + relC * w);
      sp = Math.min(sp, 0.25 + 0.5 * (1 - w));
    }

    const ae = Math.abs(e);
    let vDes;
    let omDes;

    if (ae > 140) {
      vDes = 0;
      omDes = e > 0 ? 0.60 : -0.60;
    } else if (ae > 75) {
      vDes = sp * 0.10;
      omDes = e > 0 ? 0.64 : -0.64;
    } else {
      vDes = sp * Math.max(0.18, Math.cos(e * RAD));
      omDes = clamp(e * RAD * 1.55, -0.82, 0.82);
    }

    if (frontMin < 2.5) {
      vDes = Math.min(vDes, Math.max(0, (frontMin - 0.60) * 0.55));
    }

    let vL = vDes - omDes * 0.30;
    let vR = vDes + omDes * 0.30;

    let maxW = 1.05;
    if (frontMin < 1.55) maxW = 0.34;
    else if (frontMin < 2.55) maxW = 0.62;
    else if (sp < 0.32) maxW = 0.50;

    vL = clamp(vL, -maxW, maxW);
    vR = clamp(vR, -maxW, maxW);

    return setWheels(vL, vR, false);
  }

  function driveToPoint(tx, ty, speed) {
    const dx = tx - mem.pos.x;
    const dy = ty - mem.pos.y;
    const d = hyp(dx, dy);
    if (d < 0.42) return holdStill(false);

    const absB = Math.atan2(dy, dx) * DEG;
    const rel = wrapDeg(absB - trueHeading);
    let sp = clamp(fin(speed, 0.55), 0, 0.82);

    if (d < 2.5) {
      sp = Math.min(sp, Math.max(0.09, (d - 0.28) * 0.42));
    }

    return driveRel(rel, sp);
  }

  function goBase() {
    if (beaconValid && beaconDist < 24) {
      if (beaconDist < 2.1) return holdStill(false);
      let sp;
      if (beaconDist > 15) sp = 0.72;
      else if (beaconDist > 7) sp = 0.52;
      else if (beaconDist > 3.5) sp = 0.32;
      else sp = 0.16;
      if (carried > 0) sp *= 0.94;
      return driveRel(beaconBearing, sp);
    }

    const d = dist(mem.pos.x, mem.pos.y, base.x, base.y);
    if (d < 2.0) return holdStill(false);

    let sp;
    if (d > 15) sp = 0.72;
    else if (d > 7) sp = 0.52;
    else if (d > 3.5) sp = 0.32;
    else sp = 0.16;

    return driveToPoint(base.x, base.y, sp);
  }

  function makeSpiral(cx, cy, maxR, spacing) {
    const pts = [];
    const b = spacing / (2 * PI);
    let theta = 0.35;
    for (let i = 0; i < 900; i++) {
      const r = b * theta;
      if (r > maxR) break;
      pts.push({
        x: clamp(cx + r * Math.cos(theta), 3, size - 3),
        y: clamp(cy + r * Math.sin(theta), 3, size - 3)
      });
      const step = 1.7;
      const th = clamp(step / Math.max(r, 1.0), 0.075, 0.80);
      theta += th;
    }
    return pts;
  }

  function startSearch(cx, cy, hint) {
    cx = clamp(fin(cx, mem.pos.x), 4, size - 4);
    cy = clamp(fin(cy, mem.pos.y), 4, size - 4);

    if (mem.search && mem.search.hint === hint &&
        dist(cx, cy, mem.search.cx, mem.search.cy) < 3.0 &&
        t - mem.search.startT < 3.0) {
      return;
    }

    const val = hint ? Math.max(0.3, +hint.val || 1) : 1;
    const maxR = hint ? clamp(23 + Math.min(9, val * 1.4), 23, 32) : 21;
    const pts = makeSpiral(cx, cy, maxR, 8.0);

    mem.search = {
      cx: cx,
      cy: cy,
      hint: hint || null,
      pts: pts,
      idx: 0,
      startT: t,
      lastWayT: t,
      maxTime: hint ? (val > 3 ? 170 : 115) : 75,
      maxSci: science,
      sciSeen: science > 0.012,
      lastGradT: -1e9,
      gradUntil: 0,
      gradTarget: null
    };
    mem.targetHint = null;
  }

  function finishSearch(markDone) {
    if (mem.search && mem.search.hint) {
      const h = mem.search.hint;
      h.attempts = (h.attempts || 0) + 1;
      if (markDone) h.done = true;
    }
    mem.search = null;
  }

  function runSearch() {
    const s = mem.search;
    if (!s) return null;

    if (s.hint && s.hint.done) {
      mem.search = null;
      return null;
    }

    if (science > s.maxSci) s.maxSci = science;
    if (science > 0.012) s.sciSeen = true;

    if (t - s.startT > s.maxTime) {
      finishSearch(true);
      return null;
    }

    if (t - s.startT > 20 && s.maxSci < 0.010 && !obs.site) {
      finishSearch(true);
      return null;
    }

    if (science > 0.12 &&
        mem.sciGrad &&
        t - mem.sciGrad.t < 2.2 &&
        mem.sciGrad.mag > 1e-7 &&
        t - s.lastGradT > 7.5 &&
        t > s.gradUntil) {
      const gm = mem.sciGrad.mag;
      const step = 5.8;
      const tx = clamp(mem.pos.x + mem.sciGrad.x / gm * step, 3, size - 3);
      const ty = clamp(mem.pos.y + mem.sciGrad.y / gm * step, 3, size - 3);
      if (dist(mem.pos.x, mem.pos.y, tx, ty) > 1.2) {
        s.gradTarget = { x: tx, y: ty };
        s.gradUntil = t + 2.8;
        s.lastGradT = t;
      }
    }

    if (s.gradUntil > t && s.gradTarget) {
      const dg = dist(mem.pos.x, mem.pos.y, s.gradTarget.x, s.gradTarget.y);
      if (dg > 0.9) {
        return driveToPoint(s.gradTarget.x, s.gradTarget.y, 0.56);
      }
      s.gradUntil = 0;
    }

    while (s.idx < s.pts.length) {
      const p = s.pts[s.idx];
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < 1.15 || t - s.lastWayT > 12.0) {
        s.idx++;
        s.lastWayT = t;
      } else {
        break;
      }
    }

    if (s.idx >= s.pts.length) {
      finishSearch(true);
      return null;
    }

    const p = s.pts[s.idx];
    const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
    let sp;
    if (d > 7) sp = 0.66;
    else if (d > 2.5) sp = 0.46;
    else sp = 0.30;

    return driveToPoint(p.x, p.y, sp);
  }

  function chooseHint(carrying) {
    let best = null;
    let bestScore = -1e99;
    const dbCur = dist(mem.pos.x, mem.pos.y, base.x, base.y);
    const drainUse = clamp(mem.drain || 0.0015, 0.00035, 0.010);

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.done) continue;
      if (!isFinite(h.x) || !isFinite(h.y)) continue;

      const dCur = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dBase = dist(base.x, base.y, h.x, h.y);
      const val = Math.max(0.1, +h.val || 1);

      const extra = Math.max(0, dCur + dBase - dbCur);
      const legs = dCur + dBase + Math.max(0, extra) * 0.15;
      const searchCost = h.val > 3 ? 120 : 90;
      const needT = legs / 0.40 + searchCost + 20 + 8 * carrying;
      const needE = legs * drainUse * (1 + 0.15 * carrying) * 1.9 + 0.055 + 0.012 * carrying;

      if (timeLeft < needT + 15) continue;
      if (battery < needE + 0.025 && battery < 0.22) continue;

      let score = Math.pow(val, 0.90) / (legs + 42);
      if (dCur < 20) score *= 1.30;
      if (dCur < 45) score *= 1.10;
      if (h.attempts > 0) score *= 0.45;
      if (h.x < 6 || h.x > size - 6 || h.y < 6 || h.y > size - 6) score *= 0.82;
      if (dBase > 205) score *= 0.78;
      if (carrying > 0) score *= 0.88;

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }

    if (!best && timeLeft > 150) {
      let nearest = null;
      let nd = 1e99;
      for (let i = 0; i < mem.hints.length; i++) {
        const h = mem.hints[i];
        if (!h || h.done) continue;
        const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
        const dbh = dist(base.x, base.y, h.x, h.y);
        if (timeLeft < (d + dbh) / 0.40 + 110) continue;
        if (d < nd) {
          nd = d;
          nearest = h;
        }
      }
      best = nearest;
    }

    return best;
  }

  function siteIgnored(site) {
    if (!mem.ignore || t > mem.ignore.until) return false;
    const d = fin(+site.distance, 99);
    const br = fin(+site.bearing, 0);
    if (!isFinite(d) || !isFinite(br)) return true;
    const abs = (trueHeading + br) * RAD;
    const sx = mem.pos.x + d * Math.cos(abs);
    const sy = mem.pos.y + d * Math.sin(abs);
    return dist(sx, sy, mem.ignore.x, mem.ignore.y) < 4.0;
  }

  function handleSite(site) {
    const d = Math.max(0, fin(+site.distance, 99));
    const br = fin(+site.bearing, 0);
    const val = fin(+site.value, 0);
    if (!isFinite(d) || !isFinite(br)) return null;

    const abs = (trueHeading + br) * RAD;
    const sx = mem.pos.x + d * Math.cos(abs);
    const sy = mem.pos.y + d * Math.sin(abs);

    mem.lastSite = { x: sx, y: sy, t: t, value: val };

    if (mem.sample) {
      if (!mem.sample.site || dist(sx, sy, mem.sample.site.x, mem.sample.site.y) > 3.2) {
        mem.sample = null;
      }
    }

    if (d > 1.45) {
      if (mem.sample && d > 2.0) mem.sample = null;

      let sp;
      if (d > 5) sp = 0.55;
      else if (d > 2.5) sp = 0.35;
      else if (d > 1.8) sp = 0.16;
      else sp = 0.08;

      if (d < 2.0 && wheelMax > 0.48) sp = 0.03;

      return driveRel(br, sp);
    }

    if (!mem.sample) {
      mem.sample = {
        startT: t,
        startCarried: carried,
        stable: 0,
        site: { x: sx, y: sy },
        value: val,
        hint: mem.targetHint || (mem.search && mem.search.hint) || null
      };
    }

    const s = mem.sample;
    s.site.x = sx;
    s.site.y = sy;

    const vmax = Math.max(Math.abs(wl), Math.abs(wr));
    if (vmax < 0.135 && d < 1.56) s.stable += dt;
    else s.stable = 0;

    if (t - s.startT > 24.0 && carried <= s.startCarried) {
      mem.ignore = { x: sx, y: sy, until: t + 18 };
      if (s.hint) s.hint.done = true;
      if (mem.targetHint) mem.targetHint.done = true;
      mem.sample = null;
      return holdStill(false);
    }

    let canDrill = d < 1.53 && (s.stable > 0.15 || drilling > 0.01);
    if (vmax > 0.16) canDrill = false;

    return holdStill(canDrill);
  }

  function chooseExplore() {
    if (science > 0.70 && t - mem.lastOppSearch > 55) {
      mem.lastOppSearch = t;
      startSearch(mem.pos.x, mem.pos.y, null);
      const r = runSearch();
      if (r) return r;
    }

    let best = null;
    let bestD = 1e99;
    for (let i = 0; i < mem.explore.length; i++) {
      const p = mem.explore[i];
      if (p.used) continue;
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }

    if (best) {
      if (bestD < 3.8) {
        best.used = true;
        return holdStill(false);
      }
      const sp = bestD > 42 ? 0.72 : 0.54;
      return driveToPoint(best.x, best.y, sp);
    }

    const ang = (t * 0.018) % (2 * PI);
    const tx = clamp(base.x + 80 * Math.cos(ang), 8, size - 8);
