      startSearch(h.x, h.y, h);
      const r = runSearch();
      if (r) return r;
      if (h.done) mem.targetHint = null;
    } else {
      let sp;
      if (d > 50) sp = 0.76;
      else if (d > 15) sp = 0.60;
      else sp = 0.44;
      return driveToPoint(h.x, h.y, sp);
    }
  }

