  }

  // ---------- position / heading ----------
  const dt = clamp(t - mem.lastT, 0, 0.5) || 0.1;
  mem.lastT = t;
  const moved = obs.x !== mem.gx || obs.y !== mem.gy;
  if (moved) { mem.gx = obs.x; mem.gy = obs.y; mem.gT = t; }
  const stale = (t - mem.gT) > 3;
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  const vf = (wl + wr) / 2;
  const H = wrap((obs.heading || 0) + mem.off);
  const P = stale
    ? { x: mem.P.x + vf * dt * Math.cos(H * D2R), y: mem.P.y + vf * dt * Math.sin(H * D2R) }
    : { x: obs.x, y: obs.y };
  mem.P = P;

  mem.odo += Math.abs(vf) * dt;
  if (mem.odo > 40) mem.rate = clamp((mem.b0 - battery) / mem.odo, 0.0004, 0.004);

  // compass offset calibration from GPS track over straight segments
  if (!stale) {
    const hr = (obs.heading || 0) * D2R;
    mem.seg.s += Math.sin(hr); mem.seg.c += Math.cos(hr);
    mem.seg.n += 1; mem.seg.f += vf; mem.seg.tu += Math.abs(wl - wr);
  }
  const dA = dist(P, mem.anchor);
  if (dA >= 6) {
    if (!stale && mem.seg.n > 3 && dA < 25 && mem.seg.f / mem.seg.n > 0.2 && mem.seg.tu / mem.seg.n < 0.4) {
      const track = Math.atan2(P.y - mem.anchor.y, P.x - mem.anchor.x) * R2D;
      const mean = Math.atan2(mem.seg.s, mem.seg.c) * R2D;
      const err = wrap(track - mean);
      if (!mem.offInit) { mem.off = err; mem.offInit = true; }
      else mem.off = wrap(mem.off + 0.2 * wrap(err - mem.off));
    }
    mem.anchor = { x: P.x, y: P.y };
    mem.seg = { s: 0, c: 0, n: 0, f: 0, tu: 0 };
  }

  // ---------- helpers ----------
  const rangeNear = (d) => {
    let m = 15;
    for (let i = 0; i < 9; i++) if (Math.abs(ANG[i] - d) <= 20 && R[i] < m) m = R[i];
    return m;
  };
  const sideOf = () => {
    let l = 0, r = 0;
    for (let i = 0; i < 9; i++) { if (ANG[i] > 0) l += R[i]; else if (ANG[i] < 0) r += R[i]; }
    return l >= r ? 1 : -1;
  };
  const steer = (err, vmax) => {
    let best = 0, bc = Infinity, brr = 15;
    for (let d = -90; d <= 90; d += 5) {
      const rr = rangeNear(d);
      const cost = Math.abs(d - err) + Math.max(0, 6 - rr) * 6 + (rr < 1.2 ? 100 : 0);
      if (cost < bc) { bc = cost; best = d; brr = rr; }
    }
    if (brr < 1.2) { const s = sideOf(); return mk(-0.5 * s, 0.5 * s); }
    const front = rangeNear(0);
    const fac = clamp((front - 1.0) / 5, 0.1, 1);
    let v = vmax * fac * clamp(1 - Math.abs(best) / 90, 0.1, 1);
    if (Math.abs(best) > 55) v = Math.min(v, 0.05);
    const tt = clamp(0.012 * best, -0.6, 0.6);
    return mk(v - tt, v + tt);
  };
  const nav = (Q, vmax) => {
    const err = wrap(Math.atan2(Q.y - P.y, Q.x - P.x) * R2D - H);
    const d = dist(P, Q);
    return steer(err, d < 5 ? Math.min(vmax, 0.3) : vmax);
  };
  const sampledNear = (q, r) => mem.sampled.some((s) => dist(s, q) < r);

  // ---------- escape from bumps / stuck ----------
  if (mem.esc) {
    if (t < mem.esc.u1) return mk(-0.4, -0.4);
    if (t < mem.esc.u2) return mk(-0.5 * mem.esc.s, 0.5 * mem.esc.s);
    mem.esc = null; mem.escCool = t + 2;
    mem.sref = { p: { x: P.x, y: P.y }, t: t };
  }
  if (dist(P, mem.sref.p) > 0.6) mem.sref = { p: { x: P.x, y: P.y }, t: t };
  if (!mem.esc && t > mem.escCool) {
    const stuck = (mem.lastCmd || 0) > 0.3 && (t - mem.sref.t) > 5;
    if (obs.bumped || stuck) {
      mem.esc = { u1: t + 1.2, u2: t + 2.4, s: sideOf() };
      if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
      mem.sref = { p: { x: P.x, y: P.y }, t: t };
      return mk(-0.4, -0.4);
    }
  }

  // ---------- site detection ----------
  const site = obs.site || null;
  let S = null;
  if (site) {
    const b = (H + site.bearing) * D2R;
    S = { x: P.x + site.distance * Math.cos(b), y: P.y + site.distance * Math.sin(b) };
    if (!sampledNear(S, 5) && !mem.found.some((f) => dist(f, S) < 5)) {
      mem.found.push({ x: S.x, y: S.y, value: typeof site.value === 'number' ? site.value : 1, state: 'todo' });
    }
  }
  const dB = dist(P, mem.base);
  const beacon = obs.beacon || null;
  const docked = !!obs.docked || (beacon ? beacon.distance < 2.4 : dB < 1.8);

  // start sampling a nearby site
  if (site && S && mem.phase === 'nav' && site.distance <= 8 && carried < mem.cap &&
      !docked && battery > 0.05 && !sampledNear(S, 5)) {
    mem.phase = 'sample';
    mem.sT = { x: S.x, y: S.y, t0: t, c0: carried, seen: t };
  }

  // ---------- sampling ----------
  if (mem.phase === 'sample') {
    const st = mem.sT;
    if (!st) { mem.phase = 'nav'; return zero(); }
    if (carried > st.c0) {
      mem.sampled.push({ x: st.x, y: st.y });
      mem.nSamp++;
      for (const h of mem.hints) if (h.state === 'todo' && dist(h, st) < 22) h.state = 'done';
      for (const f of mem.found) if (dist(f, st) < 5) f.state = 'done';
      mem.phase = 'nav'; mem.tgt = null; mem.sT = null;
      return zero();
    }
    if (site) st.seen = t;
    if (t - st.t0 > 80 || t - st.seen > 6) {
      for (const f of mem.found) if (dist(f, st) < 5) f.state = 'failed';
      mem.phase = 'nav'; mem.tgt = null; mem.sT = null;
      return zero();
    }
    const dS = site ? site.distance : dist(P, st);
    if (dS > 1.3) {
      const o = site ? steer(site.bearing, 0.3) : nav(st, 0.3);
      return { left: o.left, right: o.right, drill: false };
    }
    if ((obs.drilling || 0) >= 7.0) {
      for (const f of mem.found) if (dist(f, st) < 5) f.state = 'failed';
      mem.phase = 'nav'; mem.tgt = null; mem.sT = null;
      return zero();
    }
    let l = 0, r = 0;
    if (Math.abs(vf) > 0.1) { l = -0.25 * Math.sign(vf); r = l; }
    return { left: l, right: r, drill: true };
  }

  // ---------- docking ----------
  if (mem.phase === 'dock') {
    const waited = t - mem.dockT;
    if (!docked && waited > 1.5) { mem.phase = 'home'; return zero(); }
    const needCharge = battery < 0.4 && timeLeft > 150 && waited < 60;
    if ((carried === 0 && !needCharge) || waited > 30) { mem.phase = 'nav'; mem.tgt = null; }
    return zero();
  }

  const homeStep = () => {
    if (docked) { mem.phase = 'dock'; mem.dockT = t; return zero(); }
    if (beacon) return steer(beacon.bearing, beacon.distance < 6 ? 0.25 : 0.6);
    return nav(mem.base, dB < 6 ? 0.25 : 0.6);
  };
  if (mem.phase === 'home') return homeStep();

  // ---------- go home? ----------
  const needB = dB * mem.rate * 1.5 + 0.06;
  if (carried >= mem.cap || (carried > 0 && timeLeft < dB / 0.45 + 60) || battery < needB + 0.03) {
    mem.phase = 'home'; mem.tgt = null;
    return homeStep();
  }

  // ---------- target selection ----------
  const pickTarget = (sweepMode) => {
    let best = null, bs = -1;
    let cands;
    if (sweepMode) {
      cands = mem.sweep.filter((s) => !s.visited).map((s) => ({ x: s.x, y: s.y, est: mem.avgEst * 0.3, kind: 'sweep', ref: s }));
    } else {
      cands = mem.hints.filter((h) => h.state === 'todo').map((h) => ({ x: h.x, y: h.y, est: h.est, kind: 'hint', ref: h }))
        .concat(mem.found.filter((f) => f.state === 'todo').map((f) => ({ x: f.x, y: f.y, est: f.value, kind: 'found', ref: f })));
    }
    for (const c of cands) {
      if (sampledNear(c, 5)) continue;
      const d = dist(P, c), dc = dist(c, mem.base);
      if ((d + dc) / 0.45 > timeLeft - 25) continue;
      if (battery < (d + dc) * mem.rate * 1.3 + 0.08) continue;
      const sc = c.est / (d + 25);
      if (sc > bs) { bs = sc; best = c; }
    }
    if (!best) return null;
    const dd = dist(P, best);
    return { x: best.x, y: best.y, kind: best.kind, ref: best.ref, t0: t, fails: 0, search: null, deadline: t + dd * 4 + 60 };
  };

  if (!mem.tgt) {
    mem.tgt = pickTarget(false);
    if (!mem.tgt) mem.tgt = pickTarget(true);
    if (!mem.tgt && mem.sweep.some((s) => s.visited)) {
      for (const s of mem.sweep) s.visited = false;
      mem.tgt = pickTarget(true);
    }
    if (!mem.tgt) {
      if (carried > 0) { mem.phase = 'home'; return homeStep(); }
      return zero();
    }
  }

  const failTarget = () => {
    if (mem.tgt) {
      if (mem.tgt.kind === 'sweep') mem.tgt.ref.visited = true;
      else mem.tgt.ref.state = 'failed';
    }
    mem.tgt = null;
  };

  const T = mem.tgt;
  const dT = dist(P, T);
  if (T.fails >= 3 || t > T.deadline) { failTarget(); return zero(); }

  if (T.kind === 'sweep') {
    if (dT < 8) { T.ref.visited = true; mem.tgt = null; return zero(); }
    const o = nav(T, 0.7);
    return { left: o.left, right: o.right, drill: false };
  }

  if (!T.search && dT < 4) {
    T.search = { i: 0, pts: science > 0 ? SP_LONG : SP_SHORT };
    T.deadline = Math.max(T.deadline, t + 60);
  }
  if (T.search) {
    const pts = T.search.pts;
    if (T.search.i >= pts.length) { failTarget(); return zero(); }
    let wp = { x: T.x + pts[T.search.i][0], y: T.y + pts[T.search.i][1] };
    if (dist(P, wp) < 2.0) {
      T.search.i++;
      if (T.search.i >= pts.length) { failTarget(); return zero(); }
      wp = { x: T.x + pts[T.search.i][0], y: T.y + pts[T.search.i][1] };
    }
    const o = nav(wp, 0.35);
    return { left: o.left, right: o.right, drill: false };
  }

  const o = nav(T, dT < 12 ? 0.4 : 0.7);
  return { left: o.left, right: o.right, drill: false };
}

function act(obs, mem) {
  const out = step(obs, mem);
  mem.cmdF = out.drill ? 0 : Math.abs((out.left + out.right) / 2);
  return out;
}

function step(obs, mem) {
  const D2R = Math.PI / 180, R2D = 180 / Math.PI;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const wrap = (a) => ((a + 180) % 360 + 360) % 360 - 180;
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const SPIRAL = [[0, 0], [7, 0], [7, 7], [-7, 7], [-7, -7], [14, -7], [14, 14]];
  const MAP = 400;
  const zero = () => ({ left: 0, right: 0, drill: false });
  const mk = (l, r, d) => ({ left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!d });

  const t = typeof obs.t === 'number' ? obs.t : 0;
  const timeLeft = typeof obs.timeLeft === 'number' ? obs.timeLeft : 1200;
  const battery = typeof obs.battery === 'number' ? obs.battery : 1;
  const carried = obs.carried || 0;
  const science = obs.science || 0;
  const heading = typeof obs.heading === 'number' ? obs.heading : 0;
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const R = ANG.map((a, i) => {
    const v = rays[i];
    return (typeof v === 'number' && isFinite(v)) ? clamp(v, 0, 15) : 15;
  });
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  const vf = (wl + wr) / 2;
  const site = obs.site || null;
  const beacon = obs.beacon || null;
  const docked0 = !!obs.docked;
  const drl = obs.drilling || 0;

  // ---------- init ----------
  if (!mem.init) {
    mem.init = true;
    const m = obs.mission || {};
    mem.base = m.base ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
    mem.cap = m.capacity || 5;
    mem.hints = (Array.isArray(m.hints) ? m.hints : []).map((h) => ({
      x: h.x, y: h.y, est: typeof h.estimate === 'number' ? Math.max(0.05, h.estimate) : 1, state: 'todo'
    }));
    let s = 0;
    for (const h of mem.hints) s += h.est;
    mem.avgEst = mem.hints.length ? s / mem.hints.length : 1;
    mem.explore = [];
    for (const x of [50, 130, 210, 290, 370]) for (const y of [50, 130, 210, 290, 370]) mem.explore.push({ x: x, y: y, state: 'todo' });
    mem.sampled = [];
    mem.tgt = null; mem.phase = 'nav'; mem.sT = null; mem.esc = null; mem.escCool = -1;
    mem.off = 0; mem.offInit = false; mem.offBad = 0; mem.seg = null;
    mem.P = { x: obs.x, y: obs.y }; mem.gx = obs.x; mem.gy = obs.y; mem.gT = t; mem.lastT = t;
    mem.stk = { t: t, p: { x: obs.x, y: obs.y } };
    mem.ib = 0; mem.hI = 0; mem.lastD = 0; mem.cmdF = 0;
    mem.dockT = t; mem.homeT0 = t; mem.noHomeUntil = -1; mem.resets = 0; mem.nSamp = 0;
  }

  // ---------- position (GPS with dead-reckoning fallback) ----------
  const dt = clamp(t - mem.lastT, 0, 0.5);
  mem.lastT = t;
  if (obs.x !== mem.gx || obs.y !== mem.gy) { mem.gx = obs.x; mem.gy = obs.y; mem.gT = t; }
  const stale = (t - mem.gT) > 3;
  const H = wrap(heading + mem.off);
  const P = stale
    ? { x: mem.P.x + vf * dt * Math.cos(H * D2R), y: mem.P.y + vf * dt * Math.sin(H * D2R) }
    : { x: obs.x, y: obs.y };
  mem.P = P;

  // ---------- compass offset calibration from GPS track over straight segments ----------
  if (!mem.seg) mem.seg = { a: { x: P.x, y: P.y }, h0: heading, s: 0, c: 0, n: 0, fs: 0, tu: 0, bump: false };
  const sg = mem.seg;
  if (!stale) {
    const hr = heading * D2R;
    sg.s += Math.sin(hr); sg.c += Math.cos(hr); sg.n++;
    sg.fs += vf; sg.tu += Math.abs(wl - wr);
  }
  if (obs.bumped) sg.bump = true;
  const dA = dist(P, sg.a);
  if (dA >= 10) {
    if (!stale && sg.n > 5 && !sg.bump && sg.fs / sg.n > 0.2 && sg.tu / sg.n < 0.3 &&
        Math.abs(wrap(heading - sg.h0)) < 10 && dA < 25) {
      const track = Math.atan2(P.y - sg.a.y, P.x - sg.a.x) * R2D;
      const mean = Math.atan2(sg.s, sg.c) * R2D;
      const err = wrap(track - mean);
      const d = wrap(err - mem.off);
      if (!mem.offInit) { mem.off = err; mem.offInit = true; mem.offBad = 0; }
      else if (Math.abs(d) > 35) {
        mem.offBad++;
        if (mem.offBad >= 2) { mem.off = err; mem.offBad = 0; }
      } else {
        mem.offBad = 0;
        mem.off = wrap(mem.off + 0.25 * d);
      }
    }
    mem.seg = null;
  }

  // ---------- helpers ----------
  const sampledNear = (q, r) => mem.sampled.some((s) => s.until > t && dist(s, q) < r);

  const clearAt = (d) => {
    let m = 15, any = false;
    for (let i = 0; i < 9; i++) {
      if (Math.abs(ANG[i] - d) <= 22) { any = true; if (R[i] < m) m = R[i]; }
    }
    if (!any) {
      let bi = 0;
      for (let i = 1; i < 9; i++) if (Math.abs(ANG[i] - d) < Math.abs(ANG[bi] - d)) bi = i;
      m = R[bi];
    }
    return m;
  };

  const edgeDist = (d) => {
    const h = (H + d) * D2R, cx = Math.cos(h), cy = Math.sin(h);
    let e = 99;
    if (cx > 0.02) e = Math.min(e, (MAP - P.x) / cx);
    if (cx < -0.02) e = Math.min(e, P.x / -cx);
    if (cy > 0.02) e = Math.min(e, (MAP - P.y) / cy);
    if (cy < -0.02) e = Math.min(e, P.y / -cy);
    return Math.max(0, e);
  };

  // steer toward relative error err (deg, + = left), avoiding obstacles
  const navRel = (err, vmax) => {
    let best = 0, bc = Infinity;
    for (let d = -90; d <= 90; d += 10) {
      const c = Math.min(clearAt(d), edgeDist(d));
      let cost = Math.abs(d - err);
      if (c < 2.5) cost += 300 + (2.5 - c) * 40;
      else if (c < 7) cost += (7 - c) * 6;
      cost += 0.2 * Math.abs(d - mem.lastD);
      if (cost < bc) { bc = cost; best = d; }
    }
    mem.lastD = best;
    const ad = Math.abs(best);
    const front = Math.min(R[3], R[4], R[5]);
    const sf = clamp((front - 2) / 7, 0, 1);
    const v = vmax * sf * clamp(1 - ad / 70, 0, 1);
    const dr = best * D2R;
    if (v > 0.1 && ad < 30) mem.ib = clamp(mem.ib + 0.03 * dr, -0.2, 0.2);
    let tn = clamp(0.3 * dr + mem.ib, -0.4, 0.4);
    if (ad > 8 && Math.abs(tn) < 0.1) tn = Math.sign(best) * 0.1;
    return mk(v - tn, v + tn, false);
  };

  // ---------- escape from bumps / no progress ----------
  if (mem.esc) {
    if (t < mem.esc.until) return mk(mem.esc.l, mem.esc.r, false);
    mem.esc = null;
    mem.stk = { t: t, p: { x: P.x, y: P.y } };
  }
  if (dist(P, mem.stk.p) > 0.7) mem.stk = { t: t, p: { x: P.x, y: P.y } };
  const stuck = mem.cmdF > 0.2 && (t - mem.stk.t) > 4;
  if ((obs.bumped || stuck) && t > mem.escCool) {
    const s = (R[5] + R[6] + R[7] + R[8]) >= (R[0] + R[1] + R[2] + R[3]) ? 1 : -1;
    mem.esc = { until: t + 1.5, l: -0.45 - 0.25 * s, r: -0.45 + 0.25 * s };
    mem.escCool = t + 3;
    mem.stk = { t: t + 1.5, p: { x: P.x, y: P.y } };
    if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    return mk(mem.esc.l, mem.esc.r, false);
  }

  // ---------- site detection ----------
  let S = null;
  if (site) {
    const b = (H + site.bearing) * D2R;
    S = { x: P.x + site.distance * Math.cos(b), y: P.y + site.distance * Math.sin(b) };
  }
  if (site && (mem.phase === 'nav' || mem.phase === 'home') && site.distance <= 8 &&
      carried < mem.cap && battery > 0.08 && !docked0 && !sampledNear(S, 4)) {
    mem.phase = 'sample';
    mem.sT = { x: S.x, y: S.y, t0: t, c0: carried, seen: t, lastDr: 0, breaks: 0, hold: false };
  }

  // ---------- sampling ----------
  if (mem.phase === 'sample') {
    const st = mem.sT;
    if (!st) { mem.phase = 'nav'; return zero(); }
    if (carried > st.c0) {
      mem.sampled.push({ x: st.x, y: st.y, until: Infinity });
      mem.nSamp++;
      let bh = null, bd = 22;
      for (const h of mem.hints) {
        const d = dist(h, st);
        if (d < bd && h.state !== 'done') { bd = d; bh = h; }
      }
      if (bh) bh.state = 'done';
      mem.phase = 'nav'; mem.sT = null; mem.tgt = null;
      return zero();
    }
    if (site) st.seen = t;
    if (drl < st.lastDr - 0.5 && st.hold) { st.breaks++; st.hold = false; }
    st.lastDr = drl;
    const failS = () => {
      mem.sampled.push({ x: st.x, y: st.y, until: t + 120 });
      mem.phase = 'nav'; mem.sT = null; mem.tgt = null;
      return zero();
    };
    if (st.breaks > 3 || t - st.t0 > 110) return failS();
    if (!site && !st.hold && t - st.seen > 10) return failS();
    if (drl >= 9.5) return failS();
    const dS = site ? site.distance : dist(P, st);
    const bS = site ? site.bearing : wrap(Math.atan2(st.y - P.y, st.x - P.x) * R2D - H);
    if (!st.hold) {
      if (dS > 1.25) return navRel(bS, clamp(0.08 + 0.1 * dS, 0.1, 0.22));
      st.hold = true;
      mem.hI = 0;
    }
    const hold = clamp(-0.8 * vf + mem.hI + 0.005 * (obs.pitch || 0), -0.4, 0.4);
    mem.hI = clamp(mem.hI - 0.5 * vf * dt, -0.3, 0.3);
    return mk(hold, hold, true);
  }

  // ---------- docking ----------
  const dB = dist(P, mem.base);
  if (mem.phase === 'dock') {
    const waited = t - mem.dockT;
    const atBase = docked0 || (beacon ? beacon.distance < 3.2 : dB < 2.5);
    if (!atBase && waited > 1.5) { mem.phase = 'home'; mem.homeT0 = t; return zero(); }
    if (carried > 0 && waited > 12) {
      mem.phase = 'nav'; mem.tgt = null; mem.noHomeUntil = t + 40;
      return zero();
    }
    const needCharge = battery < 0.35 && timeLeft > 200 && waited < 30;
    if (carried === 0 && waited > 1.0 && (!needCharge || waited > 30)) {
      mem.phase = 'nav'; mem.tgt = null;
    }
    return zero();
  }

  const goHome = () => {
    const dB1 = dist(P, mem.base);
    if (docked0 || (beacon && beacon.distance < 2.2) || dB1 < 1.6) {
      mem.phase = 'dock'; mem.dockT = t;
      return zero();
    }
    if (beacon && beacon.distance < 20) {
      const v = clamp(0.1 + 0.06 * beacon.distance, 0.12, 0.3);
      return navRel(beacon.bearing, v);
    }
    const err = wrap(Math.atan2(mem.base.y - P.y, mem.base.x - P.x) * R2D - H);
    return navRel(err, dB1 < 8 ? 0.2 : 0.35);
  };

  if (mem.phase === 'home') return goHome();

  // ---------- go home? ----------
  const needB = dB * 0.0025 + 0.1;
  let wantHome = false;
  if (carried >= mem.cap) wantHome = true;
  if (carried >= 2 && dB < 8) wantHome = true;
  if (carried > 0 && timeLeft < dB / 0.5 + 60) wantHome = true;
  if (battery < needB) wantHome = true;
  if (battery < 0.2 && timeLeft > 200) wantHome = true;
  if (t < mem.noHomeUntil && battery >= needB) wantHome = false;
  if (wantHome) {
    mem.phase = 'home'; mem.homeT0 = t; mem.tgt = null;
    return goHome();
  }

  // ---------- target selection ----------
  const pickTarget = () => {
    let best = null, bs = -1;
    const consider = (c, est, kind, ref) => {
      if (sampledNear(c, 5)) return;
      const d = dist(P, c), db = dist(c, mem.base);
      if ((d + db) / 0.5 > timeLeft - 40) return;
      if (battery < (d + db) * 0.0025 + 0.15) return;
      const sc = est / (d + 0.5 * db + 25);
      if (sc > bs) {
        bs = sc;
        best = { x: c.x, y: c.y, kind: kind, ref: ref, t0: t, fails: 0, search: null, deadline: t + d / 0.3 + 90 };
      }
    };
    for (const h of mem.hints) if (h.state === 'todo') consider(h, h.est, 'hint', h);
    for (const e of mem.explore) if (e.state === 'todo') consider(e, mem.avgEst * 0.3, 'explore', e);
    return best;
  };

  if (!mem.tgt) {
    mem.tgt = pickTarget();
    if (!mem.tgt && mem.resets < 3) {
      mem.resets++;
      for (const e of mem.explore) e.state = 'todo';
      if (carried === 0) for (const h of mem.hints) if (h.state === 'failed') h.state = 'todo';
      mem.tgt = pickTarget();
    }
    if (!mem.tgt) {
      if (carried > 0) { mem.phase = 'home'; mem.homeT0 = t; return goHome(); }
      return zero();
    }
  }

  const T = mem.tgt;
  const dT = dist(P, T);
  const endT = (ok) => {
    if (T.kind === 'hint') T.ref.state = ok ? 'done' : 'failed';
    else T.ref.state = 'done';
    mem.tgt = null;
  };
  if (t > T.deadline || T.fails >= 3) { endT(false); return zero(); }

  if (T.search) {
    while (T.search.i < SPIRAL.length) {
      const q = SPIRAL[T.search.i];
      if (dist(P, { x: T.x + q[0], y: T.y + q[1] }) < 2) T.search.i++;
      else break;
    }
    if (T.search.i >= SPIRAL.length || t > T.search.end) { endT(true); return zero(); }
    const q = SPIRAL[T.search.i];
    const wp = { x: T.x + q[0], y: T.y + q[1] };
    const err = wrap(Math.atan2(wp.y - P.y, wp.x - P.x) * R2D - H);
    return navRel(err, 0.3);
  }

  if (dT < 5) {
    if (science > 0) {
      T.search = { i: 0, end: t + 110 };
      T.deadline = Math.max(T.deadline, t + 130);
      return zero();
    }
    endT(false);
    return zero();
  }

  const err = wrap(Math.atan2(T.y - P.y, T.x - P.x) * R2D - H);
  return navRel(err, dT < 12 ? 0.3 : 0.4);
}

function act(obs, mem) {
  let out = null;
  try { out = step(obs || {}, mem); } catch (e) { out = null; }
  if (!out) out = { left: 0, right: 0, drill: false };
  let L = Number(out.left), Rr = Number(out.right);
  if (!isFinite(L)) L = 0;
  if (!isFinite(Rr)) Rr = 0;
  out = { left: Math.max(-1, Math.min(1, L)), right: Math.max(-1, Math.min(1, Rr)), drill: !!out.drill };
  mem.cmdL = out.left; mem.cmdR = out.right;
