      if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
      mem.phase = 'nav'; mem.sT = null; mem.tgt = null;
      return zero();
    };
    if (st.breaks > 8 || t - st.t0 > 100 || drl > 9) return failS();
    if (!st.hold && !site && t - st.seen > 6) return failS();
