      if (dB < 12) wantHome = true;
      if (timeLeft < dB / VEST + 60) wantHome = true;
    }
    if (battery < dB * 0.002 + 0.12 && timeLeft > 20) wantHome = true;
    if (t < mem.noHomeUntil && battery > 0.3) wantHome = false;
    if (wantHome) { mem.phase = 'home'; mem.tgt = null; }
  }

  const homeAct = () => {
    if (docked) { mem.phase = 'dock'; mem.dockT = t; return zero(); }
    if (beacon && beacon.distance < 20) return navRel(beacon.bearing, beacon.distance < 5 ? 0.15 : 0.35);
