  if (!mem.tgt) {
    mem.tgt = pick();
    if (!mem.tgt && mem.explore.every((e) => e.state !== 'todo')) {
      for (const e of mem.explore) e.state = 'todo';
      mem.tgt = pick();
    }
    if (!mem.tgt) {
      if (carried > 0) { mem.phase = 'home'; return homeAct(); }
      return zero();
    }
  }

  const T = mem.tgt;
  const dT = dist(P, T);
  const failT = (hard) => {
    if (T.kind === 'hint') {
      T.ref.tries += hard ? 2 : 1;
      if (T.ref.tries >= 2) T.ref.state = 'failed';
    } else if (T.kind === 'found') {
      T.ref.state = 'failed';
    } else {
      T.ref.state = 'done';
    }
    mem.tgt = null;
    return zero();
  };

  if (t > T.deadline || T.fails >= 3) return failT(false);

  if (T.search) {
    while (T.search.i < SP.length &&
           dist(P, { x: T.x + SP[T.search.i][0], y: T.y + SP[T.search.i][1] }) < 2.5) T.search.i++;
    if (T.search.i >= SP.length || t > T.search.end) return failT(false);
    const wp = { x: T.x + SP[T.search.i][0], y: T.y + SP[T.search.i][1] };
    return navTo(wp, 0.3);
  }

  if (dT < 6) {
    if (science > 0) { T.search = { i: 0, end: t + 80 }; return zero(); }
    return failT(T.kind === 'hint');
  }

  return navTo(T, dT < 15 ? 0.25 : 0.4);
}

