  const wl = num(obs.wheelLeft, 0), wr = num(obs.wheelRight, 0);
  const vf = (wl + wr) / 2;
  const site = (obs.site && typeof obs.site.distance === 'number') ? obs.site : null;
  const beacon = (obs.beacon && typeof obs.beacon.distance === 'number') ? obs.beacon : null;
  const bumped = !!obs.bumped;
  const docked0 = !!obs.docked;
  const R = ANG.map((a, i) => {
    const v = Array.isArray(obs.rays) ? obs.rays[i] : undefined;
    return clamp(num(v, 15), 0, 15);
  });

  // ---------- init ----------
  if (!mem.init) {
    mem.init = true;
    const m = obs.mission || {};
    const bp = m.base || {};
    mem.base = { x: num(bp.x, num(obs.x, 0)), y: num(bp.y, num(obs.y, 0)) };
    mem.cap = Math.max(1, num(m.capacity, 5));
    const hs = Array.isArray(m.hints) ? m.hints : [];
    mem.hints = hs.filter((h) => h && typeof h.x === 'number' && typeof h.y === 'number')
      .map((h) => ({ x: h.x, y: h.y, est: Math.max(0.05, num(h.estimate, 1)), st: 'todo' }));
    let s = 0;
    for (const h of mem.hints) s += h.est;
    mem.avgEst = mem.hints.length ? s / mem.hints.length : 1;
    mem.explore = [];
    for (const x of [50, 125, 200, 275, 350]) for (const y of [50, 125, 200, 275, 350]) mem.explore.push({ x: x, y: y, st: 'todo' });
    mem.samp = [];
    mem.phase = 'nav'; mem.tgt = null; mem.hold = null; mem.esc = null; mem.escCool = -1;
    mem.off = 0; mem.offInit = false; mem.seg = null;
    mem.P = { x: num(obs.x, 0), y: num(obs.y, 0) };
    mem.gx = mem.P.x; mem.gy = mem.P.y; mem.gT = t; mem.lastT = t; mem.vE = 0;
    mem.stk = { t: t, p: { x: mem.P.x, y: mem.P.y } };
    mem.ib = 0; mem.hI = 0; mem.prevD = 0;
    mem.noHome = -1; mem.dockT = t; mem.resets = 0; mem.nSamp = 0;
  }

  // ---------- position (GPS, dead reckoning when stale) ----------
  const dt = clamp(t - mem.lastT, 0, 0.5);
  mem.lastT = t;
  const ox = num(obs.x, mem.P.x), oy = num(obs.y, mem.P.y);
  const fixNew = ox !== mem.gx || oy !== mem.gy;
  if (fixNew) { mem.gx = ox; mem.gy = oy; mem.gT = t; }
  const stale = (t - mem.gT) > 3.5;
  mem.vE = 0.3 * vf + 0.7 * mem.vE;
  const H = wrap(heading + mem.off);
  const P = stale
    ? { x: mem.P.x + mem.vE * dt * Math.cos(H * D2R), y: mem.P.y + mem.vE * dt * Math.sin(H * D2R) }
    : { x: ox, y: oy };
  mem.P = P;

  // ---------- compass offset calibration from straight GPS runs ----------
  if (fixNew && !stale) {
    const sg = mem.seg;
    if (!sg || vf < 0.15 || bumped || Math.abs(wrap(heading - sg.h0)) > 20) {
      mem.seg = { a: { x: P.x, y: P.y }, h0: heading, s: 0, c: 0, n: 0 };
    } else {
      const hr = heading * D2R;
      sg.s += Math.sin(hr); sg.c += Math.cos(hr); sg.n++;
      if (dist(P, sg.a) >= 8 && sg.n >= 4) {
        const track = Math.atan2(P.y - sg.a.y, P.x - sg.a.x) * R2D;
        const mean = Math.atan2(sg.s, sg.c) * R2D;
        const err = wrap(track - mean);
        if (!mem.offInit) { mem.off = err; mem.offInit = true; }
        else mem.off = wrap(mem.off + 0.2 * wrap(err - mem.off));
        mem.seg = { a: { x: P.x, y: P.y }, h0: heading, s: 0, c: 0, n: 0 };
      }
    }
  }

  // ---------- helpers ----------
  const edgeDist = (d) => {
    const h = (H + d) * D2R, cx = Math.cos(h), cy = Math.sin(h);
    let e = 99;
    if (cx > 0.02) e = Math.min(e, (MAP - P.x) / cx);
    if (cx < -0.02) e = Math.min(e, P.x / -cx);
    if (cy > 0.02) e = Math.min(e, (MAP - P.y) / cy);
    if (cy < -0.02) e = Math.min(e, P.y / -cy);
    return Math.max(0, e);
  };

  const clearance = (d) => {
    let m = 15, any = false, bi = 0;
    for (let i = 0; i < 9; i++) {
      const da = Math.abs(ANG[i] - d);
      if (da < Math.abs(ANG[bi] - d)) bi = i;
      if (da <= 25) { any = true; if (R[i] < m) m = R[i]; }
    }
    if (!any) m = R[bi];
    return Math.min(m, edgeDist(d));
  };

  // steer toward relative heading rel (deg, + = left) with obstacle avoidance
  const navStep = (rel, vmax) => {
    let best = 0, bc = Infinity;
    for (let d = -120; d <= 120; d += 10) {
      const c = clearance(d);
      let cost = Math.abs(d - rel);
      if (c < 2.5) cost += 120 + 40 * (2.5 - c);
      else if (c < 6) cost += 8 * (6 - c);
      cost += 0.25 * Math.abs(d - mem.prevD);
      if (cost < bc) { bc = cost; best = d; }
    }
    mem.prevD = best;
    const ad = Math.abs(best);
    const front = Math.min(clearance(0), clearance(best));
    const v = vmax * clamp(1 - ad / 60, 0, 1) * clamp((front - 1.5) / 4.5, 0, 1);
    const e = best * D2R;
    if (ad < 30 && v > 0.05) mem.ib = clamp(mem.ib + 0.05 * e * dt, -0.2, 0.2);
    const w = clamp(0.07 * e + mem.ib, -0.3, 0.3);
    return mk(v - w, v + w, false);
  };

  const markDone = (S) => {
    let bh = null, bd = 20;
    for (const h of mem.hints) {
      const d = dist(h, S);
      if (h.st !== 'done' && d < bd) { bd = d; bh = h; }
    }
    if (bh) bh.st = 'done';
    for (const e of mem.explore) if (dist(e, S) < 12) e.st = 'done';
  };

  const endT = (T, ok) => {
    if (T.kind === 'hint') T.ref.st = ok ? 'done' : 'failed';
    else T.ref.st = 'done';
    mem.tgt = null;
  };

  const pick = () => {
    let best = null, bs = -1;
    const cons = (c, est, kind, ref) => {
      const d = dist(P, c), db = dist(c, mem.base);
      if ((d + db) / 0.35 > timeLeft - 30) return;
      if (battery < 0.12 + (d + db) * 0.0025) return;
      const sc = est / (d + 0.6 * db + 40);
      if (sc > bs) {
        bs = sc;
        best = { x: c.x, y: c.y, kind: kind, ref: ref, fails: 0, search: null, deadline: t + d / 0.25 + 120 };
      }
    };
    for (const h of mem.hints) if (h.st === 'todo') cons(h, h.est, 'hint', h);
    for (const e of mem.explore) if (e.st === 'todo') cons(e, mem.avgEst * 0.4, 'explore', e);
    return best;
  };

  const dB = dist(P, mem.base);
  const docked = docked0 || dB < 2.4 || (!!beacon && beacon.distance < 2.2);

  const homeNav = () => {
    if (docked) { mem.phase = 'dock'; mem.dockT = t; mem.tgt = null; return zero(); }
    const rel = (beacon && beacon.distance < 20) ? beacon.bearing
      : wrap(Math.atan2(mem.base.y - P.y, mem.base.x - P.x) * R2D - H);
    return navStep(rel, dB < 6 ? 0.12 : 0.25);
  };

  // ---------- drive-in-escape after bump or stuck ----------
  if (dist(P, mem.stk.p) > 1.0) mem.stk = { t: t, p: { x: P.x, y: P.y } };
  if (mem.esc) {
    if (t < mem.esc.until) return mk(mem.esc.l, mem.esc.r, false);
    mem.esc = null;
    mem.stk = { t: t, p: { x: P.x, y: P.y } };
  }
  const holdingNow = mem.phase === 'sample' && mem.hold && mem.hold.holding;
  const fwd = mem.fwd || 0;
  const stuck = !holdingNow && fwd > 0.12 && (t - mem.stk.t) > 5;
  if ((bumped || stuck) && mem.phase !== 'dock' && t > mem.escCool) {
    const s = clearance(60) >= clearance(-60) ? 1 : -1;
    mem.esc = { until: t + 1.6, l: -0.35 - 0.15 * s, r: -0.35 + 0.15 * s };
    mem.escCool = t + 2.5;
    mem.stk = { t: t + 1.6, p: { x: P.x, y: P.y } };
    if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.phase === 'sample') { mem.phase = 'nav'; mem.hold = null; }
    return mk(mem.esc.l, mem.esc.r, false);
  }

  // ---------- start sampling a site seen within 8 m ----------
  if (site && (mem.phase === 'nav' || mem.phase === 'home') && site.distance <= 8 &&
      carried < mem.cap && battery > 0.05 && !docked && dB > 3.5) {
    const b = (H + site.bearing) * D2R;
    const S = { x: P.x + site.distance * Math.cos(b), y: P.y + site.distance * Math.sin(b) };
    const blocked = mem.samp.some((q) => dist(q, S) < 4 && (q.ok || t - q.t < 150));
    if (!blocked) {
      mem.phase = 'sample';
      mem.hold = { S: S, t0: t, last: drl, breaks: 0, holding: false, lastSeen: t, c0: carried };
    }
  }

  // ---------- sampling: approach, then drill with still hold ----------
  if (mem.phase === 'sample') {
    const h = mem.hold;
    if (!h) { mem.phase = 'nav'; return zero(); }
    if (carried > h.c0) {
      mem.samp.push({ x: h.S.x, y: h.S.y, t: t, ok: true });
      mem.nSamp++;
      markDone(h.S);
      mem.phase = 'nav'; mem.hold = null; mem.tgt = null;
      return zero();
    }
    if (site) {
      h.lastSeen = t;
      const b = (H + site.bearing) * D2R;
      h.S = { x: P.x + site.distance * Math.cos(b), y: P.y + site.distance * Math.sin(b) };
    }
    const dS = site ? site.distance : dist(P, h.S);
    if (drl < h.last - 0.3) { h.breaks++; h.holding = false; }
    h.last = drl;
    if (!site && dist(P, h.S) < 2.5) h.lastSeen = t;
    const failS = () => {
      mem.samp.push({ x: h.S.x, y: h.S.y, t: t, ok: false });
      mem.phase = 'nav'; mem.hold = null;
      if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
      return zero();
    };
    if (!site && t - h.lastSeen > 3) return failS();
    if (h.breaks > 4 || t - h.t0 > 80 || drl > 9.5) return failS();
    if (!h.holding) {
      if (dS > 1.3) {
        const rel = site ? site.bearing : wrap(Math.atan2(h.S.y - P.y, h.S.x - P.x) * R2D - H);
        return navStep(rel, dS > 3 ? 0.15 : 0.1);
      }
      h.holding = true;
      mem.hI = 0;
    }
    const v = vf;
    mem.hI = clamp(mem.hI - 1.2 * v * dt, -0.5, 0.5);
    const u = clamp(mem.hI - 1.0 * v, -0.5, 0.5);
    return mk(u, u, true);
  }

  // ---------- docking ----------
  if (mem.phase === 'dock') {
    const w = t - mem.dockT;
    if (dB > 3.2 && !docked0) {
      if (w > 1) { mem.phase = 'nav'; mem.tgt = null; }
      return zero();
    }
    const needCharge = battery < 0.4 && timeLeft > 200 && w < 40;
    if (carried > 0 && w > 10) { mem.phase = 'nav'; mem.tgt = null; mem.noHome = t + 30; return zero(); }
    if (carried === 0 && w > 1 && !(needCharge && battery < 0.6)) { mem.phase = 'nav'; mem.tgt = null; return zero(); }
    return zero();
  }

  // ---------- go home decision ----------
  let wantHome = false;
  if (carried > 0) {
    if (carried >= mem.cap) wantHome = true;
    if (carried >= 2 && dB < 25) wantHome = true;
    if (timeLeft < dB / 0.5 + 60) wantHome = true;
  }
  if (battery < 0.1 + dB * 0.0025) wantHome = true;
  if (t < mem.noHome && battery > 0.25) wantHome = false;
  if (wantHome && mem.phase === 'nav') { mem.phase = 'home'; mem.tgt = null; }
  if (mem.phase === 'home') return homeNav();

  // ---------- target selection ----------
  if (!mem.tgt) {
    mem.tgt = pick();
    if (!mem.tgt && carried > 0) { mem.phase = 'home'; return homeNav(); }
    if (!mem.tgt && mem.resets < 2) {
      mem.resets++;
      for (const h of mem.hints) if (h.st === 'failed') h.st = 'todo';
      for (const e of mem.explore) e.st = 'todo';
      mem.tgt = pick();
    }
    if (!mem.tgt) return zero();
  }

  const T = mem.tgt;
  if (t > T.deadline || T.fails >= 4) { endT(T, false); return zero(); }
  const dT = dist(P, T);

  if (T.search) {
    while (T.search.i < SP.length &&
           dist(P, { x: T.x + SP[T.search.i][0], y: T.y + SP[T.search.i][1] }) < 2) T.search.i++;
    if (T.search.i >= SP.length || t > T.search.end) { endT(T, false); return zero(); }
    const wp = { x: T.x + SP[T.search.i][0], y: T.y + SP[T.search.i][1] };
    return navStep(wrap(Math.atan2(wp.y - P.y, wp.x - P.x) * R2D - H), 0.2);
  }

  if (dT < 6) {
    if (science > 0) {
      T.search = { i: 0, end: t + 100 };
      T.deadline = Math.max(T.deadline, t + 115);
      return zero();
    }
    endT(T, false);
    return zero();
  }

  return navStep(wrap(Math.atan2(T.y - P.y, T.x - P.x) * R2D - H), dT < 12 ? 0.2 : 0.27);
}

function act(obs, mem) {
  let out = null;
  try { out = step(obs || {}, mem); } catch (e) { out = null; }
  if (!out) out = { left: 0, right: 0, drill: false };
  let L = Number(out.left), Rt = Number(out.right);
  if (!isFinite(L)) L = 0;
  if (!isFinite(Rt)) Rt = 0;
  L = Math.max(-1, Math.min(1, L));
  Rt = Math.max(-1, Math.min(1, Rt));
  mem.cmdL = L; mem.cmdR = Rt;
  return { left: L, right: Rt, drill: !!out.drill };
}

function step(obs, mem) {
  const D2R = Math.PI / 180, R2D = 180 / Math.PI;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const wrap = (a) => ((a + 180) % 360 + 360) % 360 - 180;
  const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const MAP = 400;
  const zero = () => ({ left: 0, right: 0, drill: false });
  const mk = (l, r, d) => ({ left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!d });

  const t = num(obs.t, 0);
  const timeLeft = num(obs.timeLeft, 1200);
  const battery = num(obs.battery, 1);
  const carried = num(obs.carried, 0);
  const science = num(obs.science, 0);
  const heading = num(obs.heading, 0);
