    mem.cap = Math.max(1, num(m.capacity, 5));
    mem.hints = (Array.isArray(m.hints) ? m.hints : [])
      .filter((h) => h && typeof h.x === 'number' && typeof h.y === 'number')
      .map((h) => ({ x: h.x, y: h.y, est: Math.max(0.05, num(h.estimate, 1)), st: 'todo' }));
    let s = 0;
    for (const h of mem.hints) s += h.est;
    mem.avgEst = mem.hints.length ? s / mem.hints.length : 1;
    mem.explore = [];
    for (const x of [50, 125, 200, 275, 350]) for (const y of [50, 125, 200, 275, 350]) mem.explore.push({ x: x, y: y, st: 'todo' });
    mem.found = [];
    mem.samp = [];
    mem.phase = 'nav'; mem.tgt = null; mem.sT = null; mem.esc = null; mem.escCool = -1; mem.escN = 0;
    mem.off = 0; mem.offInit = false; mem.seg = null;
    mem.P = { x: num(obs.x, 0), y: num(obs.y, 0) };
    mem.gx = mem.P.x; mem.gy = mem.P.y; mem.gT = t; mem.lastT = t; mem.vE = 0;
    mem.stk = { t: t, p: { x: mem.P.x, y: mem.P.y } };
    mem.ib = 0; mem.hI = 0; mem.prevD = 0;
    mem.dockT = t; mem.noHome = -1; mem.nSamp = 0; mem.resets = 0;
    mem.lastRays = ''; mem.sameN = 0; mem.rayOff = false;
    mem.cmdL = 0; mem.cmdR = 0;
