  const dt = clamp(t - mem.lastT, 0, 0.5);
  mem.lastT = t;
  const ox = num(obs.x, mem.P.x), oy = num(obs.y, mem.P.y);
  const fixNew = ox !== mem.gx || oy !== mem.gy;
  if (fixNew) { mem.gx = ox; mem.gy = oy; mem.gT = t; }
  const stale = (t - mem.gT) > 3;
  mem.vE = 0.3 * vf + 0.7 * mem.vE;
  const H = wrap(heading + mem.off);
  const P = stale
    ? { x: mem.P.x + mem.vE * dt * Math.cos(H * D2R), y: mem.P.y + mem.vE * dt * Math.sin(H * D2R) }
    : { x: ox, y: oy };
  mem.P = P;

  // ---------- compass offset from straight GPS runs ----------
  if (fixNew && !stale) {
    const straightCmd = mem.cmdL > 0.15 && mem.cmdR > 0.15 && Math.abs(mem.cmdL - mem.cmdR) < 0.12;
    if (!straightCmd || bumped || vf < 0.12) mem.seg = null;
    else {
      if (!mem.seg) mem.seg = { a: { x: P.x, y: P.y }, s: 0, c: 0, n: 0 };
      const sg = mem.seg;
      const hr = heading * D2R;
      sg.s += Math.sin(hr); sg.c += Math.cos(hr); sg.n++;
      if (dist(P, sg.a) >= 15 && sg.n >= 3) {
        const track = Math.atan2(P.y - sg.a.y, P.x - sg.a.x) * R2D;
        const mean = Math.atan2(sg.s, sg.c) * R2D;
        const err = wrap(track - mean);
        if (!mem.offInit) { mem.off = err; mem.offInit = true; }
        else {
