  mem.lastRays = rs;
  mem.rayOff = mem.sameN > 40;

  // ---------- helpers ----------
  const edgeDist = (d) => {
    const h = (H + d) * D2R, cx = Math.cos(h), cy = Math.sin(h);
    let e = 99;
    if (cx > 0.02) e = Math.min(e, (MAP - P.x) / cx);
    if (cx < -0.02) e = Math.min(e, P.x / -cx);
    if (cy > 0.02) e = Math.min(e, (MAP - P.y) / cy);
    if (cy < -0.02) e = Math.min(e, P.y / -cy);
    return Math.max(0, e);
  };
  const clr = (d) => {
    const ed = edgeDist(d);
    if (mem.rayOff) return Math.min(15, ed);
    let m = 15, any = false, bi = 0;
    for (let i = 0; i < 9; i++) {
      const da = Math.abs(ANG[i] - d);
      if (da < Math.abs(ANG[bi] - d)) bi = i;
      if (da <= 22) { any = true; if (R[i] < m) m = R[i]; }
    }
    if (!any) m = R[bi];
    return Math.min(m, ed);
  };
  // steer toward relative bearing rel (deg, + = left), avoiding obstacles
  const navStep = (rel, vmax) => {
    let best = 0, bc = Infinity;
    for (let d = -120; d <= 120; d += 10) {
      const c = clr(d);
      let cost = Math.abs(d - rel) + 0.25 * Math.abs(d - mem.prevD);
      if (c < 1.5) cost += 150 + (1.5 - c) * 40;
      else if (c < 5) cost += (5 - c) * 12;
      if (cost < bc) { bc = cost; best = d; }
    }
    mem.prevD = best;
    const ad = Math.abs(best);
    const cf = Math.min(clr(0), clr(best));
    let v = vmax * clamp((cf - 1.5) / 4, 0, 1) * clamp(1 - ad / 45, 0, 1);
    if (ad > 55) v = 0;
    const e0 = Math.abs(rel - best) <= 15 ? rel : best;
    const e = e0 * D2R;
    if (v > 0.05 && Math.abs(e0) < 25) mem.ib = clamp(mem.ib + 0.08 * e * dt, -0.12, 0.12);
    else mem.ib *= 0.98;
    let w = clamp(0.2 * e + mem.ib, -0.35, 0.35);
    if (Math.abs(e0) > 3 && Math.abs(w) < 0.08) w = 0.08 * Math.sign(e0);
    return mk(v - w, v + w, false);
  };
  const navTo = (Q, vmax) => navStep(wrap(Math.atan2(Q.y - P.y, Q.x - P.x) * R2D - H), vmax);
  const siteWorld = () => {
    const b = (H + num(site.bearing, 0)) * D2R;
    return { x: P.x + site.distance * Math.cos(b), y: P.y + site.distance * Math.sin(b) };
  };
  const endT = (T, ok) => {
    if (T.kind === 'explore') T.ref.st = 'done';
    else T.ref.st = ok ? 'done' : 'failed';
    mem.tgt = null;
  };
  const pick = () => {
    let best = null, bs = -1;
    const cons = (c, est, kind, ref) => {
      if (mem.samp.some((q) => dist(q, c) < 4 && (q.ok || t - q.t < 150))) return;
      const d = dist(P, c), db = dist(c, mem.base);
      if ((d + db) / 0.4 > timeLeft - 40) return;
      const sc = est / (d + 0.6 * db + 40);
      if (sc > bs) {
        bs = sc;
        best = { x: c.x, y: c.y, kind: kind, ref: ref, fails: 0, search: null, deadline: t + d / 0.2 + 100 };
      }
    };
    for (const h of mem.hints) if (h.st === 'todo') cons(h, h.est, 'hint', h);
    for (const f of mem.found) if (f.st === 'todo') cons(f, Math.max(0.05, f.value), 'found', f);
    if (!best) for (const e of mem.explore) if (e.st === 'todo') cons(e, mem.avgEst * 0.5, 'explore', e);
    return best;
  };

  // ---------- escape from bump / stuck ----------
  if (mem.esc) {
    if (t < mem.esc.t1) return mk(-0.4, -0.4, false);
    if (t < mem.esc.t2) return mk(-0.35 * mem.esc.s, 0.35 * mem.esc.s, false);
    mem.esc = null;
    mem.escCool = t + 2;
    mem.ib = 0;
    mem.stk = { t: t, p: { x: P.x, y: P.y } };
  }
  if (dist(P, mem.stk.p) > 0.5) mem.stk = { t: t, p: { x: P.x, y: P.y } };
  const cmdMag = Math.max(Math.abs(mem.cmdL), Math.abs(mem.cmdR));
  const holding = mem.phase === 'sample' && mem.sT && mem.sT.holding;
  const driving = mem.phase !== 'dock' && !holding;
  const straightCmd = Math.abs(mem.cmdL - mem.cmdR) < 0.2 && cmdMag > 0.25;
  const stuck = straightCmd && (t - mem.stk.t) > 6;
  if (driving && t > mem.escCool && (bumped || stuck)) {
    const s = clr(60) >= clr(-60) ? 1 : -1;
    mem.esc = { t1: t + 1.5, t2: t + 2.7, s: s };
    mem.escCool = t + 4.5;
    mem.stk = { t: t + 2.7, p: { x: P.x, y: P.y } };
    if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.phase === 'sample' && mem.sT) {
      mem.samp.push({ x: mem.sT.S.x, y: mem.sT.S.y, ok: false, t: t });
      mem.phase = 'nav'; mem.sT = null;
    }
    return mk(-0.4, -0.4, false);
  }

  // ---------- register sites seen ----------
  if (site) {
    const S = siteWorld();
    const known = mem.samp.some((q) => q.ok && dist(q, S) < 5);
    if (!known && !mem.found.some((f) => dist(f, S) < 5)) {
