  const dB = dist(P, mem.base);
  const docked = !!obs.docked || (beacon ? beacon.distance < 2.6 : dB < 2.2);
  if (mem.phase === 'dock') {
    const w = t - mem.dockT;
    if (!docked && w > 2) { mem.phase = 'home'; return zero(); }
    if (carried === 0 && w >= 1 && (battery > 0.35 || w > 25 || timeLeft < 300)) {
      mem.phase = 'nav'; mem.tgt = null; return zero();
    }
    if (carried > 0 && w > 15) { mem.phase = 'nav'; mem.tgt = null; mem.noHome = t + 25; return zero(); }
    return zero();
  }

  // ---------- start sampling a site within 8 m ----------
  if (site && num(site.distance, 99) <= 8 && mem.phase === 'nav' && carried < mem.cap &&
      battery > 0.05 && timeLeft > 40 && !docked) {
    const S = siteWorld();
    if (!mem.samp.some((q) => dist(q, S) < 4 && (q.ok || t - q.t < 150))) {
      mem.phase = 'sample';
      mem.sT = { S: S, t0: t, c0: carried, lastDr: drl, breaks: 0, holding: false, hT: 0 };
    }
  }

