  if (mem.phase === 'sample') {
    const st = mem.sT;
    if (!st) { mem.phase = 'nav'; return zero(); }
    if (carried > st.c0) {
      mem.samp.push({ x: st.S.x, y: st.S.y, ok: true, t: t });
      mem.nSamp++;
      for (const f of mem.found) if (dist(f, st.S) < 6) f.st = 'done';
      let bh = null, bd = 22;
      for (const h of mem.hints) {
        const d = dist(h, st.S);
        if (h.st !== 'done' && d < bd) { bd = d; bh = h; }
      }
      if (bh) bh.st = 'done';
      mem.phase = 'nav'; mem.sT = null; mem.tgt = null;
      return zero();
    }
    if (site) st.S = siteWorld();
    const failS = () => {
      mem.samp.push({ x: st.S.x, y: st.S.y, ok: false, t: t });
      mem.phase = 'nav'; mem.sT = null;
      if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
      return zero();
    };
    if (drl < st.lastDr - 0.3) st.breaks++;
    st.lastDr = drl;
    if (st.breaks > 3 || t - st.t0 > 150) return failS();
    const dS = site ? num(site.distance, 99) : dist(P, st.S);
    if (!st.holding) {
      if (!site && dist(P, st.S) > 10) return failS();
      if (dS > 1.3) {
        if (t - st.t0 > 80) return failS();
        const rel = site ? num(site.bearing, 0) : wrap(Math.atan2(st.S.y - P.y, st.S.x - P.x) * R2D - H);
        return navStep(rel, dS > 3 ? 0.3 : 0.15);
      }
      st.holding = true; st.hT = t; mem.hI = 0;
    }
    if (t - st.hT > 14 || drl > 12) return failS();
