  }

  if (mem.phase === 'home') {
    if (docked) { mem.phase = 'dock'; mem.dockT = t; mem.tgt = null; return zero(); }
    if (beacon && beacon.distance < 20) return navStep(num(beacon.bearing, 0), beacon.distance < 6 ? 0.18 : 0.4);
