    }
  }

  const T = mem.tgt;
  if (t > T.deadline || T.fails >= 3 || timeLeft < 20) { endT(T, false); return zero(); }

  if (T.search) {
    const Sr = T.search;
    if (science > 0) Sr.noSci = 0; else Sr.noSci = (Sr.noSci || 0) + dt;
    if (Sr.noSci > 8 || t > Sr.end) { endT(T, false); return zero(); }
    let bi = -1, bd = Infinity;
    for (let i = 0; i < Sr.pts.length; i++) {
      const p = Sr.pts[i];
      if (p.v) continue;
      const dd = dist(P, p);
      if (dd < 2.5) { p.v = true; continue; }
      if (dd < bd) { bd = dd; bi = i; }
    }
    if (bi < 0) { endT(T, false); return zero(); }
    return navTo(Sr.pts[bi], 0.25);
  }

  const dT = dist(P, T);
  if (dT < 6) {
    if (science > 0) {
      const pts = [];
      for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) {
        if (Math.hypot(6 * i, 6 * j) <= 14.5) {
          pts.push({ x: clamp(T.x + 6 * i, 2, 398), y: clamp(T.y + 6 * j, 2, 398), v: false });
        }
      }
      T.search = { end: t + 100, noSci: 0, pts: pts };
      T.deadline = Math.max(T.deadline, t + 110);
      return zero();
    }
    endT(T, false);
    return zero();
  }
  return navTo(T, dT < 15 ? 0.25 : 0.4);
}

function act(obs, mem) {
  let out = null;
  try { out = step(obs || {}, mem); } catch (e) { out = null; }
  if (!out) out = { left: 0, right: 0, drill: false };
  let L = Number(out.left), Rt = Number(out.right);
  if (!isFinite(L)) L = 0;
  if (!isFinite(Rt)) Rt = 0;
  L = Math.max(-1, Math.min(1, L));
  Rt = Math.max(-1, Math.min(1, Rt));
  mem.cmdL = L; mem.cmdR = Rt;
  return { left: L, right: Rt, drill: !!out.drill };
}

function step(obs, mem) {
