    if (!site && dS > 3) return failS();
    if (!st.holding) {
      if (t - st.t0 > 90) return failS();
      if (dS > 1.3) {
        const rel = site ? num(site.bearing, 0) : wrap(Math.atan2(st.S.y - P.y, st.S.x - P.x) * R2D - H);
        const vS = dS > 4 ? 0.4 : (dS > 2.5 ? 0.25 : 0.12);
        return navStep(rel, vS);
      }
      st.holding = true; st.hT = t;
    }
    if (t - st.hT > 12 || drl > 10) return failS();
    // hold still: motors idle, small pitch compensation only on a real slope
    const pu = Math.abs(pitch) > 3 ? clamp(0.012 * pitch, -0.2, 0.2) : 0;
    return mk(pu, pu, true);
  }

  // ---------- decide to go home ----------
  if (mem.phase === 'nav') {
    let wantHome = false;
    if (carried > 0) {
      if (carried >= mem.cap) wantHome = true;
      if (carried >= 2 && dB < 25) wantHome = true;
      if (timeLeft < dB / 0.35 + 80) wantHome = true;
      if (battery < 0.15 + dB * 0.003) wantHome = true;
    }
    if (t < mem.noHome && battery > 0.25) wantHome = false;
    if (wantHome) { mem.phase = 'home'; mem.tgt = null; }
  }

  if (mem.phase === 'home') {
    if (docked) { mem.phase = 'dock'; mem.dockT = t; mem.tgt = null; return zero(); }
    if (beacon && beacon.distance < 20) return navStep(num(beacon.bearing, 0), beacon.distance < 6 ? 0.18 : 0.45);
    return navTo(mem.base, dB < 6 ? 0.18 : 0.45);
  }

  // ---------- target selection ----------
  if (!mem.tgt) {
    mem.tgt = pick();
    if (!mem.tgt && mem.resets < 2) {
      mem.resets++;
      for (const h of mem.hints) if (h.st === 'failed') h.st = 'todo';
      for (const e of mem.explore) e.st = 'todo';
      mem.tgt = pick();
    }
    if (!mem.tgt) {
      if (carried > 0) mem.phase = 'home';
      return zero();
    }
  }

  const T = mem.tgt;
  if (t > T.deadline || T.fails >= 3 || timeLeft < 20) { endT(T, false); return zero(); }

  if (T.search) {
    const Sr = T.search;
    if (science > 0) Sr.noSci = 0; else Sr.noSci = (Sr.noSci || 0) + dt;
    if (Sr.noSci > 8 || t > Sr.end) { endT(T, false); return zero(); }
    let bi = -1, bd = Infinity;
    for (let i = 0; i < Sr.pts.length; i++) {
      const p = Sr.pts[i];
      if (p.v) continue;
      const dd = dist(P, p);
      if (dd < 2.5) { p.v = true; continue; }
      if (dd < bd) { bd = dd; bi = i; }
    }
    if (bi < 0) { endT(T, false); return zero(); }
    return navTo(Sr.pts[bi], 0.25);
  }

  const dT = dist(P, T);
  if (dT < 6) {
    if (science > 0) {
      const pts = [];
      for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) {
        if (Math.hypot(6 * i, 6 * j) <= 14.5) {
          pts.push({ x: clamp(T.x + 6 * i, 2, 398), y: clamp(T.y + 6 * j, 2, 398), v: false });
        }
      }
      T.search = { end: t + 100, noSci: 0, pts: pts };
      T.deadline = Math.max(T.deadline, t + 110);
      return zero();
    }
    endT(T, false);
    return zero();
  }
  return navTo(T, dT < 15 ? 0.3 : 0.45);
}

function act(obs, mem) {
  let out = null;
  try { out = step(obs || {}, mem); } catch (e) { out = null; }
  if (!out) out = { left: 0, right: 0, drill: false };
  let L = Number(out.left), Rt = Number(out.right);
  if (!isFinite(L)) L = 0;
  if (!isFinite(Rt)) Rt = 0;
  L = Math.max(-1, Math.min(1, L));
  Rt = Math.max(-1, Math.min(1, Rt));
  mem.cmdL = L; mem.cmdR = Rt;
  return { left: L, right: Rt, drill: !!out.drill };
}

function step(obs, mem) {
  const D2R = Math.PI / 180, R2D = 180 / Math.PI;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const wrap = (a) => ((a + 180) % 360 + 360) % 360 - 180;
  const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const MAP = 400;
  const zero = () => ({ left: 0, right: 0, drill: false });
  const mk = (l, r, d) => ({ left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!d });

  const t = num(obs.t, 0);
  const timeLeft = num(obs.timeLeft, 1200);
  const battery = num(obs.battery, 1);
  const carried = num(obs.carried, 0);
  const science = num(obs.science, 0);
  const heading = num(obs.heading, 0);
  const drl = num(obs.drilling, 0);
  const pitch = num(obs.pitch, 0);
  const vf = (num(obs.wheelLeft, 0) + num(obs.wheelRight, 0)) / 2;
  const site = (obs.site && typeof obs.site.distance === 'number') ? obs.site : null;
  const beacon = (obs.beacon && typeof obs.beacon.distance === 'number') ? obs.beacon : null;
  const bumped = !!obs.bumped;
  const R = ANG.map((a, i) => clamp(num(Array.isArray(obs.rays) ? obs.rays[i] : undefined, 15), 0, 15));

  // ---------- init ----------
  if (!mem.init) {
    mem.init = true;
    const m = obs.mission || {};
    const bp = m.base || {};
    mem.base = { x: num(bp.x, num(obs.x, 0)), y: num(bp.y, num(obs.y, 0)) };
    mem.cap = Math.max(1, num(m.capacity, 5));
    mem.hints = (Array.isArray(m.hints) ? m.hints : [])
      .filter((h) => h && typeof h.x === 'number' && typeof h.y === 'number')
      .map((h) => ({ x: h.x, y: h.y, est: Math.max(0.05, num(h.estimate, 1)), st: 'todo' }));
    let s = 0;
    for (const h of mem.hints) s += h.est;
    mem.avgEst = mem.hints.length ? s / mem.hints.length : 1;
    mem.explore = [];
    for (const x of [50, 125, 200, 275, 350]) for (const y of [50, 125, 200, 275, 350]) mem.explore.push({ x: x, y: y, st: 'todo' });
    mem.found = [];
    mem.samp = [];
    mem.phase = 'nav'; mem.tgt = null; mem.sT = null; mem.esc = null; mem.escCool = -1;
    mem.off = 0; mem.offInit = false; mem.seg = null;
    mem.P = { x: num(obs.x, 0), y: num(obs.y, 0) };
    mem.gx = mem.P.x; mem.gy = mem.P.y; mem.gT = t; mem.lastT = t; mem.vE = 0;
    mem.hist = []; mem.hT = -1;
    mem.ib = 0; mem.prevD = 0;
    mem.dockT = t; mem.noHome = -1; mem.nSamp = 0; mem.resets = 0;
    mem.lastRays = ''; mem.sameN = 0; mem.rayOff = false;
    mem.cmdL = 0; mem.cmdR = 0;
  }

  // ---------- position: GPS, dead reckoning when stale ----------
  const dt = clamp(t - mem.lastT, 0, 0.5);
  mem.lastT = t;
  const ox = num(obs.x, mem.P.x), oy = num(obs.y, mem.P.y);
  const fixNew = ox !== mem.gx || oy !== mem.gy;
  if (fixNew) { mem.gx = ox; mem.gy = oy; mem.gT = t; }
  const stale = (t - mem.gT) > 3;
  mem.vE = 0.3 * vf + 0.7 * mem.vE;
  const H = wrap(heading + mem.off);
  const P = stale
    ? { x: mem.P.x + mem.vE * dt * Math.cos(H * D2R), y: mem.P.y + mem.vE * dt * Math.sin(H * D2R) }
    : { x: ox, y: oy };
  mem.P = P;

  // ---------- compass offset from straight GPS runs ----------
  if (fixNew && !stale) {
    const straightCmd = mem.cmdL > 0.15 && mem.cmdR > 0.15 && Math.abs(mem.cmdL - mem.cmdR) < 0.12;
    if (!straightCmd || bumped || vf < 0.12) mem.seg = null;
    else {
      if (!mem.seg) mem.seg = { a: { x: P.x, y: P.y }, s: 0, c: 0, n: 0 };
      const sg = mem.seg;
      const hr = heading * D2R;
      sg.s += Math.sin(hr); sg.c += Math.cos(hr); sg.n++;
      if (dist(P, sg.a) >= 15 && sg.n >= 3) {
        const track = Math.atan2(P.y - sg.a.y, P.x - sg.a.x) * R2D;
        const mean = Math.atan2(sg.s, sg.c) * R2D;
        const err = wrap(track - mean);
        if (!mem.offInit) { mem.off = err; mem.offInit = true; }
        else {
          const dd = wrap(err - mem.off);
          if (Math.abs(dd) < 40) mem.off = wrap(mem.off + 0.25 * dd);
        }
        mem.seg = null;
      }
    }
  }

  // ---------- ray sanity (stuck sensor detection) ----------
  const rs = R.join(',');
  if (rs === mem.lastRays && vf > 0.2 && R.some((v) => v < 14.5)) mem.sameN++; else mem.sameN = 0;
  mem.lastRays = rs;
  mem.rayOff = mem.sameN > 40;

  // ---------- helpers ----------
  const edgeDist = (d) => {
    const h = (H + d) * D2R, cx = Math.cos(h), cy = Math.sin(h);
    let e = 99;
    if (cx > 0.02) e = Math.min(e, (MAP - P.x) / cx);
    if (cx < -0.02) e = Math.min(e, P.x / -cx);
    if (cy > 0.02) e = Math.min(e, (MAP - P.y) / cy);
    if (cy < -0.02) e = Math.min(e, P.y / -cy);
    return Math.max(0, e);
  };
  const clr = (d) => {
    const ed = edgeDist(d);
    if (mem.rayOff) return Math.min(15, ed);
    let m = 15, any = false, bi = 0;
    for (let i = 0; i < 9; i++) {
      const da = Math.abs(ANG[i] - d);
      if (da < Math.abs(ANG[bi] - d)) bi = i;
      if (da <= 22) { any = true; if (R[i] < m) m = R[i]; }
    }
    if (!any) m = R[bi];
    return Math.min(m, ed);
  };
  // steer toward relative bearing rel (deg, + = left), avoiding obstacles
  const navStep = (rel, vmax) => {
    let best = 0, bc = Infinity;
    for (let d = -120; d <= 120; d += 10) {
      const c = clr(d);
      let cost = Math.abs(d - rel) + 0.25 * Math.abs(d - mem.prevD);
      if (c < 1.5) cost += 150 + (1.5 - c) * 40;
      else if (c < 5) cost += (5 - c) * 12;
      if (cost < bc) { bc = cost; best = d; }
    }
    mem.prevD = best;
    const ad = Math.abs(best);
    const cf = Math.min(clr(0), clr(best));
    let v = vmax * clamp((cf - 1.5) / 4, 0, 1) * clamp(1 - ad / 45, 0, 1);
    if (ad > 55) v = 0;
    const e0 = Math.abs(rel - best) <= 15 ? rel : best;
    const e = e0 * D2R;
    if (v > 0.05 && Math.abs(e0) < 25) mem.ib = clamp(mem.ib + 0.08 * e * dt, -0.12, 0.12);
    else mem.ib *= 0.98;
    let w = clamp(0.2 * e + mem.ib, -0.35, 0.35);
    if (Math.abs(e0) > 3 && Math.abs(w) < 0.08) w = 0.08 * Math.sign(e0);
    return mk(v - w, v + w, false);
  };
  const navTo = (Q, vmax) => navStep(wrap(Math.atan2(Q.y - P.y, Q.x - P.x) * R2D - H), vmax);
  const siteWorld = () => {
    const b = (H + num(site.bearing, 0)) * D2R;
    return { x: P.x + site.distance * Math.cos(b), y: P.y + site.distance * Math.sin(b) };
  };
  const endT = (T, ok) => {
    if (T.kind === 'explore') T.ref.st = 'done';
    else T.ref.st = ok ? 'done' : 'failed';
    mem.tgt = null;
  };
  const pick = () => {
    let best = null, bs = -1;
    const cons = (c, est, kind, ref) => {
      if (mem.samp.some((q) => dist(q, c) < 4 && (q.ok || t - q.t < 150))) return;
      const d = dist(P, c), db = dist(c, mem.base);
      if ((d + db) / 0.4 > timeLeft - 40) return;
      const sc = est / (d + 0.6 * db + 40);
      if (sc > bs) {
        bs = sc;
        best = { x: c.x, y: c.y, kind: kind, ref: ref, fails: 0, search: null,
                 deadline: t + d / 0.25 + 90, bestD: Infinity, bestT: t };
      }
    };
    for (const h of mem.hints) if (h.st === 'todo') cons(h, h.est, 'hint', h);
    for (const f of mem.found) if (f.st === 'todo') cons(f, Math.max(0.05, f.value), 'found', f);
    if (!best) for (const e of mem.explore) if (e.st === 'todo') cons(e, mem.avgEst * 0.5, 'explore', e);
    return best;
  };

  // ---------- position history (1 Hz) for displacement-based stuck test ----------
  if (mem.hT < 0 || t - mem.hT >= 1) {
    mem.hist.push({ t: t, x: P.x, y: P.y, hd: heading });
    if (mem.hist.length > 6) mem.hist.shift();
    mem.hT = t;
  }
  const cmdMag = Math.max(Math.abs(mem.cmdL), Math.abs(mem.cmdR));

  // ---------- escape from bump / stuck ----------
  if (mem.esc) {
    if (t < mem.esc.t1) return mk(-0.4, -0.4, false);
    if (t < mem.esc.t2) return mk(-0.35 * mem.esc.s, 0.35 * mem.esc.s, false);
    mem.esc = null;
    mem.escCool = t + 2;
    mem.ib = 0;
    mem.hist = [];
  }
  let stuck = false;
  if (mem.hist.length >= 6 && t - mem.hist[0].t >= 4.5 && cmdMag > 0.2) {
    let mx = 0;
    for (const h of mem.hist) mx = Math.max(mx, Math.hypot(h.x - P.x, h.y - P.y));
    stuck = mx < 0.6 && Math.abs(wrap(heading - mem.hist[0].hd)) < 25;
  }
  const holding = mem.phase === 'sample' && mem.sT && mem.sT.holding;
  const driving = mem.phase !== 'dock' && !holding;
  if (driving && t > mem.escCool && (bumped || stuck)) {
    const s = clr(60) >= clr(-60) ? 1 : -1;
    mem.esc = { t1: t + 1.5, t2: t + 2.7, s: s };
    mem.escCool = t + 4.5;
    mem.hist = [];
    if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.phase === 'sample' && mem.sT) {
      mem.samp.push({ x: mem.sT.S.x, y: mem.sT.S.y, ok: false, t: t });
      mem.phase = 'nav'; mem.sT = null;
    }
    return mk(-0.4, -0.4, false);
  }

  // ---------- register sites seen ----------
  if (site) {
    const S = siteWorld();
    const known = mem.samp.some((q) => q.ok && dist(q, S) < 5);
    if (!known && !mem.found.some((f) => dist(f, S) < 5)) {
      mem.found.push({ x: S.x, y: S.y, value: num(site.value, 1), st: 'todo' });
    }
  }

  // ---------- docking ----------
  const dB = dist(P, mem.base);
  const docked = !!obs.docked || (beacon ? beacon.distance < 2.6 : dB < 2.2);
  if (mem.phase === 'dock') {
    const w = t - mem.dockT;
    if (!docked && w > 2) { mem.phase = 'home'; return zero(); }
    if (carried === 0 && w >= 1 && (battery > 0.35 || w > 25 || timeLeft < 300)) {
      mem.phase = 'nav'; mem.tgt = null; return zero();
    }
    if (carried > 0 && w > 15) { mem.phase = 'nav'; mem.tgt = null; mem.noHome = t + 25; return zero(); }
    return zero();
  }

  // ---------- start sampling a site within 8 m ----------
  if (site && num(site.distance, 99) <= 8 && mem.phase === 'nav' && carried < mem.cap &&
      battery > 0.05 && timeLeft > 40 && !docked) {
    const S = siteWorld();
    if (!mem.samp.some((q) => dist(q, S) < 4 && (q.ok || t - q.t < 150))) {
      mem.phase = 'sample';
      mem.sT = { S: S, t0: t, c0: carried, lastDr: drl, breaks: 0, holding: false, hT: 0 };
    }
  }

  // ---------- sampling: gentle approach, then drill with motors idle ----------
  if (mem.phase === 'sample') {
    const st = mem.sT;
    if (!st) { mem.phase = 'nav'; return zero(); }
    if (carried > st.c0) {
      mem.samp.push({ x: st.S.x, y: st.S.y, ok: true, t: t });
      mem.nSamp++;
      for (const f of mem.found) if (dist(f, st.S) < 6) f.st = 'done';
      let bh = null, bd = 22;
      for (const h of mem.hints) {
        const d = dist(h, st.S);
        if (h.st !== 'done' && d < bd) { bd = d; bh = h; }
      }
      if (bh) bh.st = 'done';
      mem.phase = 'nav'; mem.sT = null; mem.tgt = null;
      return zero();
    }
    if (site) st.S = siteWorld();
    const failS = () => {
      mem.samp.push({ x: st.S.x, y: st.S.y, ok: false, t: t });
      mem.phase = 'nav'; mem.sT = null;
      if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
      return zero();
    };
    if (drl < st.lastDr - 0.3) st.breaks++;
    st.lastDr = drl;
    if (st.breaks > 3 || t - st.t0 > 120) return failS();
    const dS = site ? num(site.distance, 99) : dist(P, st.S);
    if (!site && dS > 3) return failS();
    if (!st.holding) {
      if (t - st.t0 > 60) return failS();
      if (dS > 1.3) {
        const rel = site ? num(site.bearing, 0) : wrap(Math.atan2(st.S.y - P.y, st.S.x - P.x) * R2D - H);
        const vS = dS > 4 ? 0.4 : (dS > 2.5 ? 0.25 : 0.12);
        return navStep(rel, vS);
      }
      st.holding = true; st.hT = t;
    }
    if (t - st.hT > 12 || drl > 10) return failS();
    // hold still: motors idle, small pitch compensation only on a real slope
    const pu = Math.abs(pitch) > 3 ? clamp(0.012 * pitch, -0.2, 0.2) : 0;
    return mk(pu, pu, true);
  }

  // ---------- decide to go home ----------
  if (mem.phase === 'nav') {
    let wantHome = false;
    if (carried > 0) {
      if (carried >= mem.cap) wantHome = true;
      if (carried >= 2 && dB < 25) wantHome = true;
      if (timeLeft < dB / 0.4 + 80) wantHome = true;
      if (battery < 0.15 + dB * 0.003) wantHome = true;
    }
    if (t < mem.noHome && battery > 0.25) wantHome = false;
    if (wantHome) { mem.phase = 'home'; mem.tgt = null; }
  }

  if (mem.phase === 'home') {
    if (docked) { mem.phase = 'dock'; mem.dockT = t; mem.tgt = null; return zero(); }
    if (beacon && beacon.distance < 20) return navStep(num(beacon.bearing, 0), beacon.distance < 6 ? 0.18 : 0.45);
    return navTo(mem.base, dB < 6 ? 0.18 : 0.45);
  }

  // ---------- target selection ----------
  if (!mem.tgt) {
    mem.tgt = pick();
    if (!mem.tgt && mem.resets < 2) {
      mem.resets++;
      for (const h of mem.hints) if (h.st === 'failed') h.st = 'todo';
      for (const e of mem.explore) e.st = 'todo';
      mem.tgt = pick();
    }
    if (!mem.tgt) {
      if (carried > 0) mem.phase = 'home';
      return zero();
    }
  }

  const T = mem.tgt;
  if (t > T.deadline || T.fails >= 3 || timeLeft < 20) { endT(T, false); return zero(); }

  if (T.search) {
    const Sr = T.search;
    if (science > 0) Sr.noSci = 0; else Sr.noSci = (Sr.noSci || 0) + dt;
    if (Sr.noSci > 8 || t > Sr.end) { endT(T, false); return zero(); }
    let bi = -1, bd = Infinity;
    for (let i = 0; i < Sr.pts.length; i++) {
      const p = Sr.pts[i];
      if (p.v) continue;
      const dd = dist(P, p);
      if (dd < 2.5) { p.v = true; continue; }
      if (dd < bd) { bd = dd; bi = i; }
    }
    if (bi < 0) { endT(T, false); return zero(); }
    return navTo(Sr.pts[bi], 0.25);
  }

  // progress watchdog: give up if no real approach for 45 s
  const dT = dist(P, T);
  if (dT < T.bestD - 2) { T.bestD = dT; T.bestT = t; }
  if (t - T.bestT > 45) { endT(T, false); return zero(); }

  if (dT < 6) {
    if (science > 0) {
      const pts = [];
      for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) {
        if (Math.hypot(6 * i, 6 * j) <= 14.5) {
          pts.push({ x: clamp(T.x + 6 * i, 2, 398), y: clamp(T.y + 6 * j, 2, 398), v: false });
        }
      }
      T.search = { end: t + 90, noSci: 0, pts: pts };
      T.deadline = Math.max(T.deadline, t + 100);
      return zero();
    }
    endT(T, false);
    return zero();
  }
  return navTo(T, dT < 15 ? 0.3 : 0.45);
}
